// Carrega variáveis de um arquivo .env LOCAL (se existir) — assim dá pra rodar o
// localhost com login, igual ao site, sem digitar nada. Em produção (Render) não
// há .env e as variáveis reais do ambiente SEMPRE têm prioridade (não sobrescreve).
(function carregarDotEnv() {
  try {
    const envPath = path.join(RAIZ, '.env');
    if (!fs.existsSync(envPath)) return;
    for (const linha of fs.readFileSync(envPath, 'utf-8').split(/\r?\n/)) {
      const s = linha.trim();
      if (!s || s.startsWith('#')) continue;
      const i = s.indexOf('=');
      if (i < 0) continue;
      const chave = s.slice(0, i).trim();
      let valor = s.slice(i + 1).trim();
      if ((valor.startsWith('"') && valor.endsWith('"')) || (valor.startsWith("'") && valor.endsWith("'"))) valor = valor.slice(1, -1);
      if (chave && process.env[chave] === undefined) process.env[chave] = valor; // env real vence
    }
    console.log('Variáveis carregadas do arquivo .env (modo local).');
  } catch (e) { /* .env é opcional */ }
})();

// ----- Rede de segurança do processo -----
// Sem isto, QUALQUER promessa rejeitada sem catch (e as rotas async confiam que os awaits
// nunca rejeitam) derruba o processo INTEIRO no Node moderno — o sintoma é o site "oscilando"
// (morre e volta) sem nenhuma pista. Aqui: rejeição solta loga a pilha COMPLETA no stdout
// (visível nos Logs do Render) e o processo segue vivo; exceção síncrona não tratada loga e
// encerra com calma (estado imprevisível — o Render reinicia limpo, mas agora COM o motivo no log).
process.on('unhandledRejection', (motivo) => {
  console.error('[unhandledRejection]', motivo && (motivo.stack || motivo.message || motivo));
});
process.on('uncaughtException', (err) => {
  console.error('[uncaughtException]', err && (err.stack || err.message || err));
  setTimeout(() => process.exit(1), 300).unref(); // deixa o log sair antes do restart
});

const app = express();
const PORT = process.env.PORT || 3000;
app.use(compression({
  // gzip/brotli nas respostas (HTML, JS, CSS, JSON) — acelera o carregamento.
  // SSE (text/event-stream) fica FORA da compressão: o buffer do middleware atrasaria
  // os eventos em tempo real (/api/eventos). Mantém o filtro padrão para o resto.
  filter: (req, res) => {
    if (String(res.getHeader('Content-Type') || '').includes('text/event-stream')) return false;
    return compression.filter(req, res);
  },
}));
