// Validação de uploads: além do teto de tamanho, conferimos o tipo declarado (MIME) e a
// extensão contra uma allowlist por finalidade. Tipos perigosos (HTML/SVG/JS/executáveis)
// nunca entram no cofre. Rejeição é silenciosa (cb(null,false)) → o handler vê req.file
// indefinido e responde 400 sem vazar erro. limites: 10 MB e no máx. 1 arquivo por requisição.
const MIDIA_MIME = new Set(['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif', 'application/pdf']);
const MIDIA_EXT = new Set(['.jpg', '.jpeg', '.png', '.webp', '.gif', '.pdf']);
const PLANILHA_MIME = new Set([
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', // .xlsx
  'application/vnd.ms-excel',                                          // .xls
  'text/csv', 'application/csv', 'text/plain',                         // .csv (varia por navegador)
  'application/octet-stream',                                          // alguns navegadores enviam genérico
]);
const PLANILHA_EXT = new Set(['.xlsx', '.xls', '.csv']);
const PDF_MIME = new Set(['application/pdf', 'application/octet-stream']);
const PDF_EXT = new Set(['.pdf']);
const TERMO_MULTA_MIME = new Set(['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/octet-stream']);
const TERMO_MULTA_EXT = new Set(['.pdf', '.docx']);
const DOCX_MIME = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const PPTX_MIME = 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
const OLE_LEGADO_MIME = { '.doc': 'application/msword', '.xls': 'application/vnd.ms-excel', '.ppt': 'application/vnd.ms-powerpoint' };
// Confere se o ZIP é realmente um pacote OOXML do tipo esperado (docx/xlsx/pptx compartilham o
// mesmo contêiner ZIP; a extensão por si só não garante o conteúdo — um .zip renomeado passaria).
function officeZipValido(buffer, entradaChave) {
  return new Promise((resolve) => {
    yauzl.fromBuffer(buffer, { lazyEntries: true }, (err, zip) => {
      if (err || !zip) return resolve(false);
      const nomes = new Set();
      let entradas = 0, terminou = false;
      const fim = (ok) => { if (terminou) return; terminou = true; try { zip.close(); } catch (_) { /* já fechado */ } resolve(ok); };
      zip.on('entry', (entry) => {
        if (++entradas > 500) return fim(false);
        nomes.add(String(entry.fileName || ''));
        zip.readEntry();
      });
      zip.on('end', () => fim(nomes.has('[Content_Types].xml') && nomes.has(entradaChave)));
      zip.on('error', () => fim(false));
      zip.readEntry();
    });
  });
}
const docxValido = (buffer) => officeZipValido(buffer, 'word/document.xml');
// Assinaturas binárias: contêiner OLE2 (doc/xls/ppt legados) e ZIP genérico (docx/xlsx/pptx/zip).
function assinaturaOle(b) { return !!b && b.length >= 8 && b[0] === 0xD0 && b[1] === 0xCF && b[2] === 0x11 && b[3] === 0xE0 && b[4] === 0xA1 && b[5] === 0xB1 && b[6] === 0x1A && b[7] === 0xE1; }
function assinaturaZip(b) { return !!b && b.length >= 4 && b[0] === 0x50 && b[1] === 0x4B && (b[2] === 0x03 || b[2] === 0x05 || b[2] === 0x07); }
// PKCS#12 (.pfx/.p12) é DER (ASN.1): começa com a tag SEQUENCE (0x30) em formato de comprimento longo.
function assinaturaPfx(b) { return !!b && b.length >= 4 && b[0] === 0x30 && (b[1] & 0x80) !== 0; }
// Confirma o CONTEÚDO de um arquivo de documento pela extensão declarada — mesmo padrão de
// mídia/termos: o MIME do navegador é ignorado, o que decide é a extensão + os "magic bytes".
async function tipoArquivoDocumento(ext, buffer) {
  if (ext === '.pdf') return detectarTipoMidia(buffer) === 'application/pdf' ? 'application/pdf' : null;
  if (['.jpg', '.jpeg', '.png', '.webp', '.gif'].includes(ext)) { const t = detectarTipoMidia(buffer); return t && t.startsWith('image/') ? t : null; }
  if (ext === '.docx') return await officeZipValido(buffer, 'word/document.xml') ? DOCX_MIME : null;
  if (ext === '.xlsx') return await officeZipValido(buffer, 'xl/workbook.xml') ? XLSX_MIME : null;
  if (ext === '.pptx') return await officeZipValido(buffer, 'ppt/presentation.xml') ? PPTX_MIME : null;
  if (OLE_LEGADO_MIME[ext]) return assinaturaOle(buffer) ? OLE_LEGADO_MIME[ext] : null;
  if (ext === '.zip') return assinaturaZip(buffer) ? 'application/zip' : null;
  if (ext === '.csv') return 'text/csv';
  if (ext === '.txt') return 'text/plain';
  if (ext === '.pfx' || ext === '.p12') return assinaturaPfx(buffer) ? 'application/x-pkcs12' : null;
  return null;
}
const DOC_EMPRESA_EXT = new Set(['.pdf', '.jpg', '.jpeg', '.png', '.webp', '.gif', '.docx', '.doc', '.xlsx', '.xls', '.pptx', '.ppt', '.csv', '.txt', '.zip', '.pfx', '.p12']);
const DOC_EMPRESA_MIME = new Set(['application/pdf', 'image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif', DOCX_MIME, 'application/msword', XLSX_MIME, 'application/vnd.ms-excel', PPTX_MIME, 'application/vnd.ms-powerpoint', 'text/csv', 'application/csv', 'text/plain', 'application/zip', 'application/x-zip-compressed', 'application/octet-stream', 'application/x-pkcs12']);
function filtroArquivo(mimes, exts) {
  return (req, file, cb) => {
    const nome = String(file.originalname || '');
    // Rejeita nomes perigosos: travessia de diretório ou caracteres de controle/barra.
    if (/[\/\\]|\.\.|[\x00-\x1f]/.test(nome)) return cb(null, false);
    const mime = String(file.mimetype || '').toLowerCase();
    const m = nome.match(/\.[^.]+$/);
    const ext = m ? m[0].toLowerCase() : '';
    // O MIME do navegador é POUCO confiável (um JPG pode chegar como image/jpeg, image/jpg ou vazio).
    // Então a allowlist real é por EXTENSÃO — que barra .exe/.html/.svg mesmo com MIME forjado.
    // Quando há extensão, ela decide. Sem extensão (ex.: documento cujo "nome" é só um rótulo),
    // aceita MIME conhecido OU genérico (vazio/octet-stream). Em ambos os casos o CONTEÚDO ainda é
    // validado adiante: mídia confere os "magic bytes"; planilha só abre se for um xlsx/csv válido.
    if (ext) return exts.has(ext) ? cb(null, true) : cb(null, false);
    if (mimes.has(mime) || mime === '' || mime === 'application/octet-stream') return cb(null, true);
    return cb(null, false);
  };
}
const LIMITES_UPLOAD = { fileSize: 10 * 1024 * 1024, files: 1 }; // teto de 10 MB, 1 arquivo
const LIMITES_PLANILHA_UPLOAD = { fileSize: 10 * 1024 * 1024, files: 30 }; // importadores de planilhas aceitam lote
const LIMITES_PDF_LOTE_UPLOAD = { fileSize: 20 * 1024 * 1024, files: 30 }; // extratos/relatórios em lote
const uploadMidia = multer({ storage: multer.memoryStorage(), limits: LIMITES_UPLOAD, fileFilter: filtroArquivo(MIDIA_MIME, MIDIA_EXT) });
const uploadPlanilha = multer({ storage: multer.memoryStorage(), limits: LIMITES_PLANILHA_UPLOAD, fileFilter: filtroArquivo(PLANILHA_MIME, PLANILHA_EXT) });
const uploadPdfLote = multer({ storage: multer.memoryStorage(), limits: LIMITES_PDF_LOTE_UPLOAD, fileFilter: filtroArquivo(PDF_MIME, PDF_EXT) });
const uploadTermoMulta = multer({ storage: multer.memoryStorage(), limits: LIMITES_UPLOAD, fileFilter: filtroArquivo(TERMO_MULTA_MIME, TERMO_MULTA_EXT) });
const LIMITES_DOC_UPLOAD = { fileSize: 10 * 1024 * 1024, files: 20 }; // documentos aceitam lote (até 20 por envio)
const uploadDocumentos = multer({ storage: multer.memoryStorage(), limits: LIMITES_DOC_UPLOAD, fileFilter: filtroArquivo(DOC_EMPRESA_MIME, DOC_EMPRESA_EXT) });

// ----- Persistência: arquivos (local) OU MongoDB (nuvem, se MONGODB_URI existir) -----
const USE_MONGO = !!process.env.MONGODB_URI;
let mongoCol = null;                 // coleção do MongoDB
