// Grava no MongoDB e ESPERA a confirmação. Lança erro se falhar (quem chama
// decide se aborta a operação) — assim o cliente nunca recebe "salvo" sem ter salvo.
async function persistMongo(id, doc) {
  if (!mongoCol) return;
  await mongoCol.updateOne({ _id: id }, { $set: doc }, { upsert: true });
}

// Escrita atômica: grava num .tmp e renomeia por cima (rename é atômico no
// mesmo disco, inclusive no Windows). Evita corromper o JSON se o processo
// morrer no meio da escrita. Mantém um .bak da versão anterior como rede extra.
function escreverJSONAtomico(file, obj) {
  const tmp = file + '.tmp';
  try { if (fs.existsSync(file)) fs.copyFileSync(file, file + '.bak'); } catch (e) { /* backup é best-effort */ }
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2), 'utf-8');
  fs.renameSync(tmp, file);
}

