// ----- Persistência -----
function lerDados() {
  if (USE_MONGO) return { veiculos: mem.veiculos || [] };
  try {
    const raw = fs.readFileSync(DATA_FILE, 'utf-8');
    const obj = JSON.parse(raw);
    if (!Array.isArray(obj.veiculos)) obj.veiculos = [];
    return obj;
  } catch (e) {
    return { veiculos: [] };
  }
}

async function salvarDados(dados) {
  if (USE_MONGO) {
    mem.veiculos = dados.veiculos || [];
    await persistMongo('frota', { veiculos: mem.veiculos });
  } else {
    escreverJSONAtomico(DATA_FILE, dados);
  }
  notificarDados('veiculos');
}

// Snapshot da frota atual antes de uma operação destrutiva (ex.: importar
// planilha, que SUBSTITUI tudo). Em Mongo grava o doc _id:'frota_backup'
// (recuperável no Atlas); local grava data.backup.json. Não derruba a operação
// se o backup falhar — é uma rede de segurança best-effort.
async function backupFrotaAtual(motivo) {
  try {
    const veiculos = lerDados().veiculos || [];
    const snapshot = { veiculos, ts: Date.now(), motivo: motivo || '' };
    if (USE_MONGO) await persistMongo('frota_backup', snapshot);
    else escreverJSONAtomico(path.join(DATA_DIR, 'data.backup.json'), snapshot);
    console.log(`Backup da frota criado (${veiculos.length} veículos) · ${motivo || ''}`);
  } catch (e) {
    console.error('Falha ao criar backup da frota:', e.message);
  }
}

// ----- Histórico de alterações -----
const ROTULO_CAMPO = {};
for (const [campo, rotulo] of COLUNAS) ROTULO_CAMPO[campo] = rotulo;

function lerHistorico() {
  if (USE_MONGO) return mem.historico || [];
  try {
    const arr = JSON.parse(fs.readFileSync(HIST_FILE, 'utf-8'));
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

// Histórico é secundário: best-effort. Uma falha aqui NÃO deve abortar a
// operação principal (já salva), então engole o próprio erro.
async function registrarHistorico(entradas, por) {
  if (!entradas || !entradas.length) return;
  const ts = Date.now();
  // id único entre processos/restarts (gerarId usa crypto), evitando colisão de `${ts}_seq` em multi-instância
  const novas = entradas.map(e => Object.assign({ id: gerarId('H'), ts }, e, { por: por || e.por || '' }));
  if (USE_MONGO) {
    // Append ATÔMICO ($push/$slice) em vez de reler+regravar o array inteiro: assim
    // duas requisições concorrentes não sobrescrevem uma à outra (a trilha não perde entradas).
    mem.historico = (mem.historico || []).concat(novas).slice(-1000);
    if (mongoCol) {
      try { await mongoCol.updateOne({ _id: 'historico' }, { $push: { historico: { $each: novas, $slice: -1000 } } }, { upsert: true }); }
      catch (err) { console.error('Falha ao salvar histórico no Mongo:', err.message); }
    }
    return;
  }
  const hist = lerHistorico();
  for (const e of novas) hist.push(e);
  try { escreverJSONAtomico(HIST_FILE, hist.slice(-1000)); } catch (err) { /* ignora */ }
}

async function salvarHistorico(arr) {
  if (USE_MONGO) {
    mem.historico = arr || [];
    try { await persistMongo('historico', { historico: mem.historico }); } catch (err) { console.error('Falha ao salvar histórico no Mongo:', err.message); }
    return;
  }
  try { escreverJSONAtomico(HIST_FILE, arr || []); } catch (err) { /* ignora */ }
}

// ----- Logs de acesso (quem logou e quando) -----
// Trilha separada do histórico de dados: registra cada tentativa de login.
// `evento`: 'entrou' (sucesso) | 'falhou' (senha/usuário errado) | 'bloqueado' (recusado/pendente).
const LOGIN_LOGS_MAX = 1000; // mantém só os mais recentes (igual ao histórico)
function lerLoginLogs() {
  if (USE_MONGO) return mem.loginlogs || [];
  try {
    const arr = JSON.parse(fs.readFileSync(LOGIN_LOGS_FILE, 'utf-8'));
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}
// Best-effort: uma falha aqui nunca deve atrapalhar o login. Engole o próprio erro.
async function registrarLogin(req, evento, dados) {
  try {
    const entrada = {
      id: gerarId('L'), ts: Date.now(), evento,
      usuario: (dados && dados.usuario) || '',
      nome: (dados && dados.nome) || '',
      ip: ipDe(req),
      ua: String((req.headers && req.headers['user-agent']) || '').slice(0, 200),
    };
    if (USE_MONGO) {
      mem.loginlogs = (mem.loginlogs || []).concat(entrada).slice(-LOGIN_LOGS_MAX);
      if (mongoCol) await mongoCol.updateOne({ _id: 'loginlogs' }, { $push: { logs: { $each: [entrada], $slice: -LOGIN_LOGS_MAX } } }, { upsert: true });
      return;
    }
    const logs = lerLoginLogs();
    logs.push(entrada);
    escreverJSONAtomico(LOGIN_LOGS_FILE, logs.slice(-LOGIN_LOGS_MAX));
  } catch (err) { /* ignora — trilha de acesso é secundária */ }
}

// ----- Trilha de auditoria de segurança (mais ampla que os logs de acesso) -----
// Registra AÇÕES SENSÍVEIS: mudança de permissões/nível, aprovação/recusa/exclusão de
// usuário, troca de senha, download de backup, exportações sensíveis, exclusões em massa,
// e tentativas de acesso negadas (401/403). NUNCA grava senha, token, cookie, URI do Mongo
// nem PII completa — apenas o necessário, com PII mascarada via mascararPII().
const SEG_LOGS_MAX = 2000;
function lerSegLogs() {
  if (USE_MONGO) return mem.seglogs || [];
  try {
    const arr = JSON.parse(fs.readFileSync(SEG_LOGS_FILE, 'utf-8'));
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}
// Mascara PII deixando só os últimos `visiveis` caracteres (ex.: CPF/RG/usuário-alvo em logs).
function mascararPII(v, visiveis = 4) {
  const s = String(v == null ? '' : v);
  if (!s) return '';
  if (s.length <= visiveis) return '*'.repeat(s.length);
  return '*'.repeat(Math.min(s.length - visiveis, 8)) + s.slice(-visiveis);
}
// Best-effort: jamais derruba a operação principal. `extra`: { categoria, severidade, area, acao, detalhes, usuarioAlvo }.
async function registrarSeguranca(req, evento, extra = {}) {
  try {
    const u = (req && (req.usuario || usuarioAtual(req))) || null;
    const entrada = {
      id: gerarId('S'), ts: Date.now(), evento,
      categoria: extra.categoria || 'auditoria',
      severidade: extra.severidade || 'info', // info | aviso | alerta
      usuario: (u && u.usuario) || '',
      nome: (u && u.nome) || '',
      ip: req ? ipDe(req) : '',
      ua: req ? String((req.headers && req.headers['user-agent']) || '').slice(0, 200) : '',
      metodo: req ? req.method : '',
      rota: req ? String(req.originalUrl || req.path || '').slice(0, 200) : '',
      area: extra.area || '',
      acao: extra.acao || '',
      alvo: extra.usuarioAlvo || '',
      detalhes: extra.detalhes ? String(extra.detalhes).slice(0, 500) : '',
    };
    if (USE_MONGO) {
      mem.seglogs = (mem.seglogs || []).concat(entrada).slice(-SEG_LOGS_MAX);
      if (mongoCol) await mongoCol.updateOne({ _id: 'seglogs' }, { $push: { logs: { $each: [entrada], $slice: -SEG_LOGS_MAX } } }, { upsert: true });
      return;
    }
    const logs = lerSegLogs();
    logs.push(entrada);
    escreverJSONAtomico(SEG_LOGS_FILE, logs.slice(-SEG_LOGS_MAX));
  } catch (err) { /* trilha é secundária — nunca interrompe a ação */ }
}

