const PASTA_MODELOS_TERMOS_ID = 'TP-MODELOS';
const PASTA_CARROS_TERMOS_ID = 'TP-CARROS';
function idPastaTermoLegada(nivel, chave) {
  return 'TP-' + crypto.createHash('sha256').update(`${nivel}\0${chave}`).digest('hex').slice(0, 18);
}
function migrarEstruturaTermosMultas(termosBrutos, pastasBrutas) {
  const termos = Array.isArray(termosBrutos) ? termosBrutos.map(t => ({ ...t })) : [];
  if (Array.isArray(pastasBrutas)) {
    const pastas = pastasBrutas
      .map(p => ({
        id: String(p && p.id || '').trim().slice(0, 80),
        nome: String(p && p.nome || '').trim().slice(0, 100),
        pastaPaiId: String(p && p.pastaPaiId || '').trim().slice(0, 80),
        criadoEm: Number(p && p.criadoEm) || 0,
        atualizadoEm: Number(p && p.atualizadoEm) || 0,
        atualizadoPor: String(p && p.atualizadoPor || '').trim().slice(0, 120),
      }))
      .filter(p => p.id && p.nome);
    const ids = new Set(pastas.map(p => p.id));
    for (const p of pastas) if (p.pastaPaiId === p.id || !ids.has(p.pastaPaiId)) p.pastaPaiId = '';
    const porId = new Map(pastas.map(p => [p.id, p]));
    for (const p of pastas) {
      const visitadas = new Set([p.id]);
      let pai = p.pastaPaiId;
      while (pai) {
        if (visitadas.has(pai)) { p.pastaPaiId = ''; break; }
        visitadas.add(pai);
        pai = porId.get(pai)?.pastaPaiId || '';
      }
    }
    for (const t of termos) t.pastaId = ids.has(String(t.pastaId || '')) ? String(t.pastaId) : '';
    return { termos, pastas };
  }

  // Migração limpa da hierarquia virtual anterior para pastas reais e movíveis.
  const pastas = [
    { id: PASTA_MODELOS_TERMOS_ID, nome: 'Modelos prontos', pastaPaiId: '', criadoEm: 0, atualizadoEm: 0, atualizadoPor: '' },
    { id: PASTA_CARROS_TERMOS_ID, nome: 'Carros', pastaPaiId: '', criadoEm: 0, atualizadoEm: 0, atualizadoPor: '' },
  ];
  const ids = new Set(pastas.map(p => p.id));
  const criarLegada = (id, nome, pastaPaiId) => {
    if (!ids.has(id)) { ids.add(id); pastas.push({ id, nome, pastaPaiId, criadoEm: 0, atualizadoEm: 0, atualizadoPor: '' }); }
    return id;
  };
  for (const t of termos) {
    if (t.tipo === 'modelo') { t.pastaId = PASTA_MODELOS_TERMOS_ID; continue; }
    const placa = String(t.placa || 'Sem veículo').trim() || 'Sem veículo';
    const motorista = String(t.motorista || 'Sem motorista').trim() || 'Sem motorista';
    const placaId = criarLegada(idPastaTermoLegada('placa', placa.toLocaleLowerCase('pt-BR')), placa, PASTA_CARROS_TERMOS_ID);
    t.pastaId = criarLegada(idPastaTermoLegada('motorista', `${placaId}\0${motorista.toLocaleLowerCase('pt-BR')}`), motorista, placaId);
  }
  return { termos, pastas };
}
function lerEstruturaTermosMultas() {
  if (USE_MONGO) return migrarEstruturaTermosMultas(mem.termosMultas, mem.pastasTermosMultas);
  try {
    const o = JSON.parse(fs.readFileSync(TERMOS_MULTAS_FILE, 'utf-8'));
    return migrarEstruturaTermosMultas(o.termos, o.pastas);
  } catch (e) { return migrarEstruturaTermosMultas([], undefined); }
}
function lerTermosMultas() { return lerEstruturaTermosMultas().termos; }
function lerPastasTermosMultas() { return lerEstruturaTermosMultas().pastas; }
async function salvarEstruturaTermosMultas(termos, pastas) {
  const estrutura = migrarEstruturaTermosMultas(termos, Array.isArray(pastas) ? pastas : []);
  if (USE_MONGO) {
    mem.termosMultas = estrutura.termos;
    mem.pastasTermosMultas = estrutura.pastas;
    await persistMongo('termosMultas', estrutura);
  } else escreverJSONAtomico(TERMOS_MULTAS_FILE, estrutura);
  notificarDados('termosMultas');
}
async function salvarTermosMultas(termos) { await salvarEstruturaTermosMultas(termos, lerPastasTermosMultas()); }
async function salvarPastasTermosMultas(pastas) { await salvarEstruturaTermosMultas(lerTermosMultas(), pastas); }
function normalizarTermoMulta(t, anterior = {}) {
  const s = (v, max) => String(v == null ? '' : v).trim().slice(0, max);
  const tipo = (t.tipo || anterior.tipo) === 'modelo' ? 'modelo' : 'assinado';
  const a = t.arquivo && t.arquivo.id ? t.arquivo : anterior.arquivo;
  return {
    id: s(anterior.id || t.id, 80) || gerarId('TM-'),
    ts: Number(anterior.ts || t.ts) || Date.now(),
    tipo,
    pastaId: s(t.pastaId !== undefined ? t.pastaId : anterior.pastaId, 80),
    placa: tipo === 'assinado' ? s(t.placa || anterior.placa, 10).toUpperCase() : '',
    motorista: tipo === 'assinado' ? s(t.motorista || anterior.motorista, 120) : '',
    titulo: s(t.titulo, 160),
    descricao: s(t.descricao, 1200),
    arquivo: a && a.id ? { id: s(a.id, 80), nome: s(a.nome, 160), tipo: s(a.tipo, 120) } : null,
    atualizadoEm: Date.now(),
    atualizadoPor: s(t.atualizadoPor || anterior.atualizadoPor, 120),
  };
}
const ROTULO_MULTA = {
  placa: 'Placa', responsavel: 'Responsável', autoInfracao: 'Nº Auto', descricao: 'Descrição',
  dataInfracao: 'Data Infração', horaInfracao: 'Hora', local: 'Local', cidadeEstado: 'Cidade/UF',
  codigoInfracao: 'Código da infração', orgaoAutuador: 'Órgão autuador', dataNotificacao: 'Data da notificação',
  valor: 'Valor', situacao: 'Situação', formaPagamento: 'Forma Pgto',
  dataVencimento: 'Vencimento', dataPagamento: 'Pagamento', observacao: 'Observação',
  detranIdentificarOk: 'Detran: Identificar', detranIdentificarData: 'Detran: Identificar (data)', detranIdentificarObs: 'Detran: Identificar (obs)',
  detranTermoEnviadoOk: 'Detran: Termo Enviado', detranTermoEnviadoData: 'Detran: Termo Enviado (data)', detranTermoEnviadoObs: 'Detran: Termo Enviado (obs)',
  detranTermoAssinadoOk: 'Detran: Termo Assinado', detranTermoAssinadoData: 'Detran: Termo Assinado (data)', detranTermoAssinadoObs: 'Detran: Termo Assinado (obs)',
  detranPedidoDescontoOk: 'Detran: Pedido de Desconto', detranPedidoDescontoData: 'Detran: Pedido de Desconto (data)', detranPedidoDescontoObs: 'Detran: Pedido de Desconto (obs)',
};
// Gera entradas de histórico para cada campo alterado da multa (aparece no histórico da placa)
function diffMulta(antes, depois) {
  const entradas = [];
  const ref = depois.autoInfracao || 's/ nº';
  for (const campo of Object.keys(ROTULO_MULTA)) {
    const a = antes[campo], b = depois[campo];
    if (String(a ?? '') !== String(b ?? '')) {
      const fmt = (x) => {
        if (typeof x === 'boolean') return x ? 'Sim' : 'Não';
        if (x === '' || x === null || x === undefined) return '(vazio)';
        return campo === 'valor' ? 'R$ ' + (Number(x) || 0).toLocaleString('pt-BR') : String(x);
      };
      entradas.push({ placa: depois.placa, acao: 'editou', texto: `Multa ${ref}; ${ROTULO_MULTA[campo]}: ${fmt(a)} → ${fmt(b)}` });
    }
  }
  // Anexos: o laço acima só compara campos de texto (ROTULO_MULTA), então a lista de arquivos
  // precisa do seu próprio diff — senão anexar/remover um documento não deixava rastro nenhum no
  // histórico da placa. Comparamos contra TODOS os ids de cada lado (idsMidiaDoc inclui as versões
  // anteriores): assim SUBSTITUIR um arquivo registra só o "anexou" — o antigo continua guardado
  // no histórico do próprio anexo, não foi removido.
  const rotuloDoc = (d) => (d && (d.nome || d.nomeOriginal)) || 'arquivo';
  const docsDe = (l) => (Array.isArray(l) ? l : []).filter(d => d && d.id);
  const todosIds = (l) => new Set(docsDe(l).flatMap(idsMidiaDoc));
  const idsAntes = todosIds(antes.documentos), idsDepois = todosIds(depois.documentos);
  const anexados = docsDe(depois.documentos).filter(d => !idsAntes.has(d.id)).map(rotuloDoc);
  const removidos = docsDe(antes.documentos).filter(d => !idsDepois.has(d.id)).map(rotuloDoc);
  if (anexados.length) entradas.push({ placa: depois.placa, acao: 'editou', texto: `Multa ${ref} · anexou: ${anexados.join(', ')}` });
  if (removidos.length) entradas.push({ placa: depois.placa, acao: 'editou', texto: `Multa ${ref}; removeu anexo: ${removidos.join(', ')}` });
  return entradas;
}

// ----- Rastreadores -----
// USO: contextoVinculosRast() => {origem:'planilha',por:'João'} durante uma importação.
function contextoVinculosRast() {
  const req = VINCULOS_CONTEXTO.getStore();
  const rota = req && req.path || '';
  const origem = rota.includes('/cobli/') ? 'cobli' : rota.includes('/importar/') ? 'planilha'
    : rota.includes('/desfazer/') ? 'desfazer' : rota.includes('/restaurar') ? 'restauracao'
      : rota.includes('/instalacoes') ? 'instalacoes' : 'manual';
  return { origem, por: req ? quemFez(req) : '' };
}
// USO: lerRastVinculos() => [{id:'RV…',rastreadorId:'R1',tipo:'transferencia',…}].
function lerRastVinculos() {
  if (USE_MONGO) return mem.rastreadoresVinculos || [];
  return seedRastVinculos();
}
// USO: await salvarRastVinculos(eventos) — restaura a coleção própria, incluindo as fotos referenciadas.
async function salvarRastVinculos(eventos) {
  if (USE_MONGO) {
    await persistMongo('rastreadoresVinculos', { eventos });
    mem.rastreadoresVinculos = eventos;
  } else escreverJSONAtomico(RAST_VINCULOS_FILE, { eventos });
  notificarDados('rastreadores');
}
let filaVinculosRast = Promise.resolve();
// USO: await registrarVinculosRast([evento]) — acrescenta uma única vez por id, sem limite de 1.000.
// A fila serializa acréscimos dentro deste processo, inclusive em JSON local.
function registrarVinculosRast(eventos) {
  if (!eventos.length) return Promise.resolve();
  const grava = filaVinculosRast.then(async () => {
    const atuais = lerRastVinculos(), ids = new Set(atuais.map(e => e.id));
    const novos = eventos.filter(e => !ids.has(e.id) && ids.add(e.id));
    if (novos.length) await salvarRastVinculos(atuais.concat(novos));
  });
  filaVinculosRast = grava.catch(() => {});
  return grava;
}
function lerRastreadores() {
  if (USE_MONGO) return structuredClone(mem.rastreadores || []);
  try {
    const obj = JSON.parse(fs.readFileSync(RAST_FILE, 'utf-8'));
    return Array.isArray(obj.rastreadores) ? obj.rastreadores : [];
  } catch (e) { return []; }
}
async function salvarRastreadores(arr, opcoes = {}) {
  const rastreadores = arr || [];
  const antes = lerRastreadores(), hist = lerRastVinculos(), inst = lerInstalacoes();
  const eventos = opcoes.registrar === false ? [] : [
    ...vinculosRast.recuperarLegado(antes, inst, hist),
    ...vinculosRast.eventosDeRastreadores(antes, rastreadores, contextoVinculosRast()),
  ];
  if (USE_MONGO) {
    mem.rastreadores = rastreadores;
    await persistMongo('rastreadores', { rastreadores });
  } else {
    escreverJSONAtomico(RAST_FILE, { rastreadores });
  }
  if (opcoes.registrar !== false) {
    eventos.push(...vinculosRast.recuperarLegado(rastreadores, inst, hist.concat(eventos)));
    await registrarVinculosRast(eventos);
  }
  notificarDados('rastreadores');
}

// ----- Instalações (registro fotográfico das instalações em campo) -----
function lerInstalacoes() {
  if (USE_MONGO) return structuredClone(mem.instalacoes || []);
  try {
    const obj = JSON.parse(fs.readFileSync(INST_FILE, 'utf-8'));
    return Array.isArray(obj.instalacoes) ? obj.instalacoes : [];
  } catch (e) { return []; }
}
// Opções:
//   registrar:false → não gera eventos de vínculo (restore de backup, recuperarVinculosLegados);
//                     ainda re-resolve o rastreadorId (vazio casa pelo Nº de série).
//   exato:true      → grava cada rastreadorId COMO VEIO (sem re-resolver) e continua gerando os
//                     eventos de vínculo com a origem de contextoVinculosRast() ('desfazer' na
//                     rota /api/desfazer/…). Usado pelo Desfazer, que precisa do snapshot idêntico.
// USO: await salvarInstalacoes(lista)                       // gravação normal (re-resolve + eventos)
//      await salvarInstalacoes(snapshot, { exato: true })   // Desfazer: Z com rastreadorId '' fica ''
//      await salvarInstalacoes(doBackup, { registrar: false })
async function salvarInstalacoes(arr, opcoes = {}) {
  const instalacoes = arr || [];
  const antes = lerInstalacoes(), rastreadores = lerRastreadores(), hist = lerRastVinculos();
  if (!opcoes.exato) for (const i of instalacoes) {
    const anterior = antes.find(a => a.id === i.id);
    // O id vem da associação existente ou de correspondência única, nunca de um id livre no body.
    const preservado = anterior && anterior.numeroSerie === i.numeroSerie ? anterior.rastreadorId : '';
    const alvo = vinculosRast.resolverRastreador({ ...i, rastreadorId: opcoes.registrar === false ? i.rastreadorId : preservado }, rastreadores, hist);
    i.rastreadorId = alvo ? alvo.id : '';
  }
  const eventos = opcoes.registrar === false ? [] : [
    ...vinculosRast.recuperarLegado(rastreadores, antes, hist),
    ...vinculosRast.eventosDeInstalacoes(antes, instalacoes, rastreadores, hist, contextoVinculosRast()),
  ];
  if (USE_MONGO) {
    mem.instalacoes = instalacoes;
    await persistMongo('instalacoes', { instalacoes });
  } else {
    escreverJSONAtomico(INST_FILE, { instalacoes });
  }
  await registrarVinculosRast(eventos);
  notificarDados('instalacoes');
}

