const numOuVazio = (x) => { const n = Number(x); return Number.isFinite(n) ? n : (x === 0 ? 0 : ''); };
function formatarParcelaContrato(valor) {
  const texto = String(valor ?? '').trim();
  const m = texto.match(/(\d+)\s*\/\s*(\d+)/);
  if (!m) return texto;
  const numero = Number(m[1]), total = Number(m[2]);
  if (!Number.isInteger(numero) || !Number.isInteger(total) || numero < 1 || total < 1 || numero > total) return texto;
  const largura = Math.max(2, String(total).length);
  return `${String(numero).padStart(largura, '0')}/${String(total).padStart(largura, '0')}`;
}
function somarMesesContratoBR(dataBR, meses) {
  const m = String(dataBR || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (!m) return '';
  const dia = Number(m[1]), mes = Number(m[2]) - 1;
  let ano = Number(m[3]); if (ano < 100) ano += 2000;
  const d = new Date(ano, mes + meses, 1);
  const ultimoDia = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  d.setDate(Math.min(dia, ultimoDia));
  return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}
// ÂNCORA DA SÉRIE — regra ÚNICA de data, válida nos DOIS caminhos que geram parcela
// (o "Completar série" do modal, em frontend/app.js, e o /api/contratos/completar-series):
//
//     vencimento(k) = vencimentoAncora + (k − numeroAncora) meses
//
// PRIMÁRIA: o campo **Vencimento** da parcela âncora — no modal, a parcela que está sendo
// editada; no completar-series, a parcela EXISTENTE mais próxima ABAIXO do número faltante
// (sem nenhuma abaixo, a mais próxima ACIMA).
// FALLBACK: **Início das parcelas** é o vencimento DECLARADO da parcela 01 — só entra quando
// o Vencimento está vazio, e então numeroAncora = 1 (não o número da linha).
// Cada parcela é calculada A PARTIR da âncora, nunca em cascata mês a mês: o clamp de fim de
// mês (31/01 → 28/02 → 31/03) não acumula erro.
// Quando os DOIS campos existem e discordam (Início + (n−1) meses ≠ Vencimento), o gerador
// AVISA e não corrige nada — ver divergenciaAncoraContrato.
const contratoPagoDados = (c) => (Number(c && c.valorPago) > 0) || !!(c && c.dataPagamento && String(c.dataPagamento).trim());
// Confere a coerência dos dois campos de data da MESMA linha. Devolve '' quando batem (ou
// quando falta um deles) e o texto do aviso quando discordam. NUNCA corrige: a discordância
// pode ser legítima (carência que empurrou a 1ª parcela) e a escolha é do usuário.
// Ex.: divergenciaAncoraContrato({parcela:'01/20', inicioParcelas:'15/12/2025', vencimento:'21/01/2026'})
//      → '01/20: "Início das parcelas" 15/12/2025 + 0 mês(es) = 15/12/2025, mas o Vencimento gravado é 21/01/2026'
function divergenciaAncoraContrato(c) {
  const venc = String((c && c.vencimento) || '').trim();
  const inicio = String((c && c.inicioParcelas) || '').trim();
  const m = String((c && c.parcela) || '').match(/(\d+)\s*\/\s*(\d+)/);
  if (!venc || !inicio || !m) return '';
  const meses = Number(m[1]) - 1;
  const esperado = somarMesesContratoBR(inicio, meses);
  if (!esperado || esperado === venc) return '';
  return `${c.parcela}: "Início das parcelas" ${inicio} + ${meses} mês(es) = ${esperado}, mas o Vencimento gravado é ${venc}`;
}
// CADÊNCIA da série: as parcelas JÁ CADASTRADAS batem entre si pela mesma âncora? `itens` são
// { numero, contrato } com vencimento; a referência é a de MENOR número. Devolve '' quando a
// série é regular e o texto do aviso quando não é.
// Só desvio de MÊS conta. Dia diferente no mesmo mês é ajuste normal de data bancária (fim de
// semana/feriado) e viraria aviso de rotina — o que o gerador precisa denunciar é a série
// deslocada, o caso em que o "Completar série" antigo ancorava numa parcela e o resto em outra.
// Ex.: 01/20 = 15/12/2025 e 05/20 = 21/05/2026 (o esperado seria 15/04/2026) → aviso.
//      01/20 = 15/12/2025 e 02/20 = 16/01/2026 → '' (só o dia mudou).
function cadenciaIrregularContrato(itens) {
  const comData = (itens || []).filter(x => x.contrato && String(x.contrato.vencimento || '').trim()).sort((a, b) => a.numero - b.numero);
  if (comData.length < 2) return '';
  const ref = comData[0];
  const mesAno = (s) => String(s || '').slice(3);
  const fora = comData.slice(1).filter(x => {
    const esperado = somarMesesContratoBR(ref.contrato.vencimento, x.numero - ref.numero);
    return esperado && mesAno(esperado) !== mesAno(x.contrato.vencimento);
  });
  if (!fora.length) return '';
  const p = fora[0];
  const esperado = somarMesesContratoBR(ref.contrato.vencimento, p.numero - ref.numero);
  return `cadência irregular: com a âncora ${ref.contrato.parcela} = ${ref.contrato.vencimento}, a ${p.contrato.parcela} deveria vencer em ${esperado} e está em ${p.contrato.vencimento}`
    + (fora.length > 1 ? ` (e mais ${fora.length - 1} parcela(s) fora do mês)` : '');
}
// Regra ÚNICA de parcela atrasada (espelho de contrAtrasado no frontend/app.js — mudou aqui,
// muda lá): não paga E vencimento ANTES do início do dia de hoje. Vencer HOJE ainda não é
// atraso. O parse é de calendário LOCAL (dd/mm/aaaa → new Date(ano, mes-1, dia)) de propósito:
// ISO/UTC deslocaria o vencimento em um dia conforme o fuso.
// Ex.: hoje 28/08/2026 → contratoAtrasadoDados({vencimento:'27/08/2026'}) = true e
//      diasAtrasoContrato(...) = 1; vencimento '28/08/2026' → false / 0.
const dataBRContrato = (s) => { const m = String(s || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/); if (!m) return null; const d = new Date(+m[3], +m[2] - 1, +m[1]); return (d.getDate() === +m[1] && d.getMonth() === +m[2] - 1) ? d : null; };
const inicioHojeContrato = () => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; };
const contratoAtrasadoDados = (c) => { if (contratoPagoDados(c)) return false; const v = dataBRContrato(c && c.vencimento); return !!v && v < inicioHojeContrato(); };
// Marco COERENTE de parcelas pagas de uma série ("watermark"), regra ÚNICA usada pelo
// completar-series, pelo Gerar série do form (espelho de mesmo nome no app.js) e pelo
// scripts/corrigir-series-contratos.js. A maior evidência declarada (parcelasPagas gravado —
// que pode vir da heurística "cadastrei a parcela atual N ⇒ N−1 pagas" do normalizarContrato)
// só vale até a menor parcela EXISTENTE em aberto: uma parcela aberta na frente refuta a
// declaração de uma parcela posterior. Foi a falta desse teto que fez o Completar série gravar
// 3/77 em 76 parcelas da série do exemplo: a 04/80 aberta "declarava" 3 pagas, mas a 03/80
// aberta provava que só havia 2.
// Ex.: pagasAteCoerente([{numero:1,pago:true},{numero:2,pago:true},{numero:3,pago:false,parcelasPagas:2},{numero:4,pago:false,parcelasPagas:3}]) === 2
//      pagasAteCoerente([{numero:5,pago:false,parcelasPagas:4}]) === 4  // só a parcela atual cadastrada → backfill (CT-3)
//      pagasAteCoerente([{numero:1,pago:true},{numero:2,pago:true}], 2) === 2  // nenhuma aberta
//      pagasAteCoerente([{numero:4,pago:false,parcelasPagas:99}], 80) === 3    // declaração nunca passa da aberta nem do total
function pagasAteCoerente(itens, total) {
  let maiorEvidencia = 0;     // maior evidência por linha (declarada ou inferida)
  let menorAberta = Infinity; // menor nº de parcela EXISTENTE e em aberto
  for (const it of itens || []) {
    if (!Number.isInteger(it.numero) || it.numero < 1) continue;
    if (!it.pago) menorAberta = Math.min(menorAberta, it.numero);
    // Evidência da linha: parcelasPagas EXPLÍCITO tem precedência (0 é declaração válida —
    // "0 pagas" ≠ campo vazio); sem declaração, inferência estrutural: paga ⇒ nº, aberta ⇒ nº−1
    // (a antiga heurística do normalizador, agora refutável pela menor aberta abaixo).
    const declarado = Number(it.parcelasPagas);
    const declarou = it.parcelasPagas !== '' && it.parcelasPagas !== null && it.parcelasPagas !== undefined
      && Number.isFinite(declarado) && declarado >= 0;
    maiorEvidencia = Math.max(maiorEvidencia, declarou ? declarado : (it.pago ? it.numero : it.numero - 1));
  }
  const teto = Number(total); // clamp: declaração corrompida (> total) não pode inflar o marco
  if (Number.isFinite(teto) && teto >= 1) maiorEvidencia = Math.min(maiorEvidencia, teto);
  if (!Number.isFinite(menorAberta)) return maiorEvidencia;      // nenhuma aberta (ou todas pagas)
  return Math.max(0, Math.min(maiorEvidencia, menorAberta - 1)); // aberta existente refuta a evidência
}
const diasAtrasoContrato = (c) => (contratoAtrasadoDados(c) ? Math.round((inicioHojeContrato() - dataBRContrato(c.vencimento)) / 86400000) : 0);
function normalizarContrato(c) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  // "N/M" no campo Parcela = número deste lançamento / total da série. O form não pede
  // mais "Total/Pagas/Faltantes"; quando ausentes, o status deste lançamento define se N já foi pago.
  const vazio = (x) => x === undefined || x === null || String(x).trim() === '';
  const mp = s(c.parcela).match(/(\d+)\s*\/\s*(\d+)/);
  const pNum = mp ? +mp[1] : null, pTot = mp ? +mp[2] : null;
  const total = vazio(c.totalParcelas) ? (pTot ?? '') : numOuVazio(c.totalParcelas);
  // NÃO fabricar mais estado da série a partir de UMA linha (a heurística antiga "aberta N/M ⇒
  // N−1 pagas" nasceu aqui e foi a origem do bug 3/77): preserva só o que veio explícito
  // (0 é declaração válida) e deixa vazio quando não informado. A inferência coerente vive em
  // pagasAteCoerente, que enxerga a série INTEIRA (tela, export, Completar/Gerar série).
  // ⚠ O guard vazio() é OBRIGATÓRIO antes de numOuVazio: Number('') === 0, então sem ele todo
  // campo vazio viraria "0 EXPLÍCITO" (declaração válida de zero pagas) e mataria o backfill.
  const pagas = vazio(c.parcelasPagas) ? '' : numOuVazio(c.parcelasPagas);
  const faltantes = vazio(c.parcelasFaltantes)
    ? ((pTot != null && pagas !== '') ? Math.max(0, pTot - Number(pagas)) : '')
    : numOuVazio(c.parcelasFaltantes);
  return {
    id: s(c.id) || gerarId('C'),
    ts: Number(c.ts) || Date.now(),
    serieId: s(c.serieId),
    dataEmissao: fmtDataBR(c.dataEmissao),
    fornecedor: s(c.fornecedor),
    banco: s(c.banco),
    produto: s(c.produto),
    grupo: s(c.grupo),
    cota: s(c.cota),
    material: s(c.material),
    empresa: s(c.empresa).toUpperCase(),
    localCarro: s(c.localCarro),
    parcela: formatarParcelaContrato(c.parcela),
    totalParcelas: total,
    parcelasPagas: pagas,
    parcelasFaltantes: faltantes,
    valorParcela: numOuVazio(c.valorParcela),
    saldoQuitacao: numOuVazio(c.saldoQuitacao),
    descontoQuitacao: s(c.descontoQuitacao),
    descontoQuitacaoRS: numOuVazio(c.descontoQuitacaoRS),
    carencia: numOuVazio(c.carencia),
    inicioParcelas: fmtDataBR(c.inicioParcelas),
    vencimento: fmtDataBR(c.vencimento),
    dataPagamento: fmtDataBR(c.dataPagamento),
    escritorio: s(c.escritorio),
    valorPago: numOuVazio(c.valorPago),
    conta: s(c.conta),
    naJustica: !!c.naJustica,
  };
}
function chaveSerieLegadaContrato(c) {
  const texto = (x) => String(x || '').trim().replace(/\s+/g, ' ').toUpperCase();
  const grupo = texto(c.grupo), cota = texto(c.cota);
  const identidade = grupo && cota ? ['GRUPO_COTA', grupo, cota] : ['DESCRICAO', texto(c.material)];
  return [texto(c.empresa), texto(c.banco), texto(c.produto), ...identidade].join('|');
}
function chaveSerieContrato(c) {
  const serieId = String(c.serieId || '').trim();
  return serieId ? `ID|${serieId}` : `LEGADO|${chaveSerieLegadaContrato(c)}`;
}
function garantirIdsSeriesContrato(lista) {
  const idsPorChave = new Map();
  for (const c of lista) if (c.serieId) idsPorChave.set(chaveSerieLegadaContrato(c), String(c.serieId));
  let atribuidos = 0;
  for (const c of lista) {
    if (c.serieId) continue;
    const chave = chaveSerieLegadaContrato(c);
    c.serieId = idsPorChave.get(chave) || gerarId('CS');
    idsPorChave.set(chave, c.serieId);
    atribuidos++;
  }
  return atribuidos;
}
function resolverSerieIdContrato(c, lista) {
  if (c.serieId) return String(c.serieId);
  const exata = lista.find(x => chaveSerieLegadaContrato(x) === chaveSerieLegadaContrato(c));
  if (exata) return exata.serieId;
  const texto = (x) => String(x || '').trim().replace(/\s+/g, ' ').toUpperCase();
  const grupo = texto(c.grupo), cota = texto(c.cota);
  if (grupo && cota) {
    const ids = new Set(lista.filter(x =>
      texto(x.empresa) === texto(c.empresa) && texto(x.banco) === texto(c.banco)
      && texto(x.produto) === texto(c.produto) && texto(x.grupo) === grupo && texto(x.cota) === cota
    ).map(x => x.serieId).filter(Boolean));
    if (ids.size === 1) return [...ids][0];
  }
  return gerarId('CS');
}
function chaveParcelaContrato(c) {
  const p = String(c.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
  return p ? `${chaveSerieContrato(c)}|${+p[1]}/${+p[2]}` : '';
}
