// Apelidos / primeiros nomes / variações de grafia de motorista → nome completo do cadastro
// (planilhas de motoristas por empresa). Aplicado na normalização (import + edição). A CHAVE é comparada
// SEM acento e em MAIÚSCULAS (ver canonizarMotorista), então escreva as chaves em ASCII maiúsculo.
// Origem dos vínculos: nome completo único no cadastro, e/ou confirmado pela placa que a pessoa dirige
// nos abastecimentos. Casos com mais de um homônimo no cadastro estão comentados como (inferido).
const ALIAS_MOTORISTA = {
  'MATRICULA RESERVA': 'Caio Ferrer de Andrade', // placeholder de veículo reserva
  'ADRIANO': 'Adriano Coelho Vasques',
  'BEATRIZ': 'Beatriz Salgado Furtado',
  'CAIO': 'Caio Ferrer de Andrade',
  'CAIO FERRER': 'Caio Ferrer de Andrade',
  'EDUARDO': 'Eduardo Tavares Bittencourt',            // (inferido) único cujo 1º nome é Eduardo
  'EDUARDO TAVARES BITENCOURT': 'Eduardo Tavares Bittencourt', // corrige grafia (BITENCOURT → BITTENCOURT)
  'ICARO': 'Ícaro Bastos Ferrugem',
  'KLEBER': 'Kleber Antunes Sampaio',
  'NATALIA': 'Natália Werneck Guimarães',
};
function canonizarMotorista(nome) {
  const limpo = String(nome == null ? '' : nome).trim().replace(/\s+/g, ' ');
  const chave = limpo.normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase(); // casa sem acento (ex.: "Fábio", "Antônio")
  return ALIAS_MOTORISTA[chave] || limpo;
}
// Variações de grafia de centro de custo → nome canônico exibido no site (mesma ideia do
// ALIAS_MOTORISTA: aplicado na normalização, então import + edição convergem sozinhos).
// Chaves em ASCII maiúsculo (a comparação remove acento e sobe caixa).
const ALIAS_CENTRO_CUSTO = {
  'CAMPINA GRANDE': 'C.G',                          // pedido do usuário (jul/2026): exibir só "C.G"
  'REISOLAMENTO CAMPINA GRANDE': 'REISOLAMENTO C.G',
};
function canonizarCentroCusto(nome) {
  const limpo = String(nome == null ? '' : nome).trim().replace(/\s+/g, ' ');
  const chave = limpo.normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
  return ALIAS_CENTRO_CUSTO[chave] || limpo;
}
function normalizarAbastecimento(t) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const num = (x) => { const n = custoNum(x); return Number.isFinite(n) ? n : 0; }; // custoNum preserva o sinal (km negativo = alerta)
  const alertaBruto = s(t.alerta).toUpperCase();
  return {
    id: s(t.id) || gerarId('A'),
    ts: Number(t.ts) || Date.now(),
    dataHora: serialExcelDataHoraParaBR(t.dataHora), // converte serial do Excel; texto BR passa intacto

    placa: s(t.placa).toUpperCase(),
    modelo: s(t.modelo),
    ano: s(t.ano),
    motorista: canonizarMotorista(t.motorista),
    centroCusto: canonizarCentroCusto(t.centroCusto),
    posto: s(t.posto),
    cidade: s(t.cidade),
    uf: s(t.uf).toUpperCase().slice(0, 2),
    combustivel: s(t.combustivel),
    litros: num(t.litros),
    precoLitro: num(t.precoLitro),
    odometro: num(t.odometro),
    kmL: num(t.kmL),
    kmRod: num(t.kmRod),
    valor: num(t.valor),
    statusKmL: s(t.statusKmL),
    statusPreco: s(t.statusPreco),
    alerta: typeof t.alerta === 'boolean' ? t.alerta : (alertaBruto === 'SIM' || alertaBruto === 'TRUE' || alertaBruto === '1'),
    motivos: s(t.motivos),
  };
}

