// ----- Admissões (formulário público por link/token) -----
// Cada registro é um CONVITE que pode virar uma RESPOSTA. O destinatário abre o link
// (/admissao/<token>) sem login, preenche e envia. O RH revisa e aplica ao cadastro.
const ADMISSAO_VALIDADE_PADRAO_DIAS = 7;
const STATUS_ADMISSAO = ['aguardando', 'preenchido', 'aplicado', 'cancelado'];
// Trilha de autoria do convite: quem gerou o link, quem gerou de novo, quando o candidato
// enviou e quem aplicou ao cadastro. Precisam vir ANTES de `normalizarAdmissao` (const não sofre
// hoisting). O cap existe porque `persistMongo` grava o doc inteiro — 40 × ~90 B por convite é
// irrelevante contra os 16 MB/doc, e um convite normal tem 3 a 5 eventos.
const ADMISSAO_EVENTOS_MAX = 40;
const ACOES_ADMISSAO = ['criado', 'regerado', 'preenchido', 'aplicado'];
const ORDEM_ACAO_ADM = { criado: 0, regerado: 1, preenchido: 2, aplicado: 3 }; // desempate de ts igual
function lerAdmissoes() {
  if (USE_MONGO) return mem.admissoes || [];
  try { const o = JSON.parse(fs.readFileSync(ADMISSAO_FILE, 'utf-8')); return Array.isArray(o.admissoes) ? o.admissoes : []; }
  catch (e) { return []; }
}
async function salvarAdmissoes(arr) {
  const admissoes = (arr || []).map(normalizarAdmissao);
  if (USE_MONGO) { mem.admissoes = admissoes; await persistMongo('admissoes', { admissoes }); }
  else { escreverJSONAtomico(ADMISSAO_FILE, { admissoes }); }
  notificarDados('admissao');
  return admissoes;
}
function seedAdmissoes() {
  try { const o = JSON.parse(fs.readFileSync(ADMISSAO_FILE, 'utf-8')); return Array.isArray(o.admissoes) ? o.admissoes : []; }
  catch (e) { return []; }
}
// Token opaco e imprevisível para compor a URL pública (32 hex = 128 bits).
function gerarTokenAdmissao() { return crypto.randomBytes(16).toString('hex'); }
// Status efetivo p/ exibição: 'aguardando' vira 'expirado' depois da validade.
function statusEfetivoAdmissao(a) {
  if (!a) return 'cancelado';
  if (a.status === 'aguardando' && a.validadeTs && Date.now() > a.validadeTs) return 'expirado';
  return a.status;
}
// Um link só aceita preenchimento se está aguardando E dentro do prazo (uso único + validade).
function admissaoAbertaParaPreencher(a) {
  return !!a && a.status === 'aguardando' && (!a.validadeTs || Date.now() <= a.validadeTs);
}
function normalizarAdmissao(a) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const status = s(a && a.status);
  const docs = Array.isArray(a && a.docs) ? a.docs.map(d => ({
    chave: s(d && d.chave), nome: s(d && d.nome),
    id: s(d && d.id), tipo: s(d && d.tipo), nomeOriginal: s(d && d.nomeOriginal),
  })).filter(d => d.id) : [];
  // Uploads já enviados pelo candidato mas ainda não confirmados no submit (rascunho).
  const docsPendentes = Array.isArray(a && a.docsPendentes) ? a.docsPendentes.map(d => ({
    chave: s(d && d.chave), id: s(d && d.id), nome: s(d && d.nome), tipo: s(d && d.tipo),
  })).filter(d => d.id) : [];
  // Trilha append-only do convite. TEM que estar declarada aqui: `salvarAdmissoes` re-normaliza a
  // lista INTEIRA a cada escrita (inclusive quando o mexido é outro convite), e campo não declarado
  // some sem erro — a mesma pegadinha que obrigou o `docsPendentes` logo acima. Exemplo do formato:
  //   eventos: [{ ts: 1755400000000, acao: 'criado',     quem: 'Juan Balbino', detalhe: 'validade 7 dia(s)' },
  //             { ts: 1755500000000, acao: 'regerado',   quem: 'Maria RH',     detalhe: '7 dia(s) · descartou resposta preenchida' },
  //             { ts: 1755600000000, acao: 'preenchido', quem: '',             detalhe: 'IP 203.0.113.9 · 4 doc(s)' }]
  const eventos = Array.isArray(a && a.eventos) ? a.eventos
    .filter(e => e && ACOES_ADMISSAO.includes(s(e.acao)))
    .map(e => ({ ts: Number(e.ts) || 0, acao: s(e.acao), quem: s(e.quem).slice(0, 60), detalhe: s(e.detalhe).slice(0, 120) }))
    .filter(e => e.ts)
    .slice(-ADMISSAO_EVENTOS_MAX) : [];
  const out = {
    id: s(a && a.id) || gerarId('ADM'),
    token: s(a && a.token) || gerarTokenAdmissao(),
    ts: Number(a && a.ts) || Date.now(),
    funcionarioId: s(a && a.funcionarioId),       // vazio = candidato novo (vira cadastro ao aplicar)
    empresa: ['NTE', 'SUL'].includes(empresaSigla(s(a && a.empresa))) ? empresaSigla(s(a && a.empresa)) : '',
    nome: s(a && a.nome),
    email: s(a && a.email),
    status: STATUS_ADMISSAO.includes(status) ? status : 'aguardando',
    validadeTs: Number(a && a.validadeTs) || 0,
    criadoPor: s(a && a.criadoPor),
    preenchidoTs: Number(a && a.preenchidoTs) || 0,
    ip: s(a && a.ip),
    resposta: (a && a.resposta && typeof a.resposta === 'object') ? a.resposta : null,
    docs,
    aplicadoTs: Number(a && a.aplicadoTs) || 0,
    aplicadoPor: s(a && a.aplicadoPor),
    eventos,
  };
  // Só carrega o rascunho de uploads enquanto o link está aberto (não polui o registro final).
  if (docsPendentes.length) out.docsPendentes = docsPendentes;
  return out;
}

// Acrescenta um evento à trilha do convite. É APPEND-ONLY: nunca reescreve nem apaga os
// anteriores — é isso que faz a regeração preservar a história que os campos soltos perdem
// (`regenerar` zera preenchidoTs/ip/aplicadoTs/aplicadoPor). `quem` é o NOME de quem fez
// (`quemFez(req)`), e fica vazio quando foi o candidato pelo link público (sem login).
//
// USO:
//   registrarEventoAdmissao(a, 'regerado', quemFez(req), '7 dia(s)');
//   registrarEventoAdmissao(a, 'preenchido', '', 'IP 203.0.113.9 · 4 doc(s)');
// RESULTADO:
//   a.eventos → [{ ts: 1755400000000, acao: 'regerado', quem: 'Juan Balbino', detalhe: '7 dia(s)' }]
function registrarEventoAdmissao(a, acao, quem, detalhe) {
  if (!a || !ACOES_ADMISSAO.includes(acao)) return a;
  a.eventos = Array.isArray(a.eventos) ? a.eventos : [];
  a.eventos.push({ ts: Date.now(), acao, quem: String(quem || '').slice(0, 60), detalhe: String(detalhe || '').slice(0, 120) });
  if (a.eventos.length > ADMISSAO_EVENTOS_MAX) a.eventos = a.eventos.slice(-ADMISSAO_EVENTOS_MAX);
  return a;
}

// Linha do tempo COMPLETA do convite — DERIVADA na leitura, NUNCA gravada (mesma régua de
// `situacaoRetiradaAlmox` e `estoqueEpiPorId`). Convite gravado antes desta versão não tem
// `eventos`, e mesmo assim rende trilha: criado/preenchido/aplicado são sintetizados dos carimbos
// que sempre existiram (ts+criadoPor, preenchidoTs+ip, aplicadoTs+aplicadoPor). É por isso que
// não houve script de migração. `regerado` nunca deriva — não tinha onde ficar gravado antes.
//
// USO:
//   trilhaAdmissao({ ts: 1000, criadoPor: 'Juan Balbino', preenchidoTs: 2000, ip: '10.0.0.9' })
//   → [{ ts: 1000, acao: 'criado',     quem: 'Juan Balbino', detalhe: '' },
//      { ts: 2000, acao: 'preenchido', quem: '',             detalhe: 'IP 10.0.0.9' }]
function trilhaAdmissao(a) {
  const gravados = Array.isArray(a && a.eventos) ? a.eventos.filter(e => e && ACOES_ADMISSAO.includes(e.acao)) : [];
  const tem = (acao) => gravados.some(e => e.acao === acao);
  const out = gravados.slice();
  if (!tem('criado') && a && a.ts) out.push({ ts: a.ts, acao: 'criado', quem: String(a.criadoPor || ''), detalhe: '' });
  if (!tem('preenchido') && a && a.preenchidoTs) out.push({ ts: a.preenchidoTs, acao: 'preenchido', quem: '', detalhe: a.ip ? 'IP ' + a.ip : '' });
  if (!tem('aplicado') && a && a.aplicadoTs) out.push({ ts: a.aplicadoTs, acao: 'aplicado', quem: String(a.aplicadoPor || ''), detalhe: '' });
  // Criar o convite e gravar o evento acontecem no mesmo milissegundo em máquina rápida: o
  // desempate por ação impede que o 'criado' apareça depois de um 'regerado' do mesmo ms.
  return out.sort((x, y) => (x.ts - y.ts) || (ORDEM_ACAO_ADM[x.acao] - ORDEM_ACAO_ADM[y.acao]));
}

// Resumo barato da trilha para a LISTA (que é relida em polling e não mostra a trilha inteira).
// USO: resumoTrilhaAdmissao(a) → { regeracoes: 2, regeradoPor: 'Juan Balbino', regeradoTs: 1755500000000 }
function resumoTrilhaAdmissao(a) {
  const regs = trilhaAdmissao(a).filter(e => e.acao === 'regerado');
  const ult = regs[regs.length - 1];
  return { regeracoes: regs.length, regeradoPor: (ult && ult.quem) || '', regeradoTs: (ult && ult.ts) || 0 };
}
// Versão segura para a página PÚBLICA: só o necessário p/ renderizar, sem vazar dados internos.
function admissaoPublica(a) {
  return {
    ok: true,
    status: statusEfetivoAdmissao(a),
    nome: a.nome || '',
    empresa: empresaSigla(empresaDaAdmissao(a)) || 'NTE',
    validadeTs: a.validadeTs || 0,
  };
}
// ---- Proteção de mídia compartilhada entre Admissão e Funcionários ----
// Historicamente o "aplicar" anexava ao funcionário o MESMO id de mídia do convite; qualquer
// exclusão de um dos lados apagava o binário do outro (sintoma real: documento do formulário
// sumia do cadastro — "mídia não encontrada"). Hoje o aplicar DUPLICA o arquivo, mas os
// registros antigos continuam compartilhando ids — estes helpers evitam apagar um arquivo do
// cofre que o outro módulo ainda referencia.
function idsMidiaAdmissoes() {
  const ids = new Set();
  for (const a of lerAdmissoes()) {
    for (const d of [...(a.docs || []), ...(a.docsPendentes || [])]) if (d && d.id) ids.add(d.id);
  }
  return ids;
}
function idsMidiaFuncionarios() {
  const ids = new Set();
  for (const f of lerFuncionarios()) {
    for (const ref of [f.foto, f.ppp, f.asoDemissional, f.fichaEpi]) if (ref && ref.id) ids.add(ref.id);
    for (const d of (f.documentos || [])) for (const mid of idsMidiaDoc(d)) ids.add(mid);
  }
  return ids;
}

// ----- Treinamentos (catálogo: vídeo do Drive + prova com gabarito) -----
// Cada treinamento é uma capacitação (NR06, NR10, ... ou um curso) com um vídeo embutido do
// Google Drive e uma prova de múltipla escolha. O GABARITO (`correta` de cada questão) fica
// SÓ no documento — nunca é exposto nas listagens lidas pelo cliente (só no caminho de edição
// gated por exigeEditar). Mesma régua de persistência dual JSON/Mongo dos demais cadastros.
function lerTreinamentos() {
  if (USE_MONGO) return mem.treinamentos || [];
  try { const o = JSON.parse(fs.readFileSync(TREINAMENTOS_FILE, 'utf-8')); return Array.isArray(o.treinamentos) ? o.treinamentos : []; }
  catch (e) { return []; }
}
async function salvarTreinamentos(arr) {
  const treinamentos = (arr || []).map(normalizarTreinamento);
  if (USE_MONGO) { mem.treinamentos = treinamentos; await persistMongo('treinamentos', { treinamentos }); }
  else { escreverJSONAtomico(TREINAMENTOS_FILE, { treinamentos }); }
  notificarDados('integracao');
  return treinamentos;
}
function seedTreinamentos() {
  try { const o = JSON.parse(fs.readFileSync(TREINAMENTOS_FILE, 'utf-8')); return Array.isArray(o.treinamentos) ? o.treinamentos : []; }
  catch (e) { return []; }
}
// Extrai e valida o FILE_ID do Drive (Pitfall 6): se vier a URL inteira, pega o trecho
// entre /d/ e /view; só aceita o formato canônico (>=20 chars do alfabeto base64url). Se não
// bater, devolve '' (a UI valida antes de enviar; o backend não chuta um ID inválido).
function sanitizarFileId(v) {
  let s = String(v == null ? '' : v).trim();
  if (!s) return '';
  const m = s.match(/\/d\/([A-Za-z0-9_-]+)/); // URL do tipo .../file/d/<ID>/view
  if (m) s = m[1];
  return /^[A-Za-z0-9_-]{20,}$/.test(s) ? s : '';
}
function normalizarTreinamento(t) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const tipo = s(t && t.tipo).toLowerCase() === 'curso' ? 'curso' : 'NR';
  const questoes = Array.isArray(t && t.questoes) ? t.questoes.map((q, qi) => {
    const alternativas = Array.isArray(q && q.alternativas) ? q.alternativas.map((a, ai) => ({
      id: s(a && a.id) || ('alt' + qi + '_' + ai),
      texto: s(a && a.texto).slice(0, 600),
    })).filter(a => a.texto) : [];
    const correta = s(q && q.correta);
    // Mantém `correta` só se aponta para uma alternativa existente (gabarito íntegro).
    const corretaValida = alternativas.some(a => a.id === correta) ? correta : '';
    return {
      id: s(q && q.id) || ('q' + qi + '_' + crypto.randomBytes(3).toString('hex')),
      enunciado: s(q && q.enunciado).slice(0, 1000),
      alternativas,
      correta: corretaValida,
    };
  }).filter(q => q.enunciado && q.alternativas.length >= 2) : [];
  return {
    id: s(t && t.id) || gerarId('TRN'),
    ts: Number(t && t.ts) || Date.now(),
    titulo: s(t && t.titulo).slice(0, 200),
    tipo,
    fileId: sanitizarFileId(t && t.fileId),
    descricao: s(t && t.descricao).slice(0, 4000),
    validadeMeses: Math.max(0, Math.round(Number(t && t.validadeMeses) || 0)), // 0 = sem validade (D-10)
    questoes,
    // Vídeo ENVIADO ao armazenamento (bucket/pasta local) — alternativa ao `fileId` do Drive.
    // Com vídeo, a página pública usa o player travado e ignora o fileId. Chave inválida ou
    // duração fora de 1..14400 s viram null (ver normalizarVideoTreino em backend/videos-treino.js).
    // Ex.: video: { chave:'videos-treino/2026/<32hex>.mp4', nome:'NR-35.mp4', bytes:52428800,
    //        mime:'video/mp4', duracaoSeg:612, enviadoTs:1790000000000, enviadoPor:'Ana' } | null
    video: VideosTreino.normalizarVideoTreino(t && t.video),
  };
}
// Projeção SEM gabarito: remove `correta` de cada questão. Usada em toda leitura que vai pro
// cliente (listagem RH e, futuramente, página pública do funcionário). O gabarito só sai do
// servidor no GET de edição gated por exigeEditar.
function treinamentoSemGabarito(t) {
  if (!t) return t;
  return {
    ...t,
    questoes: (t.questoes || []).map(q => ({
      id: q.id, enunciado: q.enunciado,
      alternativas: (q.alternativas || []).map(a => ({ id: a.id, texto: a.texto })),
    })),
  };
}

// ----- Convites de treinamento (link público por funcionário + treinamento) -----
// Clone do ciclo de vida de `admissoes`, com a DIFERENÇA CRÍTICA: o link é REUTILIZÁVEL dentro
// do prazo (não trava ao abrir/responder) — o funcionário pode reabrir até passar (D-03/D-06).
// O RH gera um convite por (funcionário + treinamento); o funcionário abre /treinamento/<token>
// sem login. A persistência segue a régua dual JSON/Mongo dos demais cadastros.
const TREIN_CONVITE_VALIDADE_PADRAO_DIAS = 7;
const STATUS_CONVITE = ['aguardando', 'concluido', 'expirado', 'cancelado'];
function lerConvites() {
  if (USE_MONGO) return mem.treinamentoConvites || [];
  try { const o = JSON.parse(fs.readFileSync(TREIN_CONVITES_FILE, 'utf-8')); return Array.isArray(o.treinamentoConvites) ? o.treinamentoConvites : []; }
  catch (e) { return []; }
}
async function salvarConvites(arr) {
  const treinamentoConvites = (arr || []).map(normalizarConvite);
  if (USE_MONGO) { mem.treinamentoConvites = treinamentoConvites; await persistMongo('treinamentoConvites', { treinamentoConvites }); }
  else { escreverJSONAtomico(TREIN_CONVITES_FILE, { treinamentoConvites }); }
  notificarDados('integracao');
  return treinamentoConvites;
}
function seedConvites() {
  try { const o = JSON.parse(fs.readFileSync(TREIN_CONVITES_FILE, 'utf-8')); return Array.isArray(o.treinamentoConvites) ? o.treinamentoConvites : []; }
  catch (e) { return []; }
}
function normalizarConvite(c) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const status = s(c && c.status);
  return {
    id: s(c && c.id) || gerarId('TCV'),
    token: s(c && c.token) || gerarTokenAdmissao(), // 128 bits (mesma fonte de cripto do admissão)
    ts: Number(c && c.ts) || Date.now(),
    funcionarioId: s(c && c.funcionarioId),
    nome: s(c && c.nome),
    treinamentoId: s(c && c.treinamentoId),
    status: STATUS_CONVITE.includes(status) ? status : 'aguardando',
    validadeTs: Number(c && c.validadeTs) || 0,
    criadoPor: s(c && c.criadoPor),
    // Histórico do "Gerar novo link" (POST /convites/:id/regenerar): quando foi o último, quem
    // gerou e quantas vezes o link já foi trocado. O token antigo deixa de abrir a cada troca.
    // Ex.: { regeradoTs:1790000000000, regeradoPor:'Ana', regeracoes:2 } · nunca regerado → 0, '', 0
    regeradoTs: Number(c && c.regeradoTs) || 0,
    regeradoPor: s(c && c.regeradoPor).slice(0, 60),
    regeracoes: Math.max(0, Math.round(Number(c && c.regeracoes) || 0)),
    // Rastreio de acesso (gate por CPF): primeiro acesso, último acesso, CPF informado (só dígitos)
    // e nº de acessos. Preenchidos quando o funcionário "entra" no link confirmando o CPF.
    acessadoTs: Number(c && c.acessadoTs) || 0,
    ultimoAcessoTs: Number(c && c.ultimoAcessoTs) || 0,
    acessoCpf: s(c && c.acessoCpf).replace(/\D/g, ''),
    acessos: Math.max(0, Math.round(Number(c && c.acessos) || 0)),
    // Progresso do vídeo travado DESTE convite, amarrado à chave do vídeo que foi assistido:
    // trocar o vídeo do treinamento (chave nova) invalida o progresso de quem não foi aprovado.
    // Ex.: video: { chave:'videos-treino/2026/<32hex>.mp4', inicioTs:1790000000000,
    //        concluidoTs:1790000612000, liberadoTs:0, liberadoPor:'' } | null
    video: normalizarVideoConvite(c && c.video),
    comentarios: normalizarComentariosConvite(c && c.comentarios),
  };
}
// Campo `video` do convite. Sem chave válida => null (nada a lembrar).
// USO: normalizarVideoConvite({ chave:'videos-treino/2026/<32hex>.mp4', inicioTs:'1790000000000' })
//   // => { chave, inicioTs:1790000000000, concluidoTs:0, liberadoTs:0, liberadoPor:'' }
//      normalizarVideoConvite({ chave:'../x.mp4' }) // => null
function normalizarVideoConvite(v) {
  if (!v || typeof v !== 'object' || !VideosTreino.validarChave(v.chave)) return null;
  const ts = (x) => (Number.isFinite(Number(x)) && Number(x) > 0 ? Math.floor(Number(x)) : 0);
  return {
    chave: v.chave,
    inicioTs: ts(v.inicioTs),
    concluidoTs: ts(v.concluidoTs),
    liberadoTs: ts(v.liberadoTs),
    liberadoPor: String(v.liberadoPor == null ? '' : v.liberadoPor).trim().slice(0, 60),
  };
}
// Progresso do vídeo do convite para o vídeo ATUAL do treinamento. null quando o treinamento
// não tem vídeo enviado (Drive ou nenhum: nada a assistir no player travado). Progresso de
// outra chave (vídeo trocado) conta como não iniciado.
// USO: progressoVideoConvite(conv, treino)
//   // => { chave, duracaoSeg:612, iniciadoTs:1790000000000, concluidoTs:0, liberadoTs:0, liberadoPor:'' } | null
function progressoVideoConvite(conv, treino) {
  const tv = treino && treino.video;
  if (!tv || !tv.chave) return null;
  const cv = conv && conv.video && conv.video.chave === tv.chave ? conv.video : null;
  return {
    chave: tv.chave, duracaoSeg: tv.duracaoSeg,
    iniciadoTs: cv ? cv.inicioTs : 0, concluidoTs: cv ? cv.concluidoTs : 0,
    liberadoTs: cv ? cv.liberadoTs : 0, liberadoPor: cv ? cv.liberadoPor : '',
  };
}
// A prova ainda está travada pelo vídeo? true só quando o treinamento tem vídeo enviado e o
// convite não o terminou (na mesma chave) nem teve a prova liberada pelo RH. Refazer a prova
// depois de reprovar não trava de novo: o concluidoTs continua lá.
// USO: videoPendente(conv, treino) // => true (falta assistir) | false (sem vídeo, assistido ou liberado)
//      if (videoPendente(conv, treino)) return res.status(409).json({ ok:false, codigo:'VIDEO_PENDENTE', … })
function videoPendente(conv, treino) {
  const p = progressoVideoConvite(conv, treino);
  return !!p && !p.concluidoTs && !p.liberadoTs;
}
// Resumo do progresso para a página pública (sem a chave).
// USO: progressoPublicoVideo(conv, treino)
//   // => { iniciadoTs:1790000000000, concluidoTs:0, liberadoRh:false, provaLiberada:false }
//   // (treinamento sem vídeo enviado => { iniciadoTs:0, concluidoTs:0, liberadoRh:false, provaLiberada:true })
function progressoPublicoVideo(conv, treino) {
  const p = progressoVideoConvite(conv, treino);
  return {
    iniciadoTs: p ? p.iniciadoTs : 0,
    concluidoTs: p ? p.concluidoTs : 0,
    liberadoRh: !!(p && p.liberadoTs),
    provaLiberada: !videoPendente(conv, treino),
  };
}
// ----- Comentários do funcionário sobre o treinamento (usabilidade/funcionamento) -----
// Moram DENTRO do convite (1 pessoa + 1 treinamento), então herdam backup, restore e o recorte
// por empresa do Acompanhamento sem coleção nova. Só ACRESCENTA: o funcionário não edita nem
// apaga o que mandou (o RH lê como registro). `avaliacao` = 'ok' (funcionou) | 'problema'.
// USO: normalizarComentariosConvite([{ avaliacao: 'problema', texto: 'O vídeo trava no minuto 3' }])
//   → [{ id: 'TCM...', ts: 1758..., avaliacao: 'problema', texto: 'O vídeo trava no minuto 3' }]
const COMENTARIO_TREINO_MAX_CHARS = 1000;
const COMENTARIOS_TREINO_MAX_POR_CONVITE = 30; // teto anti-abuso: o link é público (só token + CPF)
const AVALIACOES_COMENTARIO_TREINO = ['ok', 'problema'];
function normalizarComentariosConvite(arr) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return (Array.isArray(arr) ? arr : []).map(c => ({
    id: s(c && c.id) || gerarId('TCM'),
    ts: Number(c && c.ts) || Date.now(),
    avaliacao: AVALIACOES_COMENTARIO_TREINO.includes(s(c && c.avaliacao)) ? s(c.avaliacao) : 'ok',
    texto: s(c && c.texto).slice(0, COMENTARIO_TREINO_MAX_CHARS),
  })).slice(-COMENTARIOS_TREINO_MAX_POR_CONVITE);
}
// Status efetivo p/ exibição: 'aguardando' vira 'expirado' depois da validade (clone de
// statusEfetivoAdmissao). 'concluido' permanece concluído mesmo após o prazo.
function statusEfetivoConvite(c) {
  if (!c) return 'cancelado';
  if (c.status === 'aguardando' && c.validadeTs && Date.now() > c.validadeTs) return 'expirado';
  return c.status;
}
// O link aceita resposta enquanto existe, está dentro do prazo e NÃO foi concluído/cancelado.
// ⚠ NÃO checa "já respondeu" (Pitfall 1) — isso quebraria a reutilização (D-03/D-06): quem
// reprova reabre o mesmo link e tenta de novo. Só 'concluido' (aprovado) fecha o ciclo.
function convAbertoParaResponder(c) {
  return !!c && c.status !== 'concluido' && c.status !== 'cancelado' && (!c.validadeTs || Date.now() <= c.validadeTs);
}
// Convite CONCLUÍDO = status 'concluido' OU existe conclusão aprovada com esse conviteId (o
// status pode não ter sido gravado se a 2ª escrita do /responder falhou).
// USO: const aprovados = idsConvitesAprovados(lerConclusoes());
//      conviteConcluido(convite, aprovados) // => true | false
function idsConvitesAprovados(conclusoes) {
  return new Set((conclusoes || []).filter(k => k && k.aprovado && k.conviteId).map(k => k.conviteId));
}
function conviteConcluido(c, aprovados) {
  return !!c && (c.status === 'concluido' || !!(aprovados && aprovados.has(c.id)));
}
// Projeção segura p/ a página PÚBLICA do funcionário: dados do treinamento SEM o gabarito
// (`correta`) em nenhuma questão (Pitfall 2 / T-02-02). Clone de admissaoPublica.
function treinamentoPublico(conv, treino) {
  return {
    ok: true,
    status: statusEfetivoConvite(conv),
    nome: (conv && conv.nome) || '',
    treino: treino ? {
      titulo: treino.titulo,
      tipo: treino.tipo,
      descricao: treino.descricao,
      fileId: treino.fileId,
      questoes: (treino.questoes || []).map(q => ({
        id: q.id,
        enunciado: q.enunciado,
        alternativas: (q.alternativas || []).map(a => ({ id: a.id, texto: a.texto })),
      })),
    } : null,
    // Os comentários que a PRÓPRIA pessoa já mandou (só saem depois do gate de CPF).
    comentarios: (conv && conv.comentarios) || [],
  };
}

// ----- Conclusões de treinamento (histórico cumulativo de tentativas da prova) -----
// CUMULATIVO (D-06): cada tentativa do funcionário gera uma entrada {nota, aprovado, ts}. O link
// é reutilizável, então há várias conclusões por (funcionário+treinamento) até passar. A correção
// é feita SÓ no servidor (gabarito secreto) — esta coleção guarda só o resultado, nunca o gabarito.
function lerConclusoes() {
  if (USE_MONGO) return mem.treinamentoConclusoes || [];
  try { const o = JSON.parse(fs.readFileSync(TREIN_CONCLUSOES_FILE, 'utf-8')); return Array.isArray(o.treinamentoConclusoes) ? o.treinamentoConclusoes : []; }
  catch (e) { return []; }
}
async function salvarConclusoes(arr) {
  const treinamentoConclusoes = (arr || []).map(normalizarConclusao);
  if (USE_MONGO) { mem.treinamentoConclusoes = treinamentoConclusoes; await persistMongo('treinamentoConclusoes', { treinamentoConclusoes }); }
  else { escreverJSONAtomico(TREIN_CONCLUSOES_FILE, { treinamentoConclusoes }); }
  notificarDados('integracao');
  return treinamentoConclusoes;
}
function seedConclusoes() {
  try { const o = JSON.parse(fs.readFileSync(TREIN_CONCLUSOES_FILE, 'utf-8')); return Array.isArray(o.treinamentoConclusoes) ? o.treinamentoConclusoes : []; }
  catch (e) { return []; }
}
function normalizarConclusao(c) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const nota = Math.max(0, Math.min(100, Math.round(Number(c && c.nota) || 0)));
  return {
    id: s(c && c.id) || gerarId('TCC'),
    funcionarioId: s(c && c.funcionarioId),
    treinamentoId: s(c && c.treinamentoId),
    conviteId: s(c && c.conviteId),
    ts: Number(c && c.ts) || Date.now(),
    nota,
    aprovado: !!(c && c.aprovado),
  };
}

// ----- Matriz de documentos obrigatórios por cargo / contrato -----
// Estrutura: { cargos: { "<cargo minúsculo>": ["ASO","NR-10"] }, contratos: { "<nº>": ["..."] } }.
// Não é regra legal fixa — é uma CONFIGURAÇÃO editável (cada empresa define o que exige).
function lerObrigatorios() {
  let o;
  if (USE_MONGO) o = mem.funcobrigatorios || {};
  else { try { o = JSON.parse(fs.readFileSync(FUNCOBR_FILE, 'utf-8')); } catch (e) { o = {}; } }
  return { cargos: (o && o.cargos) || {}, contratos: (o && o.contratos) || {} };
}
// Limpa o objeto recebido: chaves em texto, valores como listas de nomes de documento sem duplicar.
function sanitizarObrigatorios(obj) {
  const lista = (v) => [...new Set((Array.isArray(v) ? v : []).map(x => String(x || '').trim()).filter(Boolean))];
  const mapa = (m) => {
    const out = {};
    if (m && typeof m === 'object') for (const k of Object.keys(m)) { const chave = String(k || '').trim(); const docs = lista(m[k]); if (chave && docs.length) out[chave] = docs; }
    return out;
  };
  return { cargos: mapa(obj && obj.cargos), contratos: mapa(obj && obj.contratos) };
}
async function salvarObrigatorios(obj) {
  const dados = sanitizarObrigatorios(obj);
  if (USE_MONGO) { mem.funcobrigatorios = dados; await persistMongo('funcobrigatorios', dados); }
  else { escreverJSONAtomico(FUNCOBR_FILE, dados); }
  notificarDados('funcionarios');
  return dados;
}
// ----- Dias do período de experiência por contrato (matriz editável) -----
// Guardado em sistema_config.experienciaDias = { padrao, contratos:{ '<numero>': dias } }.
// Cache em memória p/ uso SÍNCRONO no normalizarFuncionario (rede de segurança do cálculo no boot/import).
let EXP_DIAS_CACHE = { padrao: 45, contratos: {} };
function sanitizarExpDias(obj) {
  const nDias = (v, def) => { const n = Math.round(Number(v)); return (Number.isFinite(n) && n >= 1 && n <= 365) ? n : def; };
  const out = { padrao: nDias(obj && obj.padrao, 45), contratos: {} };
  const c = (obj && obj.contratos) || {};
  for (const num of Object.keys(c)) { const k = String(num).trim(); const d = nDias(c[num], null); if (k && d !== null) out.contratos[k] = d; }
  return out;
}
async function lerExperienciaDias() {
  const d = await lerDocBackup('sistema_config', {});
  return sanitizarExpDias((d && d.experienciaDias) || {});
}
async function salvarExperienciaDias(obj) {
  const limpo = sanitizarExpDias(obj);
  const atual = await lerDocBackup('sistema_config', {});
  await salvarDocBackup('sistema_config', Object.assign({}, atual, { experienciaDias: limpo }));
  EXP_DIAS_CACHE = limpo;
  return limpo;
}
// ----- Vigência dos contratos (início/fim, aditivos de prorrogação e encerramento) -----
// Guardado em sistema_config.vigenciasContratos = { contratos: { '<numero>': vig } }, onde
// vig = { inicio, fimOriginal, aditivos:[{numero, inicio, novoFim, obs, ts, por}], encerramento:{data, motivo, ts, por}|null }.
// O STATUS (Vigente/Vencido/Encerrado) é sempre DERIVADO no cliente, nunca gravado — a data
// que vale é a do último aditivo (ou a original, sem aditivo), padrão do projeto.
// Exemplo de uso:
//   const vs = await lerVigenciasContratos();
//   vs.contratos['4500009202'] = { inicio: '2026-01-01', fimOriginal: '2026-12-31', aditivos: [], encerramento: null };
//   await salvarVigenciasContratos(vs);
//   → grava em sistema_config e devolve o mapa sanitizado (datas inválidas viram '').
const dataISOouVazio = (v) => { const s = String(v || '').slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : ''; };
function sanitizarVigenciaContrato(v) {
  const txt = (x) => String(x || '').trim();
  const aditivos = (Array.isArray(v && v.aditivos) ? v.aditivos : [])
    .map(a => ({
      numero: txt(a && a.numero),
      inicio: dataISOouVazio(a && a.inicio),
      novoFim: dataISOouVazio(a && a.novoFim),
      obs: txt(a && a.obs),
      ts: txt(a && a.ts),
      por: txt(a && a.por),
    }))
    .filter(a => a.novoFim);
  const e = v && v.encerramento;
  const encerramento = (e && dataISOouVazio(e.data))
    ? { data: dataISOouVazio(e.data), motivo: txt(e.motivo), ts: txt(e.ts), por: txt(e.por) }
    : null;
  return { inicio: dataISOouVazio(v && v.inicio), fimOriginal: dataISOouVazio(v && v.fimOriginal), aditivos, encerramento };
}
function sanitizarVigenciasContratos(obj) {
  const out = { contratos: {} };
  const c = (obj && obj.contratos) || {};
  for (const num of Object.keys(c)) {
    const k = String(num).trim();
    if (!k) continue;
    const v = sanitizarVigenciaContrato(c[num]);
    // Guarda só quem tem alguma coisa cadastrada — chave vazia não ocupa o doc.
    if (v.inicio || v.fimOriginal || v.aditivos.length || v.encerramento) out.contratos[k] = v;
  }
  return out;
}
async function lerVigenciasContratos() {
  const d = await lerDocBackup('sistema_config', {});
  return sanitizarVigenciasContratos((d && d.vigenciasContratos) || {});
}
async function salvarVigenciasContratos(obj) {
  const limpo = sanitizarVigenciasContratos(obj);
  const atual = await lerDocBackup('sistema_config', {});
  await salvarDocBackup('sistema_config', Object.assign({}, atual, { vigenciasContratos: limpo }));
  notificarDados('funcionarios');
  return limpo;
}
function contratoEhAtlasFunc(c) {
  const num = c && String(c.numero || '').trim();
  return num === '4600009606' || /ATLAS/i.test([num, c && c.nome, c && c.razao].filter(Boolean).join(' '));
}
// Dias de experiência aplicáveis a um funcionário: pelo contrato PRINCIPAL (contratos[0]); senão o padrão.
function diasExperienciaDe(f, matriz) {
  const m = matriz || EXP_DIAS_CACHE;
  const c0 = (Array.isArray(f && f.contratos) && f.contratos[0]) || null;
  const num = c0 && String(c0.numero || '').trim();
  return (num && m.contratos[num]) || (contratoEhAtlasFunc(c0) ? 30 : (m.padrao || 45));
}
// Fim da experiência: a ADMISSÃO conta como 1º dia → fim = admissão + (dias-1). Devolve ISO ou ''.
function calcFimExperiencia(admissaoISO, dias) {
  const m = String(admissaoISO || '').slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m || !dias) return '';
  const dt = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  dt.setDate(dt.getDate() + (dias - 1));
  const p = (n) => String(n).padStart(2, '0');
  return `${dt.getFullYear()}-${p(dt.getMonth() + 1)}-${p(dt.getDate())}`;
}
function calcFimExperienciaMeses(admissaoISO, meses) {
  const m = String(admissaoISO || '').slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m || !meses) return '';
  const ano = Number(m[1]); const mes = Number(m[2]) - 1; const dia = Number(m[3]);
  const inicioDestino = new Date(ano, mes + meses, 1);
  const ultimoDia = new Date(inicioDestino.getFullYear(), inicioDestino.getMonth() + 1, 0).getDate();
  const dt = new Date(inicioDestino.getFullYear(), inicioDestino.getMonth(), Math.min(dia, ultimoDia));
  const p = (n) => String(n).padStart(2, '0');
  return `${dt.getFullYear()}-${p(dt.getMonth() + 1)}-${p(dt.getDate())}`;
}
// Normaliza um nome de documento p/ comparar (minúsculo, sem acento/pontuação): "NR-10" → "nr10".
const normDoc = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
// Documentos exigidos de um colaborador = união (cargo + contrato) pela matriz configurada.
function obrigatoriosDoFunc(f, matriz) {
  const m = matriz || lerObrigatorios();
  const out = [];
  const cargoKey = String(f.cargo || '').trim().toLowerCase();
  if (cargoKey) for (const k of Object.keys(m.cargos || {})) if (k.trim().toLowerCase() === cargoKey) out.push(...m.cargos[k]);
  // Vários contratos: exige a UNIÃO dos obrigatórios de todos os contratos vinculados.
  const nums = (Array.isArray(f.contratos) && f.contratos.length ? f.contratos.map(c => String(c && c.numero || '').trim()) : [String(f.contratoNumero || '').trim()]).filter(Boolean);
  for (const num of nums) if (m.contratos && m.contratos[num]) out.push(...m.contratos[num]);
  return [...new Set(out.map(x => String(x).trim()).filter(Boolean))];
}
// Obrigatórios que o colaborador NÃO possui (nenhum documento VÁLIDO casa com o nome exigido).
// Um documento só satisfaz o obrigatório se o nome casar E não estiver vencido. RETROCOMPAT
// (afeta TODOS os obrigatórios, não só treinamentos): documento SEM validade continua satisfazendo
// como antes; só o que tem validade no passado deixa de satisfazer → reabre "Falta obrigatório"
// (reciclagem de treinamento vencida, Open Question 2 / Pitfall 4).
function faltantesDoFunc(f, matriz) {
  const req = obrigatoriosDoFunc(f, matriz);
  if (!req.length) return [];
  const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
  const docsNorm = (f.documentos || []).filter(d => {
    const m = String(d.validade || '').slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return true; // sem validade (ou inválida) → satisfaz (comportamento anterior)
    const dt = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])); dt.setHours(0, 0, 0, 0);
    return dt >= hoje;   // vencido (< hoje) não satisfaz mais o obrigatório
  }).map(d => normDoc(d.nome));
  return req.filter(rq => { const rn = normDoc(rq); return rn && !docsNorm.some(dn => dn.includes(rn)); });
}
const STATUS_FUNCIONARIO = ['Ativo', 'Afastado', 'Férias', 'Desligado'];
const TIPOS_VINCULO = ['CLT', 'PJ', 'Temporário', 'Estágio', 'Aprendiz', 'Terceirizado', 'Outro'];
const STATUS_ITEM = ['Entregue', 'Devolvido', 'Perdido', 'Danificado'];
// Itens entregues ao colaborador (EPI, uniforme, ferramentas, crachá, cartão, etc.).
function normalizarItensFunc(arr) {
  if (!Array.isArray(arr)) return [];
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return arr
    .map(it => ({
      id: s(it && it.id) || gerarId('I'),
      tipo: s(it && it.tipo),
      descricao: s(it && it.descricao),
      ca: s(it && it.ca),                       // nº do CA (EPI) ou nº de série
      quantidade: s(it && it.quantidade),
      dataEntrega: s(it && it.dataEntrega).slice(0, 10),
      dataDevolucao: s(it && it.dataDevolucao).slice(0, 10),
      status: STATUS_ITEM.includes(s(it && it.status)) ? s(it.status) : 'Entregue',
      obs: s(it && it.obs),
    }))
    .filter(it => it.tipo || it.descricao);
}
// Uma versão ANTERIOR de um documento (preservada ao substituir o arquivo ativo). O id da
// mídia continua no cofre (não é apagado), guardando o histórico. uploadTs/uploadPor = quando/quem
// subiu aquela versão; substituidoTs/substituidoPor = quando/quem a aposentou.
function normalizarVersaoDoc(v) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return {
    id: s(v && v.id),
    nome: s(v && v.nome),
    tipo: s(v && v.tipo),
    nomeOriginal: s(v && v.nomeOriginal),
    uploadTs: Number(v && v.uploadTs) || 0,
    uploadPor: s(v && v.uploadPor),
    substituidoTs: Number(v && v.substituidoTs) || 0,
    substituidoPor: s(v && v.substituidoPor),
  };
}
// Documentos do colaborador: ref de mídia + categoria (Pessoal | Segurança) + validade.
// A validade (AAAA-MM-DD, do <input type=date>) alimenta o aviso de vencimento de 30 dias.
// Versionamento: ao substituir o arquivo, a versão anterior vai para `versoes[]` (mais recente
// primeiro) com o id de mídia preservado — nada é perdido. `nomeOriginal/uploadTs/uploadPor`
// guardam os metadados da versão ATIVA (quem subiu o arquivo atual e quando).
function normalizarDocsFunc(arr) {
  if (!Array.isArray(arr)) return [];
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return arr
    .map(d => ({
      id: s(d && d.id),
      nome: s(d && d.nome),
      tipo: s(d && d.tipo),
      categoria: (s(d && d.categoria) === 'Segurança') ? 'Segurança' : 'Pessoal',
      validade: s(d && d.validade).slice(0, 10),
      emissao: s(d && d.emissao).slice(0, 10), // data de emissão do documento (opcional; hoje usada só pelo ASO p/ sugerir o vencimento na UI)
      semValidade: !!(d && d.semValidade), // "não vence" — dispensa a data de validade obrigatória
      nomeOriginal: s(d && d.nomeOriginal),
      uploadTs: Number(d && d.uploadTs) || 0,
      uploadPor: s(d && d.uploadPor),
      versoes: Array.isArray(d && d.versoes) ? d.versoes.map(normalizarVersaoDoc).filter(v => v.id) : [],
    }))
    .filter(d => d.id || d.nome); // mantém também itens só de controle (sem arquivo, mas com nome/validade)
}
// Todos os ids de mídia de um documento: o arquivo ATIVO + os das versões anteriores.
// Usado na limpeza de mídia órfã (PUT/DELETE) e na coleta de anexos do backup.
function idsMidiaDoc(d) {
  if (!d) return [];
  return [d.id, ...((d.versoes || []).map(v => v && v.id))].filter(Boolean);
}
// Validação de integridade: todo documento precisa de data de validade, salvo os marcados como
// "não vence" (semValidade). Vale na criação E na edição. Devolve mensagem de erro ou '' (ok).
function erroDatasObrigatoriasDocs(documentos) {
  for (const d of (documentos || [])) {
    if (d.semValidade) continue;
    if (!d.validade) {
      const rotulo = (d.nome || '').trim();
      return rotulo
        ? `A data de validade do documento "${rotulo}" é obrigatória (ou marque-o como "não vence").`
        : 'Há um documento sem data de validade. Informe a validade ou marque-o como "não vence".';
    }
  }
  return '';
}
function normalizarFuncionario(f) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const status = s(f.status);
  const foto = (f.foto && s(f.foto.id))
    ? { id: s(f.foto.id), nome: s(f.foto.nome), tipo: s(f.foto.tipo) }
    : null;
  // PPP (Perfil Profissiográfico Previdenciário) — anexo entregue na desmobilização.
  const ppp = (f.ppp && s(f.ppp.id))
    ? { id: s(f.ppp.id), nome: s(f.ppp.nome), tipo: s(f.ppp.tipo) }
    : null;
  // ASO demissional — Atestado de Saúde Ocupacional da rescisão (obrigatório ao desmobilizar).
  const asoDemissional = (f.asoDemissional && s(f.asoDemissional.id))
    ? { id: s(f.asoDemissional.id), nome: s(f.asoDemissional.nome), tipo: s(f.asoDemissional.tipo) }
    : null;
  // Ficha de EPI — documento assinado de entrega de EPIs (anexo único, SEM validade).
  const fichaEpi = (f.fichaEpi && s(f.fichaEpi.id))
    ? { id: s(f.fichaEpi.id), nome: s(f.fichaEpi.nome), tipo: s(f.fichaEpi.tipo) }
    : null;
  // Documento de salário (contracheque/contrato) — anexo único, mesmo formato da ficha de EPI.
  const salarioDoc = (f.salarioDoc && s(f.salarioDoc.id))
    ? { id: s(f.salarioDoc.id), nome: s(f.salarioDoc.nome), tipo: s(f.salarioDoc.tipo) }
    : null;
  // Vigências de salário: [{desde:'yyyy-mm', valor}] ordenadas, sem repetir mês. Guardar a série
  // (e não um valor único) mantém a folha dos meses passados correta após um aumento.
  // Dado sensível: alimenta a folha por contrato na aba Custos (só agregados saem de lá).
  const salarios = (Array.isArray(f.salarios) ? f.salarios : [])
    .map(v => ({ desde: s(v && v.desde).slice(0, 7), valor: Number(v && v.valor) || 0 }))
    .filter(v => /^\d{4}-\d{2}$/.test(v.desde) && v.valor > 0)
    .filter((v, i, arr) => arr.findIndex(x => x.desde === v.desde) === i)
    .sort((a, b) => a.desde.localeCompare(b.desde));
  const tipoVinculo = s(f.tipoVinculo);
  // Vínculos de contrato (vários). Aceita o array novo (f.contratos) ou monta a partir dos campos
  // legados. Cada item = {numero, nome, local}. O 1º item espelha contratoNumero/nome/local p/ manter
  // compatível todo o código que ainda lê o "contrato principal" (grupos, acesso, obrigatórios, etc.).
  const contratosNorm = (() => {
    const brutos = Array.isArray(f.contratos) && f.contratos.length
      ? f.contratos
      : ((s(f.contratoNumero) || s(f.contratoNome) || s(f.local)) ? [{ numero: f.contratoNumero, nome: f.contratoNome, local: f.local }] : []);
    const vistos = new Set();
    return brutos
      .map(c => ({ numero: s(c && c.numero), nome: s(c && c.nome), local: s(c && c.local) }))
      .filter(c => (c.numero || c.nome) && !vistos.has(c.numero + '|' + c.local) && vistos.add(c.numero + '|' + c.local));
  })();
  // Fim da experiência: usa o valor informado; se vazio e houver admissão, calcula (admissão + dias do
  // contrato principal - 1). Rede de segurança p/ importação/admissão pública. Não sobrescreve manual.
  // A 2ª admissão repete a mesma regra: ATLAS = 30 dias; demais contratos = padrão (45).
  const experienciaCalculo = s(f.experienciaCalculo) === '6m' ? '6m' : 'dias';
  const diasExp = diasExperienciaDe({ contratos: contratosNorm });
  const calcExpPorRegra = (admissaoISO) => (experienciaCalculo === '6m'
    ? calcFimExperienciaMeses(admissaoISO, 6)
    : calcFimExperiencia(admissaoISO, diasExp));
  const admissao1 = s(f.admissao).slice(0, 10);
  const admissao2 = s(f.admissao2).slice(0, 10);
  const experienciaFimCalc = s(f.experienciaFim).slice(0, 10) || (admissao1 ? calcExpPorRegra(admissao1) : '');
  const experienciaFim2Calc = s(f.experienciaFim2).slice(0, 10) || (admissao2 ? calcExpPorRegra(admissao2) : '');
  return {
    id: s(f.id) || gerarId('C'),
    ts: Number(f.ts) || Date.now(),
    nome: s(f.nome),
    cargo: s(f.cargo),
    // Membro da CIPA (Comissão Interna de Prevenção de Acidentes e de Assédio).
    // Ex.: normalizarFuncionario({ nome:'Ana', cargo:'Eletricista', cipa:true }) → { ..., cipa: true };
    //      ausente ou falsy ({ cipa:'' }) → cipa: false.
    cipa: !!f.cipa,
    empresa: s(f.empresa),                  // Norte Engenharia | Sul Empreendimentos (texto livre)
    status: STATUS_FUNCIONARIO.includes(status) ? status : (status || 'Ativo'),
    dataDemissao: s(f.dataDemissao).slice(0, 10), // preenchida ao desmobilizar (status Desligado)
    motivoDemissao: s(f.motivoDemissao),
    ppp,
    asoDemissional,
    cpf: s(f.cpf),
    rg: s(f.rg),
    orgaoEmissor: s(f.orgaoEmissor),
    matricula: s(f.matricula),
    nascimento: s(f.nascimento).slice(0, 10),
    admissao: admissao1,
    admissao2,
    telefone: s(f.telefone),
    email: s(f.email),
    endereco: s(f.endereco),
    cidade: s(f.cidade),
    uf: s(f.uf).toUpperCase().slice(0, 2),
    cep: s(f.cep),
    // Contato de emergência
    emergNome: s(f.emergNome),
    emergTelefone: s(f.emergTelefone),
    emergParentesco: s(f.emergParentesco),
    // Vínculo profissional
    setor: s(f.setor),
    centroCusto: s(f.centroCusto),
    tipoVinculo: TIPOS_VINCULO.includes(tipoVinculo) ? tipoVinculo : '',
    baseTrabalho: s(f.baseTrabalho),
    escala: s(f.escala),
    experienciaCalculo,
    experienciaFim: experienciaFimCalc,
    experienciaFim2: experienciaFim2Calc,
    contratos: contratosNorm,               // vínculos de contrato (vários)
    contratoNome: (contratosNorm[0] && contratosNorm[0].nome) || '',    // espelho do 1º (principal) — compat
    contratoNumero: (contratosNorm[0] && contratosNorm[0].numero) || '',
    local: (contratosNorm[0] && contratosNorm[0].local) || '',          // frente/obra do contrato principal
    // Habilitação (CNH) e vínculo com a frota
    cnhNumero: s(f.cnhNumero),
    cnhCategoria: s(f.cnhCategoria).toUpperCase().slice(0, 6),
    cnhValidade: s(f.cnhValidade).slice(0, 10),
    podeDirigir: !!f.podeDirigir,
    veiculoVinculado: s(f.veiculoVinculado).toUpperCase(),
    obs: s(f.obs),
    foto,
    fichaEpi,
    salarios,                               // vigências de salário (Remuneração) — alimenta a folha da aba Custos
    salarioDoc,                             // contracheque/contrato anexado
    documentos: normalizarDocsFunc(f.documentos),
    itens: normalizarItensFunc(f.itens),
    soDev: !!f.soDev,                       // registro de teste: visível só para a equipe de dev (ver podeVerFunc)
  };
}
// Resumo legível das diferenças entre dois cadastros (trilha de auditoria "quem mudou o quê").
function diffFuncionario(antes, depois) {
  const campos = [
    ['nome', 'nome'], ['cpf', 'CPF'], ['rg', 'RG'], ['orgaoEmissor', 'órgão emissor'],
    ['matricula', 'matrícula'], ['cargo', 'função'], ['setor', 'setor'], ['centroCusto', 'centro de custo'],
    ['tipoVinculo', 'tipo de vínculo'], ['empresa', 'empresa'], ['status', 'situação'], ['nascimento', 'nascimento'], ['admissao', '1ª admissão'], ['admissao2', '2ª admissão'],
    ['experienciaCalculo', 'cálculo da experiência'], ['experienciaFim', 'fim da 1ª experiência'], ['experienciaFim2', 'fim da 2ª experiência'], ['baseTrabalho', 'base de trabalho'], ['escala', 'escala'],
    ['telefone', 'telefone'], ['email', 'e-mail'], ['endereco', 'endereço'], ['cidade', 'cidade'], ['uf', 'UF'], ['cep', 'CEP'],
    ['emergNome', 'contato de emergência'], ['emergTelefone', 'tel. emergência'], ['emergParentesco', 'parentesco'],
    ['cnhNumero', 'CNH'], ['cnhCategoria', 'categoria CNH'], ['cnhValidade', 'validade CNH'], ['veiculoVinculado', 'veículo vinculado'],
    ['contratoNumero', 'contrato'], ['local', 'frente'], ['dataDemissao', 'demissão'], ['motivoDemissao', 'motivo da demissão'], ['obs', 'observações'],
  ];
  const mudou = [];
  for (const [k, rot] of campos) {
    const a = String((antes && antes[k]) || '').trim();
    const b = String((depois && depois[k]) || '').trim();
    if (a !== b) mudou.push(`${rot}: "${a || '—'}" → "${b || '—'}"`);
  }
  const da = !!(antes && antes.podeDirigir), db = !!(depois && depois.podeDirigir);
  if (da !== db) mudou.push(db ? 'marcado como apto a dirigir' : 'desmarcado como apto a dirigir');
  const ca = !!(antes && antes.cipa), cb = !!(depois && depois.cipa);
  if (ca !== cb) mudou.push(cb ? 'marcado como membro da CIPA' : 'desmarcado como membro da CIPA');
  const ia = ((antes && antes.itens) || []).length, ib = ((depois && depois.itens) || []).length;
  if (ia !== ib) mudou.push(`itens entregues: ${ia} → ${ib}`);
  const fa = !!(antes && antes.foto && antes.foto.id), fb = !!(depois && depois.foto && depois.foto.id);
  if (fa !== fb) mudou.push(fb ? 'foto adicionada' : 'foto removida');
  const pa = !!(antes && antes.ppp && antes.ppp.id), pb = !!(depois && depois.ppp && depois.ppp.id);
  if (pa !== pb) mudou.push(pb ? 'PPP adicionado' : 'PPP removido');
  const aa = !!(antes && antes.asoDemissional && antes.asoDemissional.id), ab = !!(depois && depois.asoDemissional && depois.asoDemissional.id);
  if (aa !== ab) mudou.push(ab ? 'ASO demissional adicionado' : 'ASO demissional removido');
  const ea = !!(antes && antes.fichaEpi && antes.fichaEpi.id), eb = !!(depois && depois.fichaEpi && depois.fichaEpi.id);
  if (ea !== eb) mudou.push(eb ? 'Ficha de EPI adicionada' : 'Ficha de EPI removida');
  // Remuneração: registra QUE mudou, nunca os valores (o histórico é lido por mais gente que o RH).
  const sa = JSON.stringify((antes && antes.salarios) || []), sb = JSON.stringify((depois && depois.salarios) || []);
  if (sa !== sb) mudou.push('remuneração atualizada');
  const sda = !!(antes && antes.salarioDoc && antes.salarioDoc.id), sdb = !!(depois && depois.salarioDoc && depois.salarioDoc.id);
  if (sda !== sdb) mudou.push(sdb ? 'documento de salário anexado' : 'documento de salário removido');
  // Documentos: além da contagem, nomeia o que entrou/saiu e mudanças no nº de versões de cada um
  // (um documento é casado pelo id da mídia atual; sem id — "só de controle" — pelo nome).
  // Ex.: ['documentos: 3 → 2', 'documento removido: "RG"', 'versões de "ASO": 3 → 2']
  const docsA = ((antes && antes.documentos) || []).filter(Boolean), docsB = ((depois && depois.documentos) || []).filter(Boolean);
  const na = docsA.length, nb = docsB.length;
  if (na !== nb) mudou.push(`documentos: ${na} → ${nb}`);
  const chaveDoc = (d) => d.id ? 'id:' + d.id : 'nome:' + String(d.nome || '').trim().toLowerCase();
  const rotuloDoc = (d) => `"${d.nome || d.nomeOriginal || d.id || '—'}"`;
  const mapaA = new Map(docsA.map(d => [chaveDoc(d), d])), mapaB = new Map(docsB.map(d => [chaveDoc(d), d]));
  for (const [k, d] of mapaA) if (!mapaB.has(k)) mudou.push(`documento removido: ${rotuloDoc(d)}`);
  for (const [k, d] of mapaB) if (!mapaA.has(k)) mudou.push(`documento adicionado: ${rotuloDoc(d)}`);
  for (const [k, dA] of mapaA) {
    const dB = mapaB.get(k);
    if (!dB) continue;
    const va = (dA.versoes || []).length, vb = (dB.versoes || []).length;
    if (va !== vb) mudou.push(`versões de ${rotuloDoc(dB)}: ${va} → ${vb}`);
  }
  return mudou;
}
// Converte um valor de célula (serial do Excel ou dd/mm/aaaa) em ISO AAAA-MM-DD.
function celulaParaISO(v) {
  if (v === '' || v === null || v === undefined) return '';
  const p = (n) => String(n).padStart(2, '0');
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    const o = XLSX.SSF.parse_date_code(v);
    return o ? `${o.y}-${p(o.m)}-${p(o.d)}` : '';
  }
  const m = String(v).trim().match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (m) { let [, d, mo, a] = m; if (a.length === 2) a = '20' + a; return `${a}-${p(mo)}-${p(d)}`; }
  return '';
}
// Validade de um documento ocupacional a partir da emissão (regra da planilha-modelo):
// NRs valem 2 anos; ASO/OS e demais valem 1 ano.
function validadeOcupacional(tipoDoc, emissaoISO) {
  if (!emissaoISO) return '';
  const [a, m, d] = emissaoISO.split('-').map(Number);
  const anos = /^nr/i.test(String(tipoDoc).replace(/\s+/g, '')) ? 2 : 1;
  const dt = new Date(a + anos, m - 1, d);
  const p = (n) => String(n).padStart(2, '0');
  return `${dt.getFullYear()}-${p(dt.getMonth() + 1)}-${p(dt.getDate())}`;
}

// ----- Programas de SST (PCMSO, PGR, PCMAT...): documentos por contrato/obra -----
// São documentos da OBRA/CONTRATO (não de um colaborador), com validade própria —
// alimentam o mesmo aviso de vencimento de 30 dias. O anexo (PDF/imagem) fica no cofre.
function lerProgramas() {
  if (USE_MONGO) return mem.programas || [];
  try { const o = JSON.parse(fs.readFileSync(PROG_FILE, 'utf-8')); return Array.isArray(o.programas) ? o.programas : []; }
  catch (e) { return []; }
}
async function salvarProgramas(arr) {
  const programas = arr || [];
  if (USE_MONGO) { mem.programas = programas; await persistMongo('programas', { programas }); }
  else { escreverJSONAtomico(PROG_FILE, { programas }); }
  notificarDados('programas');
}
function normalizarPrograma(p) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const documento = (p.documento && s(p.documento.id))
    ? { id: s(p.documento.id), nome: s(p.documento.nome), tipo: s(p.documento.tipo) }
    : null;
  return {
    id: s(p.id) || gerarId('P'),
    ts: Number(p.ts) || Date.now(),
    tipo: s(p.tipo).slice(0, 40),           // PCMSO, PGR, PCMAT... (texto livre c/ sugestões no front)
    contratoNome: s(p.contratoNome),
    contratoNumero: s(p.contratoNumero),
    local: s(p.local),                      // frente/obra do contrato (ex.: CAMPINA GRANDE, NATAL)
    emissao: s(p.emissao).slice(0, 10),
    validade: s(p.validade).slice(0, 10),
    responsavel: s(p.responsavel),          // responsável técnico (eng./médico)
    art: s(p.art),                          // nº da ART / registro (opcional)
    obs: s(p.obs),
    documento,
  };
}

// ----- Ações de Segurança (SST): controle mensal de DDS, treinamentos, inspeções... -----
// Cada registro é uma ação planejada para um mês de referência, com responsável, prazo e
// evidências da realização (fotos, listas de presença, PDFs — mesmo componente de anexos das
// multas). O STATUS nunca é gravado: é derivado por statusAcaoSst() (espelhada no app.js).
// Ex.: lerAcoesSst() → [{ id:'AS…', mesRef:'2026-08', titulo:'DDS uso de EPI', ... }];
//      await salvarAcoesSst(lista) → grava (JSON local ou Mongo) e notifica 'acoesSst' via SSE.
function lerAcoesSst() {
  if (USE_MONGO) return mem.acoesSst || [];
  try { const o = JSON.parse(fs.readFileSync(ACOES_SST_FILE, 'utf-8')); return Array.isArray(o.acoes) ? o.acoes : []; }
  catch (e) { return []; }
}
async function salvarAcoesSst(arr) {
  const acoes = arr || [];
  if (USE_MONGO) { mem.acoesSst = acoes; await persistMongo('acoesSst', { acoes }); }
  else { escreverJSONAtomico(ACOES_SST_FILE, { acoes }); }
  notificarDados('acoesSst');
}
// 'yyyy-mm' de mês real (recusa 2026-00, 2026-13, abcd-01). Ex.: mesRefValido('2026-08') → true.
function mesRefValido(v) { return /^\d{4}-(0[1-9]|1[0-2])$/.test(String(v || '')); }
// 'yyyy-mm-dd' de data que existe (round-trip pelo Date pega 2026-02-30).
// Ex.: dataISOValidaAcao('2026-02-30') → false; dataISOValidaAcao('2026-08-26') → true.
function dataISOValidaAcao(v) {
  const s = String(v || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(s + 'T12:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === s;
}
// Último dia do mês de referência — o prazo implícito de quem não definiu prazo.
// Ex.: ultimoDiaDoMesRef('2026-02') → '2026-02-28'.
function ultimoDiaDoMesRef(mesRef) {
  const [a, m] = String(mesRef || '').split('-').map(Number);
  if (!a || !m) return '';
  const d = new Date(Date.UTC(a, m, 0)); // dia 0 do mês seguinte = último dia do mês
  return d.toISOString().slice(0, 10);
}
// Paleta da "Cor no calendário" — espelho das CHAVES de CORES_ACAO_SST (frontend/app.js,
// onde vive o mapeamento chave → rótulo/classe). Mudou lá, muda aqui.
const CORES_ACAO_SST_VALIDAS = new Set(['azul', 'verde', 'ambar', 'vermelho', 'roxo', 'cinza']);
function normalizarAcaoSst(a) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const b = (x) => (x === true || x === 'true' || x === 'on' || x === 1 || x === '1');
  return {
    id: s(a.id) || gerarId('AS'),
    ts: Number(a.ts) || Date.now(),
    mesRef: s(a.mesRef).slice(0, 7),        // mês em que a ação deve acontecer
    titulo: s(a.titulo).slice(0, 160),      // rótulo na tela: "Ação de Segurança"
    tipo: s(a.tipo).slice(0, 60),           // DDS, Treinamento NR, Inspeção... (livre, sugestões no front)
    descricao: s(a.descricao).slice(0, 2000),
    responsavel: s(a.responsavel).slice(0, 120),
    // Vínculo com EMPRESA (sigla canônica, mesma régua da aba Funcionários) e CONTRATO
    // (`numero` do catálogo cadastros.contratosFuncionarios — o id de contrato do sistema
    // inteiro; o nome é sempre resolvido do catálogo na exibição, padrão EPI). Ambos
    // OPCIONAIS: ação antiga (ou geral) fica sem vínculo e aparece como "Sem empresa/contrato".
    // Validação real (existe/pertence) em erroEmpresaContratoAcaoSst(), nas rotas.
    // Ex.: normalizarAcaoSst({empresa:'sul empreendimentos', contratoNumero:'4600000101', ...})
    //      → { empresa:'SUL', contratoNumero:'4600000101', ... }.
    empresa: empresaSigla(a.empresa).slice(0, 20),
    contratoNumero: s(a.contratoNumero).slice(0, 40),
    // Cor de IDENTIDADE da pílula no CALENDÁRIO (paleta fixa; '' = Padrão, o fundo segue a
    // situação como sempre). Valor fora da paleta — ou registro antigo sem o campo — vira ''
    // (fallback silencioso, nunca 400). O mapa visual é centralizado no cliente
    // (CORES_ACAO_SST no app.js); aqui só se garante que não entra chave inventada.
    // Ex.: normalizarAcaoSst({cor:'roxo', ...}).cor → 'roxo'; normalizarAcaoSst({cor:'rosa', ...}).cor → ''.
    cor: CORES_ACAO_SST_VALIDAS.has(s(a.cor)) ? s(a.cor) : '',
    // Como a ação entra no calendário — escolha EXPLÍCITA do usuário (não se infere pelo
    // prazo em registro novo): 'fixa' ancora no dia do prazo (a "data programada");
    // 'atePrazo' flutua no dia corrente até a data limite — o dia exibido é DERIVADO a cada
    // render no cliente (diaCalendarioAcao no app.js), nunca gravado; o prazo original não muda.
    // Registro antigo sem o campo cai na inferência de agendamentoAcaoSst().
    // Ex.: normalizarAcaoSst({agendamento:'atePrazo', prazo:'2026-09-30', ...}).agendamento → 'atePrazo';
    //      normalizarAcaoSst({prazo:'2026-09-10', ...}).agendamento → 'fixa' (legado inferido).
    agendamento: agendamentoAcaoSst({ agendamento: s(a.agendamento), prazo: s(a.prazo) }),
    prazo: s(a.prazo).slice(0, 10),         // data limite ('atePrazo') ou data programada ('fixa'); vazio = fim do mês de referência
    dataRealizacao: s(a.dataRealizacao).slice(0, 10),
    observacaoRealizacao: s(a.observacaoRealizacao).slice(0, 2000), // participantes, ocorrências...
    cancelada: b(a.cancelada),
    motivoCancelamento: s(a.motivoCancelamento).slice(0, 400),
    // Auditoria: as rotas controlam estes valores (o body do cliente não manda neles).
    criadoPor: s(a.criadoPor).slice(0, 120),
    atualizadoPor: s(a.atualizadoPor).slice(0, 120),
    atualizadoEm: Number(a.atualizadoEm) || 0,
    realizadoPor: s(a.realizadoPor).slice(0, 120),
    evidencias: normalizarDocsMulta(a.evidencias), // mesmo formato dos anexos de multa (id obrigatório, versoes[])
  };
}
// Agendamento efetivo — espelhado em agendamentoAcao() no frontend/app.js. Retrocompat para
// registro gravado antes do campo existir: tinha prazo → 'fixa' (mantém o comportamento
// ancorado de antes); sem prazo → 'atePrazo' ("faça até o fim do mês", que agora flutua).
// Ex.: agendamentoAcaoSst({agendamento:'atePrazo'}) → 'atePrazo';
//      agendamentoAcaoSst({prazo:'2026-09-10'}) → 'fixa'; agendamentoAcaoSst({}) → 'atePrazo'.
function agendamentoAcaoSst(a) {
  return (a.agendamento === 'fixa' || a.agendamento === 'atePrazo') ? a.agendamento : (a.prazo ? 'fixa' : 'atePrazo');
}
// Status derivado — REGRA ÚNICA, espelhada em statusAcaoSst() no frontend/app.js. Nunca gravar.
// Janela operacional: a ação "entra em andamento" a 7 dias do prazo efetivo.
// Ex.: statusAcaoSst({mesRef:'2026-08', prazo:'2026-08-30'}, '2026-08-26') → 'Em andamento';
//      statusAcaoSst({mesRef:'2026-07'}, '2026-08-26') → 'Atrasada' (sem prazo → 31/07).
const JANELA_ACAO_SST = 7; // dias antes do prazo em que a ação vira "Em andamento" (e alerta)
function statusAcaoSst(a, hoje) {
  if (a.cancelada) return 'Cancelada';
  if (a.dataRealizacao) return 'Realizada';
  const prazoEfetivo = a.prazo || ultimoDiaDoMesRef(a.mesRef);
  if (!prazoEfetivo) return 'Programada';
  const h = hoje || hojeISO_BR();
  if (h > prazoEfetivo) return 'Atrasada';
  const dias = Math.round((new Date(prazoEfetivo + 'T12:00:00Z') - new Date(h + 'T12:00:00Z')) / 86400000);
  return dias <= JANELA_ACAO_SST ? 'Em andamento' : 'Programada';
}

// ----- Simulador bancário: comparações salvas (individuais por usuário) -----
// Lista de propostas já calculadas no cliente. Guarda só os números prontos (não recalcula
// no servidor). Mesmo padrão de arquivo local / Mongo + notificação em tempo real.
function lerSimulacoes() {
  if (USE_MONGO) return mem.simulacoes || [];
  try { const o = JSON.parse(fs.readFileSync(SIM_FILE, 'utf-8')); return Array.isArray(o.simulacoes) ? o.simulacoes : []; }
  catch (e) { return []; }
}
async function salvarSimulacoes(arr) {
  // teto POR USUÁRIO: cada login mantém só as suas 200 comparações mais recentes
  // (push adiciona no fim, então slice(-200) preserva as recentes de cada um, sem que o
  //  acúmulo de um usuário apague silenciosamente as comparações de outro).
  const porUser = new Map();
  for (const s of (arr || [])) {
    const k = s.usuario || '';
    if (!porUser.has(k)) porUser.set(k, []);
    porUser.get(k).push(s);
  }
  const simulacoes = [...porUser.values()].flatMap(v => v.slice(-200));
  if (USE_MONGO) { mem.simulacoes = simulacoes; await persistMongo('simulacoes', { simulacoes }); }
  else { escreverJSONAtomico(SIM_FILE, { simulacoes }); }
  notificarDados('simulacoes');
}
function normalizarSimulacao(c) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const num = (x) => { const n = Number(x); return Number.isFinite(n) ? n : null; };
  return {
    id: s(c.id) || gerarId('S'),
    ts: Number(c.ts) || Date.now(),
    usuario: s(c.usuario).slice(0, 80), // dono da comparação (login); definido pelo servidor no POST
    banco: s(c.banco).slice(0, 80),
    rotulo: s(c.rotulo).slice(0, 80),
    montante: num(c.montante),
    custoRS: num(c.custoRS),
    cetAnual: num(c.cetAnual),
    prazo: Math.max(0, Math.round(num(c.prazo) || 0)),
    posseImediata: c.posseImediata !== false,
  };
}
// Custo pode vir como número (planilha) ou texto "R$ 1.402,56" (edição manual). Trata os dois.
function custoNum(x) {
  if (typeof x === 'number') return Number.isFinite(x) ? x : 0;
  const s = String(x == null ? '' : x).replace(/[^\d,.-]/g, '');
  if (!s) return 0;
  // formato BR: ponto = milhar, vírgula = decimal
  const n = Number(s.replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : 0;
}
function normalizarManutencao(e) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const tipoBruto = s(e.tipo).toLowerCase();
  const tipo = tipoBruto.startsWith('prev') ? 'Preventiva' : (tipoBruto.startsWith('corr') ? 'Corretiva' : (s(e.tipo) || 'Corretiva'));
  return {
    id: s(e.id) || gerarId('MNT'),
    ts: Number(e.ts) || Date.now(),
    data: fmtDataBR(e.data),
    placa: s(e.placa).toUpperCase(),
    montadora: s(e.montadora),
    modelo: s(e.modelo),
    ano: s(e.ano),
    tipo,
    item: s(e.item),
    custo: custoNum(e.custo),
    centroCusto: canonizarCentroCusto(e.centroCusto),
    motorista: s(e.motorista),
    // Ex.: { fornecedorId: 'FORN123', fornecedor: 'Oficina Demo' } liga o cadastro
    // e conserva o nome do prestador na data do lançamento. Legado: ambos vazios.
    fornecedorId: s(e.fornecedorId).slice(0, 60),
    fornecedor: s(e.fornecedor).slice(0, 160),
  };
}

// USO: vincularFornecedorMnt(evento, anterior) => '' e preenche o nome pelo cadastro;
// id desconhecido/inativo => mensagem de erro. Mesmo vínculo preserva o nome histórico.
// Importação: vincularFornecedorMnt(evento, null, true) aceita cadastros inativos.
function vincularFornecedorMnt(evento, anterior, importar = false) {
  if (anterior && evento.fornecedorId === (anterior.fornecedorId || '')) {
    evento.fornecedor = anterior.fornecedor || '';
    return '';
  }
  if (!evento.fornecedorId) {
    if (!importar) evento.fornecedor = '';
    return '';
  }
  const fornecedor = lerFornecedores().find(f => f.id === evento.fornecedorId);
  if (!fornecedor) return 'Fornecedor não encontrado. Escolha um cadastro válido.';
  if (fornecedor.ativo === false && !importar) return 'Fornecedor inativo. Escolha um fornecedor ativo.';
  evento.fornecedor = importar && evento.fornecedor ? evento.fornecedor : fornecedor.nome;
  return '';
}

// ----- Backup / continuidade dos dados de manutenção -----
// PRIMÁRIO: snapshots versionados no Mongo (_id: manutencao_bak_<ts>), pois o disco do
// Render é efêmero (some no redeploy). Mantém os últimos N. Em dev (sem Mongo), grava em backups/.
// OFFSITE: o usuário baixa o .json/.xlsx pela tela admin e guarda fora do sistema.
const MNT_BAK_MAX = 20;
async function snapshotManutencao(motivo) {
  try {
    const manutencao = lerManutencao();
    const ts = Date.now();
    const snap = { manutencao, ts, motivo: motivo || '', total: manutencao.length };
    if (USE_MONGO) {
      await persistMongo('manutencao_bak_' + ts, snap);
      const baks = await mongoCol.find({ _id: { $regex: '^manutencao_bak_' } }).project({ _id: 1 }).toArray();
      const ids = baks.map(b => b._id).sort(); // _id termina no ts → ordem cronológica
      const excedente = ids.slice(0, Math.max(0, ids.length - MNT_BAK_MAX));
      if (excedente.length) await mongoCol.deleteMany({ _id: { $in: excedente } });
    } else {
      if (!fs.existsSync(MNT_BAK_DIR)) fs.mkdirSync(MNT_BAK_DIR, { recursive: true });
      fs.writeFileSync(path.join(MNT_BAK_DIR, `manutencao-${ts}.json`), JSON.stringify(snap, null, 2), 'utf-8');
      const files = fs.readdirSync(MNT_BAK_DIR).filter(f => /^manutencao-\d+\.json$/.test(f)).sort();
      for (const f of files.slice(0, Math.max(0, files.length - MNT_BAK_MAX))) { try { fs.unlinkSync(path.join(MNT_BAK_DIR, f)); } catch (e) { /* best-effort */ } }
    }
    console.log(`Snapshot de manutenção criado (${manutencao.length} eventos) · ${motivo || ''}`);
    return ts;
  } catch (e) { console.error('Falha ao criar snapshot de manutenção:', e.message); return null; }
}
// Assinatura de conteúdo de um evento (identidade p/ comparar dois snapshots).
// Como cada importação substitui tudo (ids são regerados), comparamos pelo CONTEÚDO.
function assinaturaEvento(e) {
  return [e.placa, e.data, e.item, e.custo, e.tipo, e.centroCusto, e.motorista]
    .map(x => String(x ?? '').trim().toLowerCase()).join('|');
}
// Diferença entre dois snapshots: quantos itens entraram (novos) e saíram (removidos).
function diffSnapshots(atual, anterior) {
  const a = new Set((atual || []).map(assinaturaEvento));
  const b = new Set((anterior || []).map(assinaturaEvento));
  let novos = 0, removidos = 0;
  for (const s of a) if (!b.has(s)) novos++;
  for (const s of b) if (!a.has(s)) removidos++;
  return { novos, removidos };
}
async function listarBackupsManutencao() {
  // Carrega os snapshots COMPLETOS (com os eventos) p/ poder comparar um com o outro.
  let snaps = [];
  if (USE_MONGO) {
    if (!mongoCol) return [];
    const baks = await mongoCol.find({ _id: { $regex: '^manutencao_bak_' } }).toArray();
    snaps = baks.map(b => ({ ts: b.ts, motivo: b.motivo || '', total: b.total || 0, dados: Array.isArray(b.manutencao) ? b.manutencao : [] }));
  } else {
    try {
      if (!fs.existsSync(MNT_BAK_DIR)) return [];
      snaps = fs.readdirSync(MNT_BAK_DIR).filter(f => /^manutencao-\d+\.json$/.test(f)).map(f => {
        try { const o = JSON.parse(fs.readFileSync(path.join(MNT_BAK_DIR, f), 'utf-8')); return { ts: o.ts, motivo: o.motivo || '', total: o.total || 0, dados: Array.isArray(o.manutencao) ? o.manutencao : [] }; }
        catch (e) { return null; }
      }).filter(Boolean);
    } catch (e) { return []; }
  }
  snaps.sort((a, b) => b.ts - a.ts); // mais recente primeiro
  // Para cada backup, compara com o imediatamente mais antigo (a "planilha anterior").
  return snaps.map((s, i) => {
    const anterior = snaps[i + 1];
    const diff = anterior ? diffSnapshots(s.dados, anterior.dados) : null;
    return {
      ts: s.ts, motivo: s.motivo, total: s.total,
      novos: diff ? diff.novos : null,
      removidos: diff ? diff.removidos : null,
      primeiro: !anterior,
    };
  });
}
async function lerBackupManutencao(ts) {
  if (USE_MONGO) {
    if (!mongoCol) return null;
    const d = await mongoCol.findOne({ _id: 'manutencao_bak_' + ts });
    return d && Array.isArray(d.manutencao) ? d.manutencao : null;
  }
  try { const o = JSON.parse(fs.readFileSync(path.join(MNT_BAK_DIR, `manutencao-${ts}.json`), 'utf-8')); return Array.isArray(o.manutencao) ? o.manutencao : null; }
  catch (e) { return null; }
}

