// ----- Mídia (fotos/comprovantes) — UM documento por arquivo, FORA do cache mem -----
// Com o R2 ligado (COFRE_R2, ver docs/ARQUIVOS_R2.md): o arquivo vai em binário para o bucket,
// chave midia/<id>. Sem ele — e, com ele, como LEITURA DE RESERVA do acervo ainda não copiado —
// o armazenamento antigo: Mongo doc _id:'midia_<id>' (lido sob demanda, nunca no boot) ou,
// no modo local, uploads/<id>.json. O antigo guarda base64 num doc por arquivo (respeita o
// limite de 16 MB do Mongo e não incha a memória do servidor).
// Todas as funções abaixo devolvem/recebem o MESMO formato {tipo, nome, b64, ts} nos dois
// armazenamentos, então as ~30 chamadas espalhadas pelo server.js não sabem onde o arquivo mora.
const MIDIA_MAX_BYTES = 9 * 1024 * 1024; // ~9 MB por arquivo (folga p/ o limite de 16 MB)
function caminhoMidiaLocal(id) {
  return path.join(UPLOADS_DIR, String(id).replace(/[^a-zA-Z0-9_-]/g, '') + '.json');
}
// Com o R2 ligado grava SÓ no bucket: o armazenamento antigo não recebe mais nada. Falha do R2
// aqui é erro de gravação comum (rota() → 500 "Falha ao salvar"), sem recair no Mongo às
// escondidas — senão o banco voltaria a encher sem ninguém perceber.
// USO: await salvarMidia('MD-0a1b…', { tipo: 'image/png', nome: 'foto.png', b64: buf.toString('base64'), ts: Date.now() })
async function salvarMidia(id, obj) {
  if (COFRE_R2) {
    const chave = CofreMidia.chaveMidia(id);
    if (!chave) throw new Error('salvarMidia: id de mídia vazio');
    await COFRE_R2.gravar(chave, { buf: Buffer.from(String(obj.b64 || ''), 'base64'), tipo: obj.tipo, nome: obj.nome, ts: obj.ts || Date.now() });
    if (!BUCKET_ARQ_MARCADO) marcarBucketComArquivos(); // 1º envio que deu certo (sem esperar; não lança)
    return;
  }
  if (USE_MONGO) { await persistMongo('midia_' + id, obj); return; }
  try { if (!fs.existsSync(UPLOADS_DIR)) fs.mkdirSync(UPLOADS_DIR, { recursive: true }); } catch (e) { /* ignora */ }
  escreverJSONAtomico(caminhoMidiaLocal(id), obj);
}
// Erro tipado: o cofre de mídia (Mongo/disco) está TEMPORARIAMENTE indisponível — o arquivo
// pode muito bem existir. É diferente de `null` (cofre respondeu e o arquivo NÃO está lá).
// O wrapper rota() converte este erro em HTTP 503 com mensagem honesta; antes, indisponibilidade
// virava o mesmo `null` de "arquivo apagado" e o usuário lia "foram removidos, peça reenvio".
//
// USO:
//   try { const m = await lerMidia(id); }               // null = não existe (ausência REAL)
//   catch (e) {
//     if (e.codigo === 'COFRE_INDISPONIVEL') { ... }    // infra fora do ar → 503 (rota() já faz)
//     else throw e;                                     // bug/estrutura → 500 (não mascarar)
//   }
class ErroCofreIndisponivel extends Error {
  constructor(motivo, causa) {
    super('Cofre de mídia indisponível: ' + motivo);
    this.codigo = 'COFRE_INDISPONIVEL';
    if (causa) this.cause = causa;
  }
}
// Classifica um erro do driver do Mongo como indisponibilidade de INFRAESTRUTURA (rede, socket,
// seleção de servidor, timeout, maxTimeMS estourado). Qualquer outro erro NÃO é reclassificado:
// esconder um bug atrás de "tente de novo em instantes" só atrasaria o diagnóstico.
function ehErroInfraMongo(e) {
  if (!e) return false;
  const nome = String(e.name || '');
  if (/^Mongo(NetworkError|NetworkTimeoutError|ServerSelectionError|TopologyClosedError|NotConnectedError|ExpiredSessionError)$/.test(nome)) return true;
  if (e.code === 50 || e.codeName === 'MaxTimeMSExpired') return true; // maxTimeMS estourou no servidor
  const msg = String(e.message || '');
  return /\b(ECONNREFUSED|ECONNRESET|ETIMEDOUT|EPIPE|EHOSTUNREACH|ENETUNREACH|EAI_AGAIN)\b|socket (closed|timed out)|server selection timed out|topology (was |is )?(closed|destroyed)/i.test(msg);
}
async function lerMidia(id) {
  // Gancho de TESTE (test/cofre-midia.test.js): simula o cofre fora do ar de forma determinística
  // — permissão de arquivo (chmod) e queda de Mongo variam entre Windows/Linux/CI e não dão um
  // teste estável. Exige NODE_ENV=test: em produção a variável sozinha NÃO tem efeito (uma env
  // errada no Render não pode derrubar o cofre).
  if (process.env.NODE_ENV === 'test' && process.env.TESTE_COFRE_INDISPONIVEL === '1') throw new ErroCofreIndisponivel('simulação de teste (TESTE_COFRE_INDISPONIVEL=1)');
  // R2 primeiro. Ausente lá → procura no armazenamento antigo (acervo ainda não copiado).
  // R2 fora do ar → procura no antigo mesmo assim (a maior parte do acervo pode estar lá, íntegra:
  // os ids nunca se repetem, então o que o antigo tiver é o mesmo arquivo); só se lá também não
  // houver é que vira 503 honesto — a ausência no antigo não prova que foi removido.
  let erroR2 = null;
  const chave = COFRE_R2_LEITURA ? CofreMidia.chaveMidia(id) : '';
  if (chave) {
    const { valor: m, erro } = await leituraR2((c) => c.ler(chave));
    erroR2 = erro || null;
    if (m) return { tipo: m.tipo, nome: m.nome, b64: m.buf.toString('base64'), ts: m.ts };
  }
  const antiga = await lerMidiaAntiga(id);
  if (!antiga && erroR2) throw new ErroCofreIndisponivel(`falha ao ler do R2 (${erroR2.codigo || erroR2.status || 'erro'})`, erroR2);
  // Há anexos só num bucket que esta instância não lê: "não achei aqui" não prova que foi
  // removido — é indisponibilidade (503), não 404 "não está mais no cofre".
  if (!antiga && AVISO_ACERVO_R2) throw new ErroCofreIndisponivel(AVISO_ACERVO_R2);
  return antiga;
}
// O armazenamento antigo (Mongo `midia_<id>` ou data/uploads/<id>.json). Mesma semântica do
// lerMidia: null = ausência real; ErroCofreIndisponivel = infraestrutura fora do ar.
// USO: await lerMidiaAntiga('MD-0a1b…') // => { tipo, nome, b64 } | null
async function lerMidiaAntiga(id) {
  if (USE_MONGO) {
    // Com o servidor de pé, mongoCol NUNCA é null: boot() conecta ANTES do app.listen e faz
    // process.exit(1) se falhar. Chegar aqui com null é bug de ciclo de vida → erro interno
    // (500), não indisponibilidade — não mascarar como 503.
    if (!mongoCol) throw new Error('lerMidia: mongoCol não inicializado (bug de lifecycle — boot() deveria ter conectado antes do listen)');
    let doc;
    try {
      doc = await mongoCol.findOne({ _id: 'midia_' + id }, { maxTimeMS: 15000 });
    } catch (e) {
      if (ehErroInfraMongo(e)) throw new ErroCofreIndisponivel('falha de rede/timeout no MongoDB', e);
      throw e; // erro de programação/estrutura → propaga como 500
    }
    return doc ? { tipo: doc.tipo, nome: doc.nome, b64: doc.b64 } : null;
  }
  try { return JSON.parse(fs.readFileSync(caminhoMidiaLocal(id), 'utf-8')); }
  catch (e) {
    if (e && e.code === 'ENOENT') return null; // arquivo não existe → ausência REAL
    if (e && ['EACCES', 'EPERM', 'EIO', 'EMFILE', 'ENFILE', 'EBUSY', 'EAGAIN', 'ENOTDIR'].includes(e.code)) {
      throw new ErroCofreIndisponivel(`falha de acesso ao uploads/ (${e.code})`, e);
    }
    throw e; // JSON corrompido e afins → erro interno (500), não "indisponível"
  }
}
// Existência BARATA no cofre, sem trafegar o base64 (Mongo: projeção só do _id; local: stat).
// Usada como PRÉ-CHECAGEM dos downloads em streaming: decide 404 ("não estão mais no cofre")
// e 503 (cofre indisponível) ANTES de enviar os cabeçalhos do .zip — depois que o streaming
// começa, já não dá para trocar a resposta por um JSON de erro. Mesma semântica do lerMidia:
// false = ausência REAL; ErroCofreIndisponivel = infraestrutura fora do ar (vira 503 na rota()).
//
// USO: if (await existeMidia('MD-ab12…')) { /* o arquivo está lá; lerMidia vai encontrá-lo */ }
async function existeMidia(id) {
  if (process.env.NODE_ENV === 'test' && process.env.TESTE_COFRE_INDISPONIVEL === '1') throw new ErroCofreIndisponivel('simulação de teste (TESTE_COFRE_INDISPONIVEL=1)');
  let erroR2 = null;
  const chave = COFRE_R2_LEITURA ? CofreMidia.chaveMidia(id) : '';
  if (chave) { // HEAD: só metadados, sem baixar o arquivo
    const { valor: h, erro } = await leituraR2((c) => c.cabeca(chave));
    erroR2 = erro || null;
    if (h) return true;
  }
  const naAntiga = await existeMidiaAntiga(id);
  if (!naAntiga && erroR2) throw new ErroCofreIndisponivel(`falha ao consultar o R2 (${erroR2.codigo || erroR2.status || 'erro'})`, erroR2); // ver lerMidia
  if (!naAntiga && AVISO_ACERVO_R2) throw new ErroCofreIndisponivel(AVISO_ACERVO_R2); // ver lerMidia
  return naAntiga;
}
// Existência só no armazenamento antigo (Mongo: projeção do _id; local: stat), sem o R2.
// USO: await existeMidiaAntiga('MD-0a1b…') // => true | false (ErroCofreIndisponivel se a infra caiu)
async function existeMidiaAntiga(id) {
  if (USE_MONGO) {
    if (!mongoCol) throw new Error('existeMidia: mongoCol não inicializado (bug de lifecycle — boot() deveria ter conectado antes do listen)');
    try {
      return !!(await mongoCol.findOne({ _id: 'midia_' + id }, { projection: { _id: 1 }, maxTimeMS: 15000 }));
    } catch (e) {
      if (ehErroInfraMongo(e)) throw new ErroCofreIndisponivel('falha de rede/timeout no MongoDB', e);
      throw e;
    }
  }
  try { fs.statSync(caminhoMidiaLocal(id)); return true; }
  catch (e) {
    if (e && e.code === 'ENOENT') return false;
    if (e && ['EACCES', 'EPERM', 'EIO', 'EMFILE', 'ENFILE', 'EBUSY', 'EAGAIN', 'ENOTDIR'].includes(e.code)) {
      throw new ErroCofreIndisponivel(`falha de acesso ao uploads/ (${e.code})`, e);
    }
    throw e;
  }
}
// Best-effort (o que falhar aqui a faxina diária de órfãs apaga depois). Durante a migração o
// arquivo pode estar nos DOIS armazenamentos: apaga dos dois, senão a leitura de reserva
// "ressuscitaria" o anexo excluído.
// USO: await excluirMidia('MD-0a1b…')   // dentro de rota com Desfazer, vai para a quarentena
async function excluirMidia(id) {
  if (!id) return;
  try {
    const contextoUndo = UNDO_CONTEXTO.getStore();
    if (contextoUndo && await quarentenarMidiaUndo(contextoUndo, id)) return;
  } catch (e) { return; /* best-effort, como sempre foi: na dúvida não apaga */ }
  if (COFRE_R2) {
    try { const chave = CofreMidia.chaveMidia(id); if (chave) await COFRE_R2.apagar(chave); } catch (e) { /* best-effort */ }
  }
  try {
    if (USE_MONGO) { if (mongoCol) await mongoCol.deleteOne({ _id: 'midia_' + id }); }
    else { const p = caminhoMidiaLocal(id); if (fs.existsSync(p)) fs.unlinkSync(p); }
  } catch (e) { /* best-effort */ }
}
function gerarIdMidia() {
  return 'MD-' + crypto.randomBytes(8).toString('hex');
}

// ----- Cofre no boot: teste do bucket + marcador `cofre_r2` no Mongo -----
// As regras são puras e testadas (backend/cofre-midia.js: bucketComArquivos, decisaoTesteBoot,
// avisoArquivosForaDeAlcance, marcadorPermiteApagar; test/cofre-r2.test.js). O marcador diz:
//   · qual bucket o SITE (a instância do Render) lê e se está saudável — ativo/bucket/origem/
//     render/commit/bootTs e vistoTs (renovado a cada 5 min). É o que o
//     scripts/migrar-midia-r2.js --apagar-do-mongo exige antes de apagar o acervo antigo;
//   · bucketArquivos: gravado UMA vez, na 1ª subida com o R2 ligado. Dali em diante há anexos
//     que só existem naquele bucket (todo envio vai só para lá), e perder o acesso a ele não pode
//     virar "arquivo removido" (404): vira AVISO_ACERVO_R2 e leitura 503 "indisponível".
//   · acervoNoR2/acervoBucket: gravados pelo script antes de apagar o acervo do Mongo.
// Só a instância do Render GRAVA o marcador: um `npm run dev` ligado no Mongo de produção não
// pode dizer ao script que "o site" lê do R2.
const ID_MARCADOR_COFRE = 'cofre_r2';
const INSTANCIA_RENDER = process.env.RENDER === 'true'; // o Render define RENDER=true em todo serviço
let MARCADOR_COFRE = null; // o marcador como estava no boot (antes desta instância gravar)
let COFRE_TESTE_OK = false; // o teste do boot gravou, releu e apagou no bucket (ele respondeu de fato)
let BUCKET_ARQ_MARCADO = false; // marcarBucketComArquivos() já rodou nesta instância
let AVISO_ACERVO_R2 = ''; // há anexos só num bucket que esta instância não lê → leitura ausente vira 503

// USO: await prepararCofreNoBoot()  // em boot(), com o Mongo conectado, antes do listen
async function prepararCofreNoBoot() {
  if (USE_MONGO && mongoCol) {
    try { MARCADOR_COFRE = await mongoCol.findOne({ _id: ID_MARCADOR_COFRE }); }
    catch (e) { console.error('[cofre] marcador do R2 não lido:', e.message); }
  }
  await conferirCofreNoBoot();
  AVISO_ACERVO_R2 = CofreMidia.avisoArquivosForaDeAlcance(MARCADOR_COFRE, COFRE_R2 ? COFRE_R2.bucket : '');
  if (AVISO_ACERVO_R2) console.error('ATENÇÃO: ' + AVISO_ACERVO_R2);
  try { await registrarEstadoCofreR2(); } catch (e) { console.error('[cofre] marcador do R2 não gravado:', e.message); }
}

// Confere o bucket UMA vez no boot (grava, relê e apaga um objeto de teste), com prazo curto para
// não segurar a subida. A decisão (decisaoTesteBoot):
//   passageiro (rede, prazo, 5xx) → o R2 fica LIGADO: desligar mandaria arquivo novo ao Mongo às escondidas;
//   desligar (config errada, bucket ainda sem anexo exclusivo) → volta ao armazenamento antigo, com
//     aviso. Sem isso, TODO download (até os antigos, que a reserva serviria) virava "indisponível";
//   manter (config errada, mas o bucket JÁ tem anexos que só existem nele) → fica ligado e quebrado,
//     de propósito: leitura 503 honesto e envio com erro, em vez de 404 "removido" nesses anexos.
// USO: await conferirCofreNoBoot()  // chamada por prepararCofreNoBoot()
async function conferirCofreNoBoot() {
  if (!COFRE_R2) return;
  const testar = () => CofreMidia.criarCofre(COFRE_CFG, { timeoutMs: 10000, retentativas: 0 }).testar();
  try {
    try { await testar(); }
    catch (e) {
      // ENOTFOUND de passagem (DNS sobrecarregado, contêiner recém-criado) não pode desligar o
      // R2 até o próximo deploy: repete uma vez, 3 s depois. Endereço errado de verdade repete o erro.
      if (!(e && e.codigo === 'REDE' && e.causa === 'ENOTFOUND')) throw e;
      await new Promise((ok) => setTimeout(ok, 3000));
      await testar();
    }
    COFRE_TESTE_OK = true;
  } catch (e) {
    const decisao = CofreMidia.decisaoTesteBoot(e, COFRE_R2.bucket, MARCADOR_COFRE);
    if (decisao === 'passageiro') {
      console.warn(`AVISO: o teste do R2 no boot não respondeu (${e.message}). O R2 segue ligado.`);
    } else if (decisao === 'manter') {
      Object.assign(COFRE_CFG, { erro: true, motivo: `O R2 recusou o acesso no boot. ${e.message} Ele segue ligado porque há anexos que só existem nele: até a configuração ser corrigida, esses anexos respondem "cofre indisponível" e os envios falham.` });
    } else {
      COFRE_R2 = null;
      COFRE_R2_LEITURA = null;
      Object.assign(COFRE_CFG, { ativo: false, erro: true, motivo: `O R2 recusou o acesso no boot e ficou desligado. ${e.message}` });
    }
  }
}

// USO: await registrarEstadoCofreR2()  // chamada por prepararCofreNoBoot(); só grava no Render
//   doc: { _id:'cofre_r2', ativo, bucket, origem, render:true, commit, bootTs, vistoTs, bucketArquivos?, … }
async function registrarEstadoCofreR2() {
  if (!USE_MONGO || !mongoCol || !INSTANCIA_RENDER) return;
  const agora = Date.now();
  await mongoCol.updateOne({ _id: ID_MARCADOR_COFRE }, { $set: {
    ativo: !!COFRE_R2 && !COFRE_CFG.erro, // ligado e SAUDÁVEL (o "manter" quebrado não libera o apagar)
    bucket: COFRE_R2 ? COFRE_R2.bucket : '', origem: COFRE_R2 ? COFRE_R2.origem : '',
    render: true, commit: process.env.RENDER_GIT_COMMIT || '', bootTs: agora, vistoTs: agora,
  } }, { upsert: true });
  // Só com o bucket tendo RESPONDIDO no teste (num boot "passageiro" ele nunca respondeu e nada
  // chegou lá; o salvarMidia marca no 1º envio que der certo).
  if (COFRE_R2 && COFRE_TESTE_OK) await marcarBucketComArquivos();
  // Sinal de vida para o script — só do registro que ESTA instância gravou (bootTs igual): se um
  // deploy novo regravou o marcador e falhou (o Render mantém esta instância no ar), renovar o
  // estado DELE diria ao script que o site lê um bucket que ele não lê. Assim ele envelhece.
  setInterval(() => {
    mongoCol.updateOne({ _id: ID_MARCADOR_COFRE, bootTs: agora }, { $set: { vistoTs: Date.now() } }).catch(() => {});
  }, 5 * 60 * 1000).unref();
}

// Grava UMA vez, e nunca troca nem apaga, que o bucket passou a ter anexos que só existem nele
// (ver o comentário do bloco). Chamada no boot com o teste aprovado e pelo salvarMidia no 1º envio
// que der certo; em qualquer instância com Mongo (é fato sobre os DADOS, não sobre quem é o site).
// USO: await marcarBucketComArquivos()  // idempotente; erro não interrompe quem chamou
async function marcarBucketComArquivos() {
  if (BUCKET_ARQ_MARCADO || !USE_MONGO || !mongoCol || !COFRE_R2) return;
  BUCKET_ARQ_MARCADO = true;
  try {
    // Uma operação só: grava se o doc não existe (upsert) ou existe sem bucketArquivos. Se ele já
    // tem bucketArquivos, o filtro não casa, o upsert tenta inserir o mesmo _id e o Mongo responde
    // chave duplicada (11000) — "já estava marcado", sucesso. Qualquer outro erro (rede, prazo)
    // cai no catch de baixo e o próximo envio tenta de novo.
    await mongoCol.updateOne(
      { _id: ID_MARCADOR_COFRE, bucketArquivos: { $exists: false } },
      { $set: { bucketArquivos: COFRE_R2.bucket, bucketArquivosDesde: Date.now() } },
      { upsert: true },
    ).catch((e) => { if (!(e && e.code === 11000)) throw e; });
  } catch (e) {
    BUCKET_ARQ_MARCADO = false; // tenta de novo no próximo envio
    console.error('[cofre] marcador bucketArquivos não gravado:', e.message);
  }
}
// ID único e estável para entidades. Sem colisão por milissegundo (ao contrário de
// Date.now()+Math.random()*1000): timestamp base36 (ordenável) + 40 bits aleatórios.
function gerarId(prefixo) { return prefixo + Date.now().toString(36) + crypto.randomBytes(5).toString('hex'); }

// ----- Cadastros (centros de custo e responsáveis) -----
function lerCadastros() {
  let base = { centrosCusto: [], responsaveis: [], motoristas: [], contratosFuncionarios: [] };
  if (USE_MONGO) {
    base = mem.cadastros || base;
  } else {
    try {
      const obj = JSON.parse(fs.readFileSync(CAD_FILE, 'utf-8'));
      base = {
        centrosCusto: Array.isArray(obj.centrosCusto) ? obj.centrosCusto : [],
        responsaveis: Array.isArray(obj.responsaveis) ? obj.responsaveis : [],
        motoristas: Array.isArray(obj.motoristas) ? obj.motoristas : [],
        contratosFuncionarios: normalizarCatalogoContratosFunc(obj.contratosFuncionarios),
      };
    } catch (e) { /* arquivo ainda não existe */ }
  }
  return {
    centrosCusto: base.centrosCusto || [],
    responsaveis: base.responsaveis || [],
    motoristas: base.motoristas || [],
    contratosFuncionarios: normalizarCatalogoContratosFunc(base.contratosFuncionarios),
  };
}
async function salvarCadastros(cad) {
  const atual = lerCadastros();
  const dados = {
    centrosCusto: cad.centrosCusto || [],
    responsaveis: cad.responsaveis || [],
    motoristas: cad.motoristas || [],
    contratosFuncionarios: normalizarCatalogoContratosFunc(cad.contratosFuncionarios !== undefined ? cad.contratosFuncionarios : atual.contratosFuncionarios),
  };
  if (USE_MONGO) {
    mem.cadastros = dados;
    await persistMongo('cadastros', dados);
  } else {
    escreverJSONAtomico(CAD_FILE, dados);
  }
  notificarDados('cadastros');
}

// ===================== USUÁRIOS (login com aprovação) =====================
// Hash de senha com PBKDF2 (nativo do Node, sem dependência). Nunca guarda
// a senha em texto puro — só o hash + um salt aleatório por usuário.
function hashSenha(senha, salt) {
  salt = salt || crypto.randomBytes(16).toString('hex');
  const hash = crypto.pbkdf2Sync(String(senha), salt, 100000, 32, 'sha256').toString('hex');
  return { salt, hash };
}
function conferirSenha(senha, salt, hash) {
  if (!salt || !hash) return false;
  const h = crypto.pbkdf2Sync(String(senha), salt, 100000, 32, 'sha256').toString('hex');
  const a = Buffer.from(h), b = Buffer.from(hash);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
// Comparação de strings em tempo constante (não vaza tamanho/conteúdo pelo tempo).
// Compara hashes de 32 bytes p/ o timingSafeEqual aceitar tamanhos diferentes.
function igualSeguro(a, b) {
  a = String(a); b = String(b);
  const ha = crypto.createHash('sha256').update(a).digest();
  const hb = crypto.createHash('sha256').update(b).digest();
  return crypto.timingSafeEqual(ha, hb) && a.length === b.length;
}
// Normaliza o nome de usuário: minúsculas, sem espaços/acentos/símbolos.
function normalizaUsuario(v) {
  return String(v || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9_.-]/g, '');
}
// Lê o "cofre" de usuários. Garante SEMPRE o admin semeado (não precisa estar
// salvo no banco/arquivo) — a senha dele vem do ambiente, não fica gravada.
function lerUsuarios() {
  let store;
  if (USE_MONGO) {
    store = mem.usuarios || { usuarios: [], cadastrosAbertos: true };
  } else {
    try {
      const o = JSON.parse(fs.readFileSync(USU_FILE, 'utf-8'));
      store = { usuarios: Array.isArray(o.usuarios) ? o.usuarios : [], cadastrosAbertos: o.cadastrosAbertos !== false };
    } catch (e) { store = { usuarios: [], cadastrosAbertos: true }; }
  }
  if (!store.usuarios.some(u => u.senhaEnv)) {
    store = {
      cadastrosAbertos: store.cadastrosAbertos,
      usuarios: [{ usuario: ADMIN_USUARIO, nome: ADMIN_NOME, nivel: 'admin', status: 'aprovado', senhaEnv: true, criadoEm: 0, id: 'U-ADMIN' }, ...store.usuarios],
    };
  }
  return store;
}
// Gera um ID curto e único para o usuário (ex.: "U-3F9A2C"). Serve para
// diferenciar pessoas com o mesmo nome e para controle interno.
function gerarIdUsuario(store) {
  const usados = new Set((store.usuarios || []).map(u => u.id).filter(Boolean));
  let id;
  do { id = 'U-' + crypto.randomBytes(3).toString('hex').toUpperCase(); } while (usados.has(id));
  return id;
}
async function salvarUsuarios(store) {
  const dados = { usuarios: store.usuarios || [], cadastrosAbertos: store.cadastrosAbertos !== false };
  if (USE_MONGO) {
    mem.usuarios = dados;
    await persistMongo('usuarios', dados);
    return;
  }
  escreverJSONAtomico(USU_FILE, dados);
}
function acharUsuario(usuario) {
  const u = normalizaUsuario(usuario);
  if (!u) return null;
  return lerUsuarios().usuarios.find(x => x.usuario === u) || null;
}

// Valores realmente em uso (para unir com a lista cadastrada e para travar exclusão)
// Centros de custo em uso = veículos + eventos de manutenção + abastecimento (os três lugares
// onde o campo existe) — assim dá para renomear/excluir pelo Cadastros um centro que só
// aparece em registros importados por planilha.
function centrosEmUso() {
  const nomes = [];
  for (const v of lerDados().veiculos) { const c = (v.centroCusto || '').trim(); if (c) nomes.push(c); }
  for (const e of lerManutencao()) { const c = (e.centroCusto || '').trim(); if (c) nomes.push(c); }
  for (const t of lerAbastecimento()) { const c = (t.centroCusto || '').trim(); if (c) nomes.push(c); }
  return [...new Set(nomes)];
}
function responsaveisEmUso() {
  return [...new Set(lerMultas().map(m => (m.responsavel || '').trim()).filter(Boolean))];
}
// Motoristas realmente em uso = os que aparecem em Manutenção e Abastecimento (ignora vazio e "—").
function motoristasEmUso() {
  const nomes = [];
  for (const e of lerManutencao()) { const m = (e.motorista || '').trim(); if (m && m !== '—') nomes.push(m); }
  for (const t of lerAbastecimento()) { const m = (t.motorista || '').trim(); if (m && m !== '—') nomes.push(m); }
  return [...new Set(nomes)];
}
// Valores em uso conforme a categoria do cadastro.
function emUsoDoTipo(tipo) {
  if (tipo === 'centrosCusto') return centrosEmUso();
  if (tipo === 'motoristas') return motoristasEmUso();
  return responsaveisEmUso();
}
// Lista final exibida = cadastrados + em uso, sem duplicar, ordenada
function listaCadastro(tipo) {
  const cad = lerCadastros();
  const salvos = cad[tipo] || [];
  const usados = emUsoDoTipo(tipo);
  const mapa = new Map();
  for (const n of [...salvos, ...usados]) {
    const v = String(n || '').trim();
    if (v && !mapa.has(v.toUpperCase())) mapa.set(v.toUpperCase(), v);
  }
  return [...mapa.values()].sort((a, b) => a.localeCompare(b, 'pt-BR'));
}

function normalizarRastreador(r) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return {
    id: s(r.id) || gerarId('R'),
    codigo: s(r.codigo),
    esn: s(r.esn),
    versao: s(r.versao),
    placa: limpaPlaca(r.placa),
    tipo: s(r.tipo) || 'Instalado',
    situacao: s(r.situacao) || 'Ativo',
    dataPedidoDevolucao: s(r.dataPedidoDevolucao),
    dataDevolucao: s(r.dataDevolucao),
    protocolo: s(r.protocolo),
    substituidoPor: s(r.substituidoPor),
    veiculoDestino: s(r.veiculoDestino).toUpperCase(),
    observacoes: s(r.observacoes),
    // Desativado = saiu do painel (devolvido à empresa / extraviado); fica na sub-aba
    // "Desativados" com a data em que foi movido. A placa preserva o veículo a que pertencia.
    desativado: r.desativado === true || r.desativado === 'true' || r.desativado === 1 || r.desativado === '1',
    desativadoEm: s(r.desativadoEm),
  };
}

// Limpa placa: maiúsculas e sem placeholders. "-", "—", "--", espaços -> "" (sem placa).
function limpaPlaca(v) {
  const p = (v === undefined || v === null ? '' : String(v)).trim().toUpperCase();
  return /[A-Z0-9]/.test(p) ? p : '';
}
// Converte datas (ex.: "2026-01-27 00:00:00" -> "27/01/2026"); mantém dd/mm/aaaa
function fmtDataBR(v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  if (!s) return '';
  if (s.length >= 10 && s[4] === '-') {
    const dp = s.split(' ')[0].split('-');
    if (dp.length === 3) return `${String(dp[2]).padStart(2, '0')}/${String(dp[1]).padStart(2, '0')}/${dp[0]}`;
  }
  return s;
}
// Normaliza tipo e situação para os valores padrão (tolerante a acentos/maiúsculas)
function normTipoRast(v) {
  const u = normalizarChave(v);
  if (u.includes('REMOV')) return 'Removível';
  if (u.includes('INSTAL')) return 'Instalado';
  return v ? String(v).trim() : 'Instalado';
}
function normSitRast(v) {
  const u = normalizarChave(v);
  if (u.includes('ATIVO')) return 'Ativo';
  if (u.includes('DEVOLV')) return 'Devolvido';
  if (u.includes('TROC')) return 'Trocado';
  if (u.includes('TRANSFER')) return 'Transferido';
  if (u.includes('EXTRAV')) return 'Extraviado';
  if (u.includes('NOVO')) return 'Novo';
  if (u.includes('REMOV')) return 'Removido';
  return v ? String(v).trim() : 'Ativo';
}
// Normaliza nome de coluna p/ casar cabeçalhos (remove acentos, símbolos como ° º, espaços extras)
function chaveCol(s) {
  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9 ]/gi, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
}
// Identificador único do rastreador: SEMPRE o Código/ID (que armazena o N° Cobli)
function chaveRast(r) {
  return String((r.codigo || '')).trim().toUpperCase();
}
// Mapa de cabeçalhos aceitos -> campo interno do rastreador
// N° Cobli é mapeado para "codigo" (identificador principal).
function mapaRotulosRast() {
  const sin = [
    ['esn', ['ESN']],
    ['versao', ['VERSAO', 'VERSAO DO VEICULO']],
    ['codigo', ['N COBLI', 'NUMERO COBLI', 'COBLI', 'NO COBLI', 'CODIGO', 'CODIGO ID', 'ID', 'CODIGO DO RASTREADOR', 'RASTREADOR']],
    ['placa', ['PLACA', 'PLACA DO VEICULO', 'PLACA VEICULO']],
    ['tipo', ['TIPO', 'TIPO DO RASTREADOR', 'TIPO DE DISPOSITIVO', 'TIPO DISPOSITIVO']],
    ['situacao', ['SITUACAO']],
    ['dataPedidoDevolucao', ['DATA DO PEDIDO DE DEVOLUCAO', 'PEDIDO DE DEVOLUCAO', 'PEDIDO DEVOLUCAO', 'DATA PEDIDO DEVOLUCAO']],
    ['dataDevolucao', ['DATA DA DEVOLUCAO', 'DATA DEVOLUCAO', 'DEVOLUCAO']],
    ['protocolo', ['PROTOCOLO', 'PROTOCOLO DA DEVOLUCAO', 'NUMERO DO PROTOCOLO']],
    ['substituidoPor', ['RASTREADOR SUBSTITUTO', 'SUBSTITUIDO POR', 'SUBSTITUTO']],
    ['veiculoDestino', ['VEICULO DE DESTINO', 'VEICULO DESTINO', 'PLACA DE DESTINO']],
    ['observacoes', ['OBSERVACOES', 'OBSERVACAO', 'OBS']],
  ];
  const mapa = {};
  for (const [campo, nomes] of sin) for (const n of nomes) mapa[chaveCol(n)] = campo;
  return mapa;
}
// Normaliza um rastreador vindo de planilha (sem id; pronto para criar/atualizar)
function normalizarRastreadorImport(r) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return {
    codigo: s(r.codigo),
    esn: s(r.esn),
    versao: s(r.versao),
    placa: limpaPlaca(r.placa),
    tipo: normTipoRast(r.tipo),
    situacao: normSitRast(r.situacao),
    dataPedidoDevolucao: fmtDataBR(r.dataPedidoDevolucao),
    dataDevolucao: fmtDataBR(r.dataDevolucao),
    protocolo: s(r.protocolo),
    substituidoPor: s(r.substituidoPor),
    veiculoDestino: s(r.veiculoDestino).toUpperCase(),
    observacoes: s(r.observacoes),
    // A planilha só manda na situação quando a coluna veio preenchida (ver o "aplicar").
    situacaoInformada: !!s(r.situacao),
  };
}

// Anexos da multa (notificação, boleto, comprovante de pagamento, termo assinado, foto...).
// MESMO formato dos documentos do colaborador — ref de mídia + categoria + versionamento por
// substituição — daí o reuso de normalizarVersaoDoc/idsMidiaDoc no resto do arquivo. O que NÃO
// vem para cá é a validade obrigatória: anexo de multa comprova um fato passado, não vence (e por
// isso também não existe "item só de controle" sem arquivo, como na ficha do colaborador).
// A categoria é texto livre (a lista mora no <select> do cliente): renomear/ampliar a lista depois
// não invalida o que já está gravado nem exige migração.
function normalizarDocsMulta(arr) {
  if (!Array.isArray(arr)) return [];
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  return arr
    .map(d => ({
      id: s(d && d.id),
      nome: s(d && d.nome).slice(0, 120),
      tipo: s(d && d.tipo),
      categoria: s(d && d.categoria).slice(0, 40) || 'Outro',
      nomeOriginal: s(d && d.nomeOriginal),
      uploadTs: Number(d && d.uploadTs) || 0,
      uploadPor: s(d && d.uploadPor),
      versoes: Array.isArray(d && d.versoes) ? d.versoes.map(normalizarVersaoDoc).filter(v => v.id) : [],
    }))
    .filter(d => d.id); // sem arquivo no cofre não é anexo
}
// "hoje" em dd/mm/aaaa (fuso de Brasília) — as datas de multa são sempre dd/mm/aaaa (nunca ISO).
function hojeBRMulta() {
  const [a, mm, d] = hojeISO_BR().split('-');
  return `${d}/${mm}/${a}`;
}
function normalizarMulta(m) {
  const s = (x) => (x === undefined || x === null ? '' : String(x).trim());
  const num = (x) => { const n = Number(x); return isNaN(n) ? 0 : n; };
  const b = (x) => (x === true || x === 'true' || x === 'on' || x === 1 || x === '1');
  return {
    id: s(m.id) || gerarId('M'),
    placa: s(m.placa).toUpperCase(),
    responsavel: s(m.responsavel),
    autoInfracao: s(m.autoInfracao),
    descricao: s(m.descricao),
    dataInfracao: s(m.dataInfracao),
    horaInfracao: s(m.horaInfracao),
    local: s(m.local),
    cidadeEstado: s(m.cidadeEstado),
    // Dados da notificação de autuação que o termo de responsabilidade pede (1.55.49; o OCR do
    // print também os lê). Ex.: { codigoInfracao: '5002-0', orgaoAutuador: '000300 - DEPARTAMENTO NACIONAL
    // DE INFRA-ESTRUTURA DE TRANSP', dataNotificacao: '08/10/2025' }. Vazios em multa antiga (sem migração).
    codigoInfracao: s(m.codigoInfracao),
    orgaoAutuador: s(m.orgaoAutuador),
    dataNotificacao: s(m.dataNotificacao),
    valor: num(m.valor),
    situacao: s(m.situacao).toUpperCase() || 'PENDENTE',
    formaPagamento: s(m.formaPagamento),
    dataVencimento: s(m.dataVencimento),
    dataPagamento: s(m.dataPagamento),
    observacao: s(m.observacao),
    // Status do Processo no Detran: cada etapa = status (bool) + data opcional + observação
    detranIdentificarOk: b(m.detranIdentificarOk),
    detranIdentificarData: s(m.detranIdentificarData),
    detranIdentificarObs: s(m.detranIdentificarObs),
    detranTermoEnviadoOk: b(m.detranTermoEnviadoOk),
    detranTermoEnviadoData: s(m.detranTermoEnviadoData),
    detranTermoEnviadoObs: s(m.detranTermoEnviadoObs),
    detranTermoAssinadoOk: b(m.detranTermoAssinadoOk),
    detranTermoAssinadoData: s(m.detranTermoAssinadoData),
    detranTermoAssinadoObs: s(m.detranTermoAssinadoObs),
    detranPedidoDescontoOk: b(m.detranPedidoDescontoOk),
    detranPedidoDescontoData: s(m.detranPedidoDescontoData),
    detranPedidoDescontoObs: s(m.detranPedidoDescontoObs),
    // Anexos (notificação, boleto, comprovante...). A edição inline da tabela manda a multa
    // inteira de volta, então o campo sobrevive a qualquer PUT vindo de lá.
    documentos: normalizarDocsMulta(m.documentos),
    // Funcionário condutor escolhido ao gerar o termo (1.55.49). Liga a multa ao cadastro de
    // Funcionários (o "Responsável" continua texto livre). Vazio = ainda sem vínculo; sem migração.
    // Ex.: { …, responsavel: 'Ana Souza', condutorFuncionarioId: 'F-1a2b3c' }
    condutorFuncionarioId: s(m.condutorFuncionarioId),
  };
}

function fmtValorHist(campo, v) {
  if (v === '' || v === null || v === undefined) return '(vazio)';
  if (campo === 'crlvDoc') return (v && v.nome) ? v.nome : '(sem CRLV)';
  if (campo === 'valorFipe') return 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR');
  if (campo === 'oficinaValorOrcamento') return 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (campo === 'pctRicardo' || campo === 'pctMarcelo') {
    return (pctFrota(v) * 100).toLocaleString('pt-BR', { maximumFractionDigits: 1 }) + '%';
  }
  if (['ipvaVenc', 'licencVenc', 'seguroVenc', 'oficinaDataEntrada', 'oficinaPrevisaoSaida'].includes(campo) && /^\d{4}-\d{2}-\d{2}$/.test(String(v))) {
    return String(v).split('-').reverse().join('/');
  }
  return String(v);
}

// Compara dois veículos e gera uma lista de entradas de histórico (uma por campo alterado)
function diffVeiculos(placa, antes, depois) {
  const entradas = [];
  const campos = ['placa', 'modelo', 'versao', 'anoFab', 'anoMod', 'cor', 'motor', 'tanque',
    'centroCusto', 'dono', 'renavam', 'chassi', 'valorFipe', 'doc',
    'ipvaVenc', 'licencVenc', 'seguroVenc', 'seguroApolice', 'status', 'oficinaPrevisaoSaida',
    'oficinaDataEntrada', 'oficinaValorOrcamento', 'oficinaMotivo', 'oficinaPrazoDias', 'gravame', 'banco', 'pctRicardo', 'pctMarcelo', 'observacoes', 'crlvDoc'];
  for (const campo of campos) {
    const a = antes[campo], b = depois[campo];
    const mudou = campo === 'crlvDoc'
      ? String((a && a.id) || '') !== String((b && b.id) || '')
      : String(a ?? '') !== String(b ?? '');
    if (mudou) {
      entradas.push({
        placa,
        acao: 'editou',
        texto: `${ROTULO_CAMPO[campo] || (campo === 'crlvDoc' ? 'CRLV' : campo)}: ${fmtValorHist(campo, a)} → ${fmtValorHist(campo, b)}`,
      });
    }
  }
  return entradas;
}

// Normaliza um veículo vindo do cliente, calculando valores derivados
function numBRVeiculo(x) {
  if (x === '' || x === null || x === undefined) return 0;
  if (typeof x === 'number') return Number.isFinite(x) ? x : 0;
  let s = String(x).trim().replace(/[^\d.,-]/g, '');
  if (!s) return 0;
  const temVirg = s.includes(','), temPonto = s.includes('.');
  if (temVirg && temPonto) {
    s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (temVirg) {
    s = s.replace(',', '.');
  } else if (temPonto) {
    const partes = s.split('.');
    const ehMilhar = partes.length > 1 && partes[0].length <= 3 && partes.slice(1).every(p => p.length === 3);
    if (ehMilhar) s = s.replace(/\./g, '');
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}
function pctFrota(v) {
  if (v === '' || v === null || v === undefined) return 0;
  const s = String(v).trim().replace('%', '');
  const n = Number(s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s);
  if (!Number.isFinite(n) || n <= 0) return 0;
  return n > 1 ? n / 100 : n;
}
function fipeFrota(v) {
  const n = Number(v) || 0;
  return n > 1000000 ? n / 100 : n;
}
// Data de vencimento legal do veículo: só aceita ISO aaaa-mm-dd (formato do input type=date).
function dataISOVeic(v) {
  const s = (v || '').toString().trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : '';
}
function normalizar(v) {
  const num = (x) => {
    if (x === '' || x === null || x === undefined) return 0;
    const n = Number(x);
    return isNaN(n) ? 0 : n;
  };
  const fipe = fipeFrota(numBRVeiculo(v.valorFipe));
  const pj = pctFrota(v.pctRicardo);
  const pd = pctFrota(v.pctMarcelo);
  const crlv = v.crlvDoc && v.crlvDoc.id
    ? { id: (v.crlvDoc.id || '').toString().trim(), nome: (v.crlvDoc.nome || '').toString().trim(), tipo: (v.crlvDoc.tipo || '').toString().trim() }
    : null;
  const status = (v.status || '').toString().trim();
  const oficinaPrevisaoSaida = dataISOVeic(v.oficinaPrevisaoSaida);
  const prazoInformado = Math.trunc(Number(v.oficinaPrazoDias));
  const oficinaPrazoDias = oficinaPrevisaoSaida && Number.isFinite(prazoInformado) && prazoInformado > 0 ? prazoInformado : null;
  return {
    placa: (v.placa || '').toString().trim().toUpperCase(),
    modelo: (v.modelo || '').toString().trim(),
    versao: (v.versao || '').toString().trim(),
    anoFab: v.anoFab === '' || v.anoFab == null ? null : num(v.anoFab),
    anoMod: v.anoMod === '' || v.anoMod == null ? null : num(v.anoMod),
    cor: (v.cor || '').toString().trim(),
    motor: (v.motor || '').toString().trim(),
    tanque: v.tanque === '' || v.tanque == null ? null : num(v.tanque),
    centroCusto: canonizarCentroCusto(v.centroCusto),
    dono: (v.dono || '').toString().trim(),
    renavam: (v.renavam || '').toString().trim(),
    chassi: (v.chassi || '').toString().trim(),
    valorFipe: fipe,
    // Vínculo com a tabela FIPE (API parallelum): codigoFipe é estável; fipeAno é o "yearId"
    // (ex.: "2018-3" = ano 2018, diesel). Com os três dá para atualizar o valor sozinho.
    codigoFipe: (v.codigoFipe || '').toString().trim(),
    fipeTipo: ['carros', 'motos', 'caminhoes'].includes(v.fipeTipo) ? v.fipeTipo : (v.codigoFipe ? 'carros' : ''),
    fipeAno: (v.fipeAno || '').toString().trim(),
    fipeAtualizadoEm: (v.fipeAtualizadoEm || '').toString().trim(),
    doc: v.doc === '' || v.doc == null ? null : num(v.doc),
    // Vencimentos legais (datas ISO aaaa-mm-dd dos inputs type=date; vazio = não controlado)
    ipvaVenc: dataISOVeic(v.ipvaVenc),
    licencVenc: dataISOVeic(v.licencVenc),
    seguroVenc: dataISOVeic(v.seguroVenc),
    seguroApolice: (v.seguroApolice || '').toString().trim(),
    status,
    // Ex.: { oficinaDataEntrada:'2026-09-28', oficinaPrevisaoSaida:'2026-10-05',
    // oficinaValorOrcamento:'1.250,50', oficinaMotivo:'Troca de embreagem' }
    // → datas ISO, orçamento 1250.50 (null se não informado), motivo em texto.
    // Mantidos após sair da oficina; os alertas continuam dependendo do status.
    oficinaDataEntrada: dataISOVeic(v.oficinaDataEntrada),
    oficinaValorOrcamento: v.oficinaValorOrcamento == null || String(v.oficinaValorOrcamento).trim() === '' ? null : numBRVeiculo(v.oficinaValorOrcamento),
    oficinaMotivo: (v.oficinaMotivo || '').toString().trim(),
    oficinaPrevisaoSaida,
    oficinaPrazoDias,
    gravame: (v.gravame || '').toString().trim(),
    banco: (v.banco || '').toString().trim(),
    pctRicardo: pj,
    pctMarcelo: pd,
    observacoes: (v.observacoes || '').toString().trim(),
    crlvDoc: crlv,
    compra: normalizarCompra(v.compra),
    venda: normalizarVenda(v.venda),
  };
}

// Dados da compra (preenchidos na sub-aba Comprados)
function normalizarCompra(compra) {
  const cp = compra || {};
  return {
    ativo: cp.ativo === true || cp.ativo === 'true' || cp.ativo === 1 || cp.ativo === '1',
    data: (cp.data || '').toString().trim(),
    valor: numBRVeiculo(cp.valor),
    forma: (cp.forma || '').toString().trim(),
    conta: (cp.conta || '').toString().trim(),
    vendedor: (cp.vendedor || '').toString().trim(),
    telefone: (cp.telefone || '').toString().trim(),
    observacao: (cp.observacao || '').toString().trim(),
  };
}

// Dados da venda (preenchidos quando o veículo é marcado como VENDIDO)
function normalizarVenda(venda) {
  const vd = venda || {};
  return {
    data: (vd.data || '').toString().trim(),
    valor: numBRVeiculo(vd.valor),
    desconto: numBRVeiculo(vd.desconto),
    forma: (vd.forma || '').toString().trim(),
    conta: (vd.conta || '').toString().trim(),
    comprador: (vd.comprador || '').toString().trim(),
    telefone: (vd.telefone || '').toString().trim(),
    statusAnterior: (vd.statusAnterior || '').toString().trim(),
  };
}

