app.put('/api/instalacoes/:id', exigeEditar('instalacoes'), rota(async (req, res) => {
  const lista = lerInstalacoes();
  const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(i => i.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Instalação não encontrada.' });
  const atualizada = normalizarInstalacao(Object.assign({}, req.body, { id, ts: lista[idx].ts }));
  if (!atualizada.fotos.length) return res.status(400).json({ erro: 'Anexe ao menos uma foto da instalação.' });
  const anterior = lista[idx];
  // remove as mídias que saíram da lista
  const idsNovos = new Set(atualizada.fotos.map(f => f.id));
  lista[idx] = atualizada;
  await salvarInstalacoes(lista);
  for (const f of anterior.fotos || []) if (!idsNovos.has(f.id) && !midiasReferenciadas().has(f.id)) await excluirMidia(f.id);
  await registrarHistorico([{ placa: atualizada.placa, acao: 'editou', texto: `Instalação editada${atualizada.numeroSerie ? ' (código ' + atualizada.numeroSerie + ')' : ''}` }], quemFez(req));
  res.json(atualizada);
}));
app.delete('/api/instalacoes/:id', exigeEditar('instalacoes'), rota(async (req, res) => {
  const lista = lerInstalacoes();
  const id = decodeURIComponent(req.params.id);
  const alvo = lista.find(i => i.id === id);
  const novas = lista.filter(i => i.id !== id);
  if (novas.length === lista.length) return res.status(404).json({ erro: 'Instalação não encontrada.' });
  await salvarInstalacoes(novas);
  if (alvo) {
    for (const f of alvo.fotos || []) if (!midiasReferenciadas().has(f.id)) await excluirMidia(f.id);
    await registrarHistorico([{ placa: alvo.placa, acao: 'excluiu', texto: `Instalação excluída${alvo.numeroSerie ? ' (código ' + alvo.numeroSerie + ')' : ''}` }], quemFez(req));
  }
  res.json({ ok: true });
}));

