// Colunas do export de Contratos (1 linha por parcela). A base é o formato que a
// importação (/api/contratos/importar) reconhece — NÃO ganha coluna em silêncio; as
// derivadas de atraso entram só na aba "Parcelas" do arquivo do Cronograma.
const COLS_CONTRATOS_EXPORT = [
  ['dataEmissao', 'DATA EMISSÃO'], ['banco', 'BANCO'], ['produto', 'PRODUTO'], ['grupo', 'GRUPO'], ['cota', 'COTA'], ['material', 'DESCRIÇÃO'],
  ['empresa', 'EMPRESA'], ['localCarro', 'LOCAL DO CARRO'], ['parcela', 'PARC'], ['totalParcelas', 'TOTAL PARC', numExp], ['parcelasPagas', 'PAGAS', numExp],
  ['parcelasFaltantes', 'FALTANTES', numExp], ['valorParcela', 'VALOR PARCELA', numExp], ['saldoQuitacao', 'SALDO QUITAÇÃO', numExp], ['descontoQuitacao', 'DESC. QUITAÇÃO'],
  ['descontoQuitacaoRS', 'DESC. R$', numExp], ['vencimento', 'VCTO'], ['dataPagamento', 'DT PAGTO'], ['escritorio', 'ESCRITÓRIO'], ['valorPago', 'VALOR PAGO', numExp],
  ['conta', 'C/C'], ['naJustica', 'NA JUSTIÇA', (v) => (v ? 'Sim' : 'Não')], ['serieId', 'ID SÉRIE'],
  // Colunas 23 e 24 (1.55.39): sem elas o round-trip Exportar → Importar APAGAVA "Início das
  // parcelas" e "Carência" da base inteira — a importação substitui tudo e o que não tem coluna
  // volta vazio. Entram no FIM de propósito: planilha antiga (22 ou 23 colunas) segue válida,
  // porque a importação lê por índice e índice ausente vira ''.
  ['inicioParcelas', 'INÍCIO PARCELAS'], ['carencia', 'CARÊNCIA', numExp],
];
// Colunas do export com PAGAS COERENTE por série (fonte única pagasAteCoerente, igual em
// todas as linhas da série, imune a declaração inconsistente tipo 99) e FALTANTES POSICIONAL
// (total − nº da parcela, a mesma regra da coluna "Faltam" da tela). PAGAS agrupa sobre a
// BASE COMPLETA (não só o recorte {ids}). Linha sem "N/M" cai no valor salvo (numExp).
// Ordem/rótulos idênticos a COLS_CONTRATOS_EXPORT — importação por índice e round-trip valem.
// Ex.: enviarPlanilha(res, 'CONTRATOS.xlsx', 'CONTRATOS', colsContratosExport(), lista)
//      → série 01/02 pagas + 03..10 abertas: PAGAS=2 em todas; FALTANTES 01/10→9 … 10/10→0.
function colsContratosExport(base = lerContratos()) {
  const grupos = new Map();
  for (const c of base) {
    const m = String(c.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
    if (!m) continue;
    const k = `${chaveSerieContrato(c)}|${+m[2]}`;
    if (!grupos.has(k)) grupos.set(k, []);
    grupos.get(k).push({ numero: +m[1], pago: contratoPagoDados(c), parcelasPagas: c.parcelasPagas });
  }
  const mapa = new Map();
  for (const [k, itens] of grupos) {
    const total = +k.slice(k.lastIndexOf('|') + 1);
    const pagas = pagasAteCoerente(itens, total);
    mapa.set(k, { pagas, faltantes: Math.max(0, total - pagas) });
  }
  const daSerie = (r) => {
    const m = String(r.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
    return m ? mapa.get(`${chaveSerieContrato(r)}|${+m[2]}`) : undefined;
  };
  return COLS_CONTRATOS_EXPORT.map(([campo, rotulo, fmt]) => {
    if (campo === 'parcelasPagas') return [campo, rotulo, (v, r) => { const s = daSerie(r); return s ? s.pagas : numExp(v); }];
    if (campo === 'parcelasFaltantes') return [campo, rotulo, (v, r) => faltamDaParcelaContrato(r)]; // sem N/M → célula vazia, não 0
    return [campo, rotulo, fmt];
  });
}
// FALTANTES do Excel = coluna "Faltam" da tela: POSICIONAL (total − nº da parcela), não o
// restante financeiro da série (esse é o Progresso). Espelho de faltamDaParcela (app.js).
// Sem "N/M" válido devolve '' (célula VAZIA no Excel — não usa o valor salvo nem inventa
// "última parcela"). Ex.: faltamDaParcelaContrato({parcela:'11/20'}) === 9 · '54/54' → 0 · '' → '' · 'abc' → ''
function faltamDaParcelaContrato(c) {
  const m = String((c && c.parcela) || '').match(/(\d+)\s*\/\s*(\d+)/);
  if (!m) return '';
  const numero = Number(m[1]), total = Number(m[2]);
  if (!Number.isFinite(numero) || !Number.isFinite(total) || total <= 0) return '';
  return Math.max(0, total - numero);
}
const COLS_CONTRATOS_EXPORT_ATRASO = [
  ['status', 'STATUS', (v, r) => (contratoPagoDados(r) ? 'Pago' : (contratoAtrasadoDados(r) ? 'Atrasada' : 'Pendente'))],
  ['competencia', 'COMPETÊNCIA', (v, r) => { const d = dataBRContrato(r.vencimento); return d ? `${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}` : ''; }],
  ['atrasada', 'ATRASADA', (v, r) => (contratoAtrasadoDados(r) ? 'Sim' : 'Não')],
  ['diasAtraso', 'DIAS EM ATRASO', (v, r) => diasAtrasoContrato(r)],
  ['valorAtraso', 'VALOR EM ATRASO', (v, r) => (contratoAtrasadoDados(r) ? (Number(r.valorParcela) || 0) : 0)],
];
// Recebe { ids } no corpo p/ exportar só os lançamentos filtrados na tela (sem ids = exporta
// todos). É leitura, mas vai por POST por causa da lista de ids — mesmo padrão do /exportar de funcionários.
// Com { cronograma: true } (botão Excel de Contratos › Cronograma) a resposta muda de formato:
// um arquivo com DUAS abas — "Cronograma" (visual da tela: 1 linha por contrato, meses nas
// colunas, cores) e "Parcelas" (1 linha por parcela + colunas de atraso). Ver
// gerarExcelCronogramaContratos abaixo. Os ids continuam sendo o recorte da tela.
// Ex.: POST /api/contratos/exportar  body { ids: ['C123','C124'], cronograma: true }
//      → CRONOGRAMA-CONTRATOS.xlsx (abas Resumo + Cronograma + Parcelas); `filtros`
//        opcional { busca, banco:[], produto:[], empresa:[], soAtraso } só vai para o cabeçalho do Resumo
//      POST /api/contratos/exportar  body { ids: ['C123'] }
//      → CONTRATOS.xlsx no formato de sempre (aba Parcelas do site, round-trip com a importação)
app.post('/api/contratos/exportar', exigeVer('contratos'), rota(async (req, res) => {
  let lista = lerContratos();
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(c => set.has(String(c.id))); }
  if (req.body && req.body.cronograma) {
    const buf = await gerarExcelCronogramaContratos(lista, req.body.filtros);
    res.setHeader('Content-Disposition', 'attachment; filename="CRONOGRAMA-CONTRATOS.xlsx"');
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    return res.send(Buffer.from(buf));
  }
  enviarPlanilha(res, 'CONTRATOS.xlsx', 'CONTRATOS', colsContratosExport(), lista);
}));

/* ---------- Excel do Cronograma (Contratos › Cronograma › ⬇ Excel) ----------
   Reproduz a TELA na aba "Cronograma": 1 linha por contrato/série, meses nas colunas,
   célula vermelha para atraso e verde para pendência — e mantém a aba "Parcelas"
   (1 linha por parcela, com as colunas de atraso) como formato analítico.
   Os helpers de agrupamento são ESPELHOS dos do app.js (consolidarParcelasCronoContr /
   referenciaCronoContr / progressoCronoContr / identidadeCronoContr) — mudou lá, muda aqui.
   Usa exceljs (só neste export): a lib `xlsx` community dos demais exports não escreve
   estilo nenhum (cor, borda, quebra de linha, altura, congelar painel).
   Ex. de uso:
     const buf = await gerarExcelCronogramaContratos(lerContratos());
     fs.writeFileSync('CRONOGRAMA-CONTRATOS.xlsx', Buffer.from(buf));
     // → aba "Cronograma": linha "Fiat Toro Freedom / PAULO AFONSO · Bradesco · SUL / ..."
     //   com "02/80 + 78 restantes", "2 ATRASADAS + R$ 4.380,00" (vermelha) e uma coluna
     //   por mês ("04/80 + R$ 2.190,00"); aba "Parcelas": as linhas analíticas.        */
function parcNumContrato(p) { const m = String(p || '').match(/\d+/); return m ? +m[0] : 0; }
function consolidarParcelasCronoContrato(parcelas) { // espelho de consolidarParcelasCronoContr (app.js)
  const unicas = new Map();
  for (const p of parcelas) {
    const m = String(p.c.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
    const chave = m ? `${Number(m[1])}/${Number(m[2])}` : `id:${p.c.id}`;
    const atual = unicas.get(chave);
    const substituir = !atual
      || (contratoPagoDados(p.c) && !contratoPagoDados(atual.c))
      || (contratoPagoDados(p.c) === contratoPagoDados(atual.c) && Number(p.c.ts) > Number(atual.c.ts));
    if (substituir) unicas.set(chave, p);
  }
  return [...unicas.values()];
}
function referenciaCronoContrato(parcelas) { // espelho de referenciaCronoContr (app.js)
  const pagas = parcelas.filter(x => contratoPagoDados(x.c));
  if (pagas.length) return pagas.sort((a, b) => parcNumContrato(b.c.parcela) - parcNumContrato(a.c.parcela))[0].c;
  return parcelas.slice().sort((a, b) => a.data - b.data)[0]?.c || {};
}
function progressoCronoContrato(referencia) { // espelho de progressoCronoContr (app.js)
  const texto = String(referencia.parcela || '');
  const m = texto.match(/(\d+)\s*\/\s*(\d+)/);
  const atual = m ? Number(m[1]) : Number(referencia.parcelasPagas) || 0;
  const total = m ? Number(m[2]) : Number(referencia.totalParcelas) || 0;
  const faltam = total ? Math.max(0, total - atual) : Number(referencia.parcelasFaltantes) || 0;
  const largura = Math.max(2, String(total).length);
  return { atual, total, faltam, texto: total ? `${String(atual).padStart(largura, '0')}/${String(total).padStart(largura, '0')}` : (texto || '—') };
}
function identidadeCronoContrato(c) { // espelho de identidadeCronoContr + veiculoBanco da linha (app.js)
  const numero = [c.grupo && `Grupo ${c.grupo}`, c.cota && `Cota ${c.cota}`].filter(Boolean).join(' · ');
  const consorcio = /cons[oó]rcio/i.test(String(c.produto || ''));
  const veiculoBanco = consorcio
    ? (String(c.localCarro || '').trim() || String(c.banco || '').trim() || 'Não informado')
    : (String(c.banco || '').trim() || 'Não informado');
  return {
    titulo: String(c.material || '').trim() || numero || String(c.produto || 'Contrato'),
    local: [veiculoBanco, c.banco, c.empresa].filter(x => x && String(x).trim()).join(' · '),
    badges: [c.produto, c.grupo && `Grupo ${c.grupo}`, c.cota && `Cota ${c.cota}`].filter(Boolean).join(' · '),
  };
}
const MESES_CURTOS_BR = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];
const rotuloMesCrono = (d) => `${MESES_CURTOS_BR[d.getMonth()]}/${String(d.getFullYear()).slice(-2)}`;
const chaveMesCrono = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
const moedaBRCrono = (v) => 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// Paleta aproximada da tela (ARGB): mesmos papéis do CSS, sem tentar ser pixel-perfect.
const CORES_CRONO = {
  cab: 'FFF3F4F6', cabAtual: 'FFDDE3EA', tinta: 'FF1F2430', apagado: 'FF6B7280',
  // Esquema BINÁRIO igual ao da tela (1.55.30): só parcela PAGA é verde; parcela NÃO paga (pendente
  // ou atrasada) usa o MESMO vermelho `atraso`. Não existe cor de "pendente" de propósito.
  atrasoFundo: 'FFFBE9E9', atraso: 'FFB91C1C', pagaFundo: 'FFEAF6EF', paga: 'FF1F7A4D',
  grade: 'FFE5E7EB',
};
/* Aba "Resumo" (1ª do arquivo) — visão gerencial do MESMO recorte das outras abas: totais,
   fluxo de caixa mês a mês, concentração por banco/empresa, 1 linha por contrato (com o mês
   previsto da quitação, que a tela não mostra) e alertas (em atraso / quita em ≤3 meses).
   Usa os MESMOS helpers de status/progresso das demais abas — nunca regra própria.
   Totais das tabelas são fórmulas SUM (quem editar a planilha vê recalcular).
   Ex. de uso (dentro de gerarExcelCronogramaContratos):
     montarAbaResumoCrono(wb, linhas, meses, hoje0, { banco: ['Bradesco'], soAtraso: true })
     → aba "Resumo" com "Filtros aplicados: Banco: Bradesco · Só com atraso", bloco de totais
       (Já pago / Em aberto / Em atraso / Próx. 6 e 12 meses), tabela "Fluxo mensal" (Mês, Parcelas,
       A pagar, Acumulado, Pagas), "Por banco", "Por empresa", "Por contrato" e "Alertas".      */
function descreverFiltrosCrono(filtros) {
  const f = filtros && typeof filtros === 'object' ? filtros : {};
  const lista = (v) => (Array.isArray(v) ? v.map(x => String(x).trim()).filter(Boolean) : []);
  const partes = [];
  const busca = String(f.busca || '').trim();
  if (busca) partes.push(`Busca: "${busca.slice(0, 80)}"`);
  for (const [chave, rotulo] of [['banco', 'Banco'], ['produto', 'Produto'], ['empresa', 'Empresa']]) {
    const v = lista(f[chave]); if (v.length) partes.push(`${rotulo}: ${v.slice(0, 20).join(', ')}`);
  }
  if (f.soAtraso) partes.push('Só com atraso');
  return partes.length ? partes.join(' · ') : 'Nenhum (todos os contratos)';
}
function montarAbaResumoCrono(wb, linhas, meses, hoje0, filtros) {
  const ws = wb.addWorksheet('Resumo', { views: [{ showGridLines: false }] });
  const MOEDA = '"R$" #,##0.00';
  const bordaFina = { style: 'thin', color: { argb: CORES_CRONO.grade } };
  const bordas = { top: bordaFina, left: bordaFina, right: bordaFina, bottom: bordaFina };
  const fundo = (argb) => ({ type: 'pattern', pattern: 'solid', fgColor: { argb } });
  const addMeses = (d, n) => new Date(d.getFullYear(), d.getMonth() + n, d.getDate());
  const arred = (v) => Math.round((Number(v) || 0) * 100) / 100; // centavos exatos (evita 38614.740000000005 na célula)
  const soma = (arr) => arred(arr.reduce((s, x) => s + (Number(x.c.valorParcela) || 0), 0));
  ws.columns = [{ width: 44 }, { width: 16 }, { width: 18 }, { width: 18 }, { width: 18 }, { width: 18 }, { width: 18 }, { width: 18 }];

  // ---- dados por contrato (mesmos helpers das outras abas) ----
  const contratos = linhas.map(({ base, parcelas }) => {
    const ident = identidadeCronoContrato(base);
    const prog = progressoCronoContrato(base);
    const pagas = parcelas.filter(x => contratoPagoDados(x.c));
    const abertas = parcelas.filter(x => !contratoPagoDados(x.c));
    const atrasadas = abertas.filter(x => contratoAtrasadoDados(x.c));
    const ultima = parcelas.reduce((m, x) => (!m || x.data > m ? x.data : m), null);
    return { base, ident, prog, pagas, abertas, atrasadas, ultima,
      valorParcela: arred(base.valorParcela), valorPago: soma(pagas), saldo: soma(abertas), valorAtraso: soma(atrasadas) };
  });
  const todasAbertas = contratos.flatMap(c => c.abertas);
  const em = (n) => soma(todasAbertas.filter(x => x.data >= hoje0 && x.data < addMeses(hoje0, n)));
  const totais = {
    contratos: contratos.length, parcelas: contratos.reduce((s, c) => s + c.pagas.length + c.abertas.length, 0),
    pago: contratos.reduce((s, c) => s + c.valorPago, 0), aberto: contratos.reduce((s, c) => s + c.saldo, 0),
    atraso: contratos.reduce((s, c) => s + c.valorAtraso, 0), qtdAtraso: contratos.reduce((s, c) => s + c.atrasadas.length, 0),
    prox6: em(6), prox12: em(12),
  };

  // ---- helpers de escrita ----
  let r = 1;
  const titulo = (texto, sub) => {
    const cel = ws.getCell(r, 1); cel.value = texto; cel.font = { bold: true, size: 12, color: { argb: CORES_CRONO.tinta } };
    if (sub) { const c2 = ws.getCell(r, 2); c2.value = sub; c2.font = { size: 9, color: { argb: CORES_CRONO.apagado } }; }
    r++;
  };
  const tabela = (cabs, linhasT, opts = {}) => { // opts: { moeda: Set<idx>, totalCols: [idx], corLinha(l) → {fundo,tinta}|null }
    const ini = r;
    cabs.forEach((t, i) => { const c = ws.getCell(r, i + 1); c.value = t; c.fill = fundo(CORES_CRONO.cab); c.font = { bold: true, size: 9, color: { argb: CORES_CRONO.tinta } }; c.alignment = { horizontal: i ? 'center' : 'left', vertical: 'middle', wrapText: true }; c.border = bordas; });
    r++;
    for (const l of linhasT) {
      const cor = opts.corLinha ? opts.corLinha(l) : null;
      l.valores.forEach((v, i) => {
        const c = ws.getCell(r, i + 1); c.value = typeof v === 'string' ? protegerCelula(v) : v; c.border = bordas;
        c.alignment = { horizontal: i ? 'center' : 'left', vertical: 'middle', wrapText: i === 0 };
        if (opts.moeda && opts.moeda.has(i)) { c.numFmt = MOEDA; c.alignment.horizontal = 'right'; }
        if (cor) { c.fill = fundo(cor.fundo); c.font = { size: 10, color: { argb: cor.tinta } }; }
      });
      r++;
    }
    if (opts.totalCols && linhasT.length) {
      const c0 = ws.getCell(r, 1); c0.value = 'TOTAL'; c0.font = { bold: true, size: 10 }; c0.border = bordas; c0.fill = fundo(CORES_CRONO.cab);
      for (let i = 1; i < cabs.length; i++) {
        const c = ws.getCell(r, i + 1); c.border = bordas; c.fill = fundo(CORES_CRONO.cab); c.font = { bold: true, size: 10 };
        if (opts.totalCols.includes(i)) {
          const col = ws.getColumn(i + 1).letter;
          const valor = linhasT.reduce((s, l) => s + (Number(l.valores[i]) || 0), 0);
          c.value = { formula: `SUM(${col}${ini + 1}:${col}${r - 1})`, result: valor };
          if (opts.moeda && opts.moeda.has(i)) { c.numFmt = MOEDA; c.alignment = { horizontal: 'right' }; } else c.alignment = { horizontal: 'center' };
        }
      }
      r++;
    }
    r++; // linha em branco entre blocos
  };
  const VERMELHO = { fundo: CORES_CRONO.atrasoFundo, tinta: CORES_CRONO.atraso };
  const VERDE = { fundo: CORES_CRONO.pagaFundo, tinta: CORES_CRONO.paga };

  // ---- cabeçalho ----
  const agora = new Date();
  titulo('Cronograma de contratos — Resumo', `gerado em ${agora.toLocaleDateString('pt-BR')} ${agora.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`);
  const periodo = meses.length ? `${rotuloMesCrono(meses[0])} a ${rotuloMesCrono(meses[meses.length - 1])} (${meses.length} meses)` : '—';
  [['Período coberto', periodo], ['Filtros aplicados', descreverFiltrosCrono(filtros)], ['Contratos', totais.contratos], ['Parcelas', totais.parcelas]]
    .forEach(([k, v]) => { ws.getCell(r, 1).value = k; ws.getCell(r, 1).font = { size: 9, color: { argb: CORES_CRONO.apagado } }; ws.getCell(r, 2).value = typeof v === 'string' ? protegerCelula(v) : v; ws.getCell(r, 2).alignment = { horizontal: 'left' }; r++; });
  r++;

  // ---- totais gerais ----
  titulo('Totais gerais');
  const cards = [['Já pago', totais.pago, VERDE], ['Em aberto', totais.aberto, null], ['Em atraso', totais.atraso, totais.atraso ? VERMELHO : null], ['Parcelas atrasadas', totais.qtdAtraso, totais.qtdAtraso ? VERMELHO : null], ['Próximos 6 meses', totais.prox6, null], ['Próximos 12 meses', totais.prox12, null]];
  cards.forEach(([k, v, cor], i) => {
    const c1 = ws.getCell(r, i + 1), c2 = ws.getCell(r + 1, i + 1);
    c1.value = k; c1.font = { size: 8, bold: true, color: { argb: cor ? cor.tinta : CORES_CRONO.apagado } }; c1.alignment = { horizontal: 'center' }; c1.border = bordas;
    c2.value = v; c2.font = { size: 12, bold: true, color: { argb: cor ? cor.tinta : CORES_CRONO.tinta } }; c2.alignment = { horizontal: 'center' }; c2.border = bordas;
    if (k !== 'Parcelas atrasadas') c2.numFmt = MOEDA;
    if (cor) { c1.fill = fundo(cor.fundo); c2.fill = fundo(cor.fundo); }
  });
  ws.getRow(r + 1).height = 22; r += 3;

  // ---- fluxo mensal ----
  titulo('Fluxo mensal', 'valores em aberto por mês de vencimento; pagas à parte');
  let acumulado = 0;
  const fluxo = meses.map(m => {
    const k = chaveMesCrono(m);
    const doMes = contratos.flatMap(c => c.abertas.concat(c.pagas)).filter(x => chaveMesCrono(x.data) === k);
    const abertas = doMes.filter(x => !contratoPagoDados(x.c)), pagas = doMes.filter(x => contratoPagoDados(x.c));
    const atrasadas = abertas.filter(x => contratoAtrasadoDados(x.c));
    acumulado = arred(acumulado + soma(abertas));
    const atual = k === chaveMesCrono(hoje0);
    return { atrasadas: atrasadas.length, atual, valores: [rotuloMesCrono(m) + (atual ? ' (mês atual)' : ''), abertas.length, soma(abertas), acumulado, atrasadas.length, pagas.length, soma(pagas)] };
  });
  tabela(['Mês', 'Parcelas a pagar', 'A pagar', 'Acumulado', 'Atrasadas', 'Pagas', 'Valor pago'], fluxo,
    { moeda: new Set([2, 3, 6]), totalCols: [1, 2, 4, 5, 6], corLinha: (l) => (l.atrasadas ? VERMELHO : (l.atual ? VERDE : null)) });

  // ---- por banco / por empresa ----
  const agrupar = (campo) => {
    const m = new Map();
    for (const c of contratos) { const k = String(c.base[campo] || '').trim() || 'Não informado'; if (!m.has(k)) m.set(k, []); m.get(k).push(c); }
    return [...m.entries()].sort((a, b) => a[0].localeCompare(b[0], 'pt-BR')).map(([k, cs]) => ({
      atraso: cs.some(c => c.atrasadas.length),
      valores: [k, cs.length, cs.reduce((s, c) => s + c.abertas.length, 0), cs.reduce((s, c) => s + c.saldo, 0), cs.reduce((s, c) => s + c.atrasadas.length, 0), cs.reduce((s, c) => s + c.valorAtraso, 0)],
    }));
  };
  const cabsGrupo = (rotulo) => [rotulo, 'Contratos', 'Parcelas em aberto', 'Saldo em aberto', 'Parcelas atrasadas', 'Valor em atraso'];
  titulo('Por banco');
  tabela(cabsGrupo('Banco'), agrupar('banco'), { moeda: new Set([3, 5]), totalCols: [1, 2, 3, 4, 5], corLinha: (l) => (l.atraso ? VERMELHO : null) });
  titulo('Por empresa');
  tabela(cabsGrupo('Empresa'), agrupar('empresa'), { moeda: new Set([3, 5]), totalCols: [1, 2, 3, 4, 5], corLinha: (l) => (l.atraso ? VERMELHO : null) });

  // ---- por contrato ----
  titulo('Por contrato', 'progresso como na tela + mês previsto da última parcela');
  const porContrato = contratos.map(c => ({
    atraso: c.atrasadas.length > 0,
    valores: [`${c.ident.titulo}${c.ident.local ? ' — ' + c.ident.local : ''}`, c.prog.texto, c.prog.faltam, c.valorParcela, c.valorPago, c.saldo, c.atrasadas.length, c.ultima ? rotuloMesCrono(c.ultima) : '—'],
  }));
  tabela(['Contrato', 'Progresso', 'Restantes', 'Valor da parcela', 'Já pago', 'Saldo em aberto', 'Atrasadas', 'Última parcela'], porContrato,
    { moeda: new Set([3, 4, 5]), totalCols: [4, 5, 6], corLinha: (l) => (l.atraso ? VERMELHO : null) });

  // ---- alertas ----
  titulo('Alertas');
  const limite3 = addMeses(hoje0, 3);
  const maisAntiga = (c) => c.atrasadas.reduce((m, x) => (!m || x.data < m ? x.data : m), null);
  const alertas = [
    ...contratos.filter(c => c.atrasadas.length).sort((a, b) => b.valorAtraso - a.valorAtraso).map(c => ({ cor: VERMELHO, valores: ['Em atraso', c.ident.titulo, `${c.atrasadas.length} parcela${c.atrasadas.length > 1 ? 's' : ''} · ${moedaBRCrono(c.valorAtraso)} · mais antiga ${maisAntiga(c).toLocaleDateString('pt-BR')}`] })),
    ...contratos.filter(c => c.abertas.length && c.ultima && c.ultima < limite3).sort((a, b) => a.ultima - b.ultima).map(c => ({ cor: VERDE, valores: ['Quita em até 3 meses', c.ident.titulo, `última parcela em ${c.ultima.toLocaleDateString('pt-BR')} · ${c.abertas.length} restante${c.abertas.length > 1 ? 's' : ''} · ${moedaBRCrono(c.saldo)}`] })),
  ];
  if (!alertas.length) alertas.push({ cor: null, valores: ['—', 'Nenhum contrato em atraso nem quitando nos próximos 3 meses', ''] });
  tabela(['Tipo', 'Contrato', 'Detalhe'], alertas, { corLinha: (l) => l.cor });
}
async function gerarExcelCronogramaContratos(lista, filtros = null) {
  const ExcelJS = require('exceljs'); // require tardio: só este export usa; não pesa no boot
  const hoje0 = inicioHojeContrato();
  const mesAtualChave = chaveMesCrono(hoje0);

  // Agrupamento IGUAL ao da tela: série → parcelas consolidadas → ordena por título.
  const comData = lista.map(c => ({ c, data: dataBRContrato(c.vencimento) })).filter(x => x.data);
  const grupos = new Map();
  for (const p of comData) {
    const chave = chaveSerieContrato(p.c);
    if (!grupos.has(chave)) grupos.set(chave, []);
    grupos.get(chave).push(p);
  }
  const linhas = [...grupos.values()].map(parcelas => {
    const unicas = consolidarParcelasCronoContrato(parcelas);
    return { base: referenciaCronoContrato(unicas), parcelas: unicas };
  }).sort((a, b) => identidadeCronoContrato(a.base).titulo.localeCompare(identidadeCronoContrato(b.base).titulo, 'pt-BR'));

  // Meses: do menor ao maior vencimento de TODAS as parcelas do recorte — pagas inclusive.
  // A planilha é o cronograma completo (como a tela): parcela paga aparece no mês dela em
  // cinza, sem entrar nos totais. Uma coluna por mês, sem teto — contrato de 80 meses gera
  // ~80 colunas (já era assim para as futuras); limite silencioso esconderia parcela.
  const todas = linhas.flatMap(l => l.parcelas);
  let meses = [];
  if (todas.length) {
    const datas = todas.map(x => x.data);
    let m = new Date(Math.min(...datas)); m = new Date(m.getFullYear(), m.getMonth(), 1);
    const fim = new Date(Math.max(...datas));
    const fimMes = new Date(fim.getFullYear(), fim.getMonth(), 1);
    while (m <= fimMes) { meses.push(m); m = new Date(m.getFullYear(), m.getMonth() + 1, 1); }
  } else {
    meses = [new Date(hoje0.getFullYear(), hoje0.getMonth(), 1)];
  }

  const wb = new ExcelJS.Workbook();
  montarAbaResumoCrono(wb, linhas, meses, hoje0, filtros); // 1ª aba: visão gerencial do recorte
  const ws = wb.addWorksheet('Cronograma', {
    views: [{ state: 'frozen', xSplit: 2, ySplit: 1 }], // Contrato + Progresso seguem visíveis no scroll
  });

  const bordaFina = { style: 'thin', color: { argb: CORES_CRONO.grade } };
  const bordas = { top: bordaFina, left: bordaFina, right: bordaFina, bottom: bordaFina };
  const fundo = (argb) => ({ type: 'pattern', pattern: 'solid', fgColor: { argb } });

  // Cabeçalho
  const cab = ['CONTRATO', 'PROGRESSO', 'ATRASADAS\nANTES DE HOJE', ...meses.map(m => {
    const atual = chaveMesCrono(m) === mesAtualChave;
    return atual ? `${rotuloMesCrono(m)}\nMÊS ATUAL` : rotuloMesCrono(m);
  })];
  ws.addRow(cab);
  const linhaCab = ws.getRow(1);
  linhaCab.height = 30;
  linhaCab.eachCell((cel, col) => {
    const atual = col > 3 && chaveMesCrono(meses[col - 4]) === mesAtualChave;
    cel.fill = fundo(atual ? CORES_CRONO.cabAtual : CORES_CRONO.cab);
    cel.font = { bold: true, size: 9, color: { argb: col === 3 ? CORES_CRONO.atraso : CORES_CRONO.tinta } };
    cel.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
    cel.border = bordas;
  });
  ws.getColumn(1).width = 42;
  ws.getColumn(2).width = 15;
  for (let i = 3; i <= cab.length; i++) ws.getColumn(i).width = 15;

  // Linhas (1 por contrato/série)
  for (const { base, parcelas } of linhas) {
    const ident = identidadeCronoContrato(base);
    const prog = progressoCronoContrato(base);
    const atrasadas = parcelas.filter(x => contratoAtrasadoDados(x.c));
    const valorAtrasado = atrasadas.reduce((s, x) => s + (Number(x.c.valorParcela) || 0), 0);
    const porMes = new Map();
    for (const p of parcelas) {
      const k = chaveMesCrono(p.data);
      if (!porMes.has(k)) porMes.set(k, []);
      porMes.get(k).push(p.c);
    }

    const row = ws.addRow([]);
    row.height = 44;

    const celContrato = row.getCell(1);
    celContrato.value = { richText: [
      { text: ident.titulo, font: { bold: true, size: 10, color: { argb: CORES_CRONO.tinta } } },
      ...(ident.local ? [{ text: `\n${ident.local}`, font: { size: 8, color: { argb: CORES_CRONO.apagado } } }] : []),
      ...(ident.badges ? [{ text: `\n${ident.badges}`, font: { size: 8, color: { argb: CORES_CRONO.apagado } } }] : []),
    ] };
    celContrato.alignment = { vertical: 'middle', wrapText: true };
    celContrato.border = bordas;

    const celProg = row.getCell(2);
    celProg.value = { richText: [
      { text: prog.texto, font: { bold: true, size: 10, color: { argb: CORES_CRONO.tinta } } },
      { text: `\n${prog.faltam} restantes`, font: { size: 8, color: { argb: CORES_CRONO.apagado } } },
    ] };
    celProg.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
    celProg.border = bordas;

    const celAtr = row.getCell(3);
    if (atrasadas.length) {
      celAtr.value = { richText: [
        { text: `${atrasadas.length} ATRASADA${atrasadas.length > 1 ? 'S' : ''}`, font: { size: 8, color: { argb: CORES_CRONO.atraso } } },
        { text: `\n${moedaBRCrono(valorAtrasado)}`, font: { bold: true, size: 10, color: { argb: CORES_CRONO.atraso } } },
      ] };
      celAtr.fill = fundo(CORES_CRONO.atrasoFundo);
      celAtr.border = { ...bordas, bottom: { style: 'medium', color: { argb: CORES_CRONO.atraso } } };
    } else {
      celAtr.value = '—';
      celAtr.font = { size: 9, color: { argb: CORES_CRONO.apagado } };
      celAtr.border = bordas;
    }
    celAtr.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };

    meses.forEach((m, i) => {
      const cel = row.getCell(4 + i);
      // Mesma regra da célula da tela: o mês TEM parcela quando `ps` (qualquer status) não
      // está vazio; só pagas → VERDE; abertas (± pagas) → VERMELHO (pendente = atrasada) com o valor EM ABERTO
      // e a linha "N PAGA(S)"; nada → "—". Nunca `!abertas.length` como "sem parcela".
      const ps = porMes.get(chaveMesCrono(m)) || [];
      const abertas = ps.filter(c => !contratoPagoDados(c));
      const pagas = ps.filter(c => contratoPagoDados(c));
      const rotuloParc = (lista) => (lista.length === 1 ? String(lista[0].parcela || 'Parcela') : `${lista.length} parcelas`);
      if (!ps.length) {
        cel.value = '—';
        cel.font = { size: 9, color: { argb: CORES_CRONO.apagado } };
        cel.alignment = { horizontal: 'center', vertical: 'middle' };
        cel.border = bordas;
        return;
      }
      if (!abertas.length) { // só pagas: verde (único verde da grade), fora dos totais
        const valorPago = pagas.reduce((s, c) => s + (Number(c.valorParcela) || 0), 0);
        cel.value = { richText: [
          { text: rotuloParc(pagas), font: { size: 8, color: { argb: CORES_CRONO.paga } } },
          { text: `\n${moedaBRCrono(valorPago)}`, font: { bold: true, size: 10, color: { argb: CORES_CRONO.tinta } } },
        ] };
        cel.fill = fundo(CORES_CRONO.pagaFundo);
        cel.border = { ...bordas, bottom: { style: 'medium', color: { argb: CORES_CRONO.paga } } };
        cel.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        return;
      }
      const valor = abertas.reduce((s, c) => s + (Number(c.valorParcela) || 0), 0); // só o em aberto
      const parcTexto = rotuloParc(ps); // conta todas as parcelas do mês
      const cor = CORES_CRONO.atraso; // não paga = vermelho, vencida ou não (a coluna "Atrasadas" já separa)
      cel.value = { richText: [
        { text: parcTexto, font: { size: 8, color: { argb: cor } } },
        { text: `\n${moedaBRCrono(valor)}`, font: { bold: true, size: 10, color: { argb: CORES_CRONO.tinta } } },
        ...(pagas.length ? [{ text: `\n${pagas.length} ${pagas.length === 1 ? 'PAGA' : 'PAGAS'}`, font: { size: 7, color: { argb: CORES_CRONO.apagado } } }] : []),
      ] };
      cel.fill = fundo(CORES_CRONO.atrasoFundo);
      cel.border = { ...bordas, bottom: { style: 'medium', color: { argb: cor } } };
      cel.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
    });
  }

  // Aba "Parcelas" — o formato analítico (1 linha por parcela), com as colunas de atraso.
  const wsP = wb.addWorksheet('Parcelas', { views: [{ state: 'frozen', ySplit: 1 }] });
  const colunas = [...colsContratosExport(), ...COLS_CONTRATOS_EXPORT_ATRASO];
  const MOEDA_PARCELAS = new Set(['VALOR PARCELA', 'SALDO QUITAÇÃO', 'DESC. R$', 'VALOR PAGO', 'VALOR EM ATRASO']);
  wsP.addRow(colunas.map(c => c[1]));
  wsP.getRow(1).eachCell((cel) => {
    cel.fill = fundo(CORES_CRONO.cab);
    cel.font = { bold: true, size: 9, color: { argb: CORES_CRONO.tinta } };
    cel.alignment = { horizontal: 'center', vertical: 'middle' };
    cel.border = bordas;
  });
  for (const r of lista) {
    wsP.addRow(colunas.map(([campo, rotulo, fmt]) => {
      const v = fmt ? fmt(r[campo], r) : (r[campo] ?? '');
      return typeof v === 'string' ? protegerCelula(v) : v;
    }));
  }
  colunas.forEach(([campo, rotulo], i) => {
    const col = wsP.getColumn(i + 1);
    let max = rotulo.length;
    col.eachCell({ includeEmpty: false }, (cel) => { const len = String(cel.value ?? '').length; if (len > max) max = len; });
    col.width = Math.min(Math.max(max + 2, 10), 60);
    if (MOEDA_PARCELAS.has(rotulo)) col.numFmt = '"R$" #,##0.00';
  });
  wsP.autoFilter = { from: { row: 1, column: 1 }, to: { row: Math.max(1, lista.length + 1), column: colunas.length } };

  return wb.xlsx.writeBuffer();
}
app.put('/api/contratos/:id', exigeEditar('contratos'), rota(async (req, res) => {
  const lista = lerContratos(); const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(c => c.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Contrato não encontrado.' });
  garantirIdsSeriesContrato(lista);
  lista[idx] = normalizarContrato(Object.assign({}, req.body, { id, ts: lista[idx].ts, serieId: lista[idx].serieId }));
  await salvarContratos(lista);
  res.json(lista[idx]);
}));
app.delete('/api/contratos/:id', exigeEditar('contratos'), rota(async (req, res) => { // exclusão unitária: qualquer logado (como editar)
  const lista = lerContratos(); const id = decodeURIComponent(req.params.id);
  const novos = lista.filter(c => c.id !== id);
  if (novos.length === lista.length) return res.status(404).json({ erro: 'Contrato não encontrado.' });
  await salvarContratos(novos);
  res.json({ ok: true });
}));
// AÇÕES EM LOTE — 1 requisição + 1 gravação (em vez de N requisições em sequência, que travavam a tela).
// Editar/status em lote: qualquer logado (como a edição unitária). Só a EXCLUSÃO EM MASSA é admin.
app.post('/api/contratos/lote-status', exigeEditar('contratos'), rota(async (req, res) => {
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids.map(x => String(x)) : [];
  const pago = !!(req.body && req.body.pago);
  if (!ids.length) return res.status(400).json({ erro: 'Nenhum lançamento informado.' });
  const alvo = new Set(ids);
  const d = new Date();
  const hoje = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
  const lista = lerContratos();
  let alterados = 0;
  for (const c of lista) {
    if (!alvo.has(c.id)) continue;
    const estaPago = (Number(c.valorPago) > 0) || !!(c.dataPagamento && String(c.dataPagamento).trim());
    if (pago === estaPago) continue; // já está no status desejado
    if (pago) { if (!(c.dataPagamento && String(c.dataPagamento).trim())) c.dataPagamento = hoje; if (!Number(c.valorPago)) c.valorPago = Number(c.valorParcela) || 0; }
    else { c.dataPagamento = ''; c.valorPago = 0; }
    alterados++;
  }
  if (alterados) await salvarContratos(lista);
  res.json({ ok: true, alterados });
}));
// Exclusão EM MASSA de lançamentos financeiros: só admin (ou local), com backup antes — única
// operação de contratos restrita (evita um "selecionar tudo + excluir" apagar a base num clique).
app.post('/api/contratos/lote-excluir', exigeAdminOuLocal, rota(async (req, res) => {
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids.map(x => String(x)) : [];
  if (!ids.length) return res.status(400).json({ erro: 'Nenhum lançamento informado.' });
  const alvo = new Set(ids);
  const lista = lerContratos();
  const novos = lista.filter(c => !alvo.has(c.id));
  const excluidos = lista.length - novos.length;
  if (excluidos) { await salvarBackupAuto(); await salvarContratos(novos); } // snapshot antes de apagar em massa
  res.json({ ok: true, excluidos });
}));
// Edita em lote os campos COMPARTILHADOS (descrição/banco/produto/empresa/grupo/cota) — só os enviados são alterados.
// `campos.totalParcelas` (1.55.36) corrige o TOTAL da série: reescreve "N/M" → "N/<novo>" em cada parcela
// selecionada (e `totalParcelas`; `parcelasFaltantes` é recalculado pelo normalizador). A parcela cujo
// número fica ACIMA do novo total NÃO é tocada nem apagada aqui — volta em `excedentes` para o cliente
// oferecer a exclusão pelo `lote-excluir` (que continua sendo o único lugar que apaga, com o gate de admin).
// Ex.: POST /api/contratos/lote-editar  body { ids: [id01..id20], campos: { totalParcelas: 15 } }
//      → { ok:true, alterados:15, excedentes:[{ id:id16, parcela:'16/20' }, …id20], semParcela:0 }
//        e 01/20…15/20 viram 01/15…15/15 (pagas, datas e valores intactos).
// Ex.: body { ids:[a,b], campos: { banco: 'Itaú' } } → { ok:true, alterados:2, excedentes:[], semParcela:0 }
app.post('/api/contratos/lote-editar', exigeEditar('contratos'), rota(async (req, res) => {
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids.map(x => String(x)) : [];
  const campos = (req.body && req.body.campos) || {};
  if (!ids.length) return res.status(400).json({ erro: 'Nenhum lançamento informado.' });
  const alterar = {};
  for (const k of ['material', 'banco', 'produto', 'empresa', 'grupo', 'cota']) {
    if (campos[k] !== undefined && campos[k] !== null && String(campos[k]).trim() !== '') alterar[k] = String(campos[k]).trim();
  }
  let novoTotal = null;
  if (campos.totalParcelas !== undefined && campos.totalParcelas !== null && String(campos.totalParcelas).trim() !== '') {
    novoTotal = Number(String(campos.totalParcelas).trim());
    if (!Number.isInteger(novoTotal) || novoTotal < 1 || novoTotal > 999) return res.status(400).json({ erro: 'Novo total da série inválido: informe um inteiro entre 1 e 999.' });
  }
  if (!Object.keys(alterar).length && novoTotal === null) return res.json({ ok: true, alterados: 0, excedentes: [], semParcela: 0 });
  const alvo = new Set(ids);
  const lista = lerContratos();
  garantirIdsSeriesContrato(lista);
  let alterados = 0, semParcela = 0;
  const excedentes = [];
  for (let i = 0; i < lista.length; i++) {
    if (!alvo.has(lista[i].id)) continue;
    const mudanca = Object.assign({}, alterar);
    if (novoTotal !== null) {
      const m = String(lista[i].parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
      if (!m) { semParcela++; if (!Object.keys(alterar).length) continue; } // sem "N/M": nada a renumerar
      else if (Number(m[1]) > novoTotal) { excedentes.push({ id: lista[i].id, parcela: lista[i].parcela }); if (!Object.keys(alterar).length) continue; }
      else {
        mudanca.parcela = `${Number(m[1])}/${novoTotal}`; // normalizarContrato refaz o zero à esquerda
        mudanca.totalParcelas = novoTotal;
        mudanca.parcelasFaltantes = ''; // vazio ⇒ recalculado a partir de pagas × novo total
      }
    }
    lista[i] = normalizarContrato(Object.assign({}, lista[i], mudanca));
    alterados++;
  }
  if (alterados) await salvarContratos(lista);
  res.json({ ok: true, alterados, excedentes, semParcela });
}));
// Criar VÁRIOS lançamentos de uma vez (1 gravação) — usado pelo "Gerar série" do form (ex.: 1/70 cria as 70 parcelas).
app.post('/api/contratos/lote-criar', exigeEditar('contratos'), rota(async (req, res) => {
  const itens = Array.isArray(req.body && req.body.itens) ? req.body.itens : [];
  if (!itens.length) return res.status(400).json({ erro: 'Nenhum lançamento informado.' });
  const lista = lerContratos();
  const idsAtribuidos = garantirIdsSeriesContrato(lista);
  const existentes = new Set(lista.map(chaveParcelaContrato).filter(Boolean));
  const novos = [];
  let ignorados = 0;
  for (const item of itens) {
    const novo = normalizarContrato(item);
    novo.serieId = resolverSerieIdContrato(novo, lista.concat(novos));
    const chave = chaveParcelaContrato(novo);
    if (chave && existentes.has(chave)) { ignorados++; continue; }
    if (chave) existentes.add(chave);
    novos.push(novo);
  }
  if (novos.length || idsAtribuidos) { lista.push(...novos); await salvarContratos(lista); }
  res.status(201).json({ criados: novos.length, ignorados });
}));

// Completa todas as séries em uma única gravação e corrige a apresentação N/M das parcelas
// existentes. NUNCA exclui nem altera linha já cadastrada: só ACRESCENTA os números que faltam,
// pela regra de âncora documentada no topo (ÂNCORA DA SÉRIE). O que era exclusão de sobreposta
// virou relatório (`sobrepostas`/`sobreposicoes`); datas contraditórias na mesma linha voltam
// em `avisos`; série com o MESMO número em vencimentos diferentes segue em `ignoradas`.
// Ex.: POST /api/contratos/completar-series
//      → { criadas: 18, padronizadas: 0, series: 1, removidas: 0, ignoradas: 0,
//          sobrepostas: 0, sobreposicoes: [], avisos: [] }
app.post('/api/contratos/completar-series', exigeEditar('contratos'), rota(async (req, res) => {
  // Trabalha numa cópia: em Mongo, lerContratos() devolve mem.contratos — normalizar in-place
  // mexeria no estado vivo antes da gravação.
  const lista = lerContratos().map(c => ({ ...c }));
  const idsAtribuidos = garantirIdsSeriesContrato(lista);
  const grupos = new Map();
  let padronizadas = 0;
  for (let i = 0; i < lista.length; i++) {
    const atual = lista[i];
    const p = String(atual.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
    if (!p) continue;
    const numero = Number(p[1]), total = Number(p[2]);
    if (!Number.isInteger(numero) || !Number.isInteger(total) || numero < 1 || total < 1 || numero > total) continue;
    const normalizado = normalizarContrato(atual);
    if (normalizado.parcela !== atual.parcela) padronizadas++;
    lista[i] = normalizado;
    const chave = `${chaveSerieContrato(normalizado)}|${total}`;
    if (!grupos.has(chave)) grupos.set(chave, { total, itens: [] });
    grupos.get(chave).itens.push({ contrato: normalizado, numero });
  }

  let criadas = 0, series = 0, ignoradas = 0;
  const sobreposicoes = []; // RELATÓRIO (não exclui nada) — ver comentário abaixo
  const avisos = [];        // Vencimento × "Início das parcelas" discordando na mesma linha
  for (const grupo of grupos.values()) {
    // SOBREPOSIÇÃO = mesmo vencimento + mesmo valor na mesma série. Até a 1.55.38 isto APAGAVA
    // a linha "perdedora" — era o único ponto do fluxo que destruía dado, e o critério é falso:
    // em série de parcela fixa, vencimento e valor repetidos são NORMAIS (entrada + 1ª parcela
    // no mesmo dia, renegociação, parcela dobrada). Agora só entra no relatório da resposta.
    const porVencimento = new Map();
    for (const item of grupo.itens) {
      if (!item.contrato.vencimento) continue;
      const chave = `${item.contrato.vencimento}|${Number(item.contrato.valorParcela) || 0}`;
      if (!porVencimento.has(chave)) porVencimento.set(chave, []);
      porVencimento.get(chave).push(item);
    }
    for (const [chave, itens] of porVencimento) {
      if (itens.length < 2) continue;
      const [vencimento, valor] = chave.split('|');
      sobreposicoes.push({
        serie: chaveSerieContrato(itens[0].contrato), vencimento, valor: Number(valor),
        parcelas: itens.map(x => x.contrato.parcela), ids: itens.map(x => x.contrato.id),
      });
    }
    for (const item of grupo.itens) {
      const aviso = divergenciaAncoraContrato(item.contrato);
      if (aviso) avisos.push(`${chaveSerieContrato(item.contrato)} · ${aviso}`);
    }
    // Um aviso POR SÉRIE (não por parcela): quando as parcelas já cadastradas não batem entre si,
    // as criadas herdam o desvio da âncora vizinha. Corrigir é decisão do usuário — o caminho é
    // acertar a parcela errada e rodar de novo, ou scripts/corrigir-vencimentos-series.js.
    const cadencia = cadenciaIrregularContrato(grupo.itens);
    if (cadencia) avisos.push(`${chaveSerieContrato(grupo.itens[0].contrato)} · ${cadencia}`);
    const datasPorNumero = new Map();
    for (const item of grupo.itens) {
      if (!item.contrato.vencimento) continue;
      if (!datasPorNumero.has(item.numero)) datasPorNumero.set(item.numero, new Set());
      datasPorNumero.get(item.numero).add(item.contrato.vencimento);
    }
    if ([...datasPorNumero.values()].some(datas => datas.size > 1)) { ignoradas++; continue; }
    const presentes = new Set(grupo.itens.map(x => x.numero));
    const faltantes = Array.from({ length: grupo.total }, (_, i) => i + 1).filter(n => !presentes.has(n));
    if (!faltantes.length) continue;
    series++;
    // Watermark coerente (regra única — ver pagasAteCoerente): a 03/80 aberta impede que a
    // "declaração" da 04/80 (pagas=3 vindo da heurística do normalizador) vire pagamento.
    const pagasAte = pagasAteCoerente(grupo.itens.map(x => ({
      numero: x.numero, pago: contratoPagoDados(x.contrato), parcelasPagas: x.contrato.parcelasPagas,
    })), grupo.total);
    // MODELO dos campos que não são data (descrição, banco, valor da parcela…): a linha mais
    // "atual" da série — paga de maior número, senão a de ts mais recente. A ÂNCORA (abaixo)
    // decide só a DATA; separar os dois é o que permite consolidar a descrição sem apagar linha.
    const modelo = grupo.itens.slice().sort((a, b) =>
      Number(contratoPagoDados(b.contrato)) - Number(contratoPagoDados(a.contrato))
      || b.numero - a.numero
      || Number(b.contrato.ts) - Number(a.contrato.ts)
    )[0].contrato;
    // Escala de âncoras: uma linha COM vencimento por número (empate no mesmo número resolve
    // por paga → ts mais recente; a outra NÃO é apagada, só não serve de âncora).
    const porNumero = new Map();
    for (const item of grupo.itens.slice().sort((a, b) =>
      Number(contratoPagoDados(b.contrato)) - Number(contratoPagoDados(a.contrato))
      || Number(b.contrato.ts) - Number(a.contrato.ts)
    )) if (item.contrato.vencimento && !porNumero.has(item.numero)) porNumero.set(item.numero, item);
    const escala = [...porNumero.values()].sort((a, b) => a.numero - b.numero);
    // Fallback: nenhuma linha tem Vencimento → "Início das parcelas" é o vencimento DECLARADO
    // da parcela 01 (numeroAncora = 1). Ver o bloco ÂNCORA DA SÉRIE no topo do arquivo.
    const inicioDeclarado = grupo.itens.find(x => x.contrato.inicioParcelas);
    const menorExistente = Math.min(...grupo.itens.map(x => x.numero));
    for (const numero of faltantes) {
      // vencimento(k) = vencimentoAncora + (k − numeroAncora) meses — âncora = a parcela
      // EXISTENTE mais próxima ABAIXO de k; sem nenhuma abaixo, a mais próxima ACIMA.
      const abaixo = escala.filter(x => x.numero < numero).pop();
      const acima = escala.find(x => x.numero > numero);
      const ancora = abaixo || acima;
      const dataBase = ancora ? ancora.contrato.vencimento : (inicioDeclarado ? inicioDeclarado.contrato.inicioParcelas : '');
      const numeroAncora = ancora ? ancora.numero : 1;
      const vencimento = dataBase ? somarMesesContratoBR(dataBase, numero - numeroAncora) : '';
      // Parcela nova nasce SEMPRE em aberto — exceto no preenchimento RETROATIVO (números
      // abaixo de tudo o que já existe, dentro do watermark): é o caso do CT-3, em que
      // cadastrar a 02/04 implica que a 01/04 já foi paga. Declaração de pagas NÃO cria
      // pagamento para a frente: era isso que marcava parcela futura como quitada.
      const pago = numero < menorExistente && numero <= pagasAte;
      const parcelasPagas = Math.min(numero, pagasAte);
      const novo = {
        ...modelo,
        parcela: formatarParcelaContrato(`${numero}/${grupo.total}`),
        totalParcelas: grupo.total,
        parcelasPagas,
        parcelasFaltantes: Math.max(0, grupo.total - parcelasPagas),
        vencimento,
        dataPagamento: pago ? vencimento : '',
        valorPago: pago ? modelo.valorParcela : '',
        // Quitação é cota de UM MOMENTO da parcela-modelo, não atributo da série — herdá-la
        // repetia o mesmo saldo em todas as parcelas criadas (bug da série do exemplo).
        saldoQuitacao: '',
        descontoQuitacao: '',
        descontoQuitacaoRS: '',
      };
      delete novo.id;
      delete novo.ts;
      lista.push(normalizarContrato(novo));
      criadas++;
    }
  }
  if (sobreposicoes.length) console.warn(`[contratos] ${sobreposicoes.length} sobreposição(ões) de vencimento+valor — nenhuma linha foi excluída:`, JSON.stringify(sobreposicoes).slice(0, 2000));
  if (avisos.length) console.warn(`[contratos] ${avisos.length} linha(s) com Vencimento e "Início das parcelas" discordando:`, avisos.slice(0, 20).join(' | '));
  if (criadas || padronizadas || idsAtribuidos) await salvarContratos(lista);
  // `removidas` continua em 0 na resposta só para não quebrar cliente antigo: a operação não
  // exclui mais nada. O que era exclusão virou `sobrepostas`/`sobreposicoes` (relatório).
  res.status(201).json({ criadas, padronizadas, series, removidas: 0, ignoradas, sobrepostas: sobreposicoes.length, sobreposicoes, avisos });
}));

// Converte serial de data do Excel (ex.: 45108) em "dd/mm/aaaa". Texto/vazio passa direto.
function serialExcelParaBR(v) {
  if (v === '' || v === null || v === undefined) return '';
  const n = Number(v);
  if (!Number.isFinite(n) || n < 1 || n > 80000) return String(v).trim();
  const d = new Date(Math.round((n - 25569) * 86400 * 1000)); // 25569 = 1970-01-01 no serial do Excel
  if (isNaN(d.getTime())) return '';
  return `${String(d.getUTCDate()).padStart(2, '0')}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${d.getUTCFullYear()}`;
}
// Variante que preserva a HORA (a coluna de abastecimento é DATA/HORA). Serial fracionário
// do Excel → "dd/mm/aaaa hh:mm"; texto já em formato BR passa intacto (mesmo guard/UTC do helper acima).
function serialExcelDataHoraParaBR(v) {
  if (v === '' || v === null || v === undefined) return '';
  const n = Number(v);
  if (!Number.isFinite(n) || n < 1 || n > 80000) return String(v).trim();
  const d = new Date(Math.round((n - 25569) * 86400 * 1000));
  if (isNaN(d.getTime())) return '';
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const aa = d.getUTCFullYear();
  if (n - Math.floor(n) > 0) { // parte fracionária = hora do dia
    const hh = String(d.getUTCHours()).padStart(2, '0');
    const mi = String(d.getUTCMinutes()).padStart(2, '0');
    return `${dd}/${mm}/${aa} ${hh}:${mi}`;
  }
  return `${dd}/${mm}/${aa}`;
}
// Importa a planilha de contratos. Substitui todos os lançamentos (backup antes). Só admin/local.
app.post('/api/contratos/importar', exigeAdminOuLocal, uploadPlanilha.single('arquivo'), rota(async (req, res) => {
  if (!req.file) return res.status(400).json({ erro: 'Nenhum arquivo enviado.' });
  let wb;
  try { wb = XLSX.read(req.file.buffer, { type: 'buffer', cellDates: false }); }
  catch (e) { console.error('Erro ao ler planilha de contratos:', e.message); return res.status(400).json({ erro: 'Não consegui ler a planilha. Confira se é um Excel válido.' }); }
  const acharAba = (frag) => wb.SheetNames.find(nm => nm.toUpperCase().includes(frag));
  const linhasDe = (nome) => XLSX.utils.sheet_to_json(wb.Sheets[nome], { header: 1, defval: '' }).slice(1);
  const contratos = [];
  // As 2 abas de parcelas têm a MESMA ordem de colunas (A..T) — mapeio por índice (robusto a acentos no cabeçalho).
  // Deriva Banco e Produto a partir do texto do fornecedor.
  const produtoDe = (f) => { const u = String(f || '').toUpperCase(); if (/CONS[OÓ]RCIO/.test(u)) return 'Consórcio'; if (/FINANCIAMENTO/.test(u)) return 'Financiamento'; if (/EMPR[ÉE]STIMO/.test(u)) return 'Empréstimo'; return ''; };
  const bancoDe = (f) => { const u = String(f || '').toUpperCase(); if (/ITA[UÚ]/.test(u)) return 'Itaú'; if (/CAIXA/.test(u)) return 'Caixa'; if (/BRADESCO/.test(u)) return 'Bradesco'; if (/DISAL/.test(u)) return 'Disal'; if (/EMBRACOM/.test(u)) return 'Embracom'; if (/\bBB\b|BRASIL/.test(u)) return 'BB'; return ''; };
  // Lançamentos que não devem entrar (já não existem / sem dívida).
  const obsoleto = (c) => {
    if (c.empresa === 'ED') return true;                                                          // ED não tem dívida bancária
    if (c.produto === 'Consórcio' && c.banco === 'Itaú' && c.empresa === 'KV') return true;       // Consórcio Itaú KV
    if (c.empresa === 'NTE' && c.banco === 'Caixa' && /1\.?000\.?000/.test(c.material || '')) return true; // Giro Caixa NTE 1.000.000
    return false;
  };
  // Parcelas com vencimento já passado entram como "Pago" (presumem-se quitadas),
  // EXCETO as que estão em disputa na justiça (essas seguem pendentes).
  const jaPago = (c) => (Number(c.valorPago) > 0) || !!(c.dataPagamento && String(c.dataPagamento).trim());
  const dataBR = (s) => { const m = String(s || '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; };
  const HOJE = new Date(); HOJE.setHours(23, 59, 59, 999);
  let pagosVenc = 0;
  let ignorados = 0;
  // Formato atual: o mesmo arquivo gerado por /api/contratos/exportar. Assim, a própria
  // exportação pode voltar ao sistema preservando também o identificador interno da série.
  const nomeAtual = wb.SheetNames.find(nm => nm.trim().toUpperCase() === 'CONTRATOS');
  if (nomeAtual) {
    const linhas = XLSX.utils.sheet_to_json(wb.Sheets[nomeAtual], { header: 1, defval: '' });
    const cab = (linhas[0] || []).map(x => String(x || '').trim().toUpperCase());
    if (cab.includes('BANCO') && cab.includes('PRODUTO') && cab.includes('COTA')) {
      for (const r of linhas.slice(1)) {
        if (!r || !String(r[1] || '').trim()) continue;
        const justicaTxt = String(r[21] || '').trim().toUpperCase();
        const c = normalizarContrato({
          dataEmissao: serialExcelParaBR(r[0]), banco: r[1], produto: r[2], grupo: r[3], cota: r[4],
          material: r[5], empresa: r[6], localCarro: r[7], parcela: r[8], totalParcelas: r[9],
          parcelasPagas: r[10], parcelasFaltantes: r[11], valorParcela: r[12], saldoQuitacao: r[13],
          descontoQuitacao: r[14], descontoQuitacaoRS: r[15], vencimento: serialExcelParaBR(r[16]),
          dataPagamento: serialExcelParaBR(r[17]), escritorio: r[18], valorPago: r[19], conta: r[20],
          naJustica: /^(SIM|TRUE|1)$/.test(justicaTxt),
          serieId: r[22],
          // Colunas novas (1.55.39) no fim da planilha: em arquivo antigo elas não existem e
          // `r[23]`/`r[24]` são undefined → normalizarContrato grava ''/'' (mesmo resultado de antes).
          inicioParcelas: serialExcelParaBR(r[23]), carencia: r[24],
        });
        if (obsoleto(c)) { ignorados++; continue; }
        if (/FGI/i.test(c.material || '') && (c.empresa === 'KV' || c.empresa === 'NTE')) c.naJustica = true;
        if (!jaPago(c) && !c.naJustica) {
          const v = dataBR(c.vencimento);
          if (v && v <= HOJE) { c.dataPagamento = c.dataPagamento || c.vencimento; if (!Number(c.valorPago)) c.valorPago = Number(c.valorParcela) || 0; pagosVenc++; }
        }
        contratos.push(c);
      }
    }
  }
  for (const [frag, naJustica] of [['PARCELAS', false], ['JUSTI', true]]) {
    const nome = acharAba(frag); if (!nome) continue;
    for (const r of linhasDe(nome)) {
      if (!r || !String(r[1] || '').trim()) continue; // sem fornecedor = linha em branco
      const c = normalizarContrato({
        dataEmissao: serialExcelParaBR(r[0]), fornecedor: r[1], banco: bancoDe(r[1]), produto: produtoDe(r[1]),
        grupo: r[2], cota: r[3], material: r[4], empresa: r[5], localCarro: r[6], parcela: r[7],
        totalParcelas: r[8], parcelasPagas: r[9], parcelasFaltantes: r[10], valorParcela: r[11],
        saldoQuitacao: r[12], descontoQuitacao: r[13], descontoQuitacaoRS: r[14],
        vencimento: serialExcelParaBR(r[15]), dataPagamento: serialExcelParaBR(r[16]),
        escritorio: r[17], valorPago: r[18], conta: r[19], naJustica,
      });
      if (obsoleto(c)) { ignorados++; continue; }
      // Empréstimos FGI da KV e da NTE estão todos em disputa na justiça
      if (/FGI/i.test(c.material || '') && (c.empresa === 'KV' || c.empresa === 'NTE')) c.naJustica = true;
      // Vencimento já passou e não está na justiça → marca como paga
      if (!jaPago(c) && !c.naJustica) {
        const v = dataBR(c.vencimento);
        if (v && v <= HOJE) { c.dataPagamento = c.dataPagamento || c.vencimento; if (!Number(c.valorPago)) c.valorPago = Number(c.valorParcela) || 0; pagosVenc++; }
      }
      contratos.push(c);
    }
  }
  if (!contratos.length) return res.status(400).json({ erro: 'Nenhum dado reconhecido na planilha (aba CONTRATOS ou modelo antigo com PARCELAS/JUSTIÇA).' });
  garantirIdsSeriesContrato(contratos);
  await salvarBackupAuto(); // rede de segurança antes de substituir
  await salvarContratos(contratos);
  await registrarHistorico([{ placa: '', acao: 'importou', texto: `Contratos importados; ${contratos.length} parcelas (${ignorados} ignorados; ${pagosVenc} vencidas marcadas pagas)` }], quemFez(req));
  res.json({ ok: true, contratos: contratos.length, ignorados, pagosVencidas: pagosVenc });
}));

