app.get('/api/manutencao', exigeVer('manutencao'), (req, res) => { res.set('Cache-Control', 'no-store'); res.json(lerManutencao()); });

// USO: GET /api/manutencao/fornecedores => 200 [{ id:'FORN123', nome:'Oficina Demo', ativo:true }].
// 403 sem acesso à Manutenção. Só identificação: não expõe o cadastro completo de fornecedores.
