// Inclusão manual de um evento avulso.
// USO: POST /api/manutencao { placa:'ABC1D23', item:'Revisão', fornecedorId:'FORN123' }
// => 200 { ok:true, evento:{ ..., fornecedorId:'FORN123', fornecedor:'Oficina Demo' } };
// 400 se o fornecedor não existir ou estiver inativo; fornecedorId:'' deixa sem vínculo.
app.post('/api/manutencao', exigeEditar('manutencao'), rota(async (req, res) => {
  const ev = normalizarManutencao(req.body || {});
  if (!ev.placa) return res.status(400).json({ erro: 'Informe a placa.' });
  const erroFornecedor = vincularFornecedorMnt(ev);
  if (erroFornecedor) return res.status(400).json({ erro: erroFornecedor });
  const lista = lerManutencao();
  lista.push(ev);
  await salvarManutencao(lista);
  await registrarHistorico([{ placa: ev.placa, acao: 'adicionou', texto: `Manutenção (${ev.tipo}) · ${ev.item || 's/ descrição'} · R$ ${(Number(ev.custo) || 0).toFixed(2)}` }], quemFez(req));
  res.json({ ok: true, evento: ev });
}));

app.put('/api/manutencao/:id', exigeEditar('manutencao'), rota(async (req, res) => {
  const lista = lerManutencao();
  const id = decodeURIComponent(req.params.id);
  const i = lista.findIndex(e => e.id === id);
  if (i < 0) return res.status(404).json({ erro: 'Evento não encontrado.' });
  const ev = normalizarManutencao(Object.assign({}, lista[i], req.body, { id: lista[i].id, ts: lista[i].ts }));
  const erroFornecedor = vincularFornecedorMnt(ev, lista[i]);
  if (erroFornecedor) return res.status(400).json({ erro: erroFornecedor });
  lista[i] = ev;
  await salvarManutencao(lista);
  await registrarHistorico([{ placa: ev.placa, acao: 'editou', texto: `Manutenção (${ev.tipo}) · ${ev.item || 's/ descrição'}` }], quemFez(req));
  res.json({ ok: true, evento: ev });
}));

// Troca o motorista de UM veículo (placa) em TODOS os seus eventos de uma vez
// e registra a mudança no histórico — "histórico do motorista" por placa.
app.put('/api/manutencao/motorista/:placa', exigeEditar('manutencao'), rota(async (req, res) => {
  const placa = decodeURIComponent(req.params.placa || '').trim().toUpperCase(); // cliente envia encodeURIComponent

  const motorista = String((req.body && req.body.motorista) || '').trim();
  const lista = lerManutencao();
  const doVeiculo = lista.filter(e => String(e.placa || '').toUpperCase() === placa);
  if (!doVeiculo.length) return res.status(404).json({ erro: 'Nenhum evento para essa placa.' });
  const anterior = (doVeiculo.find(e => e.motorista && e.motorista !== '—') || {}).motorista || '';
  if (anterior === motorista) return res.json({ ok: true, alterados: 0, anterior });
  let n = 0;
  for (const e of lista) if (String(e.placa || '').toUpperCase() === placa) { e.motorista = motorista; n++; }
  await salvarManutencao(lista);
  await registrarHistorico([{ placa, acao: 'trocou o motorista', texto: `Motorista: ${anterior || '—'} → ${motorista || '—'} (${n} evento${n > 1 ? 's' : ''})` }], quemFez(req));
  res.json({ ok: true, alterados: n, anterior });
}));

app.delete('/api/manutencao/:id', exigeEditar('manutencao'), rota(async (req, res) => {
  const lista = lerManutencao();
  const id = decodeURIComponent(req.params.id);
  const ev = lista.find(e => e.id === id);
  if (!ev) return res.status(404).json({ erro: 'Evento não encontrado.' });
  await salvarManutencao(lista.filter(e => e.id !== id));
  await registrarHistorico([{ placa: ev.placa, acao: 'excluiu', texto: `Manutenção (${ev.tipo}) · ${ev.item || 's/ descrição'}` }], quemFez(req));
  res.json({ ok: true });
}));

// Exclui em lote por ids (com snapshot antes). Mesma permissão do delete individual.
app.post('/api/manutencao/lote-excluir', exigeEditar('manutencao'), rota(async (req, res) => {
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids.map(x => String(x)) : [];
  if (!ids.length) return res.status(400).json({ erro: 'Nenhum evento informado.' });
  const alvo = new Set(ids);
  const lista = lerManutencao();
  const novos = lista.filter(e => !alvo.has(e.id));
  const excluidos = lista.length - novos.length;
  if (excluidos) {
    await snapshotManutencao('antes de excluir em lote');
    await salvarManutencao(novos);
    await registrarHistorico([{ acao: 'excluiu em lote', texto: `${excluidos} evento(s) de manutenção excluído(s)` }], quemFez(req));
  }
  res.json({ ok: true, excluidos });
}));

// Apaga TODOS os eventos (com snapshot antes). Só admin/local.
app.delete('/api/manutencao', exigeAdminOuLocal, rota(async (req, res) => {
  await snapshotManutencao('antes de limpar tudo');
  const n = lerManutencao().length;
  await salvarManutencao([]);
  await registrarHistorico([{ placa: '', acao: 'limpou', texto: `Manutenção zerada; ${n} eventos removidos` }], quemFez(req));
  res.json({ ok: true, removidos: n });
}));

// Importa a planilha "Relatório de Manutenção". Lê SÓ a aba de histórico detalhado
// (base bruta) e SUBSTITUI tudo. Faz snapshot antes. Só admin/local.
app.post('/api/manutencao/importar', exigeAdminOuLocal, uploadPlanilha.single('arquivo'), rota(async (req, res) => {
  if (!req.file) return res.status(400).json({ erro: 'Nenhum arquivo enviado.' });
  let wb;
  try { wb = XLSX.read(req.file.buffer, { type: 'buffer', cellDates: false }); }
  catch (e) { console.error('Erro ao ler planilha de manutenção:', e.message); return res.status(400).json({ erro: 'Não consegui ler a planilha. Confira se é um Excel válido.' }); }

  // Acha a aba de histórico detalhado (base bruta). Aceita variações de nome.
  const norm = (x) => String(x || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  let abaHist = wb.SheetNames.find(nm => norm(nm).includes('HISTORICODETALHADO'))
    || wb.SheetNames.find(nm => norm(nm).includes('HISTORICO') && norm(nm).includes('DETALH'))
    || wb.SheetNames.find(nm => norm(nm).includes('DETALHADO'));
  // Fallback: primeira aba cujo cabeçalho tenha Placa + Custo.
  if (!abaHist) {
    abaHist = wb.SheetNames.find(nm => {
      const linhas = XLSX.utils.sheet_to_json(wb.Sheets[nm], { header: 1, defval: '' });
      const cab = (linhas[0] || []).map(norm);
      return cab.some(c => c.includes('PLACA')) && cab.some(c => c.includes('CUSTO'));
    });
  }
  if (!abaHist) return res.status(400).json({ erro: 'Não encontrei a aba de histórico detalhado (esperado: "5. Histórico Detalhado" com colunas Data/Placa/Custo).' });

  const linhas = XLSX.utils.sheet_to_json(wb.Sheets[abaHist], { header: 1, defval: '' });
  if (!linhas.length) return res.status(400).json({ erro: 'A aba de histórico está vazia.' });
  // Mapeia colunas pelo cabeçalho (robusto a ordem/acentos).
  const cab = (linhas[0] || []).map(norm);
  const acharCol = (...frags) => cab.findIndex(c => frags.some(f => c.includes(f)));
  const idx = {
    data: acharCol('DATA'), placa: acharCol('PLACA'), montadora: acharCol('MONTADORA', 'MARCA'),
    modelo: acharCol('MODELO'), ano: acharCol('ANO'), tipo: acharCol('TIPO'),
    item: acharCol('ITEM', 'DESCRICAO', 'SERVICO'), custo: acharCol('CUSTO', 'VALOR'), centro: acharCol('CENTRO'),
    fornecedor: cab.indexOf('FORNECEDOR'), fornecedorId: cab.indexOf('FORNECEDORID'),
  };
  if (idx.placa < 0 || idx.custo < 0) return res.status(400).json({ erro: 'A aba não tem as colunas Placa e Custo esperadas.' });

  // Mapa placa→motorista a partir da aba "Motoristas" (se houver).
  const motoristas = {};
  const abaMot = wb.SheetNames.find(nm => norm(nm).includes('MOTORISTA'));
  if (abaMot) {
    for (const r of XLSX.utils.sheet_to_json(wb.Sheets[abaMot], { header: 1, defval: '' }).slice(1)) {
      const pl = String(r[0] || '').trim().toUpperCase();
      const mo = String(r[1] || '').trim();
      if (pl && mo) motoristas[pl] = mo;
    }
  }

  const eventos = [];
  for (const r of linhas.slice(1)) {
    const placa = String(idx.placa >= 0 ? r[idx.placa] : '').trim().toUpperCase();
    if (!placa) continue; // linha em branco
    const ev = normalizarManutencao({
      data: idx.data >= 0 ? serialExcelParaBR(r[idx.data]) : '',
      placa,
      montadora: idx.montadora >= 0 ? r[idx.montadora] : '',
      modelo: idx.modelo >= 0 ? r[idx.modelo] : '',
      ano: idx.ano >= 0 ? r[idx.ano] : '',
      tipo: idx.tipo >= 0 ? r[idx.tipo] : '',
      item: idx.item >= 0 ? r[idx.item] : '',
      custo: idx.custo >= 0 ? r[idx.custo] : 0,
      centroCusto: idx.centro >= 0 ? r[idx.centro] : '',
      motorista: motoristas[placa] || '',
      fornecedor: idx.fornecedor >= 0 ? r[idx.fornecedor] : '',
      fornecedorId: idx.fornecedorId >= 0 ? r[idx.fornecedorId] : '',
    });
    const erroFornecedor = vincularFornecedorMnt(ev, null, true);
    if (erroFornecedor) return res.status(400).json({ erro: `${placa}: ${erroFornecedor}` });
    eventos.push(ev);
  }
  if (!eventos.length) return res.status(400).json({ erro: 'Nenhum evento reconhecido na aba de histórico.' });

  await snapshotManutencao(`antes de importar (${eventos.length} eventos)`); // rede de segurança
  await salvarManutencao(eventos);
  // Guarda o Excel CRU que o usuário subiu (terça/quinta) p/ baixar depois como "Excel Original".
  try {
    await salvarDocBackup('manutencao_original', {
      nome: req.file.originalname || 'manutencao.xlsx',
      mime: req.file.mimetype || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      ts: Date.now(), tamanho: req.file.size || req.file.buffer.length,
      b64: req.file.buffer.toString('base64'),
    });
  } catch (e) { console.error('Falha ao guardar planilha original de manutenção:', e.message); }
  const placas = new Set(eventos.map(e => e.placa)).size;
  await registrarHistorico([{ placa: '', acao: 'importou', texto: `Manutenção importada; ${eventos.length} eventos · ${placas} veículos` }], quemFez(req));
  res.json({ ok: true, eventos: eventos.length, veiculos: placas, motoristas: Object.keys(motoristas).length });
}));

// Baixa a ÚLTIMA planilha original importada (o Excel cru que o usuário subiu).
app.get('/api/manutencao/original', exigeVer('manutencao'), rota(async (req, res) => {
  const doc = await lerDocBackup('manutencao_original', null);
  if (!doc || !doc.b64) return res.status(404).json({ erro: 'Nenhuma planilha original foi importada ainda.' });
  const buf = Buffer.from(doc.b64, 'base64');
  res.set('Content-Type', doc.mime || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.set('X-Content-Type-Options', 'nosniff');
  res.set('Cache-Control', 'no-store');
  const nome = String(doc.nome || 'manutencao-original.xlsx');
  const ascii = nome.replace(/[^\x20-\x7E]/g, '_').replace(/["\\]/g, '_');
  const extValue = encodeURIComponent(nome).replace(/['()*!]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase());
  res.set('Content-Disposition', `attachment; filename="${ascii}"; filename*=UTF-8''${extValue}`);
  res.send(buf);
}));

app.get('/api/manutencao/exportar', exigeVer('manutencao'), (req, res) => {
  let eventos = lerManutencao();
  // ?ids=a,b,c → exporta só os eventos selecionados (barra de seleção da aba)
  const idsQ = String(req.query.ids || '').trim();
  if (idsQ) {
    const alvo = new Set(idsQ.split(',').map(s => s.trim()).filter(Boolean));
    eventos = eventos.filter(e => alvo.has(e.id));
  }
  enviarPlanilha(res, 'MANUTENCAO.xlsx', 'Histórico Detalhado', [
    ['data', 'DATA'], ['placa', 'PLACA'], ['montadora', 'MONTADORA'], ['modelo', 'MODELO'], ['ano', 'ANO'],
    ['tipo', 'TIPO'], ['item', 'ITEM'], ['custo', 'CUSTO DO ITEM (R$)', (v) => Number(v) || 0],
    ['centroCusto', 'CENTRO DE CUSTO'], ['motorista', 'MOTORISTA'],
    ['fornecedor', 'FORNECEDOR'], ['fornecedorId', 'FORNECEDOR ID'],
  ], eventos);
});

/* ============================================================
   RELATÓRIOS POR VEÍCULO (aba Manutenção › Relatórios)
   Um PDF por carro: identificação (placa, modelo, chassi, renavam…), resumo dos
   custos e o histórico DETALHADO; eventos de manutenção, notas fiscais e o
   consolidado por oficina. Junta três fontes pela PLACA: cadastro da frota,
   eventos (`manutencao`) e notas fiscais (`oficina`).
   Permissão: 'manutencao' (o relatório é sobre a manutenção do veículo). Por isso
   só entram os campos de IDENTIFICAÇÃO do cadastro; nada financeiro da Frota
   (valor FIPE, percentuais de sócio, compra/venda) vaza para cá.
   ============================================================ */
const chavePlaca = (p) => String(p == null ? '' : p).trim().toUpperCase();
// "id1,id2" (query) → nomes dos usuários ATIVOS correspondentes, na ordem pedida e sem repetir.
// Teto de MAX_ASSINANTES só para não deixar a URL/o documento crescerem sem limite.
// IDs desconhecidos/inativos são ignorados em silêncio.
const MAX_ASSINANTES = 12;
function resolverAssinantes(param) {
  const ids = String(param || '').split(',').map(s => s.trim()).filter(Boolean).slice(0, MAX_ASSINANTES);
  if (!ids.length) return [];
  const porId = new Map();
  for (const u of lerUsuarios().usuarios) {
    if (u.status !== 'aprovado') continue;
    if (u.id) porId.set(String(u.id), (u.nome || u.usuario || '').trim());
  }
  const nomes = [];
  for (const id of ids) {
    const nome = porId.get(id);
    if (nome && !nomes.includes(nome)) nomes.push(nome);
  }
  return nomes;
}
// "dd/mm/aaaa" → aaaammdd (ordenável). 0 quando ilegível.
const ordDataBRRel = (d) => { const m = String(d || '').match(/(\d{2})\/(\d{2})\/(\d{4})/); return m ? Number(m[3] + m[2] + m[1]) : 0; };
// Reúne tudo o que o relatório de UMA placa precisa. veiculo = null se a placa só existe
// nos eventos importados (carro que saiu da frota, planilha antiga…) — o relatório sai igual.
function dadosRelatorioVeiculo(placa) {
  const alvo = chavePlaca(placa);
  const veiculo = lerDados().veiculos.find(v => chavePlaca(v.placa) === alvo) || null;
  const eventos = lerManutencao().filter(e => chavePlaca(e.placa) === alvo)
    .sort((a, b) => ordDataBRRel(b.data) - ordDataBRRel(a.data));
  const notas = lerOficina().filter(o => chavePlaca(o.placa) === alvo)
    .sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')));
  return { placa: alvo, veiculo, eventos, notas };
}

// Relatório de manutenção do veículo em PDF (pdf-lib). Clona o molde de
// gerarRelatorioFuncPDF (A4, Helvetica/HelveticaBold, safe()/wrap()/secao()) e acrescenta
// um desenhador de TABELAS com quebra de página e cabeçalho repetido — é o que muda aqui:
// o miolo do relatório é lista, não ficha. Veículo sem cadastro na frota → só a placa.
async function gerarRelatorioVeiculoPDF(v, eventos, notas, meta) {
  const veic = v || {};
  const placa = (meta && meta.placa) || veic.placa || '—';
  const A4_W = 595.28, A4_H = 841.89, MARGEM = 42;
  const LARG = A4_W - MARGEM * 2;
  const COR_INK = rgb(0.11, 0.14, 0.20), COR_MUTED = rgb(0.42, 0.46, 0.54);
  const COR_BRAND = rgb(0.192, 0.212, 0.243), COR_LINHA = rgb(0.88, 0.90, 0.94);
  const COR_BOX = rgb(0.96, 0.97, 0.99), COR_ZEBRA = rgb(0.972, 0.978, 0.988);
  const COR_BRANCO = rgb(1, 1, 1), COR_VERM = rgb(0.77, 0.15, 0.15), COR_VERDE = rgb(0.06, 0.5, 0.22);
  // WinAnsi (cp1252) cobre os acentos do português; troca a tipografia "esperta" e descarta o resto.
  const safe = (s) => String(s == null ? '' : s)
    .replace(/[–—]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/…/g, '...').replace(/•/g, '-').replace(/[^\x00-\xFF]/g, '?');
  const moeda = (n) => 'R$ ' + (Number(n) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const isoBR = (s) => { const m = String(s || '').slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? `${m[3]}/${m[2]}/${m[1]}` : String(s || ''); };
  const custoDe = (e) => Number(e.custo) || 0;
  const ehCorretivaRel = (e) => String(e.tipo || '').toLowerCase().startsWith('corr');

  const doc = await PDFDocument.create();
  doc.setTitle('Relatório de manutenção - ' + safe(placa));
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const fontB = await doc.embedFont(StandardFonts.HelveticaBold);

  let page = doc.addPage([A4_W, A4_H]);
  let y = A4_H - MARGEM;
  const novaPagina = () => { page = doc.addPage([A4_W, A4_H]); y = A4_H - MARGEM; };
  const garante = (h) => { if (y - h < MARGEM + 24) novaPagina(); };
  // Quebra em linhas que cabem em maxW. Palavra única gigante (código de peça, URL) parte
  // no caractere — pdf-lib não faz clipping, então sem isso transbordaria a margem.
  const wrap = (texto, fnt, size, maxW) => {
    const palavras = safe(texto).split(/\s+/).filter(Boolean);
    if (!palavras.length) return [''];
    const linhas = []; let cur = '';
    for (let w of palavras) {
      while (fnt.widthOfTextAtSize(w, size) > maxW && w.length > 1) {
        let i = 1;
        while (i < w.length && fnt.widthOfTextAtSize(w.slice(0, i + 1), size) <= maxW) i++;
        if (cur) { linhas.push(cur); cur = ''; }
        linhas.push(w.slice(0, i));
        w = w.slice(i);
      }
      const teste = cur ? cur + ' ' + w : w;
      if (fnt.widthOfTextAtSize(teste, size) > maxW && cur) { linhas.push(cur); cur = w; } else cur = teste;
    }
    if (cur) linhas.push(cur);
    return linhas;
  };
  const secao = (titulo, sub) => {
    garante(46);
    y -= 16;
    page.drawText(safe(titulo).toUpperCase(), { x: MARGEM, y: y - 10, size: 10.5, font: fontB, color: COR_BRAND });
    if (sub) {
      const t = safe(sub);
      page.drawText(t, { x: MARGEM + LARG - font.widthOfTextAtSize(t, 8.5), y: y - 9, size: 8.5, font, color: COR_MUTED });
    }
    y -= 15;
    page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.8, color: COR_LINHA });
    y -= 8;
  };
  // Grade de campos rótulo-em-cima/valor-embaixo em N colunas (ficha de identificação).
  const grid = (pares, cols) => {
    const cheios = pares.filter(([, val]) => String(val == null ? '' : val).trim() !== '');
    if (!cheios.length) return;
    const cw = LARG / cols;
    for (let i = 0; i < cheios.length; i += cols) {
      const bloco = cheios.slice(i, i + cols);
      const celulas = bloco.map(([, val]) => wrap(val, font, 10, cw - 12));
      const h = 13 + Math.max(...celulas.map(c => c.length)) * 12.5 + 7;
      garante(h);
      bloco.forEach(([rot], j) => {
        page.drawText(safe(String(rot).toUpperCase()), { x: MARGEM + j * cw, y: y - 8, size: 6.8, font: fontB, color: COR_MUTED });
      });
      celulas.forEach((linhas, j) => {
        linhas.forEach((ln, k) => page.drawText(ln, { x: MARGEM + j * cw, y: y - 22 - k * 12.5, size: 10, font, color: COR_INK }));
      });
      y -= h;
    }
  };
  // Faixa de indicadores (caixas lado a lado) — o "resumo em números" do veículo.
  const kpis = (itens) => {
    const gap = 9, w = (LARG - gap * (itens.length - 1)) / itens.length, h = 52;
    garante(h + 8);
    itens.forEach((it, i) => {
      const x = MARGEM + i * (w + gap);
      page.drawRectangle({ x, y: y - h, width: w, height: h, color: COR_BOX, borderColor: COR_LINHA, borderWidth: 1 });
      page.drawText(safe(it.rotulo.toUpperCase()), { x: x + 9, y: y - 17, size: 6.8, font: fontB, color: COR_MUTED });
      const val = safe(it.valor);
      let size = 13.5;
      while (size > 7.5 && fontB.widthOfTextAtSize(val, size) > w - 18) size -= 0.5;
      page.drawText(val, { x: x + 9, y: y - 35, size, font: fontB, color: it.cor || COR_INK });
      if (it.sub) page.drawText(safe(it.sub), { x: x + 9, y: y - 46, size: 7, font, color: COR_MUTED });
    });
    y -= h + 8;
  };
  // Tabela com cabeçalho repetido a cada página, zebra e linha de total opcional.
  // colunas: [{ tit, larg, dir?: true (alinha à direita), max?: nº máx. de linhas na célula }]
  const tabela = (colunas, linhas, totais) => {
    const SIZE = 8.5, LH = 10.5, PAD = 6;
    const xs = []; let acc = MARGEM;
    colunas.forEach(c => { xs.push(acc); acc += c.larg; });
    const posX = (i, txt, fnt, size) => colunas[i].dir
      ? xs[i] + colunas[i].larg - PAD - fnt.widthOfTextAtSize(txt, size)
      : xs[i] + PAD;
    const cabecalho = () => {
      garante(20);
      page.drawRectangle({ x: MARGEM, y: y - 16, width: LARG, height: 16, color: COR_BOX });
      colunas.forEach((c, i) => {
        const t = safe(c.tit);
        page.drawText(t, { x: posX(i, t, fontB, 7.6), y: y - 11, size: 7.6, font: fontB, color: COR_MUTED });
      });
      y -= 16;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.6, color: COR_LINHA });
    };
    cabecalho();
    linhas.forEach((linha, idx) => {
      const celulas = colunas.map((c, i) => {
        const ls = wrap(linha[i], font, SIZE, c.larg - PAD * 2);
        return c.max && ls.length > c.max ? ls.slice(0, c.max).map((t, k) => (k === c.max - 1 ? t + '...' : t)) : ls;
      });
      const h = Math.max(...celulas.map(c => c.length)) * LH + 6;
      if (y - h < MARGEM + 26) { novaPagina(); cabecalho(); }
      if (idx % 2 === 1) page.drawRectangle({ x: MARGEM, y: y - h, width: LARG, height: h, color: COR_ZEBRA });
      celulas.forEach((ls, i) => ls.forEach((ln, j) => {
        page.drawText(ln, { x: posX(i, ln, font, SIZE), y: y - 11 - j * LH, size: SIZE, font, color: COR_INK });
      }));
      y -= h;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.4, color: COR_LINHA });
    });
    if (totais) {
      const h = 18;
      if (y - h < MARGEM + 26) { novaPagina(); cabecalho(); }
      page.drawRectangle({ x: MARGEM, y: y - h, width: LARG, height: h, color: COR_BOX });
      totais.forEach((t, i) => {
        if (!t) return;
        const txt = safe(t);
        page.drawText(txt, { x: posX(i, txt, fontB, 8.5), y: y - 12.5, size: 8.5, font: fontB, color: COR_INK });
      });
      y -= h;
    }
    y -= 2;
  };

  // ---- Cabeçalho institucional: logo da empresa dona (SUL/NTE) + título do documento ----
  const sigla = empresaSigla(veic.dono) || '';
  let logoImg = null;
  try {
    const arq = 'logo-' + (['NTE', 'SUL'].includes(sigla) ? sigla.toLowerCase() : 'rm') + '.png';
    const lp = path.join(RAIZ, 'frontend', 'img', arq);
    if (fs.existsSync(lp)) logoImg = await doc.embedPng(fs.readFileSync(lp));
  } catch (e) { logoImg = null; }
  const LOGO_H = 32;
  const topo = y;
  let esqX = MARGEM;
  if (logoImg) {
    const lw = logoImg.width * (LOGO_H / logoImg.height);
    page.drawImage(logoImg, { x: MARGEM, y: topo - LOGO_H, width: lw, height: LOGO_H });
    esqX += lw + 14;
  }
  page.drawText(safe('RELATÓRIO DE MANUTENÇÃO DO VEÍCULO'), { x: esqX, y: topo - 15, size: 13, font: fontB, color: COR_INK });
  page.drawText(safe('Histórico completo de serviços, custos e notas fiscais'), { x: esqX, y: topo - 28, size: 8.5, font, color: COR_MUTED });
  y = topo - LOGO_H - 12;
  page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 1.5, color: COR_BRAND });
  y -= 14;

  // ---- Faixa do veículo: placa em destaque + modelo/versão ----
  const FAIXA = 54;
  garante(FAIXA + 6);
  const faixaTopo = y;
  page.drawRectangle({ x: MARGEM, y: faixaTopo - FAIXA, width: LARG, height: FAIXA, color: COR_BOX, borderColor: COR_LINHA, borderWidth: 1 });
  const PLACA_W = 132;
  page.drawRectangle({ x: MARGEM + 10, y: faixaTopo - FAIXA + 11, width: PLACA_W, height: 32, color: COR_BRAND });
  let pSize = 19;
  while (pSize > 10 && fontB.widthOfTextAtSize(safe(placa), pSize) > PLACA_W - 14) pSize -= 0.5;
  page.drawText(safe(placa), {
    x: MARGEM + 10 + (PLACA_W - fontB.widthOfTextAtSize(safe(placa), pSize)) / 2,
    y: faixaTopo - FAIXA + 11 + (32 - pSize) / 2 + 2, size: pSize, font: fontB, color: COR_BRANCO,
  });
  const infoX = MARGEM + 10 + PLACA_W + 16, infoW = LARG - (PLACA_W + 36);
  const tituloVeic = [veic.modelo, veic.versao].filter(Boolean).join(' ') || (eventos[0] && eventos[0].modelo) || 'Veículo sem cadastro na frota';
  wrap(tituloVeic, fontB, 13, infoW).slice(0, 1).forEach(ln => page.drawText(ln, { x: infoX, y: faixaTopo - 24, size: 13, font: fontB, color: COR_INK }));
  const anos = [veic.anoFab, veic.anoMod].filter(Boolean).join('/') || (eventos[0] && eventos[0].ano) || '';
  const sub = [
    (eventos[0] && eventos[0].montadora) || '', anos ? 'Ano ' + anos : '', veic.cor || '',
    veic.centroCusto || '', veic.status ? 'Situação: ' + veic.status : '',
  ].filter(Boolean).join('  ·  ');
  // Até 2 linhas: montadora + ano + cor + centro de custo + situação não cabem em uma só.
  if (sub) wrap(sub, font, 9, infoW).slice(0, 2).forEach((ln, i) => page.drawText(ln, { x: infoX, y: faixaTopo - 37 - i * 11, size: 9, font, color: COR_MUTED }));
  y = faixaTopo - FAIXA - 4;

  // ---- Identificação do veículo (só campos de cadastro; nada financeiro da Frota) ----
  const motoristaVeic = (eventos.find(e => e.motorista && e.motorista !== '—') || {}).motorista || '';
  secao('Identificação do veículo');
  if (!v) {
    y -= 4;
    page.drawText(safe('Este veículo não está cadastrado na aba Frota; os dados abaixo vêm dos próprios registros de manutenção.'), { x: MARGEM, y: y - 9, size: 8.5, font, color: COR_MUTED });
    y -= 18;
  }
  grid([
    ['Placa', placa],
    ['Modelo', veic.modelo || (eventos[0] && eventos[0].modelo) || ''],
    ['Versão', veic.versao],
    ['Montadora', (eventos[0] && eventos[0].montadora) || ''],
    ['Ano fab./modelo', anos],
    ['Cor', veic.cor],
    ['Chassi', veic.chassi],
    ['Renavam', veic.renavam],
    ['Motor', veic.motor],
    ['Centro de custo', veic.centroCusto || (eventos[0] && eventos[0].centroCusto) || ''],
    ['Proprietário', veic.dono],
    ['Situação', veic.status],
    ['Motorista', motoristaVeic],
    ['Documento (ano)', veic.doc ? String(veic.doc) : ''],
  ], 3);

  // ---- Resumo dos custos ----
  const total = eventos.reduce((s, e) => s + custoDe(e), 0);
  const corretivas = eventos.filter(ehCorretivaRel);
  const preventivas = eventos.filter(e => !ehCorretivaRel(e));
  const totalCorr = corretivas.reduce((s, e) => s + custoDe(e), 0);
  const totalPrev = preventivas.reduce((s, e) => s + custoDe(e), 0);
  const totalNotas = notas.reduce((s, n) => s + (Number(n.valor) || 0), 0);
  const datas = eventos.map(e => e.data).filter(d => ordDataBRRel(d)).sort((a, b) => ordDataBRRel(a) - ordDataBRRel(b));
  const periodo = datas.length ? `${datas[0]} a ${datas[datas.length - 1]}` : '';
  const pctCorr = total ? Math.round((totalCorr / total) * 100) : 0;
  secao('Resumo das manutenções', periodo ? 'Período: ' + periodo : '');
  kpis([
    { rotulo: 'Custo total', valor: moeda(total), cor: COR_VERM, sub: `${eventos.length} manutenção(ões)` },
    { rotulo: 'Corretiva', valor: moeda(totalCorr), cor: COR_VERM, sub: `${corretivas.length} evento(s) · ${pctCorr}% do total` },
    { rotulo: 'Preventiva', valor: moeda(totalPrev), cor: COR_VERDE, sub: `${preventivas.length} evento(s)` },
    { rotulo: 'Custo médio', valor: moeda(eventos.length ? total / eventos.length : 0), sub: 'por manutenção' },
    { rotulo: 'Notas fiscais', valor: moeda(totalNotas), sub: `${notas.length} nota(s) arquivada(s)` },
  ]);

  // Gastos por ano (só quando o histórico cruza mais de um ano)
  const porAno = new Map();
  eventos.forEach(e => {
    const m = String(e.data || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
    const ano = m ? m[3] : 'Sem data';
    const a = porAno.get(ano) || { ano, qtd: 0, corr: 0, prev: 0, total: 0 };
    a.qtd++; a.total += custoDe(e);
    if (ehCorretivaRel(e)) a.corr += custoDe(e); else a.prev += custoDe(e);
    porAno.set(ano, a);
  });
  if (porAno.size > 1) {
    secao('Gastos por ano');
    tabela(
      [{ tit: 'Ano', larg: 80 }, { tit: 'Manutenções', larg: 90, dir: true }, { tit: 'Corretiva', larg: 110, dir: true }, { tit: 'Preventiva', larg: 110, dir: true }, { tit: 'Total', larg: 121.28, dir: true }],
      [...porAno.values()].sort((a, b) => String(b.ano).localeCompare(String(a.ano)))
        .map(a => [a.ano, String(a.qtd), moeda(a.corr), moeda(a.prev), moeda(a.total)]),
      ['TOTAL', String(eventos.length), moeda(totalCorr), moeda(totalPrev), moeda(total)],
    );
  }

  // ---- Manutenções realizadas (detalhado) ----
  secao('Manutenções realizadas (detalhado)', `${eventos.length} registro(s)`);
  if (!eventos.length) {
    page.drawText(safe('Nenhuma manutenção registrada para este veículo.'), { x: MARGEM, y: y - 10, size: 9.5, font, color: COR_MUTED });
    y -= 20;
  } else {
    tabela(
      [
        { tit: 'Data', larg: 56 }, { tit: 'Tipo', larg: 60 },
        { tit: 'Item / serviço realizado', larg: 214, max: 4 },
        { tit: 'Centro de custo', larg: 100, max: 2 }, { tit: 'Valor', larg: 81.28, dir: true },
      ],
      eventos.map(e => [e.data || '—', ehCorretivaRel(e) ? 'Corretiva' : 'Preventiva', e.item || '—', e.centroCusto || '—', moeda(custoDe(e))]),
      ['TOTAL', '', '', '', moeda(total)],
    );
  }

  // ---- Notas fiscais das oficinas ----
  if (notas.length) {
    secao('Notas fiscais das oficinas', `${notas.length} nota(s)`);
    tabela(
      [
        { tit: 'Data', larg: 56 }, { tit: 'Nº NF', larg: 58, max: 2 },
        { tit: 'Fornecedor / oficina', larg: 124, max: 3 },
        { tit: 'Serviço', larg: 142, max: 4 },
        { tit: 'KM', larg: 48, dir: true }, { tit: 'Valor', larg: 83.28, dir: true },
      ],
      notas.map(n => [isoBR(n.data) || '—', n.numeroNF || '—', n.fornecedor || '—', n.descricao || '—', n.km || '—', moeda(n.valor)]),
      ['TOTAL', '', '', '', '', moeda(totalNotas)],
    );

    // Consolidado por oficina — quanto foi para cada fornecedor
    const porForn = new Map();
    notas.forEach(n => {
      const nome = (n.fornecedor || '').trim() || 'Sem fornecedor informado';
      const f = porForn.get(nome) || { nome, cnpj: n.cnpjFornecedor || '', qtd: 0, total: 0, ultima: '' };
      f.qtd++; f.total += Number(n.valor) || 0;
      if (!f.cnpj && n.cnpjFornecedor) f.cnpj = n.cnpjFornecedor;
      if (String(n.data || '') > String(f.ultima || '')) f.ultima = n.data || '';
      porForn.set(nome, f);
    });
    secao('Gastos por oficina / fornecedor');
    tabela(
      [
        { tit: 'Fornecedor / oficina', larg: 200, max: 2 }, { tit: 'CNPJ', larg: 110, max: 1 },
        { tit: 'Notas', larg: 50, dir: true }, { tit: 'Última', larg: 66, dir: true }, { tit: 'Total', larg: 85.28, dir: true },
      ],
      [...porForn.values()].sort((a, b) => b.total - a.total)
        .map(f => [f.nome, f.cnpj || '—', String(f.qtd), isoBR(f.ultima) || '—', moeda(f.total)]),
      ['TOTAL', '', String(notas.length), '', moeda(totalNotas)],
    );
  }

  // ---- Observações do cadastro ----
  if (String(veic.observacoes || '').trim()) {
    secao('Observações do cadastro');
    wrap(veic.observacoes, font, 10, LARG).forEach(ln => { garante(13.5); page.drawText(ln, { x: MARGEM, y: y - 10, size: 10, font, color: COR_INK }); y -= 13.5; });
  }

  // ---- Assinaturas (quem o usuário escolheu no popup antes de gerar) ----
  // Nomes vêm resolvidos por ID no servidor (nunca do texto do cliente). 1 assinante = linha
  // centralizada; 2+ = duas por linha. O bloco inteiro não se parte entre páginas.
  const assinantes = (meta && Array.isArray(meta.assinantes) ? meta.assinantes : []).filter(n => String(n || '').trim());
  if (assinantes.length) {
    const cols = assinantes.length === 1 ? 1 : 2;
    // Cabeçalho + a 1ª dupla de linhas nunca ficam órfãos no pé da página; daí em diante
    // cada dupla se vira com garante() (muitos assinantes podem passar para a página seguinte).
    if (y - 96 < MARGEM + 30) novaPagina();
    secao('Assinaturas', (meta && meta.carimbo) ? 'Data: ' + String(meta.carimbo).slice(0, 10) : '');
    y -= 16;
    const cw = LARG / cols;
    for (let i = 0; i < assinantes.length; i += cols) {
      const bloco = assinantes.slice(i, i + cols);
      garante(56);
      bloco.forEach((nome, j) => {
        const largLinha = Math.min(cw - 30, 240);
        const x = MARGEM + j * cw + (cw - largLinha) / 2;
        page.drawLine({ start: { x, y: y - 20 }, end: { x: x + largLinha, y: y - 20 }, thickness: 0.8, color: COR_INK });
        const t = safe(nome);
        let s = 10;
        while (s > 6.5 && fontB.widthOfTextAtSize(t, s) > largLinha) s -= 0.5;
        page.drawText(t, { x: x + (largLinha - fontB.widthOfTextAtSize(t, s)) / 2, y: y - 33, size: s, font: fontB, color: COR_INK });
      });
      y -= 56;
    }
  }

  // ---- Rodapé em todas as páginas: stamp + paginação ----
  const paginas = doc.getPages();
  const quem = (meta && meta.quem) || 'sistema';
  const carimbo = (meta && meta.carimbo) || '';
  paginas.forEach((p, i) => {
    const rod = safe(`Gestão RM · ${placa} · Relatório gerado por ${quem}${carimbo ? ' em ' + carimbo : ''}`);
    p.drawText(rod, { x: MARGEM, y: MARGEM - 18, size: 8, font, color: COR_MUTED });
    const pg = `${i + 1}/${paginas.length}`;
    p.drawText(pg, { x: A4_W - MARGEM - font.widthOfTextAtSize(pg, 8), y: MARGEM - 18, size: 8, font, color: COR_MUTED });
  });

  return Buffer.from(await doc.save());
}

// Lista de cartões da sub-aba: um por veículo (cadastro da frota + placas órfãs que só
// aparecem nos eventos), já com os números agregados que o cartão mostra.
app.get('/api/manutencao/relatorios', exigeVer('manutencao'), (req, res) => {
  const eventos = lerManutencao();
  const notas = lerOficina();
  const mapa = new Map();
  const criar = (placa) => {
    const p = chavePlaca(placa);
    if (!p) return null;
    if (!mapa.has(p)) {
      mapa.set(p, {
        placa: p, modelo: '', versao: '', montadora: '', ano: '', cor: '', chassi: '', renavam: '',
        centroCusto: '', dono: '', status: '', motorista: '', noCadastro: false,
        eventos: 0, custoTotal: 0, corretivas: 0, custoCorretiva: 0, preventivas: 0, custoPreventiva: 0,
        ultima: '', notas: 0, custoNotas: 0,
      });
    }
    return mapa.get(p);
  };
  for (const v of lerDados().veiculos) {
    const c = criar(v.placa); if (!c) continue;
    c.noCadastro = true;
    c.modelo = v.modelo || ''; c.versao = v.versao || ''; c.cor = v.cor || '';
    c.ano = [v.anoFab, v.anoMod].filter(Boolean).join('/');
    c.chassi = v.chassi || ''; c.renavam = v.renavam || '';
    c.centroCusto = v.centroCusto || ''; c.dono = v.dono || ''; c.status = v.status || '';
  }
  for (const e of eventos) {
    const c = criar(e.placa); if (!c) continue;
    const custo = Number(e.custo) || 0;
    c.eventos++; c.custoTotal += custo;
    if (String(e.tipo || '').toLowerCase().startsWith('corr')) { c.corretivas++; c.custoCorretiva += custo; }
    else { c.preventivas++; c.custoPreventiva += custo; }
    if (ordDataBRRel(e.data) > ordDataBRRel(c.ultima)) c.ultima = e.data || '';
    if (!c.modelo && e.modelo) c.modelo = e.modelo;
    if (!c.montadora && e.montadora) c.montadora = e.montadora;
    if (!c.ano && e.ano) c.ano = e.ano;
    if (!c.centroCusto && e.centroCusto) c.centroCusto = e.centroCusto;
    if ((!c.motorista || c.motorista === '—') && e.motorista) c.motorista = e.motorista;
  }
  for (const n of notas) {
    const c = criar(n.placa); if (!c) continue;
    c.notas++; c.custoNotas += Number(n.valor) || 0;
    if (!c.modelo && n.modelo) c.modelo = n.modelo;
  }
  const lista = [...mapa.values()].sort((a, b) => a.placa.localeCompare(b.placa, 'pt-BR'));
  res.set('Cache-Control', 'no-store');
  res.json({ veiculos: lista });
});

// PDF do relatório de UMA placa. ?ver=1 abre no navegador (inline); sem ele, baixa.
app.get('/api/manutencao/relatorio/:placa', exigeVer('manutencao'), rota(async (req, res) => {
  const { placa, veiculo, eventos, notas } = dadosRelatorioVeiculo(decodeURIComponent(req.params.placa || ''));
  if (!placa) return res.status(400).json({ erro: 'Informe a placa do veículo.' });
  if (!veiculo && !eventos.length && !notas.length) {
    return res.status(404).json({ erro: 'Nenhum veículo, manutenção ou nota fiscal encontrada para esta placa.' });
  }
  const agora = new Date();
  const carimbo = `${String(agora.getDate()).padStart(2, '0')}/${String(agora.getMonth() + 1).padStart(2, '0')}/${agora.getFullYear()} ${String(agora.getHours()).padStart(2, '0')}:${String(agora.getMinutes()).padStart(2, '0')}`;
  // Assinantes: o cliente manda só IDs; o NOME sai daqui, do cadastro de usuários ativos.
  // (nunca aceitar o nome digitado pelo cliente — seria texto arbitrário impresso no documento)
  const assinantes = resolverAssinantes(req.query.assinantes);
  const buf = await gerarRelatorioVeiculoPDF(veiculo, eventos, notas, { placa, quem: quemFez(req) || 'sistema', carimbo, assinantes });
  const inline = String(req.query.ver || '') === '1';
  registrarSeguranca(req, inline ? 'ver_relatorio_veiculo' : 'download_relatorio_veiculo', {
    categoria: 'auditoria', area: 'manutencao', acao: inline ? 'ver_relatorio' : 'baixar_relatorio',
    detalhes: `${placa} · ${eventos.length} manutenção(ões)${assinantes.length ? ' · assina: ' + assinantes.join(', ') : ''}`,
  });
  const nome = 'RELATORIO_MANUTENCAO_' + nomeArquivoSeguro(placa).replace(/\s+/g, '_') + '.pdf';
  res.set('Content-Type', 'application/pdf');
  res.set('Content-Disposition', `${inline ? 'inline' : 'attachment'}; filename="${nome.replace(/[^\x20-\x7E]/g, '_')}"; filename*=UTF-8''${encodeURIComponent(nome)}`);
  res.set('Cache-Control', 'no-store');
  res.send(buf);
}));

