// ─── Leitor das planilhas de abastecimento (combustível) ─────────────────────
// Aceita o export financeiro "Conta Azul" (uma aba por mês) e variações de layout:
//   • Data · Valor · Categoria · Descrição · Fornecedor/Posto · Centro de Custo,
//     com PLACA e MOTORISTA embutidos na Descrição ("Abastecimento - PCT9G58(George)").
//   • Layout de cartão/transação (colunas próprias: DATA · PLACA · MOTORISTA · VALOR · ESTABELECIMENTO · CENTRO).
// Valores negativos (despesa) viram positivos. Datas: serial do Excel OU texto BR. Se a aba tem nome de
// mês e a coluna de data está SISTEMATICAMENTE errada (a maioria das linhas cai fora do mês da aba —
// ex.: aba "Junho" com seriais de janeiro), as datas dessa aba são fixadas no 1º dia do mês da aba.
const MESES_ABA_ABT = { JANEIRO: 1, FEVEREIRO: 2, MARCO: 3, ABRIL: 4, MAIO: 5, JUNHO: 6, JULHO: 7, AGOSTO: 8, SETEMBRO: 9, OUTUBRO: 10, NOVEMBRO: 11, DEZEMBRO: 12 };
function parseAbastecimentoPlanilha(buffer) {
  const wb = XLSX.read(buffer, { type: 'buffer', cellDates: false });
  const norm = (x) => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const PLACA_RE = /\b[A-Z]{3}\d(?:[A-Z]\d{2}|\d{3})\b/;         // placa isolada (\b evita casar dentro de um código maior)
  const PLACA_FULL = /^[A-Z]{3}\d(?:[A-Z]\d{2}|\d{3})$/;         // Mercosul (LLLDLDD) ou antiga (LLLDDDD)
  const DESC_RE = /([A-Z]{3}\d(?:[A-Z]\d{2}|\d{3}))\s*\(\s*([^)]*?)\s*\)/i; // "PLACA(Motorista)" na Descrição
  const KW = ['DATA', 'VALOR', 'CATEGORIA', 'DESCRICAO', 'PLACA', 'CENTRO', 'FORNECEDOR', 'ESTABELECIMENTO', 'MOTORISTA'];
  const trans = [];
  let datasAjustadas = 0;
  for (const nm of wb.SheetNames) {
    // Mês da aba: casa por TOKEN exato (evita "MARCOS" → março, "Junho 2026" → junho).
    const tokens = String(nm).normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().split(/[^A-Z]+/).filter(Boolean);
    const chaveMes = tokens.find(t => MESES_ABA_ABT[t] !== undefined);
    const mesAba = chaveMes ? MESES_ABA_ABT[chaveMes] : 0;
    const linhas = XLSX.utils.sheet_to_json(wb.Sheets[nm], { header: 1, defval: '' });
    // Cabeçalho nas 12 primeiras linhas: precisa de coluna de valor + pelo menos 2 palavras conhecidas.
    let h = -1;
    for (let i = 0; i < Math.min(12, linhas.length); i++) {
      const c = (linhas[i] || []).map(norm);
      if (c.some(x => x.includes('VALOR') || x.includes('TOTAL')) && KW.filter(k => c.some(x => x.includes(k))).length >= 2) { h = i; break; }
    }
    if (h < 0) continue;
    const cab = (linhas[h] || []).map(norm);
    let idxData = cab.findIndex(c => c.includes('COMPETENCIA') || c.includes('TRANSACAO'));
    if (idxData < 0) idxData = cab.findIndex(c => c.includes('DATA') && !c.includes('VENCIMENTO'));
    let idxValor = cab.findIndex(c => c.includes('VALOR'));
    if (idxValor < 0) idxValor = cab.findIndex(c => c.includes('TOTAL')); // formato antigo: "TOTAL R$"
    const idxCat = cab.findIndex(c => c.includes('CATEGORIA'));
    const idxDesc = cab.findIndex(c => c.includes('DESCRICAO'));
    let idxPosto = cab.findIndex(c => c.includes('ESTABELECIMENTO'));
    if (idxPosto < 0) idxPosto = cab.findIndex(c => c.includes('FORNECEDOR') || c.includes('CLIENTE'));
    let idxCentro = cab.findIndex(c => c.includes('CENTRO'));
    if (idxCentro < 0) idxCentro = cab.findIndex(c => c.includes('INFORMACAO')); // "INFORMAÇÃO ADICIONAL 1" = centro (layout cartão)
    const idxPlaca = cab.findIndex(c => c.includes('PLACA'));
    const idxMot = cab.findIndex(c => c.includes('MOTORISTA'));
    if (idxValor < 0) continue;
    const get = (r, i) => (i >= 0 ? r[i] : '');
    // 1ª passada: lê as linhas desta aba (data ainda "crua", só decodificada de serial→BR).
    const daAba = [];
    for (const r of linhas.slice(h + 1)) {
      const valor = Math.abs(custoNum(get(r, idxValor)));
      if (!valor) continue;                                        // linha vazia / total / legenda
      const cat = norm(get(r, idxCat));
      const descRaw = String(get(r, idxDesc) || '');
      // É combustível se a categoria/descrição dizem, OU se é um extrato de cartão (placa + estabelecimento, sem categoria).
      const ehComb = cat.includes('COMBUST') || /ABASTEC/i.test(descRaw) || (idxCat < 0 && idxDesc < 0 && idxPlaca >= 0 && idxPosto >= 0);
      if (!ehComb) continue;                                       // ignora linhas que não são de combustível
      let placa = '', motorista = '';
      const placaCol = String(get(r, idxPlaca) || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
      if (idxPlaca >= 0 && PLACA_FULL.test(placaCol)) {
        placa = placaCol;
        motorista = String(get(r, idxMot) || '').trim();
      } else {
        const m = descRaw.match(DESC_RE);
        if (m) { placa = m[1].toUpperCase(); motorista = (m[2] || '').trim(); }
        else { const m2 = descRaw.toUpperCase().match(PLACA_RE); if (m2) placa = m2[0]; }
      }
      if (!PLACA_FULL.test(placa)) continue;                       // sem placa reconhecível → fora
      daAba.push({ dataHora: serialExcelDataHoraParaBR(get(r, idxData)), placa, motorista, posto: String(get(r, idxPosto) || '').trim(), centroCusto: String(get(r, idxCentro) || '').trim(), valor, combustivel: '' });
    }
    // 2ª passada: só corrige a data quando a aba-mês está SISTEMATICAMENTE errada (< 50% das linhas
    // no mês da aba). Nesse caso fixa no 1º dia do mês (dia da célula não é confiável) mantendo o ano
    // dominante. Abas coerentes ficam intactas — datas legítimas fora do mês (competência) são preservadas.
    if (mesAba && daAba.length) {
      const anos = {};
      let comData = 0, batem = 0;
      for (const t of daAba) {
        const m = t.dataHora.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
        if (!m) continue;
        comData++; if (Number(m[2]) === mesAba) batem++;
        anos[m[3]] = (anos[m[3]] || 0) + 1;
      }
      if (comData && batem / comData < 0.5) {
        const anoDom = Object.keys(anos).sort((a, b) => anos[b] - anos[a])[0];
        const mm = String(mesAba).padStart(2, '0');
        for (const t of daAba) {
          const m = t.dataHora.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
          const ano = (m && m[3]) || anoDom;
          if (ano) { const nova = `01/${mm}/${ano}`; if (nova !== t.dataHora) { t.dataHora = nova; datasAjustadas++; } }
        }
      }
    }
    trans.push(...daAba);
  }
  return { trans, datasAjustadas };
}

// Importa uma OU MAIS planilhas de abastecimento. Por padrão MESCLA (soma sem duplicar);
// `?modo=substituir` zera antes. Snapshot automático antes de gravar. Só admin/local.
app.post('/api/abastecimento/importar', exigeAdminOuLocal, uploadPlanilha.any(), rota(async (req, res) => {
  const files = req.files || [];
  if (!files.length) return res.status(400).json({ erro: 'Nenhum arquivo enviado.' });
  let brutos = [], datasAjustadas = 0;
  try {
    for (const f of files) { const r = parseAbastecimentoPlanilha(f.buffer); brutos.push(...r.trans); datasAjustadas += r.datasAjustadas; }
  } catch (e) { console.error('Erro ao ler planilha de abastecimento:', e.message); return res.status(400).json({ erro: 'Não consegui ler a planilha. Confira se é um Excel válido.' }); }
  if (!brutos.length) return res.status(400).json({ erro: 'Nenhuma transação de combustível reconhecida. Confira se a planilha tem coluna de Valor e a placa (na coluna Placa OU dentro da Descrição, ex.: "Abastecimento - ABC1D23").' });
  const novos = brutos.map(normalizarAbastecimento);
  const modo = String(req.query.modo || (req.body && req.body.modo) || '').toLowerCase();
  const substituir = modo === 'substituir';
  // Idempotência sem perder lançamentos legítimos:
  //  • A assinatura usa só campos que NÃO são editáveis na tela (data + placa + valor + posto).
  //    Centro de custo e motorista ficam de fora porque o usuário pode reclassificá-los — se entrassem,
  //    reimportar a mesma planilha depois de uma edição criaria duplicata.
  //  • Dois abastecimentos verdadeiros idênticos (mesmo dia, posto e valor) são preservados por CONTAGEM:
  //    uma ocorrência nova só é "duplicada" se a base já tem aquela mesma ocorrência da assinatura.
  //    Assim reimportar a mesma planilha não repete, mas dois lançamentos iguais no mesmo dia entram os dois.
  const assinatura = (t) => `${t.dataHora}|${t.placa}|${(Number(t.valor) || 0).toFixed(2)}|${(t.posto || '').trim().toLowerCase()}`;
  await snapshotAbastecimento(substituir ? 'antes de importar (substituir)' : 'antes de importar (mesclar)'); // rede de segurança
  const base = substituir ? [] : lerAbastecimento();
  const baseCont = new Map();                                   // assinatura → nº de ocorrências já na base
  for (const t of base) { const a = assinatura(t); baseCont.set(a, (baseCont.get(a) || 0) + 1); }
  const loteCont = new Map();                                   // ocorrências já vistas neste lote
  let criados = 0, ignorados = 0;
  for (const t of novos) {
    const a = assinatura(t);
    const k = loteCont.get(a) || 0;                             // índice (0-based) desta ocorrência no lote
    loteCont.set(a, k + 1);
    if (k < (baseCont.get(a) || 0)) { ignorados++; continue; }  // a base já cobre esta ocorrência
    base.push(t); criados++;
  }
  const veiculos = new Set(base.map(t => t.placa)).size;
  if (!criados && !substituir) return res.json({ ok: true, criados: 0, ignorados, total: base.length, veiculos, arquivos: files.length, datasAjustadas });
  await salvarAbastecimento(base);
  await registrarHistorico([{ placa: '', acao: 'importou', texto: `Abastecimento importado · ${criados} nova(s)${ignorados ? `, ${ignorados} duplicada(s) ignorada(s)` : ''} · ${veiculos} veículos${files.length > 1 ? ` · ${files.length} arquivos` : ''}${substituir ? ' (substituição)' : ''}` }], quemFez(req));
  res.json({ ok: true, criados, ignorados, total: base.length, veiculos, arquivos: files.length, datasAjustadas });
}));

app.get('/api/abastecimento/exportar', exigeVer('abastecimento'), (req, res) => {
  let trans = lerAbastecimento();
  const idsQ = String(req.query.ids || '').trim();
  if (idsQ) { const alvo = new Set(idsQ.split(',').map(s => s.trim()).filter(Boolean)); trans = trans.filter(t => alvo.has(t.id)); }
  enviarPlanilha(res, 'ABASTECIMENTO.xlsx', 'Dados Completos', [
    ['dataHora', 'DATA/HORA'], ['placa', 'PLACA'], ['modelo', 'MODELO'], ['ano', 'ANO'], ['motorista', 'MOTORISTA'],
    ['centroCusto', 'CENTRO DE CUSTO'], ['posto', 'POSTO'], ['cidade', 'CIDADE'], ['uf', 'UF'], ['combustivel', 'COMBUSTÍVEL'],
    ['litros', 'LITROS', (v) => Number(v) || 0], ['precoLitro', 'R$/L', (v) => Number(v) || 0], ['kmL', 'KM/L', (v) => Number(v) || 0],
    ['odometro', 'ODÔMETRO', (v) => Number(v) || 0], ['kmRod', 'KM ROD.', (v) => Number(v) || 0], ['valor', 'TOTAL R$', (v) => Number(v) || 0],
    ['statusKmL', 'STATUS KM/L'], ['statusPreco', 'STATUS PREÇO'], ['alerta', 'ALERTA?', (v) => v ? 'SIM' : 'NÃO'], ['motivos', 'MOTIVOS'],
  ], trans);
});

