// ROTAS ESTÁTICAS ANTES DAS DE `:id` — senão `/categorias` e `/pendencias` caem no PUT/DELETE.
// Categorias = as sugeridas + as que já estão em uso (o cadastro aceita digitar uma nova).
app.get('/api/fornecedores/categorias', exigeVer('fornecedores'), (req, res) => {
  const usadas = new Set();
  for (const f of lerFornecedores()) for (const c of f.categorias || []) usadas.add(c);
  for (const c of CATEGORIAS_FORNECEDOR) usadas.delete(c);
  res.json({ padrao: CATEGORIAS_FORNECEDOR, usadas: [...usadas].sort((a, b) => a.localeCompare(b, 'pt-BR')) });
});

// Pendências cadastrais: quem está sem CNPJ, incompleto ou parece repetido. Tudo DERIVADO
// da base atual — não existe fila gravada que possa ficar desatualizada.
app.get('/api/fornecedores/pendencias', exigeVer('fornecedores'), (req, res) => {
  const lista = lerFornecedores().filter(f => f.ativo);
  const semCnpj = [], incompletos = [];
  for (const f of lista) {
    const q = qualidadeFornecedor(f);
    const resumo = { id: f.id, nome: f.nome, razaoSocial: f.razaoSocial, cidade: f.cidade, uf: f.uf, faltando: q.faltando };
    if (q.status === 'Sem CNPJ') semCnpj.push(resumo);
    else if (q.status === 'Incompleto') incompletos.push(resumo);
  }
  // Suspeita de duplicidade: mesmo CNPJ (certeza) ou mesmo nome-raiz na mesma cidade (suspeita).
  const porCnpj = new Map(), porNome = new Map(), duplicados = [];
  for (const f of lista) {
    if (f.cnpj) { const g = porCnpj.get(f.cnpj) || []; g.push(f); porCnpj.set(f.cnpj, g); }
    const k = chaveNomeForn(f.nome) + '|' + normalizarChave(f.cidade);
    if (chaveNomeForn(f.nome)) { const g = porNome.get(k) || []; g.push(f); porNome.set(k, g); }
  }
  const jaVistos = new Set();
  for (const [cnpj, grupo] of porCnpj) {
    if (grupo.length < 2) continue;
    grupo.forEach(f => jaVistos.add(f.id));
    duplicados.push({ motivo: 'CNPJ igual', chave: formatarCnpj(cnpj), itens: grupo.map(f => ({ id: f.id, nome: f.nome, cidade: f.cidade, uf: f.uf })) });
  }
  for (const [, grupo] of porNome) {
    if (grupo.length < 2 || grupo.every(f => jaVistos.has(f.id))) continue;
    duplicados.push({ motivo: 'Nome parecido na mesma cidade', chave: grupo[0].nome, itens: grupo.map(f => ({ id: f.id, nome: f.nome, cidade: f.cidade, uf: f.uf })) });
  }
  res.json({ semCnpj, incompletos, duplicados });
});

app.post('/api/fornecedores', exigeEditar('fornecedores'), rota(async (req, res) => {
  const novo = normalizarFornecedor(Object.assign({ origem: 'MANUAL' }, req.body || {}, { id: '', historico: [] }));
  if (!novo.nome) return res.status(400).json({ erro: 'Informe o nome do fornecedor.' });
  if (novo.cnpj && !cnpjValido(novo.cnpj)) return res.status(400).json({ erro: 'CNPJ inválido. Confira os números.' });
  const lista = lerFornecedores();
  if (novo.cnpj) {
    const igual = lista.find(f => f.cnpj === novo.cnpj);
    if (igual) return res.status(409).json({ erro: `Este CNPJ já está cadastrado em "${igual.nome}".`, id: igual.id });
  }
  novo.historico = [eventoForn('cadastrou', `Cadastrado manualmente${novo.cnpj ? ' com CNPJ ' + formatarCnpj(novo.cnpj) : ' sem CNPJ'}`, quemFez(req))];
  lista.push(novo);
  await salvarFornecedores(lista);
  await registrarHistorico([{ placa: '', acao: 'adicionou', texto: `Fornecedor "${novo.nome}" (${novo.tipo})` }], quemFez(req));
  res.status(201).json(novo);
}));
app.put('/api/fornecedores/:id', exigeEditar('fornecedores'), rota(async (req, res) => {
  const lista = lerFornecedores(); const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(f => f.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Fornecedor não encontrado.' });
  const antes = lista[idx];
  // O formulário não devolve histórico/origem/consulta: preserva o que já estava gravado.
  const atualizado = normalizarFornecedor(Object.assign({}, req.body, {
    id, ts: antes.ts, historico: antes.historico,
    origem: (req.body && req.body.origem) || antes.origem,
    consultaCadastral: (req.body && req.body.consultaCadastral) || antes.consultaCadastral,
  }));
  if (!atualizado.nome) return res.status(400).json({ erro: 'Informe o nome do fornecedor.' });
  if (atualizado.cnpj && !cnpjValido(atualizado.cnpj)) return res.status(400).json({ erro: 'CNPJ inválido. Confira os números.' });
  if (atualizado.cnpj && atualizado.cnpj !== antes.cnpj) {
    const igual = lista.find(f => f.cnpj === atualizado.cnpj && f.id !== id);
    if (igual) return res.status(409).json({ erro: `Este CNPJ já está cadastrado em "${igual.nome}".`, id: igual.id });
    atualizado.historico = atualizado.historico.concat(eventoForn('CNPJ', `CNPJ ${antes.cnpj ? 'alterado de ' + formatarCnpj(antes.cnpj) + ' para ' : 'informado: '}${formatarCnpj(atualizado.cnpj)}`, quemFez(req)));
  }
  if (antes.ativo !== atualizado.ativo) atualizado.historico = atualizado.historico.concat(eventoForn(atualizado.ativo ? 'reativou' : 'desativou', atualizado.ativo ? 'Fornecedor reativado' : 'Fornecedor desativado', quemFez(req)));
  else if (atualizado.cnpj === antes.cnpj) atualizado.historico = atualizado.historico.concat(eventoForn('editou', 'Cadastro editado', quemFez(req)));
  lista[idx] = normalizarFornecedor(atualizado); // reaplica o corte de 100 eventos
  await salvarFornecedores(lista);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Fornecedor "${atualizado.nome}"` }], quemFez(req));
  res.json(lista[idx]);
}));
app.delete('/api/fornecedores/:id', exigeEditar('fornecedores'), rota(async (req, res) => {
  const lista = lerFornecedores(); const id = decodeURIComponent(req.params.id);
  const alvo = lista.find(f => f.id === id);
  if (!alvo) return res.status(404).json({ erro: 'Fornecedor não encontrado.' });
  // Quem já tem nota fiscal atrelada não se apaga: apagar quebraria o gasto histórico da frota.
  const notas = lerOficina().filter(o => chaveNomeForn(o.fornecedor) && chaveNomeForn(o.fornecedor) === chaveNomeForn(alvo.nome)).length;
  if (notas) return res.status(409).json({ erro: `"${alvo.nome}" tem ${notas} nota${notas > 1 ? 's' : ''} fiscal atrelada. Desative o cadastro em vez de excluir.`, notas });
  // Ex.: FORN123 usado em um evento => 409; desativar preserva o vínculo histórico.
  const manutencoes = lerManutencao().filter(e => e.fornecedorId === id).length;
  if (manutencoes) return res.status(409).json({ erro: `"${alvo.nome}" tem ${manutencoes} evento(s) de manutenção vinculado(s). Desative o cadastro em vez de excluir.`, manutencoes });
  await salvarFornecedores(lista.filter(f => f.id !== id));
  await registrarHistorico([{ placa: '', acao: 'excluiu', texto: `Fornecedor "${alvo.nome}"` }], quemFez(req));
  res.json({ ok: true });
}));

