// ===================== ALMOXARIFADO (retirada de material assinada pelo colaborador) =====================
// ⚠️ ROTAS ESPECÍFICAS (exportar, relatorio.pdf) ANTES de /:id — senão o Express as captura como id.

// Mesma régua de visibilidade da aba Funcionários: quem só enxerga uma empresa não vê as
// retiradas da outra. Registro sem empresa passa (não é dado de nenhuma delas), igual a podeVerFunc.
function filtrarAlmox(lista, u) {
  const setE = empresasFuncPermitidas(u);
  if (setE === null) return lista || [];
  if (setE.size === 0) return [];
  return (lista || []).filter(r => { const e = empresaSigla(r && r.empresa); return !e || setE.has(e); });
}

app.get('/api/almoxarifado', exigeVer('almoxarifado'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json(filtrarAlmox(lerAlmoxarifado(), req.usuario).map(comSituacaoAlmox));
});

// Uma linha POR ITEM — é o formato da planilha que o almoxarifado mantinha no papel
// (colaborador, data, item, assinatura) e o que permite filtrar/ordenar por item no Excel.
const COLS_ALMOX = [
  ['colaborador', 'COLABORADOR'], ['cpf', 'CPF'], ['cargo', 'CARGO'], ['empresa', 'EMPRESA'],
  ['data', 'DATA'], ['hora', 'HORA'],
  ['item', 'ITEM'], ['tipo', 'TIPO'], ['quantidade', 'QUANTIDADE'], ['unidade', 'UNIDADE'],
  ['contrato', 'CONTRATO / OBRA'], ['finalidade', 'FINALIDADE'],
  ['entreguePor', 'ENTREGUE POR'], ['situacao', 'SITUAÇÃO'],
  // Devolução por partes: as duas colunas de saldo são o que responde "o que ainda está na rua".
  ['qtdDevolvida', 'QTD DEVOLVIDA'], ['qtdPendente', 'QTD EM POSSE'],
  ['devolucao', 'DEVOLVIDO EM'], ['devolvidoPara', 'DEVOLUÇÃO RECEBIDA POR'], ['devolvidoPor', 'DEVOLVIDO POR'],
  ['previsaoDevolucao', 'PREVISÃO DE DEVOLUÇÃO'],
  ['assinado', 'ASSINADO'], ['assinadoPor', 'ASSINADO POR'], ['assinadoEm', 'ASSINADO EM'], ['assinaturaLink', 'ASSINATURA (LINK)'],
  ['obs', 'OBSERVAÇÃO'], ['recibo', 'Nº DO RECIBO'],
];
function linhasPlanilhaAlmox(lista, origem) {
  const isoBR = (v) => { const m = String(v || '').slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? `${m[3]}/${m[2]}/${m[1]}` : String(v || ''); };
  const carimbo = (ts) => ts ? new Date(ts).toLocaleString('pt-BR') : '';
  const linhas = [];
  for (const r of lista) {
    const base = {
      colaborador: r.funcionarioNome, cpf: r.funcionarioCpf, cargo: r.funcionarioCargo, empresa: r.empresa,
      data: isoBR(r.data), hora: r.hora,
      contrato: r.contrato, finalidade: r.finalidade,
      entreguePor: r.responsavel, situacao: situacaoRetiradaAlmox(r),
      previsaoDevolucao: isoBR(r.previsaoDevolucao),
      assinado: (r.assinatura && r.assinatura.id) ? 'Sim' : 'Não',
      assinadoPor: r.assinaturaNome, assinadoEm: carimbo(r.assinaturaEm),
      // Link direto para a imagem da assinatura (abre para quem estiver logado no sistema).
      assinaturaLink: (r.assinatura && r.assinatura.id) ? `${origem}/api/midia/${encodeURIComponent(r.assinatura.id)}` : '',
      obs: r.obs, recibo: r.id,
    };
    if (!r.itens.length) { linhas.push({ ...base, item: '', tipo: '', quantidade: '', unidade: '', qtdDevolvida: '', qtdPendente: '', devolucao: '', devolvidoPara: '', devolvidoPor: '' }); continue; }
    for (const i of r.itens) {
      // "Devolvido em" traz a data da ÚLTIMA parcela; se a devolução foi por partes, o Excel
      // mostra também quantas ainda estão em posse (é o número que o almoxarife cobra).
      const parcial = i.retornavel && i.qtdDevolvida > 0 && !i.devolvido;
      linhas.push({
        ...base,
        item: i.nome, tipo: i.tipo, quantidade: i.quantidade, unidade: i.unidade,
        qtdDevolvida: i.retornavel ? i.qtdDevolvida : '',
        qtdPendente: i.retornavel ? i.qtdPendente : '',
        devolucao: !i.retornavel ? 'não se aplica'
          : i.devolvido ? (isoBR(i.dataDevolucao) || 'sim')
            : parcial ? `parcial · ${isoBR(i.dataDevolucao)}` : '',
        devolvidoPara: i.dataDevolucao || i.devolvidoPara ? (i.devolvidoPara || '') : '',
        devolvidoPor: i.dataDevolucao || i.devolvidoPor ? (i.devolvidoPor || '') : '',
      });
    }
  }
  return linhas;
}
// POST (e não GET) porque o cliente manda os ids que estão na tela — o Excel sai com o
// MESMO recorte que o usuário filtrou. Sem ids, exporta tudo o que ele pode ver.
app.post('/api/almoxarifado/exportar', exigeVer('almoxarifado'), rota(async (req, res) => {
  let lista = filtrarAlmox(lerAlmoxarifado(), req.usuario);
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(r => set.has(String(r.id))); }
  lista = lista.slice().sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')) || (b.ts - a.ts));
  const origem = `${req.protocol}://${req.get('host')}`;
  enviarPlanilha(res, 'ALMOXARIFADO.xlsx', 'RETIRADAS', COLS_ALMOX, linhasPlanilhaAlmox(lista, origem));
}));

// Desenha um QR Code direto no PDF, como quadradinhos vetoriais (nítido em qualquer zoom e
// sem precisar codificar um PNG). Usa o mesmo gerador do crachá, que roda em Node por UMD.
const qrcodeGen = require('../frontend/qrcode.js');

// ---- Helpers de PDF compartilhados (sem estado — os que capturam page/y ficam dentro de cada
// gerador). Ficam aqui porque documentos assinados de módulos diferentes precisam das MESMAS
// regras de escape e de data: divergir nisso é como um deles sair com "?" no meio do nome. ----
// As fontes padrão do pdf-lib são WinAnsi: um "ç", "ã", travessão ou "º" fora dessa tabela faz
// o drawText LANÇAR. Tem de passar por aqui TODO texto que vai para o PDF.
const textoWinAnsi = (s) => String(s == null ? '' : s)
  .replace(/[–—]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/…/g, '...').replace(/•/g, '-').replace(/[^\x00-\xFF]/g, '?');
const isoParaBR = (s) => { const m = String(s || '').slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? `${m[3]}/${m[2]}/${m[1]}` : String(s || ''); };

function desenharQrNoPdf(page, texto, x, y, lado, cor) {
  try {
    const qr = qrcodeGen(0, 'M');       // versão automática, correção média
    qr.addData(String(texto || ''));
    qr.make();
    const n = qr.getModuleCount();
    const p = lado / n;                 // lado de cada módulo
    for (let linha = 0; linha < n; linha++) {
      for (let col = 0; col < n; col++) {
        if (!qr.isDark(linha, col)) continue;
        // +0.15 de folga cobre a costura entre módulos vizinhos (senão aparecem fios brancos).
        page.drawRectangle({ x: x + col * p, y: y + (n - 1 - linha) * p, width: p + 0.15, height: p + 0.15, color: cor });
      }
    }
    return true;
  } catch (e) { return false; }         // QR é um extra: se falhar, o certificado sai sem ele
}
// Endereço onde se confere um recibo assinado. Sem código = a página de consulta.
function urlVerificacaoAlmox(codigo, origem) {
  const base = String(origem || '').replace(/\/+$/, '');
  return codigo ? `${base}/verificar/${encodeURIComponent(codigo)}` : `${base}/verificar`;
}

// ---- PDF: recibo individual (1 página por retirada, com a assinatura desenhada) e
// relatório consolidado (uma linha por retirada, com a assinatura em miniatura na coluna). ----
async function gerarPdfAlmox(lista, modo, origem) {
  const A4_W = 595.28, A4_H = 841.89, MARGEM = 42;
  const LARG = A4_W - MARGEM * 2;
  const COR_INK = rgb(0.11, 0.14, 0.20), COR_MUTED = rgb(0.42, 0.46, 0.54);
  const COR_BRAND = rgb(0.192, 0.212, 0.243), COR_LINHA = rgb(0.88, 0.90, 0.94);
  const COR_BOX = rgb(0.96, 0.97, 0.99), COR_ZEBRA = rgb(0.972, 0.978, 0.988);
  const COR_VERM = rgb(0.77, 0.15, 0.15), COR_VERDE = rgb(0.06, 0.5, 0.22);
  const COR_AMBAR = rgb(0.72, 0.45, 0.03);   // devolução PARCIAL: nem fechada, nem intocada
  // safe/isoBR agora são os helpers compartilhados com gerarPdfEpi (hoistados no merge do EPI):
  // as definições locais que viviam aqui eram idênticas, palavra por palavra.
  const safe = textoWinAnsi, isoBR = isoParaBR;

  const doc = await PDFDocument.create();
  doc.setTitle(modo === 'recibo' ? 'Recibo de entrega de material' : 'Relatório do almoxarifado');
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const fontB = await doc.embedFont(StandardFonts.HelveticaBold);

  // Cache de logos e de assinaturas: o mesmo PNG costuma repetir no relatório — embutir uma
  // única vez mantém o arquivo pequeno e a geração rápida.
  const logos = new Map();
  const carregarLogo = async (sigla) => {
    const chave = ['NTE', 'SUL'].includes(sigla) ? sigla.toLowerCase() : 'rm';
    if (logos.has(chave)) return logos.get(chave);
    let img = null;
    try {
      const lp = path.join(RAIZ, 'frontend', 'img', 'logo-' + chave + '.png');
      if (fs.existsSync(lp)) img = await doc.embedPng(fs.readFileSync(lp));
    } catch (e) { img = null; }
    logos.set(chave, img);
    return img;
  };
  const imagensPdf = new Map();
  const carregarImagem = async (ref) => {   // assinaturas e fotos da entrega
    if (!ref || !ref.id) return null;
    if (imagensPdf.has(ref.id)) return imagensPdf.get(ref.id);
    let img = null;
    try {
      const m = await lerMidia(ref.id);
      if (m && m.b64) {
        const buf = Buffer.from(m.b64, 'base64');
        img = (m.tipo === 'image/png') ? await doc.embedPng(buf) : await doc.embedJpg(buf);
      }
    } catch (e) {
      // Indisponibilidade do cofre SOBE (rota() → 503): imprimir o comprovante sem a assinatura
      // seria entregar um recibo "sem assinatura" que foi assinado. Imagem corrompida ou em
      // formato que o pdf-lib não embute continua virando só o quadro vazio.
      if (e && e.codigo === 'COFRE_INDISPONIVEL') throw e;
      img = null;
    }
    imagensPdf.set(ref.id, img);
    return img;
  };

  let page = doc.addPage([A4_W, A4_H]);
  let y = A4_H - MARGEM;
  const novaPagina = () => { page = doc.addPage([A4_W, A4_H]); y = A4_H - MARGEM; };
  const garante = (h) => { if (y - h < MARGEM + 24) novaPagina(); };
  const wrap = (texto, fnt, size, maxW) => {
    const palavras = safe(texto).split(/\s+/).filter(Boolean);
    if (!palavras.length) return [''];
    const linhas = []; let cur = '';
    for (let w of palavras) {
      while (fnt.widthOfTextAtSize(w, size) > maxW && w.length > 1) {
        let i = 1;
        while (i < w.length && fnt.widthOfTextAtSize(w.slice(0, i + 1), size) <= maxW) i++;
        if (cur) { linhas.push(cur); cur = ''; }
        linhas.push(w.slice(0, i));
        w = w.slice(i);
      }
      const teste = cur ? cur + ' ' + w : w;
      if (fnt.widthOfTextAtSize(teste, size) > maxW && cur) { linhas.push(cur); cur = w; } else cur = teste;
    }
    if (cur) linhas.push(cur);
    return linhas;
  };
  const cabecalho = async (sigla, titulo, sub) => {
    const logo = await carregarLogo(sigla);
    const LOGO_H = 30, topo = y;
    let esqX = MARGEM;
    if (logo) {
      const lw = logo.width * (LOGO_H / logo.height);
      page.drawImage(logo, { x: MARGEM, y: topo - LOGO_H, width: lw, height: LOGO_H });
      esqX += lw + 14;
    }
    page.drawText(safe(titulo), { x: esqX, y: topo - 14, size: 13, font: fontB, color: COR_INK });
    page.drawText(safe(sub), { x: esqX, y: topo - 27, size: 8.5, font, color: COR_MUTED });
    y = topo - LOGO_H - 12;
    page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 1.5, color: COR_BRAND });
    y -= 14;
  };
  const grid = (pares, cols) => {
    const cheios = pares.filter(([, val]) => String(val == null ? '' : val).trim() !== '');
    if (!cheios.length) return;
    const cw = LARG / cols;
    for (let i = 0; i < cheios.length; i += cols) {
      const bloco = cheios.slice(i, i + cols);
      const celulas = bloco.map(([, val]) => wrap(val, font, 10, cw - 12));
      const h = 13 + Math.max(...celulas.map(c => c.length)) * 12.5 + 7;
      garante(h);
      bloco.forEach(([rot], j) => page.drawText(safe(String(rot).toUpperCase()), { x: MARGEM + j * cw, y: y - 8, size: 6.8, font: fontB, color: COR_MUTED }));
      celulas.forEach((linhas, j) => linhas.forEach((ln, k) => page.drawText(ln, { x: MARGEM + j * cw, y: y - 22 - k * 12.5, size: 10, font, color: COR_INK })));
      y -= h;
    }
  };

  if (modo === 'recibo') {
    for (let n = 0; n < lista.length; n++) {
      const r = lista[n];
      if (n > 0) novaPagina();
      await cabecalho(empresaSigla(r.empresa), 'RECIBO DE ENTREGA DE MATERIAL',
        'Almoxarifado - entrega de EPI, ferramentas e materiais ao colaborador');
      grid([
        ['Colaborador', r.funcionarioNome], ['CPF', r.funcionarioCpf], ['Cargo', r.funcionarioCargo],
        ['Data da retirada', isoBR(r.data) + (r.hora ? ' as ' + r.hora : '')], ['Contrato / obra', r.contrato],
        ['Entregue por', r.responsavel],
        ['Previsao de devolucao', isoBR(r.previsaoDevolucao)], ['Finalidade', r.finalidade],
      ], 3);
      // ---- Itens retirados ----
      y -= 10;
      page.drawText('ITENS RETIRADOS', { x: MARGEM, y: y - 10, size: 10.5, font: fontB, color: COR_BRAND });
      y -= 15;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.8, color: COR_LINHA });
      y -= 8;
      // Sem coluna de CA (saiu na v1.48): o espaço foi para o nome do item e para a coluna de
      // devolução, que agora precisa caber "3 de 5" quando a volta é por partes.
      const cols = [{ tit: '#', larg: 24 }, { tit: 'ITEM', larg: 248 }, { tit: 'TIPO', larg: 100 },
        { tit: 'QTD', larg: 55, dir: true }, { tit: 'DEVOLUÇÃO', larg: 84 }];
      const xs = []; let acc = MARGEM;
      cols.forEach(c => { xs.push(acc); acc += c.larg; });
      page.drawRectangle({ x: MARGEM, y: y - 16, width: LARG, height: 16, color: COR_BOX });
      cols.forEach((c, i) => {
        const t = safe(c.tit);
        const x = c.dir ? xs[i] + c.larg - 6 - fontB.widthOfTextAtSize(t, 7.6) : xs[i] + 6;
        page.drawText(t, { x, y: y - 11, size: 7.6, font: fontB, color: COR_MUTED });
      });
      y -= 16;
      r.itens.forEach((it, idx) => {
        const nomeLinhas = wrap(it.nome, font, 8.5, cols[1].larg - 12);
        const h = Math.max(16, nomeLinhas.length * 10.5 + 6);
        garante(h);
        if (idx % 2) page.drawRectangle({ x: MARGEM, y: y - h, width: LARG, height: h, color: COR_ZEBRA });
        const base = y - 11;
        const cel = (i, txt, cor) => {
          const t = safe(txt);
          const x = cols[i].dir ? xs[i] + cols[i].larg - 6 - font.widthOfTextAtSize(t, 8.5) : xs[i] + 6;
          page.drawText(t, { x, y: base, size: 8.5, font, color: cor || COR_INK });
        };
        cel(0, String(idx + 1));
        nomeLinhas.forEach((ln, k) => page.drawText(ln, { x: xs[1] + 6, y: base - k * 10.5, size: 8.5, font, color: COR_INK }));
        cel(2, it.tipo);
        cel(3, `${it.quantidade} ${it.unidade}`);
        // A coluna de devolução conta a história completa em uma linha: nao volta / a data em
        // que voltou / quanto já voltou de quanto saiu / ainda esta com o colaborador.
        if (!it.retornavel) cel(4, 'nao volta', COR_MUTED);
        else if (it.devolvido) cel(4, isoBR(it.dataDevolucao) || 'sim', COR_VERDE);
        else if (it.qtdDevolvida > 0) cel(4, `${it.qtdDevolvida} de ${it.quantidade}`, COR_AMBAR);
        else cel(4, 'em posse', COR_VERM);
        y -= h;
      });
      // ---- Devoluções: a quem cada peça foi entregue de volta ----
      // Fica FORA da tabela de itens porque é informação de outro momento (e de outra
      // pessoa): quem recebeu de volta costuma não ser quem entregou na saída.
      // Uma linha por PARCELA (e não por item): quando o material volta em etapas, cada
      // entrega tem sua data, quem trouxe e quem recebeu — é isso que se confere depois.
      const parcelas = [];
      for (const it of r.itens) {
        for (const d of (it.devolucoes || [])) parcelas.push({ it, d });
      }
      if (parcelas.length) {
        garante(20 + parcelas.length * 11);
        y -= 4;
        page.drawText('DEVOLUCOES REGISTRADAS', { x: MARGEM, y: y - 9, size: 6.8, font: fontB, color: COR_MUTED });
        y -= 18;
        parcelas.forEach(({ it, d }) => {
          const quanto = d.qtd < it.quantidade ? `${d.qtd} de ${it.quantidade} ${it.unidade}` : 'tudo';
          const txt = `${it.nome}: ${quanto} em ${isoBR(d.data) || '-'}`
            + (d.devolvidoPor ? ` por ${d.devolvidoPor}` : '')
            + (d.devolvidoPara ? `, recebido por ${d.devolvidoPara}` : '');
          wrap(txt, font, 8, LARG).forEach((ln, k) => page.drawText(ln, { x: MARGEM, y: y - k * 10, size: 8, font, color: COR_INK }));
          y -= 11;
        });
        // Saldo em aberto: o que o recibo ainda cobra do colaborador.
        const emPosse = r.itens.filter(i => i.retornavel && i.qtdPendente > 0);
        if (emPosse.length) {
          garante(14);
          const txt = 'Ainda em posse do colaborador: '
            + emPosse.map(i => `${i.nome} (${i.qtdPendente} ${i.unidade})`).join('; ');
          wrap(txt, font, 8, LARG).forEach((ln, k) => page.drawText(ln, { x: MARGEM, y: y - k * 10, size: 8, font, color: COR_VERM }));
          y -= 12;
        }
        y -= 6;
      }
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.6, color: COR_LINHA });
      y -= 16;
      // ---- Declaração + assinatura ----
      const declaracao = 'Declaro ter recebido do almoxarifado os itens acima relacionados, em condicoes de uso, '
        + 'comprometendo-me a utiliza-los exclusivamente na execucao dos servicos, a zelar pela sua conservacao e a '
        + 'devolve-los quando solicitado ou ao termino das atividades, respondendo por perda ou dano decorrente de mau uso.';
      const linhasDec = wrap(declaracao, font, 8.5, LARG - 20);
      garante(linhasDec.length * 11 + 130);
      page.drawRectangle({ x: MARGEM, y: y - (linhasDec.length * 11 + 14), width: LARG, height: linhasDec.length * 11 + 14, color: COR_BOX, borderColor: COR_LINHA, borderWidth: 1 });
      linhasDec.forEach((ln, k) => page.drawText(ln, { x: MARGEM + 10, y: y - 16 - k * 11, size: 8.5, font, color: COR_INK }));
      y -= linhasDec.length * 11 + 14 + 24;
      if (r.obs) {
        const obs = wrap('Observacoes: ' + r.obs, font, 8.5, LARG);
        garante(obs.length * 11 + 10);
        obs.forEach((ln, k) => page.drawText(ln, { x: MARGEM, y: y - k * 11, size: 8.5, font, color: COR_MUTED }));
        y -= obs.length * 11 + 14;
      }
      // ---- Fotos do material no ato da entrega ----
      // Vão ANTES da assinatura de propósito: é o que o colaborador viu e confirmou.
      const fotos = [];
      for (const ref of (r.fotos || [])) { const im = await carregarImagem(ref); if (im) fotos.push(im); }
      if (fotos.length) {
        const FOTO_H = 92, gapF = 8;
        garante(FOTO_H + 26);
        page.drawText('FOTOS DA ENTREGA', { x: MARGEM, y: y - 9, size: 6.8, font: fontB, color: COR_MUTED });
        y -= 16;
        let xf = MARGEM;
        for (const im of fotos) {
          // Encaixa na altura fixa preservando a proporção; se estourar a largura, para.
          const larg = im.width * (FOTO_H / im.height);
          if (xf + larg > MARGEM + LARG) break;
          page.drawImage(im, { x: xf, y: y - FOTO_H, width: larg, height: FOTO_H });
          page.drawRectangle({ x: xf, y: y - FOTO_H, width: larg, height: FOTO_H, borderColor: COR_LINHA, borderWidth: 0.8 });
          xf += larg + gapF;
        }
        y -= FOTO_H + 14;
      }
      const img = await carregarImagem(r.assinatura);
      const ASS_W = 240, ASS_H = 72;
      garante(ASS_H + 46);
      if (img) {
        // Encaixa a assinatura na caixa preservando a proporção do traço.
        const escala = Math.min(ASS_W / img.width, ASS_H / img.height);
        page.drawImage(img, { x: MARGEM + (ASS_W - img.width * escala) / 2, y: y - ASS_H + 2, width: img.width * escala, height: img.height * escala });
      }
      const linhaY = y - ASS_H - 2;
      page.drawLine({ start: { x: MARGEM, y: linhaY }, end: { x: MARGEM + ASS_W, y: linhaY }, thickness: 0.8, color: COR_INK });
      page.drawText(safe(r.assinaturaNome || r.funcionarioNome || 'Colaborador'), { x: MARGEM, y: linhaY - 11, size: 8.5, font: fontB, color: COR_INK });
      const carimbo = r.assinaturaEm
        ? 'Assinado eletronicamente em ' + new Date(r.assinaturaEm).toLocaleString('pt-BR')
        : 'Sem assinatura eletronica - assinar de proprio punho';
      page.drawText(safe(carimbo), { x: MARGEM, y: linhaY - 22, size: 7.5, font, color: r.assinaturaEm ? COR_MUTED : COR_VERM });
      // Assinatura de quem entregou fica ao lado, sempre manuscrita (o almoxarife assina o papel).
      const x2 = MARGEM + LARG - ASS_W;
      page.drawLine({ start: { x: x2, y: linhaY }, end: { x: x2 + ASS_W, y: linhaY }, thickness: 0.8, color: COR_INK });
      page.drawText(safe(r.responsavel || 'Responsavel pelo almoxarifado'), { x: x2, y: linhaY - 11, size: 8.5, font: fontB, color: COR_INK });
      page.drawText('Responsavel pela entrega', { x: x2, y: linhaY - 22, size: 7.5, font, color: COR_MUTED });
      y = linhaY - 40;
      // ---- Certificado da assinatura eletrônica (as evidências + como conferir) ----
      if (r.assinaturaEm) {
        const alterada = retiradaAlmoxAlterada(r);
        const CERT_H = 110;
        garante(CERT_H + 8);
        const topoCert = y;
        page.drawRectangle({ x: MARGEM, y: topoCert - CERT_H, width: LARG, height: CERT_H,
          color: alterada ? rgb(0.99, 0.95, 0.95) : COR_BOX,
          borderColor: alterada ? COR_VERM : COR_LINHA, borderWidth: 1 });
        page.drawText('CERTIFICADO DA ASSINATURA ELETRONICA', { x: MARGEM + 10, y: topoCert - 15, size: 7.5, font: fontB, color: alterada ? COR_VERM : COR_BRAND });
        const evid = [
          ['Assinado por', r.assinaturaNome || r.funcionarioNome],
          ['Data e hora', new Date(r.assinaturaEm).toLocaleString('pt-BR')],
          ['Forma', r.assinaturaModo === 'digitado' ? 'Nome digitado pelo signatario' : 'Tracado de proprio punho na tela'],
          ['Endereco IP', r.assinaturaIp || '-'],
          ['Dispositivo', r.assinaturaDispositivo || '-'],
          ['Declaracao', r.assinaturaAceite ? 'Aceite de recebimento confirmado' : 'sem registro de aceite'],
        ];
        // Duas colunas de evidências, deixando a direita livre para o código + QR.
        const colW = (LARG - 210) / 2;
        evid.forEach(([rot, val], i) => {
          const cx = MARGEM + 10 + (i % 2) * colW;
          const cy = topoCert - 32 - Math.floor(i / 2) * 21;
          page.drawText(safe(rot.toUpperCase()), { x: cx, y: cy, size: 6, font: fontB, color: COR_MUTED });
          // Corta pela LARGURA real (não por nº de caracteres): nome comprido não pode
          // invadir a coluna vizinha — pdf-lib não recorta texto que transborda.
          let t = safe(String(val));
          const maxW = colW - 20;
          while (t.length > 4 && font.widthOfTextAtSize(t, 8) > maxW) t = t.slice(0, -2);
          if (t !== safe(String(val))) t += '...';
          page.drawText(t, { x: cx, y: cy - 9, size: 8, font, color: COR_INK });
        });
        // Código + QR: quem tem o papel na mão confere a autenticidade sem depender de ninguém.
        if (r.assinaturaCodigo) {
          const qrLado = 58;
          const qrX = MARGEM + LARG - qrLado - 12;
          desenharQrNoPdf(page, urlVerificacaoAlmox(r.assinaturaCodigo, origem), qrX, topoCert - CERT_H + 26, qrLado, COR_INK);
          const txtX = qrX - 132;
          page.drawText('CONFIRA A AUTENTICIDADE', { x: txtX, y: topoCert - 34, size: 6, font: fontB, color: COR_MUTED });
          page.drawText(safe(r.assinaturaCodigo), { x: txtX, y: topoCert - 49, size: 12, font: fontB, color: COR_INK });
          wrap('Leia o QR ao lado ou informe este codigo em ' + urlVerificacaoAlmox('', origem), font, 6, 126)
            .forEach((ln, k) => page.drawText(ln, { x: txtX, y: topoCert - 62 - k * 7.5, size: 6, font, color: COR_MUTED }));
        }
        if (alterada) {
          page.drawText(safe('ATENCAO: o recibo foi alterado depois de assinado - a assinatura nao cobre o conteudo atual.'),
            { x: MARGEM + 10, y: topoCert - CERT_H + 6, size: 7, font: fontB, color: COR_VERM });
        }
        y = topoCert - CERT_H - 10;
      }
    }
  } else {
    await cabecalho('', 'RELATÓRIO DO ALMOXARIFADO', `Retiradas de material - ${lista.length} registro(s) - emitido em ${new Date().toLocaleString('pt-BR')}`);
    // Resumo em números do recorte exportado.
    const totItens = lista.reduce((s, r) => s + r.itens.reduce((t, i) => t + (Number(i.quantidade) || 0), 0), 0);
    const pendAss = lista.filter(r => !(r.assinatura && r.assinatura.id)).length;
    const emPosse = lista.filter(r => situacaoRetiradaAlmox(r) === 'Em posse').length;
    const pessoas = new Set(lista.map(r => r.funcionarioNome).filter(Boolean)).size;
    const kpis = [
      { rotulo: 'Retiradas', valor: String(lista.length) }, { rotulo: 'Itens entregues', valor: String(totItens) },
      { rotulo: 'Colaboradores', valor: String(pessoas) }, { rotulo: 'Em posse', valor: String(emPosse) },
      { rotulo: 'Sem assinatura', valor: String(pendAss), cor: pendAss ? COR_VERM : COR_VERDE },
    ];
    const gap = 9, w = (LARG - gap * (kpis.length - 1)) / kpis.length, hK = 44;
    kpis.forEach((it, i) => {
      const x = MARGEM + i * (w + gap);
      page.drawRectangle({ x, y: y - hK, width: w, height: hK, color: COR_BOX, borderColor: COR_LINHA, borderWidth: 1 });
      page.drawText(safe(it.rotulo.toUpperCase()), { x: x + 8, y: y - 15, size: 6.5, font: fontB, color: COR_MUTED });
      page.drawText(safe(it.valor), { x: x + 8, y: y - 33, size: 14, font: fontB, color: it.cor || COR_INK });
    });
    y -= hK + 14;
    const cols = [{ tit: 'DATA', larg: 52 }, { tit: 'COLABORADOR', larg: 116 }, { tit: 'ITENS RETIRADOS', larg: 190 },
      { tit: 'ENTREGUE POR', larg: 76 }, { tit: 'ASSINATURA', larg: 77 }];
    const xs = []; let acc = MARGEM;
    cols.forEach(c => { xs.push(acc); acc += c.larg; });
    const cabTabela = () => {
      garante(20);
      page.drawRectangle({ x: MARGEM, y: y - 16, width: LARG, height: 16, color: COR_BOX });
      cols.forEach((c, i) => page.drawText(safe(c.tit), { x: xs[i] + 6, y: y - 11, size: 7.6, font: fontB, color: COR_MUTED }));
      y -= 16;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.6, color: COR_LINHA });
    };
    cabTabela();
    for (let idx = 0; idx < lista.length; idx++) {
      const r = lista[idx];
      const itensTxt = r.itens.map(i => `${i.nome} (${i.quantidade} ${i.unidade})`).join('; ') || '-';
      const linhasItens = wrap(itensTxt, font, 8, cols[2].larg - 12);
      const nomeLinhas = wrap(r.funcionarioNome || '-', font, 8, cols[1].larg - 12);
      const h = Math.max(30, linhasItens.length * 10, nomeLinhas.length * 10) + 8;
      if (y - h < MARGEM + 24) { novaPagina(); cabTabela(); }
      if (idx % 2) page.drawRectangle({ x: MARGEM, y: y - h, width: LARG, height: h, color: COR_ZEBRA });
      const base = y - 11;
      page.drawText(safe(isoBR(r.data)), { x: xs[0] + 6, y: base, size: 8, font, color: COR_INK });
      if (r.hora) page.drawText(safe(r.hora), { x: xs[0] + 6, y: base - 10, size: 7, font, color: COR_MUTED });
      nomeLinhas.forEach((ln, k) => page.drawText(ln, { x: xs[1] + 6, y: base - k * 10, size: 8, font, color: COR_INK }));
      linhasItens.forEach((ln, k) => page.drawText(ln, { x: xs[2] + 6, y: base - k * 10, size: 8, font, color: COR_INK }));
      page.drawText(safe(r.responsavel || '-').slice(0, 22), { x: xs[3] + 6, y: base, size: 8, font, color: COR_INK });
      const img = await carregarImagem(r.assinatura);
      if (img) {
        const cw = cols[4].larg - 12, ch = h - 10;
        const escala = Math.min(cw / img.width, ch / img.height);
        page.drawImage(img, { x: xs[4] + 6, y: y - h + 5, width: img.width * escala, height: img.height * escala });
      } else {
        page.drawText('sem assinatura', { x: xs[4] + 6, y: base, size: 7.5, font, color: COR_VERM });
      }
      y -= h;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.4, color: COR_LINHA });
    }
  }
  // Rodapé com paginação em todas as páginas.
  const paginas = doc.getPages();
  paginas.forEach((p, i) => {
    p.drawText(safe(`Gestao RM - Almoxarifado  |  pagina ${i + 1} de ${paginas.length}`),
      { x: MARGEM, y: 24, size: 7.5, font, color: COR_MUTED });
  });
  return Buffer.from(await doc.save());
}

app.post('/api/almoxarifado/relatorio.pdf', exigeVer('almoxarifado'), rota(async (req, res) => {
  let lista = filtrarAlmox(lerAlmoxarifado(), req.usuario);
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(r => set.has(String(r.id))); }
  if (!lista.length) return res.status(400).json({ erro: 'Nenhuma retirada no filtro atual para gerar o relatório.' });
  lista = lista.slice().sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')) || (b.ts - a.ts));
  const pdf = await gerarPdfAlmox(lista, 'relatorio', `${req.protocol}://${req.get('host')}`);
  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Disposition', `attachment; filename="almoxarifado-${new Date().toISOString().slice(0, 10)}.pdf"`);
  res.send(pdf);
}));

// Todos os recibos do recorte, um PDF por retirada, dentro de um .zip — é o que substitui
// o arquivo físico das folhas assinadas (dá para guardar a pasta do mês inteira de uma vez).
const ALMOX_ZIP_MAX = 400; // teto de segurança: cada recibo é um PDF montado na memória
app.post('/api/almoxarifado/recibos.zip', exigeVer('almoxarifado'), rota(async (req, res) => {
  let lista = filtrarAlmox(lerAlmoxarifado(), req.usuario);
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(r => set.has(String(r.id))); }
  if (!lista.length) return res.status(400).json({ erro: 'Nenhuma retirada no filtro atual para gerar os recibos.' });
  lista = lista.slice().sort((a, b) => String(a.data || '').localeCompare(String(b.data || '')) || (a.ts - b.ts));
  let avisoCorte = '';
  if (lista.length > ALMOX_ZIP_MAX) {
    avisoCorte = `O filtro tinha ${lista.length} retiradas; este pacote traz as ${ALMOX_ZIP_MAX} mais antigas. Refine o período para baixar o restante.\n`;
    lista = lista.slice(0, ALMOX_ZIP_MAX);
  }
  const origem = `${req.protocol}://${req.get('host')}`;
  const semAcento = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase();
  const entradas = [];
  const usados = new Set();
  for (const r of lista) {
    const pdf = await gerarPdfAlmox([r], 'recibo', origem);
    // Nome legível e ordenável: data primeiro, depois o colaborador.
    let nome = `${r.data || 'sem-data'}_${semAcento(r.funcionarioNome) || 'colaborador'}`;
    let final = `${nome}.pdf`, n = 2;
    while (usados.has(final)) final = `${nome}-${n++}.pdf`;   // duas retiradas do mesmo dia/pessoa
    usados.add(final);
    entradas.push({ path: `recibos/${final}`, buffer: pdf });
  }
  // Índice em texto: quem abre o zip entende o pacote sem abrir PDF por PDF.
  const linhas = ['RECIBOS DO ALMOXARIFADO', '='.repeat(50), `Gerado em: ${new Date().toLocaleString('pt-BR')}`,
    `Recibos: ${lista.length}`, ''];
  if (avisoCorte) linhas.push(avisoCorte);
  for (const r of lista) {
    const itens = (r.itens || []).map(i => `${i.nome} (${i.quantidade} ${i.unidade})`).join('; ');
    linhas.push(`${r.data || '—'}  ${r.funcionarioNome || '—'}`);
    linhas.push(`   Itens: ${itens || '—'}`);
    linhas.push(`   Situação: ${situacaoRetiradaAlmox(r)}${r.assinaturaCodigo ? '  ·  Código: ' + r.assinaturaCodigo : '  ·  SEM ASSINATURA'}`);
    linhas.push('');
  }
  entradas.push({ path: 'INDICE.txt', buffer: Buffer.from(linhas.join('\n'), 'utf-8') });
  enviarZip(res, `recibos-almoxarifado-${new Date().toISOString().slice(0, 10)}.zip`, entradas);
}));

app.get('/api/almoxarifado/:id/recibo.pdf', exigeVer('almoxarifado'), rota(async (req, res) => {
  const id = decodeURIComponent(req.params.id);
  const r = filtrarAlmox(lerAlmoxarifado(), req.usuario).find(x => x.id === id);
  if (!r) return res.status(404).json({ erro: 'Retirada não encontrada.' });
  const pdf = await gerarPdfAlmox([r], 'recibo', `${req.protocol}://${req.get('host')}`);
  const quem = (r.funcionarioNome || 'colaborador').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase();
  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Disposition', `${req.query.ver === '1' ? 'inline' : 'attachment'}; filename="recibo-${quem}-${r.data || ''}.pdf"`);
  res.send(pdf);
}));

// ---- Conferência pública de um recibo assinado (sem login; a chave é o código) ----
// Limite por IP: o código tem 48 bits, mas nada impede alguém de tentar em massa — e cada
// tentativa lê a coleção inteira. 20 consultas por minuto é folgado para uso humano.
const verificarTentativas = new Map(); // ip -> { count, ate }
function limiteVerificacao(ip) {
  const agora = Date.now();
  const reg = verificarTentativas.get(ip);
  if (!reg || agora > reg.ate) { verificarTentativas.set(ip, { count: 1, ate: agora + 60000 }); return true; }
  if (reg.count >= 20) return false;
  reg.count++;
  return true;
}
// Faxina periódica do mapa (senão cresce com cada IP que já passou).
setInterval(() => {
  const agora = Date.now();
  for (const [ip, reg] of verificarTentativas) if (agora > reg.ate) verificarTentativas.delete(ip);
}, 5 * 60000).unref();

// Devolve SÓ o que já está impresso no próprio recibo — nada de CPF, obra interna ou id.
function respostaVerificacaoAlmox(r) {
  const alterada = retiradaAlmoxAlterada(r);
  return {
    autentico: !alterada,
    alteradoAposAssinatura: alterada,
    codigo: r.assinaturaCodigo,
    colaborador: r.funcionarioNome,
    cargo: r.funcionarioCargo,
    empresa: r.empresa,
    data: r.data,
    hora: r.hora,
    entreguePor: r.responsavel,
    itens: (r.itens || []).map(i => ({ nome: i.nome, quantidade: i.quantidade, unidade: i.unidade, tipo: i.tipo })),
    assinadoPor: r.assinaturaNome,
    assinadoEm: r.assinaturaEm,
    forma: r.assinaturaModo === 'digitado' ? 'Nome digitado pelo signatário' : 'Traçado de próprio punho na tela',
    dispositivo: r.assinaturaDispositivo,
    aceite: !!r.assinaturaAceite,
    impressao: (r.assinaturaHash || '').slice(0, 32), // trecho do hash, para conferência visual
    // Frases prontas (e não pedaços a colar): "Ficha de EPI autêntico" erraria a concordância.
    rotulos: { data: 'Data da retirada', itens: 'Itens recebidos', autentico: 'Recibo autêntico' },
  };
}

// Documentos assinados que a página pública sabe conferir. Cada módulo entra aqui com o seu
// leitor e a sua tradução para o formato que `frontend/verificar.js` renderiza.
const MODULOS_VERIFICACAO = [
  { chave: 'almoxarifado', documento: 'Recibo de entrega de material', ler: lerAlmoxarifado, resposta: respostaVerificacaoAlmox },
  { chave: 'epi', documento: 'Ficha de EPI', ler: lerEpiMov, resposta: respostaVerificacaoEpi },
  { chave: 'ti', documento: 'Termo de responsabilidade de TI', ler: lerTiMov, resposta: respostaVerificacaoTi },
];
// O gerador de código nunca foi específico do almoxarifado — só nasceu lá.
const gerarCodigoVerificacao = gerarCodigoAlmox;
// Unicidade do código ENTRE módulos: se dois emitissem o mesmo, a conferência devolveria o do
// primeiro do registro — errado, silencioso e não reproduzível.
function codigosVerificacaoEmUso() {
  const usados = new Set();
  for (const reg of MODULOS_VERIFICACAO) {
    for (const r of reg.ler()) if (r && r.assinaturaCodigo) usados.add(r.assinaturaCodigo);
  }
  return usados;
}

app.get('/api/verificar/:codigo', rota(async (req, res) => {
  res.set('Cache-Control', 'no-store');
  if (!limiteVerificacao(ipDe(req))) return res.status(429).json({ erro: 'Muitas consultas. Aguarde um minuto e tente de novo.' });
  const codigo = String(req.params.codigo || '').toUpperCase().replace(/[^A-Z0-9-]/g, '').slice(0, 20);
  for (const reg of MODULOS_VERIFICACAO) {
    const r = reg.ler().find(x => x.assinaturaCodigo && x.assinaturaCodigo === codigo);
    if (r) return res.json({ ok: true, modulo: reg.chave, documento: reg.documento, ...reg.resposta(r) });
  }
  res.status(404).json({ ok: false, erro: 'Nenhum documento encontrado com este código.' });
}));

app.post('/api/almoxarifado', exigeEditar('almoxarifado'), rota(async (req, res) => {
  const agora = agoraBrasilAlmox();
  const corpo = req.body || {};
  const novo = normalizarRetiradaAlmox({
    ...corpo,
    id: gerarId('ALM'),
    ts: Date.now(),
    data: corpo.data || agora.data,
    hora: corpo.hora || agora.hora,
    // Quem ENTREGOU pode ser outra pessoa que não a que está digitando (o almoxarife lança
    // depois, em nome do encarregado que atendeu) — por isso o campo é editável na tela.
    responsavel: String(corpo.responsavel || '').trim() || quemFez(req) || 'Sistema',
    // Quem REGISTROU no sistema é sempre o usuário logado: essa é a trilha que não se edita.
    responsavelUsuario: (usuarioAtual(req) || {}).usuario || '',
    // Recibo novo nasce sem assinatura: assinar é um passo próprio (POST /:id/assinar).
    assinatura: null, assinaturaNome: '', assinaturaEm: 0, assinaturaHash: '',
  });
  if (!novo.funcionarioNome) return res.status(400).json({ erro: 'Informe quem está retirando o material.' });
  if (!novo.itens.length) return res.status(400).json({ erro: 'Informe pelo menos um item retirado.' });
  const lista = lerAlmoxarifado();
  lista.push(novo);
  await salvarAlmoxarifado(lista);
  await registrarHistorico([{ placa: '', acao: 'adicionou', texto: `Almoxarifado: ${novo.itens.length} item(ns) para "${novo.funcionarioNome}"` }], quemFez(req));
  res.status(201).json(comSituacaoAlmox(novo));
}));

app.put('/api/almoxarifado/:id', exigeEditar('almoxarifado'), rota(async (req, res) => {
  const lista = lerAlmoxarifado(); const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(r => r.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Retirada não encontrada.' });
  const antes = lista[idx];
  // A assinatura e o carimbo NÃO se editam por aqui: quem quiser mudar o recibo assinado
  // precisa colher a assinatura de novo (o hash guardado denuncia a alteração até lá).
  const atualizado = normalizarRetiradaAlmox({
    ...req.body, id, ts: antes.ts,
    responsavel: String((req.body && req.body.responsavel) || '').trim() || antes.responsavel,
    responsavelUsuario: antes.responsavelUsuario, // quem criou o registro não muda
    assinatura: antes.assinatura, assinaturaNome: antes.assinaturaNome,
    assinaturaEm: antes.assinaturaEm, assinaturaHash: antes.assinaturaHash,
  });
  if (!atualizado.funcionarioNome) return res.status(400).json({ erro: 'Informe quem está retirando o material.' });
  if (!atualizado.itens.length) return res.status(400).json({ erro: 'Informe pelo menos um item retirado.' });
  lista[idx] = atualizado;
  await salvarAlmoxarifado(lista);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Almoxarifado: retirada de "${atualizado.funcionarioNome}"` }], quemFez(req));
  res.json(comSituacaoAlmox(atualizado));
}));

// Colhe a assinatura do colaborador (PNG desenhado no canvas) e carimba o hash do conteúdo.
app.post('/api/almoxarifado/:id/assinar', exigeEditar('almoxarifado'), rota(async (req, res) => {
  const lista = lerAlmoxarifado(); const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(r => r.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Retirada não encontrada.' });
  const dataUrl = String((req.body && req.body.imagem) || '');
  const m = /^data:image\/png;base64,([A-Za-z0-9+/=]+)$/.exec(dataUrl.trim());
  if (!m) return res.status(400).json({ erro: 'Assinatura inválida. Assine no quadro antes de confirmar.' });
  const buf = Buffer.from(m[1], 'base64');
  if (buf.length > 2 * 1024 * 1024) return res.status(413).json({ erro: 'Assinatura muito grande.' });
  // Confere pelo CONTEÚDO (magic bytes), como o /api/midia — o rótulo do data URL é forjável.
  if (detectarTipoMidia(buf) !== 'image/png') return res.status(400).json({ erro: 'Assinatura inválida (não é uma imagem PNG).' });
  const nomeAssinante = String((req.body && req.body.nome) || '').trim().slice(0, 120);
  // O aceite é obrigatório: sem marcar "declaro que recebi", não há assinatura — é o mesmo
  // princípio das plataformas de assinatura eletrônica (consentimento explícito e registrado).
  if (!(req.body && req.body.aceite)) {
    return res.status(400).json({ erro: 'Marque a declaração de recebimento antes de assinar.' });
  }
  const alvo = lista[idx];
  const midiaId = gerarIdMidia();
  await salvarMidia(midiaId, { tipo: 'image/png', nome: `assinatura-${alvo.id}.png`, b64: buf.toString('base64'), ts: Date.now() });
  alvo.assinatura = { id: midiaId, nome: `assinatura-${alvo.id}.png`, tipo: 'image/png' };
  alvo.assinaturaNome = nomeAssinante || alvo.funcionarioNome;
  alvo.assinaturaEm = Date.now();
  alvo.assinaturaHash = hashRetiradaAlmox(alvo);
  // Evidências: ficam com o recibo e saem no certificado do PDF. Assinar de novo gera um
  // código novo (o anterior deixa de valer — é outra assinatura, com outro conteúdo).
  alvo.assinaturaCodigo = gerarCodigoVerificacao(codigosVerificacaoEmUso());
  alvo.assinaturaIp = ipDe(req);
  alvo.assinaturaDispositivo = dispositivoDoUA(req.get('user-agent'));
  alvo.assinaturaModo = ['desenho', 'digitado'].includes(String(req.body.modo)) ? String(req.body.modo) : 'desenho';
  alvo.assinaturaAceite = true;
  lista[idx] = alvo;
  await salvarAlmoxarifado(lista);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Almoxarifado: "${alvo.funcionarioNome}" assinou o recibo de ${alvo.itens.length} item(ns)` }], quemFez(req));
  res.json(comSituacaoAlmox(alvo));
}));

// Registra a devolução de itens retornáveis. Não mexe na assinatura do recebimento —
// devolver é o curso normal do processo, não uma alteração do que foi assinado.
//
// Aceita dois formatos em `itens`:
//   [{ i: 0, qtd: 3 }]  devolução PARCIAL — acrescenta uma parcela ao item 0 (pegou 5, trouxe 3)
//   [0, 1]              formato antigo — devolve o SALDO INTEIRO dos itens 0 e 1
// e ainda `estornar: [0]`, que desfaz a última parcela do item (corrige lançamento errado).
//
// Cada chamada só ACRESCENTA parcelas: não existe "desmarcar" apagando o histórico. Quem
// errou usa o estorno, que remove uma parcela por vez e deixa as anteriores intactas.
app.post('/api/almoxarifado/:id/devolver', exigeEditar('almoxarifado'), rota(async (req, res) => {
  const lista = lerAlmoxarifado(); const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(r => r.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Retirada não encontrada.' });
  const alvo = lista[idx];
  const corpo = req.body || {};
  const data = String(corpo.data || '').slice(0, 10) || agoraBrasilAlmox().data;
  // Quem RECEBEU de volta no almoxarifado não é necessariamente quem entregou na saída —
  // é comum o material voltar num turno diferente, para outro credenciado. Por padrão é o
  // usuário logado, mas dá para informar outro nome (lançamento feito depois).
  const recebidoPor = String(corpo.recebidoPor || '').trim().slice(0, 120)
    || quemFez(req) || alvo.responsavel || '';
  // Quem DEVOLVEU: normalmente o próprio colaborador, mas pode ser um colega levando a peça.
  const devolvidoPor = String(corpo.devolvidoPor || '').trim().slice(0, 120)
    || alvo.funcionarioNome || '';

  const itens = alvo.itens.map(it => ({ ...it, devolucoes: (it.devolucoes || []).slice() }));
  const nomeDoItem = (i) => itens[i] && itens[i].nome ? `"${itens[i].nome}"` : `item ${i + 1}`;
  const validarIndice = (i) => (Number.isInteger(i) && i >= 0 && i < itens.length)
    ? '' : 'Item não encontrado nesta retirada.';

  // ---- Estorno (desfaz a última parcela) ----
  const estornar = Array.isArray(corpo.estornar) ? corpo.estornar.map(Number) : [];
  for (const i of estornar) {
    const erro = validarIndice(i);
    if (erro) return res.status(400).json({ erro });
    if (!itens[i].devolucoes.length) {
      return res.status(400).json({ erro: `${nomeDoItem(i)} não tem devolução registrada para estornar.` });
    }
  }

  // ---- Devoluções (valida TUDO antes de gravar: ou entra a chamada inteira, ou nada) ----
  const brutos = Array.isArray(corpo.itens) ? corpo.itens : [];
  const parcelas = [];
  for (const bruto of brutos) {
    const objeto = bruto && typeof bruto === 'object';
    const i = Number(objeto ? bruto.i : bruto);
    const erroIdx = validarIndice(i);
    if (erroIdx) return res.status(400).json({ erro: erroIdx });
    const it = itens[i];
    if (!it.retornavel) {
      return res.status(400).json({ erro: `${nomeDoItem(i)} é material de consumo; não há o que devolver.` });
    }
    // O saldo já considera o que foi estornado nesta mesma chamada.
    const estornado = estornar.includes(i) && it.devolucoes.length
      ? it.devolucoes[it.devolucoes.length - 1].qtd : 0;
    const saldo = arred3(it.quantidade - it.devolucoes.reduce((t, d) => t + d.qtd, 0) + estornado);
    if (saldo <= TOLERANCIA_ALMOX) {
      return res.status(400).json({ erro: `${nomeDoItem(i)} já foi devolvido por inteiro.` });
    }
    // Sem qtd (formato antigo, lista de índices) = devolver o saldo inteiro.
    let qtd = saldo;
    if (objeto) {
      const n = arred3(Number(String(bruto.qtd ?? '').replace(',', '.')));
      if (!Number.isFinite(n) || n <= 0) {
        return res.status(400).json({ erro: `Informe uma quantidade válida para devolver ${nomeDoItem(i)}.` });
      }
      if (n > saldo + TOLERANCIA_ALMOX) {
        return res.status(400).json({ erro: `${nomeDoItem(i)}: há ${saldo} ${it.unidade} em posse; não dá para devolver ${n}.` });
      }
      qtd = Math.min(n, saldo);
    }
    parcelas.push({ i, qtd });
  }

  if (!parcelas.length && !estornar.length) {
    return res.status(400).json({ erro: 'Nada para registrar: informe o que foi devolvido.' });
  }

  // ---- Aplica (validação já passou) ----
  for (const i of estornar) itens[i].devolucoes.pop();
  const agora = Date.now();
  for (const { i, qtd } of parcelas) {
    itens[i].devolucoes.push({ qtd, data, devolvidoPara: recebidoPor, devolvidoPor, ts: agora });
  }
  alvo.itens = itens;
  lista[idx] = normalizarRetiradaAlmox(alvo);
  await salvarAlmoxarifado(lista);
  const resumo = parcelas.length
    ? `${parcelas.length} item(ns) recebido(s) por ${recebidoPor || '—'}`
    : `estorno de ${estornar.length} devolução(ões)`;
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Almoxarifado: devolução de "${alvo.funcionarioNome}" · ${resumo}` }], quemFez(req));
  res.json(comSituacaoAlmox(lista[idx]));
}));

app.delete('/api/almoxarifado/:id', exigeEditar('almoxarifado'), rota(async (req, res) => {
  const lista = lerAlmoxarifado(); const id = decodeURIComponent(req.params.id);
  const alvo = lista.find(r => r.id === id);
  const novos = lista.filter(r => r.id !== id);
  if (novos.length === lista.length) return res.status(404).json({ erro: 'Retirada não encontrada.' });
  await salvarAlmoxarifado(novos);
  // A assinatura e as fotos são exclusivas deste recibo (não são compartilhadas com nenhuma
  // outra entidade), então somem junto — senão ficariam órfãs no cofre para sempre.
  // excluirMidia respeita a quarentena do desfazer: se o usuário voltar atrás, elas voltam.
  if (alvo && alvo.assinatura && alvo.assinatura.id) await excluirMidia(alvo.assinatura.id);
  for (const f of ((alvo && alvo.fotos) || [])) if (f && f.id) await excluirMidia(f.id);
  await registrarHistorico([{ placa: '', acao: 'excluiu', texto: `Almoxarifado: retirada de "${alvo ? alvo.funcionarioNome : id}"` }], quemFez(req));
  res.json({ ok: true });
}));

// ===================== EPI — CONTROLE =====================
// ⚠️ NÃO existe `/api/epi/:id`. Tudo mora sob /catalogo ou /movimentacoes, e as rotas estáticas
// (exportar, relatorio.pdf, fichas.zip, excluir-lote) vêm ANTES das que têm :id. Isso mata de
// saída a classe de bug do /:id genérico que já morderam aqui (ver /api/funcionarios/obrigatorios).

// Mesma régua da aba Funcionários, aplicada só às MOVIMENTAÇÕES: quem enxerga uma empresa ou um
// contrato não vê as entregas de outro. Movimentação sem empresa/contrato passa (uma Entrada de
// estoque não é de ninguém em particular, e movimentação antiga ainda não carrega contratoNumero).
function filtrarEpiMov(lista, u) {
  const setE = empresasFuncPermitidas(u);
  const setC = contratosFuncPermitidos(u);
  if (setE === null && setC === null) return lista || [];
  if (setE && setE.size === 0) return [];
  return (lista || []).filter(m => {
    const e = empresaSigla(m && m.empresa);
    if (setE !== null && e && !setE.has(e)) return false;
    if (setC !== null) {
      const numero = String((m && m.contratoNumero) || '');
      if (numero && !setC.has(numero)) return false;
    }
    return true;
  });
}

// Recorte de acesso das NOTAS FISCAIS, irmão do `filtrarEpiMov`. Sem ele, quem tinha a aba EPI
// liberada mas acesso restrito a uma empresa/contrato via fornecedor, valor, descrição e centro
// de custo das compras de contratos alheios — o mesmo dado que o sistema esconde nas entregas.
// A NF não carrega empresa (só contrato/obra), então o corte possível é por CONTRATO. NF sem
// contrato passa para todos ("Sem contrato" nos gráficos): são as antigas, anteriores ao campo,
// e escondê-las faria a lista mentir para quem tem recorte.
// Ex.: usuário liberado só no contrato 4600009505, com 3 NFs na base —
//   filtrarEpiNota([{contratoNumero:'4600009505'}, {contratoNumero:'4600009606'}, {contratoNumero:''}], u)
//   → [{contratoNumero:'4600009505'}, {contratoNumero:''}]   (a do outro contrato sai; a sem contrato fica)
function filtrarEpiNota(lista, u) {
  const setE = empresasFuncPermitidas(u);
  const setC = contratosFuncPermitidos(u);
  if (setE && setE.size === 0) return [];
  if (setC === null) return lista || [];
  return (lista || []).filter(n => {
    const numero = String((n && n.contratoNumero) || '');
    return !numero || setC.has(numero);
  });
}

// ----- Notas fiscais de compra de EPI -----
// Rotas ESTÁTICAS (`/notas-fiscais`) antes das que têm `:id`, pela mesma razão de sempre neste
// arquivo: a dinâmica capturaria o caminho fixo. E `GET /api/epi` já devolve a lista junto —
// este GET existe para quem quer só as NFs (export/consulta) sem carregar a aba inteira.
app.get('/api/epi/notas-fiscais', exigeVer('epi'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json(filtrarEpiNota(lerEpiNotasFiscais(), req.usuario).slice()
    .sort((a, b) => String(b.dataCompra || '').localeCompare(String(a.dataCompra || '')) || (b.ts - a.ts)));
});
app.post('/api/epi/notas-fiscais', exigeEditar('epi'), rota(async (req, res) => {
  const n = normalizarEpiNota({ ...req.body, id: gerarId('EPI-NF'), ts: Date.now(), lancadoPor: quemFez(req) });
  const erro = erroNotaEpi(n);
  if (erro) return res.status(400).json({ erro });
  const arr = lerEpiNotasFiscais();
  if (!req.body.permitirDuplicada && notaEpiDuplicada(arr, n)) {
    return res.status(409).json({ erro: `A NF ${n.numero} de ${n.fornecedor} já está lançada.`, duplicada: true });
  }
  arr.push(n);
  await salvarEpiNotasFiscais(arr);
  // O VALOR não entra no texto: `GET /api/historico` não tem guard de área (qualquer conta
  // logada lê, inclusive recém-aprovada, que nasce sem permissão nenhuma), então o preço de
  // compra contornaria o `exigeVer('epi')` da própria lista de NFs. Número e fornecedor bastam
  // para a auditoria — o valor está na aba EPI, atrás da permissão.
  await registrarHistorico([{ placa: '', acao: 'adicionou', texto: `EPI: NF ${n.numero} — ${n.fornecedor}` }], quemFez(req));
  res.status(201).json(n);
}));
app.put('/api/epi/notas-fiscais/:id', exigeEditar('epi'), rota(async (req, res) => {
  const arr = lerEpiNotasFiscais();
  const i = arr.findIndex(x => x.id === req.params.id);
  if (i < 0) return res.status(404).json({ erro: 'Nota fiscal não encontrada.' });
  // `id`, `ts` e `lancadoPor` são do lançamento original — o corpo do request não os reescreve.
  const n = normalizarEpiNota({ ...arr[i], ...req.body, id: arr[i].id, ts: arr[i].ts, lancadoPor: arr[i].lancadoPor });
  const erro = erroNotaEpi(n);
  if (erro) return res.status(400).json({ erro });
  if (!req.body.permitirDuplicada && notaEpiDuplicada(arr, n, n.id)) {
    return res.status(409).json({ erro: `A NF ${n.numero} de ${n.fornecedor} já está lançada.`, duplicada: true });
  }
  arr[i] = n;
  await salvarEpiNotasFiscais(arr);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `EPI: NF ${n.numero} — ${n.fornecedor}` }], quemFez(req));
  res.json(n);
}));
app.delete('/api/epi/notas-fiscais/:id', exigeEditar('epi'), rota(async (req, res) => {
  const arr = lerEpiNotasFiscais();
  const n = arr.find(x => x.id === req.params.id);
  if (!n) return res.status(404).json({ erro: 'Nota fiscal não encontrada.' });
  await salvarEpiNotasFiscais(arr.filter(x => x.id !== n.id));
  await registrarHistorico([{ placa: '', acao: 'excluiu', texto: `EPI: NF ${n.numero} — ${n.fornecedor}` }], quemFez(req));
  res.json({ ok: true });
}));

// Payload único da aba: um request traz catálogo, movimentações, notas fiscais, posse e indicadores.
// O CATÁLOGO NÃO É FILTRADO por empresa/contrato — o cadastro/estoque de um contrato que o usuário
// não vê continua existindo, só a LISTA de movimentações é que respeita o acesso.
app.get('/api/epi', exigeVer('epi'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  const todasMovs = lerEpiMov();
  const mapaEstoque = estoquePorEpiEContrato(todasMovs);
  const nomesContratos = mapaNomesContratosFunc();
  const catalogo = lerEpiCatalogo().map(e => comDerivadosEpi(e, mapaEstoque, nomesContratos));
  const minhas = filtrarEpiMov(todasMovs, req.usuario);
  res.json({
    catalogo,
    movimentacoes: minhas
      .slice()
      .sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')) || (b.ts - a.ts))
      .map(comSituacaoMovEpi),
    // Compras (NF) seguem o MESMO recorte de acesso das movimentações (ver `filtrarEpiNota`):
    // o depósito é um só, mas fornecedor/valor/centro de custo são dado de contrato e não podem
    // vazar para quem só enxerga outra obra. Ordenam por `dataCompra` (a NF não tem `data`).
    notasFiscais: filtrarEpiNota(lerEpiNotasFiscais(), req.usuario)
      .slice()
      .sort((a, b) => String(b.dataCompra || '').localeCompare(String(a.dataCompra || '')) || (b.ts - a.ts)),
    posse: posseEpi(minhas),
    indicadores: indicadoresEpi(catalogo, todasMovs, posseEpi(todasMovs)),
    geradoEm: Date.now(),
  });
});

// Quem está com o quê (e quando vence a troca). Usado no modal da ficha para o RH ver, antes de
// entregar, o que aquele colaborador já tem em posse.
app.get('/api/epi/posse', exigeVer('epi'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  const lista = posseEpi(filtrarEpiMov(lerEpiMov(), req.usuario));
  const fid = String(req.query.funcionarioId || '').trim();
  res.json(fid ? lista.filter(p => String(p.funcionarioId) === fid) : lista);
});

// ---- Excel ----
const COLS_EPI_CAT = [
  ['nome', 'EPI'], ['codigo', 'CÓDIGO'], ['ca', 'Nº DO CA'], ['validadeCa', 'VALIDADE DO CA'],
  ['statusCa', 'STATUS DO CA'], ['diasCa', 'DIAS ATÉ VENCER'], ['fabricante', 'FABRICANTE'],
  ['categoria', 'CATEGORIA'], ['tamanho', 'TAMANHO'], ['unidade', 'UNIDADE'], ['contratos', 'CONTRATOS'],
  ['estoque', 'ESTOQUE'], ['estoquePorContrato', 'ESTOQUE POR CONTRATO'],
  ['estoqueMinimo', 'ESTOQUE MÍNIMO'], ['situacaoEstoque', 'SITUAÇÃO DO ESTOQUE'],
  ['vidaUtilMeses', 'VIDA ÚTIL (MESES)'], ['ativo', 'ATIVO'], ['descricao', 'DESCRIÇÃO'], ['obs', 'OBSERVAÇÃO'], ['id', 'ID'],
];
function linhasPlanilhaEpiCat(lista) {
  return lista.map(e => ({
    nome: e.nome, codigo: e.codigo, ca: e.ca, validadeCa: isoParaBR(e.caValidade),
    statusCa: e.statusCa || 'Sem CA', diasCa: e.diasCa === null ? '' : e.diasCa,
    fabricante: e.fabricante, categoria: e.categoria, tamanho: e.tamanho, unidade: e.unidade,
    contratos: (e.contratos && e.contratos.length) ? e.contratos.join(', ') : 'Sem contrato · migrar',
    estoque: e.estoque,
    estoquePorContrato: (e.estoquePorContrato || []).map(l => `${l.nome || l.numero || 'sem contrato'}: ${l.estoque}`).join(' · '),
    estoqueMinimo: e.estoqueMinimo,
    situacaoEstoque: e.semEstoque ? 'Zerado' : e.abaixoMinimo ? 'Abaixo do mínimo' : 'Normal',
    vidaUtilMeses: e.vidaUtilMeses || '', ativo: e.ativo ? 'Sim' : 'Não',
    descricao: e.descricao, obs: e.obs, id: e.id,
  }));
}

// Uma linha POR ITEM — é o formato que se filtra e se soma no Excel.
const COLS_EPI_MOV = [
  ['data', 'DATA'], ['hora', 'HORA'], ['tipo', 'TIPO'],
  ['colaborador', 'COLABORADOR'], ['cpf', 'CPF'], ['cargo', 'CARGO'], ['empresa', 'EMPRESA'],
  ['contrato', 'CONTRATO / OBRA'], ['setor', 'SETOR'], ['centroCusto', 'CENTRO DE CUSTO'],
  ['epi', 'EPI'], ['codigo', 'CÓDIGO'], ['ca', 'Nº DO CA'], ['validadeCa', 'VALIDADE DO CA'], ['statusCa', 'STATUS DO CA'],
  ['tamanho', 'TAMANHO'], ['quantidade', 'QUANTIDADE'], ['unidade', 'UNIDADE'],
  ['vidaUtilMeses', 'VIDA ÚTIL (MESES)'], ['trocaPrevista', 'TROCA PREVISTA'],
  ['descartado', 'DESCARTADO NA DEVOLUÇÃO'], ['condicao', 'CONDIÇÃO'],
  ['fornecedor', 'FORNECEDOR'], ['notaFiscal', 'NOTA FISCAL'],
  ['responsavel', 'RESPONSÁVEL'], ['lancadoPor', 'LANÇADO POR'], ['motivo', 'MOTIVO'],
  ['situacao', 'SITUAÇÃO'], ['assinado', 'ASSINADO'], ['assinadoPor', 'ASSINADO POR'], ['assinadoEm', 'ASSINADO EM'],
  ['assinaturaLink', 'ASSINATURA (LINK)'], ['codigoVerificacao', 'CÓDIGO DE CONFERÊNCIA'],
  ['obs', 'OBSERVAÇÃO'], ['movimentacao', 'Nº DA MOVIMENTAÇÃO'],
];
function linhasPlanilhaEpiMov(lista, origem) {
  const carimbo = (ts) => ts ? new Date(ts).toLocaleString('pt-BR') : '';
  const linhas = [];
  for (const m of lista) {
    const base = {
      data: isoParaBR(m.data), hora: m.hora, tipo: m.tipo,
      colaborador: m.funcionarioNome, cpf: m.funcionarioCpf, cargo: m.funcionarioCargo, empresa: m.empresa,
      contrato: m.contrato, setor: m.setor, centroCusto: m.centroCusto,
      fornecedor: m.fornecedor, notaFiscal: m.notaFiscal,
      responsavel: m.responsavel, lancadoPor: m.responsavelUsuario, motivo: m.motivo,
      situacao: situacaoMovEpi(m),
      assinado: (m.assinatura && m.assinatura.id) ? 'Sim' : 'Não',
      assinadoPor: m.assinaturaNome, assinadoEm: carimbo(m.assinaturaEm),
      assinaturaLink: (m.assinatura && m.assinatura.id) ? `${origem}/api/midia/${encodeURIComponent(m.assinatura.id)}` : '',
      codigoVerificacao: m.assinaturaCodigo, obs: m.obs, movimentacao: m.id,
    };
    if (!m.itens.length) { linhas.push({ ...base, epi: '', codigo: '', ca: '', validadeCa: '', statusCa: '', tamanho: '', quantidade: '', unidade: '', vidaUtilMeses: '', trocaPrevista: '', descartado: '', condicao: '' }); continue; }
    for (const i of m.itens) {
      const troca = (m.tipo === 'Entrega' || m.tipo === 'Substituição') ? addMesesEpi(m.data, i.vidaUtilMeses) : '';
      linhas.push({
        ...base,
        epi: i.nome, codigo: i.codigo, ca: i.ca,
        validadeCa: isoParaBR(i.caValidade), statusCa: statusCaEpi(i.caValidade) || 'Sem CA',
        tamanho: i.tamanho, quantidade: i.quantidade, unidade: i.unidade,
        vidaUtilMeses: i.vidaUtilMeses || '', trocaPrevista: isoParaBR(troca),
        descartado: m.tipo === 'Devolução' ? (i.descartar ? 'Sim' : 'Não') : '',
        condicao: i.condicao,
      });
    }
  }
  return linhas;
}

// POST (e não GET) porque o cliente manda os ids da tela: a planilha sai com o MESMO recorte
// que o usuário filtrou. Sem ids, exporta tudo o que ele pode ver.
app.post('/api/epi/catalogo/exportar', exigeVer('epi'), rota(async (req, res) => {
  const mapaEstoque = estoquePorEpiEContrato(lerEpiMov());
  const nomesContratos = mapaNomesContratosFunc();
  let lista = lerEpiCatalogo().map(e => comDerivadosEpi(e, mapaEstoque, nomesContratos));
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(e => set.has(String(e.id))); }
  lista = lista.slice().sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR'));
  enviarPlanilha(res, 'EPI-CATALOGO.xlsx', 'CATALOGO', COLS_EPI_CAT, linhasPlanilhaEpiCat(lista));
}));

app.post('/api/epi/movimentacoes/exportar', exigeVer('epi'), rota(async (req, res) => {
  let lista = filtrarEpiMov(lerEpiMov(), req.usuario);
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(m => set.has(String(m.id))); }
  lista = lista.slice().sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')) || (b.ts - a.ts));
  const origem = `${req.protocol}://${req.get('host')}`;
  enviarPlanilha(res, 'EPI-MOVIMENTACOES.xlsx', 'MOVIMENTACOES', COLS_EPI_MOV, linhasPlanilhaEpiMov(lista, origem));
}));

// Exportação das NOTAS FISCAIS de EPI — mesmo contrato dos outros dois exports: o cliente
// manda os ids filtrados da tela; sem ids, sai tudo.
// Ex. de uso: POST /api/epi/notas-fiscais/exportar {ids:['EPI-NF-1']} → EPI-NOTAS-FISCAIS.xlsx
const COLS_EPI_NF = [
  ['dataCompra', 'DATA DA COMPRA'], ['numero', 'Nº DA NF'], ['fornecedor', 'FORNECEDOR'],
  ['descricao', 'DESCRIÇÃO'], ['valorTotal', 'VALOR TOTAL (R$)'], ['parcelas', 'PARCELAS'],
  ['valorParcela', 'VALOR DA PARCELA (R$)'], ['contrato', 'CONTRATO'], ['centroCusto', 'CENTRO DE CUSTO'],
  ['observacoes', 'OBSERVAÇÕES'], ['lancadoPor', 'LANÇADO POR'],
];
function linhasPlanilhaEpiNf(lista) {
  const moeda = (v) => (Number(v) || 0).toFixed(2).replace('.', ',');
  return lista.map(n => ({
    dataCompra: isoParaBR(n.dataCompra), numero: n.numero, fornecedor: n.fornecedor,
    descricao: n.descricao, valorTotal: moeda(n.valorTotal), parcelas: n.parcelas,
    valorParcela: moeda((Number(n.valorTotal) || 0) / Math.max(1, Number(n.parcelas) || 1)),
    contrato: n.contratoNumero ? (n.contrato || n.contratoNumero) : 'Sem contrato',
    centroCusto: n.centroCusto, observacoes: n.observacoes, lancadoPor: n.lancadoPor,
  }));
}
app.post('/api/epi/notas-fiscais/exportar', exigeVer('epi'), rota(async (req, res) => {
  let lista = lerEpiNotasFiscais();
  const ids = (req.body && Array.isArray(req.body.ids)) ? req.body.ids : null;
  if (ids && ids.length) { const set = new Set(ids.map(String)); lista = lista.filter(n => set.has(String(n.id))); }
  lista = lista.slice().sort((a, b) => String(b.dataCompra || '').localeCompare(String(a.dataCompra || '')) || (b.ts - a.ts));
  enviarPlanilha(res, 'EPI-NOTAS-FISCAIS.xlsx', 'NOTAS FISCAIS', COLS_EPI_NF, linhasPlanilhaEpiNf(lista));
}));

// ---- PDF ----
// Estrutura IRMÃ de gerarPdfAlmox: os helpers que capturam page/y são copiados de propósito
// (extrair exigiria virar fábrica-com-estado, um diff grande num documento com valor de
// comprovante e sem teste de layout). Mudança de layout comum tem de ir nos DOIS.
// A ficha de EPI divergiu de verdade: colunas de CA/validade/vida útil/troca prevista e a
// declaração da NR-6, que é o que dá valor legal ao documento.
async function gerarPdfEpi(lista, modo, origem) {
  const A4_W = 595.28, A4_H = 841.89, MARGEM = 42;
  const LARG = A4_W - MARGEM * 2;
  const COR_INK = rgb(0.11, 0.14, 0.20), COR_MUTED = rgb(0.42, 0.46, 0.54);
  const COR_BRAND = rgb(0.192, 0.212, 0.243), COR_LINHA = rgb(0.88, 0.90, 0.94);
  const COR_BOX = rgb(0.96, 0.97, 0.99), COR_ZEBRA = rgb(0.972, 0.978, 0.988);
  const COR_VERM = rgb(0.77, 0.15, 0.15), COR_VERDE = rgb(0.06, 0.5, 0.22);
  const COR_AMBAR = rgb(0.85, 0.47, 0.02);
  const safe = textoWinAnsi, isoBR = isoParaBR;

  const doc = await PDFDocument.create();
  doc.setTitle(modo === 'ficha' ? 'Ficha de entrega de EPI' : modo === 'estoque' ? 'Estoque de EPI' : 'Relatório de EPI');
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const fontB = await doc.embedFont(StandardFonts.HelveticaBold);

  const logos = new Map();
  const carregarLogo = async (sigla) => {
    const chave = ['NTE', 'SUL'].includes(sigla) ? sigla.toLowerCase() : 'rm';
    if (logos.has(chave)) return logos.get(chave);
    let img = null;
    try {
      const lp = path.join(RAIZ, 'frontend', 'img', 'logo-' + chave + '.png');
      if (fs.existsSync(lp)) img = await doc.embedPng(fs.readFileSync(lp));
    } catch (e) { img = null; }
    logos.set(chave, img);
    return img;
  };
  const imagensPdf = new Map();
  const carregarImagem = async (ref) => {
    if (!ref || !ref.id) return null;
    if (imagensPdf.has(ref.id)) return imagensPdf.get(ref.id);
    let img = null;
    try {
      const m = await lerMidia(ref.id);
      if (m && m.b64) {
        const buf = Buffer.from(m.b64, 'base64');
        img = (m.tipo === 'image/png') ? await doc.embedPng(buf) : await doc.embedJpg(buf);
      }
    } catch (e) {
      // Indisponibilidade do cofre SOBE (rota() → 503): imprimir o comprovante sem a assinatura
      // seria entregar um recibo "sem assinatura" que foi assinado. Imagem corrompida ou em
      // formato que o pdf-lib não embute continua virando só o quadro vazio.
      if (e && e.codigo === 'COFRE_INDISPONIVEL') throw e;
      img = null;
    }
    imagensPdf.set(ref.id, img);
    return img;
  };

  let page = doc.addPage([A4_W, A4_H]);
  let y = A4_H - MARGEM;
  const novaPagina = () => { page = doc.addPage([A4_W, A4_H]); y = A4_H - MARGEM; };
  const garante = (h) => { if (y - h < MARGEM + 24) novaPagina(); };
  const wrap = (texto, fnt, size, maxW) => {
    const palavras = safe(texto).split(/\s+/).filter(Boolean);
    if (!palavras.length) return [''];
    const linhas = []; let cur = '';
    for (let w of palavras) {
      while (fnt.widthOfTextAtSize(w, size) > maxW && w.length > 1) {
        let i = 1;
        while (i < w.length && fnt.widthOfTextAtSize(w.slice(0, i + 1), size) <= maxW) i++;
        if (cur) { linhas.push(cur); cur = ''; }
        linhas.push(w.slice(0, i));
        w = w.slice(i);
      }
      const teste = cur ? cur + ' ' + w : w;
      if (fnt.widthOfTextAtSize(teste, size) > maxW && cur) { linhas.push(cur); cur = w; } else cur = teste;
    }
    if (cur) linhas.push(cur);
    return linhas;
  };
  const cabecalho = async (sigla, titulo, sub) => {
    const logo = await carregarLogo(sigla);
    const LOGO_H = 30, topo = y;
    let esqX = MARGEM;
    if (logo) {
      const lw = logo.width * (LOGO_H / logo.height);
      page.drawImage(logo, { x: MARGEM, y: topo - LOGO_H, width: lw, height: LOGO_H });
      esqX += lw + 14;
    }
    page.drawText(safe(titulo), { x: esqX, y: topo - 14, size: 13, font: fontB, color: COR_INK });
    page.drawText(safe(sub), { x: esqX, y: topo - 27, size: 8.5, font, color: COR_MUTED });
    y = topo - LOGO_H - 12;
    page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 1.5, color: COR_BRAND });
    y -= 14;
  };
  const grid = (pares, cols) => {
    const cheios = pares.filter(([, val]) => String(val == null ? '' : val).trim() !== '');
    if (!cheios.length) return;
    const cw = LARG / cols;
    for (let i = 0; i < cheios.length; i += cols) {
      const bloco = cheios.slice(i, i + cols);
      const celulas = bloco.map(([, val]) => wrap(val, font, 10, cw - 12));
      const h = 13 + Math.max(...celulas.map(c => c.length)) * 12.5 + 7;
      garante(h);
      bloco.forEach(([rot], j) => page.drawText(safe(String(rot).toUpperCase()), { x: MARGEM + j * cw, y: y - 8, size: 6.8, font: fontB, color: COR_MUTED }));
      celulas.forEach((linhas, j) => linhas.forEach((ln, k) => page.drawText(ln, { x: MARGEM + j * cw, y: y - 22 - k * 12.5, size: 10, font, color: COR_INK })));
      y -= h;
    }
  };
  // Tabela genérica: cols = [{tit, larg, dir?}]; monta o cabeçalho e devolve o desenhador de célula.
  const montarTabela = (cols, titulo) => {
    if (titulo) {
      y -= 10;
      page.drawText(safe(titulo), { x: MARGEM, y: y - 10, size: 10.5, font: fontB, color: COR_BRAND });
      y -= 15;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.8, color: COR_LINHA });
      y -= 8;
    }
    const xs = []; let acc = MARGEM;
    cols.forEach(c => { xs.push(acc); acc += c.larg; });
    const cabecalhoTabela = () => {
      garante(20);
      page.drawRectangle({ x: MARGEM, y: y - 16, width: LARG, height: 16, color: COR_BOX });
      cols.forEach((c, i) => {
        const t = safe(c.tit);
        const x = c.dir ? xs[i] + c.larg - 6 - fontB.widthOfTextAtSize(t, 7.2) : xs[i] + 6;
        page.drawText(t, { x, y: y - 11, size: 7.2, font: fontB, color: COR_MUTED });
      });
      y -= 16;
    };
    cabecalhoTabela();
    // Corta pela LARGURA real: pdf-lib não recorta texto que transborda, ele invade a coluna vizinha.
    const cel = (i, txt, base, cor, size) => {
      const sz = size || 8.5;
      let t = safe(txt);
      const maxW = cols[i].larg - 12;
      while (t.length > 2 && font.widthOfTextAtSize(t, sz) > maxW) t = t.slice(0, -2);
      const x = cols[i].dir ? xs[i] + cols[i].larg - 6 - font.widthOfTextAtSize(t, sz) : xs[i] + 6;
      page.drawText(t, { x, y: base, size: sz, font, color: cor || COR_INK });
    };
    return { xs, cel, cabecalhoTabela };
  };

  if (modo === 'ficha') {
    // O "papel" É o modelo oficial: em vez de redesenhar o formulario, usamos o PROPRIO PDF do
    // Word como fundo (frontend/modelos/epi-ficha-<nte|sul>.pdf, gerado uma vez a partir de
    // "docs/EPI Modelo/FICHA DE EPI NTE.doc"/"...SUL.doc") e só escrevemos os dados por cima — fidelidade
    // total de layout/fonte/borda, porque é literalmente o mesmo documento. As coordenadas abaixo
    // foram extraídas de VERDADE do PDF oficial (via pdfjs-dist, texto por texto), não estimadas.
    const funcById = new Map(lerFuncionarios().map(f => [f.id, f]));
    const PRETO = rgb(0, 0, 0), BRANCO = rgb(1, 1, 1);
    const MESES_PT = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
    const partesData = (iso) => {
      const m2 = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
      if (!m2) return null;
      return { dia: m2[3], mes: MESES_PT[Number(m2[2]) - 1], ano: m2[1] };
    };
    const templatesDoc = new Map();
    const carregarTemplateDoc = async (sigla) => {
      const chave = sigla === 'SUL' ? 'sul' : 'nte';
      if (templatesDoc.has(chave)) return templatesDoc.get(chave);
      const bytes = fs.readFileSync(path.join(RAIZ, 'frontend', 'modelos', `epi-ficha-${chave}.pdf`));
      const tpl = await PDFDocument.load(bytes);
      templatesDoc.set(chave, tpl);
      return tpl;
    };
    // A conversão do .doc com logo SUL saiu 6.36pt mais alta que a versão NTE (mesmo layout,
    // só um parágrafo do cabeçalho com altura levemente diferente no Word) — confirmado
    // comparando as posições reais dos dois PDFs. Corrige somando este deslocamento pra SUL.
    const OFFSET_Y = { NTE: 0, SUL: 6.36 };
    // Coordenadas do modelo NTE (página 595.56x842.04pt, y crescendo de baixo pra cima — igual
    // ao pdf-lib). NÃO ajustar de olho: recalibrar extraindo as posições reais do PDF se o
    // arquivo em frontend/modelos/ for trocado.
    const POS = {
      colaborador: { x: 109.6, y: 737.7, maxW: 271 }, cpf: { x: 462.6, y: 737.7, maxW: 103 },
      cargo: { x: 109.6, y: 723.3, maxW: 111 }, admissao: { x: 300, y: 723.3, maxW: 81 }, matricula: { x: 462.6, y: 723.3, maxW: 103 },
      // colX/tabColMaxW vêm das bordas REAIS das células (extraídas dos operadores "re" do
      // content stream do PDF-modelo — não de estimativa por centralização, que errou feio a
      // coluna de descrição): QTDE 19.32-57.38, DESCRIÇÃO 58.46-233.57, DATA 234.53-297.43,
      // CA 298.87-377.71, ASSINATURA 378.67-576.84.
      tabColX: [24, 64, 239.5, 302.5], tabColMaxW: [30, 165, 55, 72], tabTopo: 678, tabAltura: 22.14, tabMaxLinhas: 19, tabBase: 8,
      dataDia: { x: 140.2, y: 97.56 }, dataMes: { x: 217.9, y: 97.56 }, dataAno: { x: 304.2, y: 97.56 },
      nomeFuncionario: { x: 85, y: 39.96, maxW: 255 }, carimbo: { x: 24, y: 52 },
      assinaturaImg: { x: 24, y: 62, w: 230, h: 26 },
      // Bloco da empresa (cabeçalho E rodapé): os DOIS modelos vieram do Word com "NTE
      // ENGENHARIA"/CNPJ da NTE escritos no papel — o .doc da SUL é cópia do da NTE e só o logo foi
      // trocado, então toda ficha da SUL saía com a identificação jurídica da outra empresa. Logo o
      // bloco deixou de ser fundo e virou DADO: `tapa` é o retângulo branco que cobre o texto do
      // modelo e o valor é reescrito de EMPRESAS_FUNC_ROTULOS. Vale para os dois modelos (na NTE o
      // texto sai idêntico ao do papel) — um caminho só, sem `if` pendurado no acaso de um .doc.
      // As tapas foram medidas rasterizando os modelos: o fundo das 4 células é branco puro, dentro
      // de cada retângulo só existe a tinta do texto errado, e o sublinhado cinza do campo, a borda
      // da linha e a borda do quadro do rodapé ficam FORA (sobrevivem). Recalibrar se trocar o PDF.
      empresaTopo: { x: 109.58, y: 752.02, maxW: 271, size: 9, tapa: { x: 99, y: 751.5, w: 283, h: 15.5 } },
      cnpjTopo: { x: 462.58, y: 752.02, maxW: 110, size: 9, tapa: { x: 451.5, y: 751.5, w: 125.5, h: 15.5 } },
      empresaPe: { x: 392.23, y: 39.72, maxW: 184, size: 10, tapa: { x: 391, y: 36.4, w: 186, h: 12.6 } },
      cnpjPe: { x: 373.51, y: 26.16, maxW: 203, size: 10, tapa: { x: 372.5, y: 23.6, w: 204.5, h: 12.3 } },
    };
    // Escreve truncando pela LARGURA real (não por nº de caracteres) — nomes/cargos longos não
    // podem invadir o próximo campo do formulário oficial.
    const campo = (txt, x, yv, maxW, size, fnt, cor) => {
      let t = safe(txt || '');
      while (t.length > 2 && fnt.widthOfTextAtSize(t, size) > maxW) t = t.slice(0, -2);
      page.drawText(t, { x, y: yv, size, font: fnt, color: cor || PRETO });
    };
    const centro = (texto, size, cx, yv) => {
      const t = safe(texto);
      const w = font.widthOfTextAtSize(t, size);
      page.drawText(t, { x: cx - w / 2, y: yv, size, font, color: PRETO });
    };
    // Tapa o valor que veio impresso no modelo e escreve o certo em cima (ver POS.empresaTopo).
    const campoEmpresa = (p, txt, dy) => {
      page.drawRectangle({ x: p.tapa.x, y: p.tapa.y + dy, width: p.tapa.w, height: p.tapa.h, color: BRANCO });
      campo(txt, p.x, p.y + dy, p.maxW, p.size, font);
    };
    // Esta função sempre cria 1 página em branco antes do "if" (usada direto nos modos
    // 'estoque'/'relatorio'); aqui cada movimentação ganha a SUA cópia da página-modelo, então
    // a página em branco inicial não serve pra nada — remove antes de começar.
    while (doc.getPageCount() > 0) doc.removePage(0);

    for (let n = 0; n < lista.length; n++) {
      const m = lista[n];
      const sigla = empresaSigla(m.empresa);
      const siglaLogo = sigla === 'SUL' ? 'SUL' : 'NTE';
      const func = m.funcionarioId ? funcById.get(m.funcionarioId) : null;
      const dy = OFFSET_Y[siglaLogo] || 0;
      const tpl = await carregarTemplateDoc(siglaLogo);
      const [copiada] = await doc.copyPages(tpl, [0]);
      page = doc.addPage(copiada);

      // Empresa do colaborador — mesma fonte de verdade do catálogo de contratos. Sigla fora de
      // NTE/SUL cai no papel da NTE (é o modelo usado), então os dados também.
      const emp = EMPRESAS_FUNC_ROTULOS[siglaLogo] || EMPRESAS_FUNC_ROTULOS.NTE;
      campoEmpresa(POS.empresaTopo, emp.nome, dy);
      campoEmpresa(POS.cnpjTopo, emp.cnpj, dy);
      campoEmpresa(POS.empresaPe, emp.nome, dy);
      campoEmpresa(POS.cnpjPe, emp.cnpj, dy);

      campo(m.funcionarioNome, POS.colaborador.x, POS.colaborador.y + dy, POS.colaborador.maxW, 9, font);
      campo(m.funcionarioCpf, POS.cpf.x, POS.cpf.y + dy, POS.cpf.maxW, 9, font);
      campo(m.funcionarioCargo, POS.cargo.x, POS.cargo.y + dy, POS.cargo.maxW, 9, font);
      if (func && func.admissao) campo(isoBR(func.admissao), POS.admissao.x, POS.admissao.y + dy, POS.admissao.maxW, 9, font);
      if (func && func.matricula) campo(func.matricula, POS.matricula.x, POS.matricula.y + dy, POS.matricula.maxW, 9, font);

      m.itens.slice(0, POS.tabMaxLinhas).forEach((it, idx) => {
        const base = POS.tabTopo - POS.tabAltura * idx + dy - POS.tabBase;
        campo(`${it.quantidade} ${it.unidade}`, POS.tabColX[0], base, POS.tabColMaxW[0], 8.5, font);
        // Coluna estreita (é a largura real do formulário oficial) — solta o código entre
        // parênteses antes de truncar o nome, senão vira "...(CA" cortado no meio.
        let desc = it.nome + (it.codigo ? ' (' + it.codigo + ')' : '');
        if (it.codigo && font.widthOfTextAtSize(safe(desc), 8.5) > POS.tabColMaxW[1]) desc = it.nome;
        campo(desc, POS.tabColX[1], base, POS.tabColMaxW[1], 8.5, font);
        campo(isoBR(m.data), POS.tabColX[2], base, POS.tabColMaxW[2], 8.5, font);
        // CA já vencido NO DIA da entrega sai em vermelho: é a irregularidade que a fiscalização procura.
        const venc = statusCaEpi(it.caValidade);
        campo(it.ca || '-', POS.tabColX[3], base, POS.tabColMaxW[3], 8.5, font,
          venc === 'Vencido' ? COR_VERM : venc === 'Próximo do vencimento' ? COR_AMBAR : PRETO);
      });

      const dp = partesData(m.data);
      if (dp) {
        centro(dp.dia, 9, POS.dataDia.x, POS.dataDia.y + dy);
        centro(dp.mes, 9, POS.dataMes.x, POS.dataMes.y + dy);
        centro(dp.ano, 9, POS.dataAno.x, POS.dataAno.y + dy);
      }

      campo(m.assinaturaNome || m.funcionarioNome, POS.nomeFuncionario.x, POS.nomeFuncionario.y + dy, POS.nomeFuncionario.maxW, 9, fontB);
      const img = await carregarImagem(m.assinatura);
      if (img) {
        const escala = Math.min(POS.assinaturaImg.w / img.width, POS.assinaturaImg.h / img.height);
        const iw = img.width * escala, ih = img.height * escala;
        page.drawImage(img, { x: POS.assinaturaImg.x + (POS.assinaturaImg.w - iw) / 2, y: POS.assinaturaImg.y + dy, width: iw, height: ih });
        page.drawText(safe('Assinado eletronicamente em ' + new Date(m.assinaturaEm).toLocaleString('pt-BR')),
          { x: POS.carimbo.x, y: POS.carimbo.y + dy, size: 6.5, font, color: COR_MUTED });
      } else {
        page.drawText(safe('Sem assinatura eletrônica - assinar de próprio punho'),
          { x: POS.carimbo.x, y: POS.carimbo.y + dy, size: 6.5, font, color: COR_VERM });
      }

      // Itens além da capacidade do formulário (raro) continuam numa página extra simples —
      // o modelo oficial não prevê continuação, então aqui é só uma lista, sem tentar imitar a grade.
      if (m.itens.length > POS.tabMaxLinhas) {
        novaPagina();
        page.drawText(safe('EPIs entregues (continuação); ' + (m.funcionarioNome || '')), { x: MARGEM, y: y - 9, size: 10, font: fontB, color: PRETO });
        y -= 26;
        m.itens.slice(POS.tabMaxLinhas).forEach((it) => {
          const venc = statusCaEpi(it.caValidade);
          const linhas = wrap(`${it.quantidade} ${it.unidade} - ${it.nome}${it.codigo ? ' (' + it.codigo + ')' : ''} - CA ${it.ca || '-'}`, font, 9, LARG);
          garante(linhas.length * 12 + 4);
          linhas.forEach((ln, k) => page.drawText(ln, { x: MARGEM, y: y - k * 12, size: 9, font,
            color: venc === 'Vencido' ? COR_VERM : venc === 'Próximo do vencimento' ? COR_AMBAR : PRETO }));
          y -= linhas.length * 12 + 4;
        });
      }

      // Certificado de assinatura eletrônica + QR não existe no papel (é o valor extra da
      // assinatura digital) — vai numa página própria, junto com tipo/responsável/motivo/observações
      // (que também não têm onde entrar no formulário oficial).
      if (m.assinaturaEm) {
        novaPagina();
        const metaPartes = [];
        if (m.tipo) metaPartes.push('Tipo: ' + m.tipo);
        if (m.responsavel) metaPartes.push('Registrado por: ' + m.responsavel);
        if (m.motivo) metaPartes.push('Motivo: ' + m.motivo);
        if (m.obs) metaPartes.push('Observações: ' + m.obs);
        if (metaPartes.length) {
          const meta = wrap(metaPartes.join('   -   '), font, 9, LARG);
          meta.forEach((ln, k) => page.drawText(ln, { x: MARGEM, y: y - k * 12, size: 9, font, color: COR_MUTED }));
          y -= meta.length * 12 + 16;
        }
        const alterada = movEpiAlterada(m);
        const CERT_H = 110;
        garante(CERT_H + 8);
        const topoCert = y;
        page.drawRectangle({ x: MARGEM, y: topoCert - CERT_H, width: LARG, height: CERT_H,
          borderColor: alterada ? COR_VERM : PRETO, borderWidth: alterada ? 1.2 : 0.8 });
        page.drawText('CERTIFICADO DA ASSINATURA ELETRÔNICA', { x: MARGEM + 10, y: topoCert - 15, size: 7.5, font: fontB, color: alterada ? COR_VERM : PRETO });
        const evid = [
          ['Assinado por', m.assinaturaNome || m.funcionarioNome],
          ['Data e hora', new Date(m.assinaturaEm).toLocaleString('pt-BR')],
          ['Forma', m.assinaturaModo === 'digitado' ? 'Nome digitado pelo signatário' : 'Traçado de próprio punho na tela'],
          ['Endereço IP', m.assinaturaIp || '-'],
          ['Dispositivo', m.assinaturaDispositivo || '-'],
          ['Declaração', m.assinaturaAceite ? 'Aceite de recebimento confirmado' : 'sem registro de aceite'],
        ];
        const colW = (LARG - 210) / 2;
        evid.forEach(([rot, val], i) => {
          const cx = MARGEM + 10 + (i % 2) * colW;
          const cy = topoCert - 32 - Math.floor(i / 2) * 21;
          page.drawText(safe(rot.toUpperCase()), { x: cx, y: cy, size: 6, font: fontB, color: COR_MUTED });
          let t = safe(String(val));
          const maxW = colW - 20;
          while (t.length > 4 && font.widthOfTextAtSize(t, 8) > maxW) t = t.slice(0, -2);
          if (t !== safe(String(val))) t += '...';
          page.drawText(t, { x: cx, y: cy - 9, size: 8, font, color: PRETO });
        });
        if (m.assinaturaCodigo) {
          const qrLado = 58;
          const qrX = MARGEM + LARG - qrLado - 12;
          desenharQrNoPdf(page, urlVerificacaoAlmox(m.assinaturaCodigo, origem), qrX, topoCert - CERT_H + 26, qrLado, PRETO);
          const txtX = qrX - 132;
          page.drawText('CONFIRA A AUTENTICIDADE', { x: txtX, y: topoCert - 34, size: 6, font: fontB, color: COR_MUTED });
          page.drawText(safe(m.assinaturaCodigo), { x: txtX, y: topoCert - 49, size: 12, font: fontB, color: PRETO });
          wrap('Leia o QR ao lado ou informe este código em ' + urlVerificacaoAlmox('', origem), font, 6, 126)
            .forEach((ln, k) => page.drawText(ln, { x: txtX, y: topoCert - 62 - k * 7.5, size: 6, font, color: COR_MUTED }));
        }
        if (alterada) {
          page.drawText(safe('ATENÇÃO: a ficha foi alterada depois de assinada - a assinatura não cobre o conteúdo atual.'),
            { x: MARGEM + 10, y: topoCert - CERT_H + 6, size: 7, font: fontB, color: COR_VERM });
        }
      }
    }
  } else if (modo === 'estoque') {
    await cabecalho('', 'ESTOQUE DE EPI', `Catalogo - ${lista.length} item(ns) - emitido em ${new Date().toLocaleString('pt-BR')}`);
    const total = lista.reduce((s, e) => s + (Number(e.estoque) || 0), 0);
    // Uma linha por (EPI x contrato vinculado) — o estoque agora é separado por contrato, não um
    // número só por EPI. EPI sem nenhuma linha (ainda não migrado e sem movimentação nenhuma)
    // ainda ganha uma linha própria "sem contrato": não pode desaparecer do relatório.
    const linhas = [];
    lista.forEach((e) => {
      const porContrato = (e.estoquePorContrato && e.estoquePorContrato.length)
        ? e.estoquePorContrato
        : [{ numero: '', nome: '— sem contrato —', estoque: 0, abaixoMinimo: false, semEstoque: true }];
      porContrato.forEach(l => linhas.push({ epi: e, linha: l }));
    });
    const kpis = [
      { rotulo: 'Itens no catalogo', valor: String(lista.length) },
      { rotulo: 'Total em estoque', valor: String(total) },
      { rotulo: 'Abaixo do minimo', valor: String(linhas.filter(r => r.linha.abaixoMinimo).length), cor: linhas.some(r => r.linha.abaixoMinimo) ? COR_VERM : COR_VERDE },
      { rotulo: 'CA vencido', valor: String(lista.filter(e => e.statusCa === 'Vencido').length), cor: lista.some(e => e.statusCa === 'Vencido') ? COR_VERM : COR_VERDE },
      { rotulo: 'CA a vencer', valor: String(lista.filter(e => e.statusCa === 'Próximo do vencimento').length), cor: COR_AMBAR },
    ];
    const gap = 9, w = (LARG - gap * (kpis.length - 1)) / kpis.length, hK = 44;
    kpis.forEach((it, i) => {
      const x = MARGEM + i * (w + gap);
      page.drawRectangle({ x, y: y - hK, width: w, height: hK, color: COR_BOX, borderColor: COR_LINHA, borderWidth: 1 });
      page.drawText(safe(it.rotulo.toUpperCase()), { x: x + 8, y: y - 15, size: 6.5, font: fontB, color: COR_MUTED });
      page.drawText(safe(it.valor), { x: x + 8, y: y - 33, size: 14, font: fontB, color: it.cor || COR_INK });
    });
    y -= hK + 14;
    const cols = [{ tit: 'EPI', larg: 128 }, { tit: 'CONTRATO', larg: 90 }, { tit: 'CODIGO', larg: 56 }, { tit: 'CA', larg: 46 },
      { tit: 'VALID. CA', larg: 50 }, { tit: 'STATUS DO CA', larg: 62 },
      { tit: 'ESTOQUE', larg: 46, dir: true }, { tit: 'MINIMO', larg: 33, dir: true }];
    const T = montarTabela(cols, '');
    linhas.forEach((r, idx) => {
      const e = r.epi, l = r.linha;
      const nomeLinhas = wrap(e.nome, font, 8.5, cols[0].larg - 12);
      const h = Math.max(16, nomeLinhas.length * 10.5 + 6);
      if (y - h < MARGEM + 24) { novaPagina(); T.cabecalhoTabela(); }
      if (idx % 2) page.drawRectangle({ x: MARGEM, y: y - h, width: LARG, height: h, color: COR_ZEBRA });
      const base = y - 11;
      nomeLinhas.forEach((ln, k) => page.drawText(ln, { x: T.xs[0] + 6, y: base - k * 10.5, size: 8.5, font, color: COR_INK }));
      T.cel(1, l.nome || '— sem contrato —', base, l.numero ? COR_INK : COR_MUTED);
      T.cel(2, e.codigo || '-', base);
      T.cel(3, e.ca || '-', base);
      T.cel(4, e.caValidade ? isoBR(e.caValidade) : '-', base);
      T.cel(5, e.statusCa || 'Sem CA', base, e.statusCa === 'Vencido' ? COR_VERM : e.statusCa === 'Próximo do vencimento' ? COR_AMBAR : e.statusCa ? COR_VERDE : COR_MUTED);
      T.cel(6, String(l.estoque), base, l.semEstoque ? COR_VERM : l.abaixoMinimo ? COR_AMBAR : COR_INK);
      T.cel(7, String(e.estoqueMinimo || '-'), base, COR_MUTED);
      y -= h;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.4, color: COR_LINHA });
    });
  } else {
    await cabecalho('', 'RELATÓRIO DE EPI', `Movimentacoes - ${lista.length} registro(s) - emitido em ${new Date().toLocaleString('pt-BR')}`);
    const somaItens = (tipos) => lista.filter(m => tipos.includes(m.tipo))
      .reduce((t, m) => t + m.itens.reduce((s, i) => s + (Number(i.quantidade) || 0), 0), 0);
    const semAss = lista.filter(m => TIPOS_MOV_EPI_ASSINAVEL.has(m.tipo) && !(m.assinatura && m.assinatura.id)).length;
    const kpis = [
      { rotulo: 'Movimentacoes', valor: String(lista.length) },
      { rotulo: 'Itens entregues', valor: String(somaItens(['Entrega', 'Substituição'])) },
      { rotulo: 'Itens devolvidos', valor: String(somaItens(['Devolução'])) },
      { rotulo: 'Colaboradores', valor: String(new Set(lista.map(m => m.funcionarioNome).filter(Boolean)).size) },
      { rotulo: 'Sem assinatura', valor: String(semAss), cor: semAss ? COR_VERM : COR_VERDE },
    ];
    const gap = 9, w = (LARG - gap * (kpis.length - 1)) / kpis.length, hK = 44;
    kpis.forEach((it, i) => {
      const x = MARGEM + i * (w + gap);
      page.drawRectangle({ x, y: y - hK, width: w, height: hK, color: COR_BOX, borderColor: COR_LINHA, borderWidth: 1 });
      page.drawText(safe(it.rotulo.toUpperCase()), { x: x + 8, y: y - 15, size: 6.5, font: fontB, color: COR_MUTED });
      page.drawText(safe(it.valor), { x: x + 8, y: y - 33, size: 14, font: fontB, color: it.cor || COR_INK });
    });
    y -= hK + 14;
    const cols = [{ tit: 'DATA', larg: 48 }, { tit: 'TIPO', larg: 66 }, { tit: 'COLABORADOR', larg: 104 },
      { tit: 'EPIs', larg: 150 }, { tit: 'QTD', larg: 32, dir: true }, { tit: 'LANCADO POR', larg: 60 },
      { tit: 'ASSINATURA', larg: 51 }];
    const T = montarTabela(cols, '');
    for (let idx = 0; idx < lista.length; idx++) {
      const m = lista[idx];
      const itensTxt = m.itens.map(i => `${i.nome} (${i.quantidade} ${i.unidade})`).join('; ') || '-';
      const linhasItens = wrap(itensTxt, font, 8, cols[3].larg - 12);
      const nomeLinhas = wrap(m.funcionarioNome || (m.tipo === 'Entrada' ? 'Entrada de estoque' : '-'), font, 8, cols[2].larg - 12);
      const h = Math.max(30, linhasItens.length * 10, nomeLinhas.length * 10) + 8;
      if (y - h < MARGEM + 24) { novaPagina(); T.cabecalhoTabela(); }
      if (idx % 2) page.drawRectangle({ x: MARGEM, y: y - h, width: LARG, height: h, color: COR_ZEBRA });
      const base = y - 11;
      page.drawText(safe(isoBR(m.data)), { x: T.xs[0] + 6, y: base, size: 8, font, color: COR_INK });
      if (m.hora) page.drawText(safe(m.hora), { x: T.xs[0] + 6, y: base - 10, size: 7, font, color: COR_MUTED });
      T.cel(1, m.tipo, base, m.tipo === 'Entrada' ? COR_VERDE : m.tipo === 'Substituição' ? COR_AMBAR : COR_INK, 8);
      nomeLinhas.forEach((ln, k) => page.drawText(ln, { x: T.xs[2] + 6, y: base - k * 10, size: 8, font, color: COR_INK }));
      linhasItens.forEach((ln, k) => page.drawText(ln, { x: T.xs[3] + 6, y: base - k * 10, size: 8, font, color: COR_INK }));
      T.cel(4, String(m.itens.reduce((s, i) => s + (Number(i.quantidade) || 0), 0)), base, COR_INK, 8);
      T.cel(5, m.responsavelUsuario || m.responsavel || '-', base, COR_MUTED, 8);
      const img = await carregarImagem(m.assinatura);
      if (img) {
        const cw = cols[6].larg - 12, ch = h - 10;
        const escala = Math.min(cw / img.width, ch / img.height);
        page.drawImage(img, { x: T.xs[6] + 6, y: y - h + 5, width: img.width * escala, height: img.height * escala });
      } else {
        page.drawText(TIPOS_MOV_EPI_ASSINAVEL.has(m.tipo) ? 'sem assinatura' : 'nao se aplica',
          { x: T.xs[6] + 6, y: base, size: 7, font, color: TIPOS_MOV_EPI_ASSINAVEL.has(m.tipo) ? COR_VERM : COR_MUTED });
      }
      y -= h;
      page.drawLine({ start: { x: MARGEM, y }, end: { x: MARGEM + LARG, y }, thickness: 0.4, color: COR_LINHA });
    }
  }
  const paginas = doc.getPages();
  paginas.forEach((p, i) => {
    p.drawText(safe(`Gestao RM - Controle de EPI  |  pagina ${i + 1} de ${paginas.length}`),
      { x: MARGEM, y: 24, size: 7.5, font, color: COR_MUTED });
  });
  return Buffer.from(await doc.save());
}

