  if (!lista.length) return res.status(400).json({ erro: 'Nenhum EPI no filtro atual para gerar o relatório.' });
  lista = lista.slice().sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR'));
