// Cadastro de locação. Veículo (padrão) exige placa; equipamento/ferramental/outro exige só a
// descrição (`modelo`) e aceita `identificacao` opcional (nº de série, patrimônio, tag).
//
// USO:
//   POST /api/locacoes  { placa: 'QYF1D77', modelo: 'HILUX', dataChegada: '11/05/2025', valorInicial: 7000, contrato: '01' }
//   POST /api/locacoes  { tipo: 'ferramental', identificacao: 'PAT-0451', modelo: 'Ferramental de reisolamento',
//                         dataChegada: '01/09/2026', valorInicial: 'R$ 1.800,00', contrato: '01', polo: 'ARACAJU' }
//
// RESPOSTA (201): o registro normalizado — { id: 'loc-…', tipo: 'ferramental', placa: '', identificacao: 'PAT-0451',
//   modelo: 'Ferramental de reisolamento', valorInicial: 1800, … }
// ERROS (400): 'Informe a placa do veículo.' (veículo sem placa) · 'Informe a descrição do item locado.'
//   (outro tipo sem modelo) · 'Tipo de item inválido…' · 'Informe um valor mensal maior que zero.'
app.get('/api/locacoes', exigeVer('locacoes'), (req, res) => { res.set('Cache-Control', 'no-store'); res.json(lerLocacoes()); });
app.post('/api/locacoes', exigeEditar('locacoes'), rota(async (req, res) => {
  const lista = lerLocacoes();
  const novo = normalizarLocacao({ id: 'loc-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), ...req.body, ts: Date.now() });
  const erro = erroLocacao(req.body, novo);
  if (erro) return res.status(400).json({ erro });
  lista.push(novo);
  await salvarLocacoes(lista);
  await registrarHistorico([{ placa: identificadorLocacao(novo), acao: 'adicionou', texto: `Locação: ${rotuloLocacao(novo)}` }], quemFez(req));
  res.status(201).json(novo);
}));
// PUT /api/locacoes/:id — mesmas regras do POST; mandar { tipo: 'equipamento' } num veículo apaga a
// placa e os anos, e { tipo: 'veiculo' } num equipamento passa a exigir a placa no mesmo corpo.
app.put('/api/locacoes/:id', exigeEditar('locacoes'), rota(async (req, res) => {
  const lista = lerLocacoes(); const id = decodeURIComponent(req.params.id);
  const idx = lista.findIndex(l => l.id === id);
  if (idx === -1) return res.status(404).json({ erro: 'Locação não encontrada.' });
  const editada = normalizarLocacao({ ...lista[idx], ...req.body, id, ts: lista[idx].ts });
  const erro = erroLocacao(req.body, editada);
  if (erro) return res.status(400).json({ erro });
  lista[idx] = editada;
  await salvarLocacoes(lista);
  await registrarHistorico([{ placa: identificadorLocacao(editada), acao: 'editou', texto: `Locação: ${rotuloLocacao(editada)}` }], quemFez(req));
  res.json(lista[idx]);
}));
app.delete('/api/locacoes/:id', exigeEditar('locacoes'), rota(async (req, res) => {
  const lista = lerLocacoes(); const id = decodeURIComponent(req.params.id);
  const alvo = lista.find(l => l.id === id);
  const novos = lista.filter(l => l.id !== id);
  if (novos.length === lista.length) return res.status(404).json({ erro: 'Locação não encontrada.' });
  await salvarLocacoes(novos);
  await registrarHistorico([{ placa: alvo ? identificadorLocacao(alvo) : id, acao: 'excluiu', texto: `Locação: ${alvo ? rotuloLocacao(alvo) : id}` }], quemFez(req));
  res.json({ ok: true });
}));

function escHtml(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

