app.get('/api/senhas/categorias', exigeVer('senhas'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  const personalizadas = lerCategoriasSenhas();
  const usos = Object.fromEntries(personalizadas.map(c => [c, lerSenhas().filter(s => String(s.categoria || '').toLocaleLowerCase('pt-BR') === c.toLocaleLowerCase('pt-BR')).length]));
  res.json({ padrao: CATEGORIAS_SENHA_PADRAO, personalizadas, usos });
});
app.put('/api/senhas/categorias/:nome', exigeEditar('senhas'), rota(async (req, res) => {
  const antigo = decodeURIComponent(req.params.nome), novo = textoCofre(req.body && req.body.nome, 80);
  const categorias = lerCategoriasSenhas();
  const idx = categorias.findIndex(c => c.toLocaleLowerCase('pt-BR') === antigo.trim().toLocaleLowerCase('pt-BR'));
  if (idx < 0) return res.status(404).json({ erro: 'Categoria personalizada não encontrada.' });
  if (!novo || categoriaSenhaEhPadrao(novo) || novo.toLocaleLowerCase('pt-BR') === 'outro') return res.status(400).json({ erro: 'Informe um nome personalizado diferente das categorias padrão.' });
  if (categorias.some((c, i) => i !== idx && c.toLocaleLowerCase('pt-BR') === novo.toLocaleLowerCase('pt-BR'))) return res.status(409).json({ erro: 'Já existe uma categoria com esse nome.' });
  const senhas = lerSenhas().map(s => String(s.categoria || '').toLocaleLowerCase('pt-BR') === antigo.trim().toLocaleLowerCase('pt-BR') ? { ...s, categoria: novo, atualizadoEm: Date.now(), atualizadoPor: quemFez(req) } : s);
  categorias[idx] = novo;
  await persistirCofreSenhas(senhas, categorias);
  registrarSeguranca(req, 'cofre_categoria_renomeou', { categoria: 'auditoria', area: 'senhas', acao: 'editar', detalhes: `${antigo} → ${novo}` });
  res.json({ ok: true, nome: novo });
}));
app.delete('/api/senhas/categorias/:nome', exigeEditar('senhas'), rota(async (req, res) => {
  const nome = decodeURIComponent(req.params.nome), categorias = lerCategoriasSenhas();
  const existe = categorias.some(c => c.toLocaleLowerCase('pt-BR') === nome.trim().toLocaleLowerCase('pt-BR'));
  if (!existe) return res.status(404).json({ erro: 'Categoria personalizada não encontrada.' });
  let movidas = 0;
  const senhas = lerSenhas().map(s => {
    if (String(s.categoria || '').toLocaleLowerCase('pt-BR') !== nome.trim().toLocaleLowerCase('pt-BR')) return s;
    movidas++; return { ...s, categoria: 'Sem categoria', atualizadoEm: Date.now(), atualizadoPor: quemFez(req) };
  });
  await persistirCofreSenhas(senhas, categorias.filter(c => c.toLocaleLowerCase('pt-BR') !== nome.trim().toLocaleLowerCase('pt-BR')));
  registrarSeguranca(req, 'cofre_categoria_excluiu', { categoria: 'auditoria', area: 'senhas', acao: 'excluir', detalhes: `${nome}; ${movidas} credencial(is) movida(s)` });
  res.json({ ok: true, movidas });
}));
