app.post('/api/investimentos/importar-extratos', exigeEditar('investimentos'), uploadPdfLote.array('arquivos', 30), rota(async (req, res) => {
  const arquivos = Array.isArray(req.files) ? req.files : [];
  if (!arquivos.length) return res.status(400).json({ erro: 'Envie pelo menos um PDF de extrato do Banco Inter.' });
  const ruim = arquivos.find(f => !parecePDFBuffer(f.buffer));
  if (ruim) return res.status(400).json({ erro: `O arquivo "${String(ruim.originalname || 'sem nome').slice(0, 80)}" não parece ser um PDF válido.` });

  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frota-invest-'));
  const dirExtratos = path.join(tmpDir, 'extratos');
  const dirOutput = path.join(tmpDir, 'output');
  try {
    fs.mkdirSync(dirExtratos, { recursive: true });
    fs.mkdirSync(dirOutput, { recursive: true });
    arquivos.forEach((file, i) => {
      let nome = nomeArquivoSeguro(file.originalname || `extrato-${i + 1}.pdf`);
      if (!/\.pdf$/i.test(nome)) nome += '.pdf';
      fs.writeFileSync(path.join(dirExtratos, `${String(i + 1).padStart(2, '0')}-${nome}`), file.buffer);
    });

    const consolidado = await consolidarInvestimentosPorPDFs(dirExtratos, dirOutput);
    if (!consolidado || !consolidado.meta || !consolidado.meta.fonte_posicao) {
      return res.status(400).json({ erro: 'Inclua também o extrato de posição do Banco Inter. Ele é a foto da carteira atual e evita salvar uma carteira vazia.' });
    }
    const anterior = lerInvestimentos();
    let registro;
    try { registro = normalizarInvestimentos(consolidado, quemFez(req), anterior); }
    catch (e) { return res.status(400).json({ erro: e.message || 'Não consegui consolidar estes extratos.' }); }

    const confirmarAntigo = ['1', 'true', 'sim'].includes(String((req.body && req.body.confirmar_antigo) || '').toLowerCase());
    if (!confirmarAntigo && registro.data_base && anterior && anterior.data_base && registro.data_base <= anterior.data_base) {
      return res.status(409).json({
        erro: `A carteira atual é de ${anterior.data_base} e os extratos enviados geraram data-base ${registro.data_base}.`,
        precisaConfirmar: true,
        data_base: registro.data_base,
        atualBase: anterior.data_base,
      });
    }

    projetarAteHoje(registro);
    await salvarInvestimentos(registro);
    const cont = (registro.snapshot.meta.contagens) || {};
    await registrarHistorico([{ placa: '', acao: 'importou', texto:
      `Carteira de investimentos por PDFs (data-base ${registro.data_base}; ${cont.posicoes_abertas || 0} abertas; ${cont.pdfs_total || arquivos.length} PDF(s))` }], quemFez(req));
    res.json({
      ok: true,
      data_base: registro.data_base,
      importado_em: registro.importado_em,
      avisos: (registro.snapshot.meta && registro.snapshot.meta.avisos) || [],
      contagens: cont,
    });
  } catch (e) {
    const msg = e.erroUsuario || e.message || 'Não consegui processar os extratos.';
    const status = /Python|dependências|pdfplumber|servidor/i.test(msg) ? 500 : 400;
    res.status(status).json({ erro: msg });
  } finally {
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch (e) { /* ok */ }
  }
}));
// Define a taxa CDI anual (fração, ex.: 0.105 = 10,5% a.a.) usada na projeção diária.
