// Importa uma planilha de custos (.xlsx). Por padrão MESCLA por centro de custo: os contratos
// presentes na planilha são substituídos (dados frescos), os demais continuam. Assim dá para
// ter um arquivo por contrato (CUSTOS ATLAS, CUSTOS ORION, ...). `?modo=substituir` troca tudo.
app.post('/api/custos/importar', exigeEditar('custos'), uploadPlanilha.single('arquivo'), rota(async (req, res) => {
  if (!req.file) return res.status(400).json({ erro: 'Envie a planilha (.xlsx) de custos.' });
  let novo;
  try { novo = parseCustosPlanilha(req.file.buffer); }
  catch (e) { return res.status(400).json({ erro: e.message || 'Não consegui ler a planilha.' }); }
  if (!novo.lancamentos.length) return res.status(400).json({ erro: 'Nenhum lançamento encontrado na aba "CONTA AZUL - CUSTOS".' });

  const canon = (s) => String(s == null ? '' : s).trim().replace(/\s+/g, ' ').toUpperCase();
  const substituir = String((req.query && req.query.modo) || (req.body && req.body.modo) || '') === 'substituir';
  const arquivo = String((req.file.originalname || '').slice(0, 160));
  const agora = Date.now();
  const quem = quemFez(req) || 'local';

  const antigo = (!substituir && lerCustos()) || { lancamentos: [], recebimentos: [], porContrato: {} };
  const centrosNovos = new Set(novo.lancamentos.map(l => canon(l.centroCusto)));
  const contratosNovos = new Set(novo.recebimentos.map(r => canon(r.contrato)));
  // mescla: remove os centros/contratos presentes nesta planilha e junta os novos
  const lancamentos = (antigo.lancamentos || []).filter(l => !centrosNovos.has(canon(l.centroCusto))).concat(novo.lancamentos);
  const recebimentos = (antigo.recebimentos || []).filter(r => !contratosNovos.has(canon(r.contrato))).concat(novo.recebimentos);

  // metadados por contrato (quando cada um foi importado, de qual arquivo)
  const porContrato = Object.assign({}, antigo.porContrato || {});
  for (const c of centrosNovos) {
    const nome = (novo.lancamentos.find(l => canon(l.centroCusto) === c) || {}).centroCusto || c;
    porContrato[c] = { nome, importadoEm: agora, importadoPor: quem, arquivo, lancamentos: novo.lancamentos.filter(l => canon(l.centroCusto) === c).length };
  }
  const datas = lancamentos.map(l => l.data).filter(Boolean).sort();
  const dados = {
    lancamentos, recebimentos, porContrato,
    meta: { periodoDe: datas[0] || '', periodoAte: datas[datas.length - 1] || '', totalLancamentos: lancamentos.length, contratos: Object.values(porContrato).map(x => x.nome) },
    importadoEm: agora, importadoPor: quem, arquivo,
  };
  await salvarCustos(dados);
  const nomesImportados = [...centrosNovos].map(c => porContrato[c].nome).join(', ');
  await registrarHistorico([{ acao: 'importou custos', texto: `Custos importados (${substituir ? 'substituição' : 'mesclagem'}); contrato(s): ${nomesImportados} · ${novo.lancamentos.length} lançamento(s)` }], quem);
  res.json({ ok: true, modo: substituir ? 'substituir' : 'mesclar', contratos: [...centrosNovos].map(c => porContrato[c].nome), lancamentosImportados: novo.lancamentos.length, recebimentosImportados: novo.recebimentos.length, totalLancamentos: lancamentos.length, periodoDe: dados.meta.periodoDe, periodoAte: dados.meta.periodoAte });
}));
