// ----- Equipe (folha fixa calculada dos salários + horas extras) -----
// Mês no formato 'yyyy-mm' (compara certo como texto). Helpers de calendário:
function mesAnteriorStr(m) { let [a, mm] = m.split('-').map(Number); mm--; if (mm < 1) { mm = 12; a--; } return `${a}-${String(mm).padStart(2, '0')}`; }
function proximoMesStr(m) { let [a, mm] = m.split('-').map(Number); mm++; if (mm > 12) { mm = 1; a++; } return `${a}-${String(mm).padStart(2, '0')}`; }
// Salário vigente no mês: última vigência com desde <= mês (0 se nenhuma começou ainda).
function salarioNoMes(f, m) {
  let v = 0;
  for (const vig of (f.salarios || [])) { if (vig.desde <= m) v = vig.valor; else break; }
  return v;
}
// Conta no mês se foi admitido até o fim dele e ainda não estava desligado antes dele.
// SEM proporcionalidade por dia (v1): o alvo de conciliação (razão do Conta Azul) é mensal.
// Afastado/Férias continuam contando (seguem na folha); só Desligado com data corta a série.
function funcAtivoNoMes(f, m, mesAtual) {
  const adm = String(f.admissao || '').slice(0, 7);
  const dem = String(f.dataDemissao || '').slice(0, 7);
  if (adm && adm > m) return false;
  if (dem && dem < m) return false;
  if (!dem && f.status === 'Desligado') return m < mesAtual; // desligado sem data: para de contar no mês corrente
  return true;
}
// Agregado por contrato/mês — NUNCA sai salário individual daqui (por isso o endpoint fica sob a
// permissão 'custos'). Lê lerFuncionarios() SEM filtrarFunc: o recorte por empresa/contrato do
// módulo Funcionários é ignorado de propósito, porque só agregados são expostos. Registros de
// teste (soDev) só entram para quem é dev (mesma regra de visibilidade da lista de Funcionários).
app.get('/api/custos/equipe', exigeVer('custos'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  const dev = ehNivelDev(usuarioAtual(req));
  const canon = (s) => canonizarCentroCusto(s).replace(/\s+/g, ' ').trim().toUpperCase();
  const d = new Date();
  const mesAtual = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;

  const funcs = lerFuncionarios().filter(f => dev || !f.soDev);
  const horasExtras = lerHorasExtras(); // inclui competências futuras (lançamento antecipado aparece na tabela)

  // Faixa de meses: da vigência/HE mais antiga (no mínimo 12 meses) até o mês atual — com teto de
  // 10 anos para um "desde" digitado errado não gerar uma lista gigante.
  let inicio = mesAtual;
  for (let i = 0; i < 11; i++) inicio = mesAnteriorStr(inicio);
  for (const f of funcs) for (const vig of (f.salarios || [])) if (vig.desde && vig.desde < inicio) inicio = vig.desde;
  for (const h of horasExtras) if (h.competencia && h.competencia < inicio) inicio = h.competencia;
  let fim = mesAtual;
  for (const h of horasExtras) if (h.competencia && h.competencia > fim) fim = h.competencia;
  const meses = [];
  for (let m = inicio; m <= fim && meses.length < 120; m = proximoMesStr(m)) meses.push(m);

  const nomes = new Map();      // chave canônica → nome de exibição
  const folhaMap = new Map();   // chave → { 'yyyy-mm': soma dos salários }
  const headMap = new Map();    // chave → { 'yyyy-mm': nº de ativos }
  let semSalario = 0;           // ativos hoje sem nenhuma vigência de salário (alimenta o aviso da tela)
  for (const f of funcs) {
    const aloc = String(f.centroCusto || f.contratoNome || '').trim();
    const chave = aloc ? canon(aloc) : 'SEM CONTRATO';
    if (!nomes.has(chave)) nomes.set(chave, aloc ? canonizarCentroCusto(aloc) : 'Sem contrato');
    const temSalario = (f.salarios || []).length > 0;
    if (!temSalario && funcAtivoNoMes(f, mesAtual, mesAtual)) semSalario++;
    for (const m of meses) {
      if (m > mesAtual) continue;                 // folha/headcount não projetam o futuro
      if (!funcAtivoNoMes(f, m, mesAtual)) continue;
      const head = headMap.get(chave) || {}; head[m] = (head[m] || 0) + 1; headMap.set(chave, head);
      const v = salarioNoMes(f, m);
      if (v > 0) { const fol = folhaMap.get(chave) || {}; fol[m] = (fol[m] || 0) + v; folhaMap.set(chave, fol); }
    }
  }
  res.json({
    meses,
    mesAtual,
    folha: [...folhaMap.entries()].map(([chave, porMes]) => ({ centroCusto: nomes.get(chave) || chave, porMes })),
    headcount: [...headMap.entries()].map(([chave, porMes]) => ({ centroCusto: nomes.get(chave) || chave, porMes })),
    semSalario,
    horasExtras,
    geradoEm: Date.now(),
  });
});
// Upsert em lote por (competência, contrato): valor > 0 grava/atualiza, valor 0 (ou vazio) remove.
app.post('/api/custos/horas-extras', exigeEditar('custos'), rota(async (req, res) => {
  const itens = Array.isArray(req.body && req.body.itens) ? req.body.itens : [];
  if (!itens.length) return res.status(400).json({ erro: 'Envie os lançamentos de horas extras.' });
  const canon = (s) => String(s == null ? '' : s).trim().replace(/\s+/g, ' ').toUpperCase();
  const quem = quemFez(req) || 'local';
  const agora = Date.now();
  const lista = lerHorasExtras().slice();
  let gravados = 0, removidos = 0;
  const competencias = new Set();
  for (const item of itens) {
    const n = normalizarHoraExtra(Object.assign({}, item, { id: '', quem, atualizadoEm: agora }));
    if (!n.competencia || !n.centroCusto) continue;
    const idx = lista.findIndex(h => h.competencia === n.competencia && canon(h.centroCusto) === canon(n.centroCusto));
    if (n.valor > 0) {
      if (idx >= 0) lista[idx] = Object.assign({}, lista[idx], { centroCusto: n.centroCusto, valor: n.valor, obs: n.obs, quem, atualizadoEm: agora });
      else lista.push(n);
      gravados++; competencias.add(n.competencia);
    } else if (idx >= 0) { lista.splice(idx, 1); removidos++; competencias.add(n.competencia); }
  }
  if (!gravados && !removidos) return res.status(400).json({ erro: 'Nenhum lançamento válido (informe competência, contrato e valor).' });
  const salvas = await salvarHorasExtras(lista);
  await registrarHistorico([{ acao: 'editou', texto: `Horas extras ${[...competencias].sort().join(', ')} · ${gravados} lançamento(s)${removidos ? `, ${removidos} removido(s)` : ''}` }], quem);
  res.json({ ok: true, total: salvas.length, gravados, removidos });
}));
app.delete('/api/custos/horas-extras/:id', exigeEditar('custos'), rota(async (req, res) => {
  const lista = lerHorasExtras().slice();
  const idx = lista.findIndex(h => h.id === req.params.id);
  if (idx < 0) return res.status(404).json({ erro: 'Lançamento não encontrado.' });
  const rem = lista.splice(idx, 1)[0];
  await salvarHorasExtras(lista);
  await registrarHistorico([{ acao: 'excluiu', texto: `Horas extras removidas · ${rem.centroCusto} ${rem.competencia}` }], quemFez(req) || 'local');
  res.json({ ok: true });
}));

