function numeroPlanilha(v) {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').trim();
  if (!s) return 0;
  const limpo = s.replace(/[R$\s%]/g, '');
  if (limpo.includes(',')) return Number(limpo.replace(/\./g, '').replace(',', '.')) || 0;
  return Number(limpo) || 0;
}
function textoPlanilha(v) { return String(v ?? '').trim(); }
function dataPlanilha(v) { return serialExcelParaBR(v); }
function dataBRValida(v) {
  const m = String(v || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!m) return false;
  const d = Number(m[1]), mo = Number(m[2]), a = Number(m[3]);
  const dt = new Date(a, mo - 1, d);
  return dt.getFullYear() === a && dt.getMonth() === mo - 1 && dt.getDate() === d;
}
function anoDataBR(v) {
  const m = String(v || '').trim().match(/^\d{2}\/\d{2}\/(\d{4})$/);
  return m ? Number(m[1]) : 0;
}
function dataControlePlausivel(v) {
  return dataBRValida(v) && anoDataBR(v) >= 2020;
}
function textoPareceDinheiro(v) {
  return /^R\$/i.test(String(v || '').trim());
}
function taxaJurosPlanilha(v) {
  const n = numeroPlanilha(v);
  if (!Number.isFinite(n) || n <= 0) return 0;
  if (n <= 0.02) return n; // fração diária já pronta (ex.: 0,000416667)
  if (n <= 100) return n / 100 / 30; // porcentagem mensal (ex.: 1,25%)
  return 0; // serial de data ou lixo de planilha nunca pode virar taxa
}
function corrigirMojibakeTexto(s) {
  const txt = String(s || '');
  if (!/[ÃÂ�]/.test(txt)) return txt;
  try {
    const corrigido = Buffer.from(txt, 'latin1').toString('utf8');
    return corrigido.includes('\uFFFD') ? txt : corrigido;
  } catch (e) {
    return txt;
  }
}
function nomeBasePlanilha(nome) {
  const nomeLimpo = corrigirMojibakeTexto(nome);
  return path.basename(String(nomeLimpo || ''), path.extname(String(nomeLimpo || '')))
    .replace(/^CONTROLE\s+/i, '')
    .replace(/\bAPORTES\b/ig, '')
    .replace(/\bPERCENTUAIS\b/ig, '')
    .replace(/\bJUROS\b/ig, '')
    .replace(/\s*-\s*/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();
}
function linhasDaAba(wb, aba) {
  return XLSX.utils.sheet_to_json(wb.Sheets[aba], { header: 1, defval: '', raw: true });
}
function cabecalhoEm(row) {
  const mapa = {};
  (row || []).forEach((v, i) => {
    const k = normalizarChave(v);
    if (k && mapa[k] === undefined) mapa[k] = i;
  });
  return mapa;
}
function col(mapa, nomes) {
  for (const n of nomes) {
    const k = normalizarChave(n);
    if (mapa[k] !== undefined) return mapa[k];
  }
  return -1;
}
function valorLinha(row, idx) { return idx >= 0 ? row[idx] : ''; }
function importarModelo(rows, colunas, normalizar, valida, exigidos = []) {
  const out = [];
  const porCabecalho = {};
  for (const [campo, rotulo] of colunas) porCabecalho[normalizarChave(rotulo)] = campo;
  porCabecalho[normalizarChave('DATA QUITACAO')] = 'dataQuitacao';
  porCabecalho[normalizarChave('DATA DE PAGAMENTO')] = 'dataPagamento';
  porCabecalho[normalizarChave('DATA PAGAMENTO')] = 'dataPagamento';
  porCabecalho[normalizarChave('OBS')] = 'obs';
  porCabecalho[normalizarChave('OBS.')] = 'obs';
  porCabecalho[normalizarChave('OBSERVACOES')] = 'obs';
  const numericos = new Set(['valor', 'marcelo', 'ricardo', 'fernando', 'tiago', 'taxaJuros', 'valorPago', 'faturamento']);
  const datas = new Set(['data', 'dataQuitacao', 'dataPagamento']);
  const exigidosNorm = exigidos.map(normalizarChave);
  const cabIdx = rows.findIndex(r => {
    const chaves = new Set((r || []).map(normalizarChave).filter(Boolean));
    if (exigidosNorm.length) return exigidosNorm.every(k => chaves.has(k));
    return (r || []).filter(c => porCabecalho[normalizarChave(c)]).length >= 3;
  });
  if (cabIdx < 0) return out;
  const header = rows[cabIdx] || [];
  for (const row of rows.slice(cabIdx + 1)) {
    const dados = {};
    header.forEach((h, i) => {
      const campo = porCabecalho[normalizarChave(h)];
      if (!campo) return;
      const v = row[i];
      dados[campo] = datas.has(campo) ? dataPlanilha(v) : (numericos.has(campo) ? numeroPlanilha(v) : textoPlanilha(v));
    });
    const norm = normalizar(dados);
    if (valida(norm)) out.push(norm);
  }
  return out;
}
function aporteValidoImportacao(a) {
  return !!(a && dataBRValida(a.data) && Number(a.valor) > 0);
}
function limparAportesInvalidos(lista) {
  let removidos = 0, taxasCorrigidas = 0, quitacoesCorrigidas = 0;
  const limpos = [];
  for (const item of lista || []) {
    const a = normalizarAporte(item);
    if (!dataControlePlausivel(a.data) || Number(a.valor) <= 0) { removidos++; continue; }
    if (a.dataQuitacao && !dataControlePlausivel(a.dataQuitacao)) {
      a.dataQuitacao = '';
      quitacoesCorrigidas++;
    }
    if ((Number(item && item.taxaJuros) || 0) !== a.taxaJuros) taxasCorrigidas++;
    limpos.push(a);
  }
  return { lista: limpos, removidos, taxasCorrigidas, quitacoesCorrigidas };
}
function montarAporteImportado({ data, grupo, contrato, valor, marcelo, ricardo, fernando, tiago, taxaJuros, dataQuitacao, obs }) {
  return normalizarAporte({
    data,
    grupo,
    contrato,
    valor,
    marcelo,
    ricardo,
    fernando,
    tiago,
    taxaJuros: taxaJurosPlanilha(taxaJuros),
    dataQuitacao: dataControlePlausivel(dataQuitacao) ? dataQuitacao : '',
    obs,
  });
}
function chaveAporte(a) {
  return [
    normalizarChave(a.data),
    normalizarChave(a.grupo),
    normalizarChave(a.contrato),
    String(Number(a.valor) || 0),
  ].join('|');
}
function socioCampo(v) {
  const k = normalizarChave(v);
  if (k.includes('MARCELO')) return 'marcelo';
  if (k.includes('RICARDO')) return 'ricardo';
  if (k.includes('FERNANDO')) return 'fernando';
  if (k.includes('TIAGO')) return 'tiago';
  return '';
}
function parseAportesPlanilha(file) {
  const wb = XLSX.read(file.buffer, { type: 'buffer', cellDates: false });
  const candidatos = [];
  const grupoArquivo = nomeBasePlanilha(file.originalname);
  for (const aba of wb.SheetNames) {
    const rows = linhasDaAba(wb, aba);
    candidatos.push(...importarModelo(rows, COLS_APORTE, normalizarAporte, aporteValidoImportacao, ['GRUPO', 'VALOR']));
    const nomeAba = normalizarChave(aba);
    if (nomeAba.includes('HISTORICO') || nomeAba.includes('PAGTO JUROS')) continue;
    for (let ri = 0; ri < rows.length; ri++) {
      const row = rows[ri] || [];
      const mapa = cabecalhoEm(row);
      const isSocios = col(mapa, ['DATA']) >= 0 && col(mapa, ['VALOR']) >= 0 && col(mapa, ['SOCIO', 'SÓCIO']) >= 0;
      if (isSocios && nomeAba.includes('APORTE SOCIOS') && nomeAba.includes('CORRETA')) {
        const iData = col(mapa, ['DATA']);
        const iValor = col(mapa, ['VALOR']);
        const iSocio = col(mapa, ['SOCIO', 'SÓCIO']);
        const iObs = col(mapa, ['OBS', 'OBS.']);
        const agrupados = new Map();
        for (const r of rows.slice(ri + 1)) {
          const data = dataPlanilha(valorLinha(r, iData));
          const valor = numeroPlanilha(valorLinha(r, iValor));
          const campo = socioCampo(valorLinha(r, iSocio));
          if (!dataBRValida(data) || !valor || !campo) continue;
          const obs = textoPlanilha(valorLinha(r, iObs));
          const key = [data, obs].join('|');
          if (!agrupados.has(key)) agrupados.set(key, normalizarAporte({ data, grupo: grupoArquivo || 'OBRAS RM', contrato: grupoArquivo || 'OBRAS RM', obs }));
          const a = agrupados.get(key);
          a[campo] = (Number(a[campo]) || 0) + valor;
          a.valor = (Number(a.valor) || 0) + valor;
        }
        candidatos.push(...agrupados.values());
      }
    }
    const cab0 = cabecalhoEm(rows[0] || []);
    const iData1 = col(cab0, ['DATA']);
    const iContrato1 = col(cab0, ['CONTRATO']);
    const iValor1 = col(cab0, ['VALOR', 'APORTE']);
    const iJer1 = col(cab0, ['RICARDO']);
    const iDoug1 = col(cab0, ['MARCELO']);
    const iAlb1 = col(cab0, ['FERNANDO']);
    const iRan1 = col(cab0, ['TIAGO']);
    const iJuros1 = col(cab0, ['JUROS', 'TAXA JUROS']);
    const iQuit1 = col(cab0, ['DATA PAGAMENTO', 'DATA DE PAGAMENTO', 'PAGAMENTO', 'DATA QUITACAO', 'DATA QUITAÇÃO']);
    if (iData1 >= 0 && iValor1 >= 0) {
      for (const row of rows.slice(1)) {
        const data = dataPlanilha(valorLinha(row, iData1));
        const valor = numeroPlanilha(valorLinha(row, iValor1));
        if (!dataBRValida(data) || !valor) continue;
        candidatos.push(montarAporteImportado({
          data,
          grupo: grupoArquivo || textoPlanilha(aba),
          contrato: textoPlanilha(valorLinha(row, iContrato1)) || grupoArquivo || textoPlanilha(aba),
          valor,
          ricardo: numeroPlanilha(valorLinha(row, iJer1)),
          marcelo: numeroPlanilha(valorLinha(row, iDoug1)),
          fernando: numeroPlanilha(valorLinha(row, iAlb1)),
          tiago: numeroPlanilha(valorLinha(row, iRan1)),
          taxaJuros: valorLinha(row, iJuros1),
          dataQuitacao: dataPlanilha(valorLinha(row, iQuit1)),
          obs: textoPlanilha(aba),
        }));
      }
    }
    for (let ci = 1; ci < (rows[0] || []).length; ci++) {
      const h = rows[0] || [];
      if (normalizarChave(h[ci]) !== 'DATA' || normalizarChave(h[ci + 1]) !== 'CONTRATO') continue;
      for (const row of rows.slice(1)) {
        const data = dataPlanilha(row[ci]);
        const valor = numeroPlanilha(row[ci + 2]);
        if (!dataBRValida(data) || !valor) continue;
        candidatos.push(montarAporteImportado({
          data,
          grupo: grupoArquivo || textoPlanilha(aba),
          contrato: textoPlanilha(row[ci + 1]) || grupoArquivo || textoPlanilha(aba),
          valor,
          ricardo: numeroPlanilha(row[ci + 3]),
          marcelo: numeroPlanilha(row[ci + 4]),
          dataQuitacao: dataPlanilha(row[ci + 5]),
          taxaJuros: row[ci + 7],
          obs: 'Importado da tabela de quitados',
        }));
      }
    }
    if (iData1 < 0) for (const row of rows.slice(1)) {
      const d1 = dataPlanilha(row[0]);
      const v1 = numeroPlanilha(row[2]);
      if (dataBRValida(d1) && v1) candidatos.push(montarAporteImportado({
        data: d1,
        grupo: grupoArquivo || textoPlanilha(aba),
        contrato: textoPlanilha(row[1]) || grupoArquivo || textoPlanilha(aba),
        valor: v1,
        ricardo: numeroPlanilha(row[3]),
        marcelo: numeroPlanilha(row[4]),
        fernando: numeroPlanilha(row[5]),
        taxaJuros: row[7],
        dataQuitacao: dataPlanilha(row[8]) || dataPlanilha(row[7]),
        obs: textoPlanilha(row[10]),
      }));
      const d2 = dataPlanilha(row[11]);
      const v2 = numeroPlanilha(row[13]);
      if (dataBRValida(d2) && v2) candidatos.push(montarAporteImportado({
        data: d2,
        grupo: grupoArquivo || textoPlanilha(aba),
        contrato: textoPlanilha(row[12]) || grupoArquivo || textoPlanilha(aba),
        valor: v2,
        ricardo: numeroPlanilha(row[14]),
        marcelo: numeroPlanilha(row[15]),
        dataQuitacao: dataPlanilha(row[16]),
        taxaJuros: row[18],
        obs: 'Importado da tabela de quitados',
      }));
    }
  }
  return candidatos.filter(aporteValidoImportacao);
}
app.post('/api/aportes/importar', exigeEditar('controles'), uploadPlanilha.array('arquivos', 30), rota(async (req, res) => {
  const files = req.files || [];
  if (!files.length) return res.status(400).json({ erro: 'Nenhum arquivo enviado.' });
  let candidatos = [];
  try {
    for (const file of files) candidatos.push(...parseAportesPlanilha(file));
  } catch (e) { return res.status(400).json({ erro: 'Não consegui ler a planilha.' }); }
  const candidatosUnicos = new Map();
  for (const norm of candidatos) {
    if (aporteValidoImportacao(norm)) candidatosUnicos.set(chaveAporte(norm), norm);
  }
  candidatos = [...candidatosUnicos.values()];
  let lista = lerAportes();
  const limpeza = limparAportesInvalidos(lista);
  lista = limpeza.lista;
  const idxPorChave = {};
  lista.forEach((a, i) => { idxPorChave[chaveAporte(a)] = i; });
  let criados = 0, atualizados = 0, ignorados = 0;
  for (const norm of candidatos) {
    if (!norm.data || !norm.valor) { ignorados++; continue; }
    const k = chaveAporte(norm);
    if (idxPorChave[k] !== undefined) {
      const i = idxPorChave[k];
      norm.id = lista[i].id; norm.ts = lista[i].ts;
      lista[i] = norm; atualizados++;
    } else {
      lista.push(norm); idxPorChave[k] = lista.length - 1; criados++;
    }
  }
  if (!criados && !atualizados) return res.status(400).json({ erro: 'Nenhuma linha válida encontrada (confira o cabeçalho: DATA, GRUPO, CONTRATO, VALOR).' });
  await salvarAportes(lista);
  await registrarHistorico([{ placa: '', acao: 'importou', texto: `Aportes importados: ${criados} novo(s), ${atualizados} atualizado(s)` }], quemFez(req));
  res.json({ ok: true, criados, atualizados, ignorados, removidosInvalidos: limpeza.removidos, taxasCorrigidas: limpeza.taxasCorrigidas, quitacoesCorrigidas: limpeza.quitacoesCorrigidas, arquivos: files.length });
}));

