// ===================== PERCENTUAIS (distribuição de lucro por NF) =====================
function chaveEmprestimo(e) {
  return [normalizarChave(e.data), normalizarChave(e.origem), normalizarChave(e.destino), String(Number(e.valor) || 0)].join('|');
}
function emprestimoValidoImportacao(e) {
  return !!(e && dataBRValida(e.data) && Number(e.valor) > 0);
}
function parseEmprestimosPlanilha(file) {
  const wb = XLSX.read(file.buffer, { type: 'buffer', cellDates: false });
  const candidatos = [];
  for (const aba of wb.SheetNames) {
    const rows = linhasDaAba(wb, aba);
    candidatos.push(...importarModelo(rows, COLS_EMPRESTIMO, normalizarEmprestimo, emprestimoValidoImportacao, ['DATA', 'VALOR']));
    for (let ri = 0; ri < rows.length; ri++) {
      const mapa = cabecalhoEm(rows[ri] || []);
      const iData = col(mapa, ['DATA/EMPRÉSTIMO', 'DATA DO EMPRÉSTIMO', 'DATA DO EMPRESTIMO']);
      const iValor = col(mapa, ['VALOR EMPRESTADO', 'VALOR']);
      const iOrigem = col(mapa, ['QUEM EMPRESTOU']);
      const iDestino = col(mapa, ['QUEM RECEBEU']);
      if (iData < 0 || iValor < 0 || iOrigem < 0) continue;
      const iPago = col(mapa, ['VALOR PAGO DO EMPRÉSTIMO', 'VALOR PAGO DO EMPRESTIMO', 'VALOR PAGO']);
      const iDataPgto = col(mapa, ['DATA DE PAGAMENTO', 'DATA PAGAMENTO', 'DT PGTO EMPRÉSTIMO', 'DT DO PAGTO', 'DT PGTO EMPRESTIMO']);
      for (const r of rows.slice(ri + 1)) {
        const data = dataPlanilha(valorLinha(r, iData));
        const valor = numeroPlanilha(valorLinha(r, iValor));
        const origem = textoPlanilha(valorLinha(r, iOrigem));
        const destino = textoPlanilha(valorLinha(r, iDestino));
        if (!dataBRValida(data) || !valor || !origem) continue;
        candidatos.push(normalizarEmprestimo({
          data, valor, origem, destino,
          valorPago: numeroPlanilha(valorLinha(r, iPago)),
          dataPagamento: dataPlanilha(valorLinha(r, iDataPgto)),
          obs: textoPlanilha(aba),
        }));
      }
      break;
    }
  }
  return candidatos.filter(emprestimoValidoImportacao);
}
