// ===================== RETIRADAS (sócios: lucro / devolução de capital) =====================
function chavePercentual(p) {
  return [normalizarChave(p.nf), normalizarChave(p.data), String(Number(p.faturamento) || 0)].join('|');
}
function percentualValidoImportacao(p) {
  const nf = String((p && p.nf) || '').trim();
  const data = String((p && p.data) || '').trim();
  if (!p || Number(p.faturamento) <= 0) return false;
  if (textoPareceDinheiro(nf)) return false;
  if (data && !dataBRValida(data)) return false;
  return !!(nf || data);
}
function parsePercentuaisPlanilha(file) {
  const wb = XLSX.read(file.buffer, { type: 'buffer', cellDates: false });
  const candidatos = [];
  for (const aba of wb.SheetNames) {
    const rows = linhasDaAba(wb, aba);
    candidatos.push(...importarModelo(rows, COLS_PERCENTUAL, normalizarPercentual, percentualValidoImportacao, ['NF', 'FATURAMENTO']));
    for (let ri = 0; ri < rows.length; ri++) {
      const mapa = cabecalhoEm(rows[ri] || []);
      const iNf = col(mapa, ['Nº DA NOTA FISCAL ELETRÔNICA', 'N DA NOTA FISCAL ELETRONICA', 'NF']);
      const iData = col(mapa, ['DATA DA EMISSÃO NFS-E/DSR-E', 'DATA DA EMISSAO NFS-E/DSR-E', 'DATA']);
      const iCidade = col(mapa, ['CIDADE DO TOMADOR', 'CIDADE']);
      const iFat = col(mapa, ['FATURAMENTO']);
      if (iFat < 0 || (iNf < 0 && iData < 0)) continue;
      const iJer = col(mapa, ['SÓCIO RICARDO 1%', 'SOCIO RICARDO 1%']);
      const iAdm2 = col(mapa, ['ADM  2%', 'ADM 2%']);
      const iAdm4 = col(mapa, ['ADM 4%']);
      const iAdm4Fixo = col(mapa, ['ADM 4% + R$2.500', 'ADM 4% + R$2500']);
      const iDoug1 = col(mapa, ['SÓCIO MARCELO  1%', 'SOCIO MARCELO 1%', 'SÓCIO MARCELO 1%']);
      const iDoug2 = col(mapa, ['MARCELO 2%']);
      const iAlb = col(mapa, ['FERNANDO 1%', 'FERNANDO']);
      for (const r of rows.slice(ri + 1)) {
        const faturamento = numeroPlanilha(valorLinha(r, iFat));
        const nf = textoPlanilha(valorLinha(r, iNf));
        const data = dataPlanilha(valorLinha(r, iData));
        if (!percentualValidoImportacao({ nf, data, faturamento })) continue;
        candidatos.push(normalizarPercentual({
          nf,
          data,
          cidade: textoPlanilha(valorLinha(r, iCidade)),
          faturamento,
          ricardo: numeroPlanilha(valorLinha(r, iJer)) + numeroPlanilha(valorLinha(r, iAdm2)) + numeroPlanilha(valorLinha(r, iAdm4)) + numeroPlanilha(valorLinha(r, iAdm4Fixo)),
          marcelo: numeroPlanilha(valorLinha(r, iDoug1)) + numeroPlanilha(valorLinha(r, iDoug2)),
          fernando: numeroPlanilha(valorLinha(r, iAlb)),
          obs: textoPlanilha(aba),
        }));
      }
      break;
    }
  }
  return candidatos.filter(percentualValidoImportacao);
}
