// Aprova um pedido de cadastro (somente admin).
app.post('/api/usuarios/:usuario/aprovar', exigeAdmin, rota(async (req, res) => {
  const store = lerUsuarios();
  const u = store.usuarios.find(x => x.usuario === normalizaUsuario(req.params.usuario));
  if (!u) return res.status(404).json({ erro: 'Usuário não encontrado.' });
  if (u.senhaEnv) return res.status(400).json({ erro: 'O admin mestre já está ativo.' });
  u.status = 'aprovado'; u.aprovadoEm = Date.now();
  // Garante que ninguém seja aprovado com acesso total por padrão: se ainda não tem
  // permissões definidas (cadastros antigos, anteriores a esta regra), começa SEM acesso
  // a nenhuma aba — o admin libera depois. Quem já tem permissões definidas é preservado.
  if (!u.permissoes || !Object.keys(u.permissoes).length) u.permissoes = permissoesIniciais();
  await salvarUsuarios(store);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Cadastro aprovado: ${u.nome}` }], req.usuario.nome);
  registrarSeguranca(req, 'usuario_aprovado', { categoria: 'usuarios', severidade: 'aviso', acao: 'aprovar', usuarioAlvo: u.usuario });
  notificarAdmins('atualizar-usuarios', { motivo: 'aprovado' });
  res.json({ ok: true });
}));

