// Remove um usuário (somente admin) — não dá para remover o admin mestre.
app.delete('/api/usuarios/:usuario', exigeAdmin, rota(async (req, res) => {
  const store = lerUsuarios();
  const alvo = normalizaUsuario(req.params.usuario);
  const u = store.usuarios.find(x => x.usuario === alvo);
  if (!u) return res.status(404).json({ erro: 'Usuário não encontrado.' });
  if (u.senhaEnv) return res.status(400).json({ erro: 'O admin mestre não pode ser removido.' });
  store.usuarios = store.usuarios.filter(x => x.usuario !== alvo);
  await salvarUsuarios(store);
  await registrarHistorico([{ placa: '', acao: 'excluiu', texto: `Usuário removido: ${u.nome}` }], req.usuario.nome);
  registrarSeguranca(req, 'usuario_excluido', { categoria: 'usuarios', severidade: 'alerta', acao: 'excluir', usuarioAlvo: u.usuario });
  notificarAdmins('atualizar-usuarios', { motivo: 'removido' });
  notificarUsuario(u.usuario, 'sessao-encerrada', {}); // se estiver logado, será deslogado
  res.json({ ok: true });
}));

// Redefine a senha de um usuário (somente admin). A senha antiga é irrecuperável
// (hash); aqui apenas gravamos um novo hash. Isso também desloga sessões antigas
// daquele usuário (o token de sessão depende do hash da senha).
app.post('/api/usuarios/:usuario/senha', exigeAdmin, rota(async (req, res) => {
  const store = lerUsuarios();
  const u = store.usuarios.find(x => x.usuario === normalizaUsuario(req.params.usuario));
  if (!u) return res.status(404).json({ erro: 'Usuário não encontrado.' });
  if (u.senhaEnv) return res.status(400).json({ erro: 'A senha do admin é definida pela variável de ambiente SENHA_ADMIN.' });
  const senha = String((req.body && req.body.senha) || '');
  if (senha.length < 4) return res.status(400).json({ erro: 'A senha precisa ter pelo menos 4 caracteres.' });
  if (senha.length > 60) return res.status(400).json({ erro: 'A senha pode ter no máximo 60 caracteres.' });
  const h = hashSenha(senha);
  u.salt = h.salt; u.senhaHash = h.hash;
  await salvarUsuarios(store);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Senha redefinida: ${u.nome}` }], req.usuario.nome);
  registrarSeguranca(req, 'senha_redefinida', { categoria: 'usuarios', severidade: 'alerta', acao: 'redefinir_senha', usuarioAlvo: u.usuario });
  notificarUsuario(u.usuario, 'sessao-encerrada', {}); // a senha mudou: sessões antigas caem
  res.json({ ok: true });
}));

// Promove/rebaixa um usuário (admin <-> comum) — somente admin.
app.post('/api/usuarios/:usuario/nivel', exigeAdmin, rota(async (req, res) => {
  const store = lerUsuarios();
  const u = store.usuarios.find(x => x.usuario === normalizaUsuario(req.params.usuario));
  if (!u) return res.status(404).json({ erro: 'Usuário não encontrado.' });
  if (u.senhaEnv) return res.status(400).json({ erro: 'O admin mestre não muda de nível.' });
  if (u.status !== 'aprovado') return res.status(400).json({ erro: 'Aprove o usuário antes de mudar o nível.' });
  const pedido = (req.body && req.body.nivel);
  const nivel = (pedido === 'admin' || pedido === 'dev') ? pedido : 'comum';
  u.nivel = nivel;
  await salvarUsuarios(store);
  const rotuloNivel = nivel === 'dev' ? 'desenvolvedor' : (nivel === 'admin' ? 'administrador' : 'comum');
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Nível alterado: ${u.nome} → ${rotuloNivel}` }], req.usuario.nome);
  registrarSeguranca(req, 'nivel_alterado', { categoria: 'usuarios', severidade: 'alerta', acao: 'alterar_nivel', usuarioAlvo: u.usuario, detalhes: 'novo nível: ' + nivel });
  // mantém o nível dos clientes SSE em dia e avisa o usuário na hora
  for (const c of clientesSSE) if (c.usuario === u.usuario) c.nivel = nivel;
  notificarUsuario(u.usuario, 'nivel-mudou', { nivel });
  notificarAdmins('atualizar-usuarios', { motivo: 'nivel' });
  res.json({ ok: true, nivel });
}));

// Define quais abas o usuário comum pode ver/editar (somente admin).
// Body: { permissoes: { frota:'editar'|'ver'|'nenhum', ... } }. Áreas omitidas ficam 'editar'.
app.post('/api/usuarios/:usuario/permissoes', exigeAdmin, rota(async (req, res) => {
  const store = lerUsuarios();
  const u = store.usuarios.find(x => x.usuario === normalizaUsuario(req.params.usuario));
  if (!u) return res.status(404).json({ erro: 'Usuário não encontrado.' });
  if (u.senhaEnv) return res.status(400).json({ erro: 'O admin mestre tem acesso total.' });
  if (ehNivelAdmin(u.nivel)) return res.status(400).json({ erro: 'Administradores e desenvolvedores têm acesso total. Rebaixe para comum primeiro.' });
  const body = req.body || {};
  if ('empresasFunc' in body && !EMPRESAS_FUNC_VALIDAS.has(String(body.empresasFunc || ''))) return res.status(400).json({ erro: 'Valor de acesso por empresa inválido.' });
  // Guarda só o que difere do padrão ('editar') — mantém o doc enxuto.
  const limpo = sanitizarPermissoes(body.permissoes || {});
  // Combinação silenciosamente inútil: permissão em Funcionários/Admissão com empresa
  // "Nenhuma" — a aba nunca aparece (aplicarPermissoesAbas força 'nenhum' sem empresa).
  // Rejeitar aqui evita o admin "conceder" um acesso que não existe. Espelho da
  // validação do painel (salvarPermissoes no app.js).
  {
    const empDepois = ('empresasFunc' in body) ? String(body.empresasFunc || '') : (u.empresasFunc || '');
    const pf = limpo.funcionarios || permissaoDe(u, 'funcionarios');
    const pa = limpo.admissao || permissaoDe(u, 'admissao');
    if (!empDepois && (pf !== 'nenhum' || pa !== 'nenhum')) {
      return res.status(400).json({ erro: 'Permissão em Funcionários/Form. Admissão exige uma empresa liberada. Escolha NTE, SUL ou ambas em "Acesso por empresa" — ou deixe essas abas em "Não ver".' });
    }
  }
  u.permissoes = {};
  for (const area of AREAS_PERMISSAO) if (limpo[area] && limpo[area] !== 'editar') u.permissoes[area] = limpo[area];
  // Acesso por empresa na aba Funcionários (independente da permissão de aba). '' = nenhuma (padrão).
  const empAntes = u.empresasFunc || '';
  const ctrAntes = Array.isArray(u.contratosFunc) ? u.contratosFunc.slice() : [];
  if ('empresasFunc' in body) {
    const ev = String(body.empresasFunc || '');
    if (ev) u.empresasFunc = ev; else delete u.empresasFunc; // omite quando 'nenhuma'
  }
  // Acesso por contrato: lista de números (subconjunto dos contratos da empresa liberada).
  // Vazio => sem restrição de contrato (todos da empresa). Guardamos só números não vazios e únicos.
  if ('contratosFunc' in body) {
    const raw = Array.isArray(body.contratosFunc) ? body.contratosFunc : [];
    const lista = [...new Set(raw.map(x => String(x || '').trim()).filter(Boolean))].slice(0, 100);
    if (lista.length) u.contratosFunc = lista; else delete u.contratosFunc;
  }
  await salvarUsuarios(store);
  await registrarHistorico([{ placa: '', acao: 'editou', texto: `Permissões de acesso alteradas: ${u.nome}` }], req.usuario.nome);
  registrarSeguranca(req, 'permissoes_alteradas', { categoria: 'usuarios', severidade: 'alerta', acao: 'alterar_permissoes', usuarioAlvo: u.usuario, detalhes: JSON.stringify({ permissoes: u.permissoes || {}, empresasFunc: { de: empAntes, para: u.empresasFunc || '' }, contratosFunc: { de: ctrAntes, para: u.contratosFunc || [] } }).slice(0, 400) });
  // Avisa o próprio usuário na hora (libera/esconde abas sem F5) e atualiza os admins.
  const efetivas = {};
  for (const area of AREAS_PERMISSAO) efetivas[area] = permissaoDe(u, area);
  notificarUsuario(u.usuario, 'permissoes-mudou', { permissoes: efetivas, empresasFunc: empresasFuncEfetivo(u), contratosFunc: contratosFuncEfetivo(u) });
  notificarAdmins('atualizar-usuarios', { motivo: 'permissoes' });
  res.json({ ok: true, permissoes: u.permissoes, empresasFunc: u.empresasFunc || '', contratosFunc: u.contratosFunc || [] });
}));

// Logs de acesso: quem logou (ou tentou) e quando (somente admin). Mais recentes primeiro.
// O `ua` cru (até 200 chars de fingerprint) NÃO sai daqui: a tela só mostra "Chrome · Windows ·
// computador", então quem resume é o servidor, com a MESMA dispositivoDoUA() usada na trilha de
// assinaturas — espelhar esse parser no cliente seria duas implementações para o mesmo texto.
// Ex.: { evento:'entrou', usuario:'dev.demo', ip:'::1', dispositivo:'Chrome · Windows · computador' }
app.get('/api/usuarios/logs', exigeAdmin, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const limite = Math.min(Math.max(parseInt(req.query.limite, 10) || 200, 1), LOGIN_LOGS_MAX);
  const logs = lerLoginLogs().slice(-limite).reverse()
    .map(({ ua, ...l }) => ({ ...l, dispositivo: dispositivoDoUA(ua) }));
  res.json({ logs });
});

// Trilha de auditoria de segurança (somente admin): ações sensíveis e acessos negados.
// Filtros opcionais por querystring: evento, severidade, usuario, ip, area, de, ate (ms epoch).
app.get('/api/seguranca/logs', exigeAdminOuLocal, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const q = req.query || {};
  const de = parseInt(q.de, 10), ate = parseInt(q.ate, 10);
  let logs = lerSegLogs().filter((l) => {
    if (q.evento && l.evento !== q.evento) return false;
    if (q.severidade && l.severidade !== q.severidade) return false;
    if (q.area && l.area !== q.area) return false;
    if (q.usuario && !String(l.usuario || '').includes(String(q.usuario).toLowerCase())) return false;
    if (q.ip && !String(l.ip || '').includes(String(q.ip))) return false;
    if (Number.isFinite(de) && l.ts < de) return false;
    if (Number.isFinite(ate) && l.ts > ate) return false;
    return true;
  });
  const limite = Math.min(Math.max(parseInt(q.limite, 10) || 300, 1), SEG_LOGS_MAX);
  logs = logs.slice(-limite).reverse();
  res.json({ logs });
});

// ═══════════════════════════════════════════════════════════════════════════
//  TELAS ADMIN DE SEGURANÇA (grupo "Segurança" na sidebar) — só admin/dev.
//  Backend das 7 telas: Visão geral, Logs, Endpoints, Segredos, Bloqueios,
//  Sessões, Config. Toda mutação grava na trilha `seglogs`.
// ═══════════════════════════════════════════════════════════════════════════

// ---- Config de segurança: carga no boot + persistência ----
async function carregarConfigSeguranca() {
  const d = await lerDocBackup('sistema_config', {});
  const s = (d && d.seguranca) || {};
  SEG_CFG = {
    inatividadeMin: Math.max(1, Math.min(1440, Number(s.inatividadeMin) || SEG_DEFAULTS.inatividadeMin)),
    absolutoH: Math.max(1, Math.min(720, Number(s.absolutoH) || SEG_DEFAULTS.absolutoH)),
    loginMaxTentativas: Math.max(1, Math.min(100, Number(s.loginMaxTentativas) || SEG_DEFAULTS.loginMaxTentativas)),
    loginJanelaMin: Math.max(1, Math.min(1440, Number(s.loginJanelaMin) || SEG_DEFAULTS.loginJanelaMin)),
  };
  SESS_EPOCA_GLOBAL = Number(s.sessEpocaGlobal) || 0;
  SESS_EPOCAS.clear();
  for (const [usuario, n] of Object.entries(s.sessEpocas || {})) SESS_EPOCAS.set(usuario, Number(n) || 0);
  IP_BLOQUEADOS.clear();
  for (const b of (d.ipBloqueados || [])) if (b && b.ip) IP_BLOQUEADOS.set(b.ip, { motivo: b.motivo || '', ts: b.ts || Date.now(), por: b.por || '' });
}
async function salvarConfigSeguranca() {
  const atual = await lerDocBackup('sistema_config', {});
  const seguranca = Object.assign({}, atual.seguranca, {
    inatividadeMin: SEG_CFG.inatividadeMin, absolutoH: SEG_CFG.absolutoH,
    loginMaxTentativas: SEG_CFG.loginMaxTentativas, loginJanelaMin: SEG_CFG.loginJanelaMin,
    sessEpocaGlobal: SESS_EPOCA_GLOBAL, sessEpocas: Object.fromEntries(SESS_EPOCAS),
  });
  const ipBloqueados = [...IP_BLOQUEADOS.entries()].map(([ip, v]) => ({ ip, ...v }));
  await salvarDocBackup('sistema_config', Object.assign({}, atual, { seguranca, ipBloqueados }));
}

// SEG-1 — Visão geral: um retrato do estado de segurança agora.
app.get('/api/seguranca/geral', exigeAdminOuLocal, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const logs = lerSegLogs();
  const desde24h = Date.now() - 24 * 60 * 60 * 1000;
  const recentes = logs.filter(l => l.ts >= desde24h);
  const porSeveridade = { info: 0, aviso: 0, alerta: 0 };
  for (const l of recentes) porSeveridade[l.severidade] = (porSeveridade[l.severidade] || 0) + 1;
  const tentativasAtivas = [...tentativasLogin.values()].filter(r => Date.now() < r.ate && r.count >= LOGIN_MAX_TENTATIVAS()).length;
  res.json({
    controles: [
      { nome: 'Cabeçalhos + CSP', ok: true, detalhe: 'CSP, nosniff, X-Frame-Options, Referrer-Policy' },
      { nome: 'Anti-CSRF (Origin)', ok: true, detalhe: 'mutações exigem Origin/Referer do próprio site' },
      { nome: 'Rate-limit por IP', ok: true, detalhe: `${REQ_MAX} req/min` },
      { nome: 'Força-bruta no login', ok: true, detalhe: `${SEG_CFG.loginMaxTentativas} erros / ${SEG_CFG.loginJanelaMin} min` },
      { nome: 'Timeout de sessão', ok: true, detalhe: `${SEG_CFG.inatividadeMin} min ocioso · ${SEG_CFG.absolutoH} h no máximo` },
      { nome: 'Login em produção', ok: LOGIN_ATIVO, detalhe: LOGIN_ATIVO ? 'ativo' : 'desligado (ambiente local)' },
    ],
    eventos24h: recentes.length,
    porSeveridade,
    ultimosAlertas: logs.filter(l => l.severidade === 'alerta').slice(-6).reverse(),
    sessoesVivas: clientesSSE.size,
    ipsBloqueados: IP_BLOQUEADOS.size,
    tentativasAtivas,
    totalEventos: logs.length,
  });
});

// SEG-3 — Endpoints: inventário das rotas da API + o guard de cada uma (introspecção).
function rotuloGuard(fn) {
  if (!fn) return null;
  if (fn.guardId) return fn.guardId;                 // exigeVer/exigeEditar (fábrica etiquetada)
  const n = fn.name || '';
  if (n === 'exigeAdmin') return 'admin';
  if (n === 'exigeAdminOuLocal') return 'admin (livre no local)';
  if (n === 'exigeVerMidia') return 'ver:mídia';
  if (n === 'exigeEditarMidia') return 'editar:mídia';
  if (/^upload/.test(n)) return null;                // multer não é guard
  return null;
}
// Rotas /api que passam pelo GATE de login sem sessão (token/anônimas). O resto, sem
// guard de área, ainda exige LOGIN (gate global) — a introspecção reflete isso.
const API_ANONIMAS_EXATAS = new Set(['/api/login', '/api/logout', '/api/versao', '/api/cadastro/aberto', '/api/cadastro/solicitar', '/api/cadastro/status']);
// `/api/verificar/` estava faltando aqui desde que a conferência pública nasceu: ela passa pelo
// gate (é pública de propósito) mas a tela a classificava como "logado", escondendo do auditor
// justamente a rota que qualquer um de fora alcança.
const API_ANONIMAS_PREFIXO = ['/api/admissao/publico/', '/api/treinamentos/publico/', '/api/epi/publico/', '/api/verificar/'];
// Rotas que fazem a checagem de admin DENTRO do handler (não por middleware) — a
// introspecção não as vê como guardadas, então documentamos aqui para não marcá-las "só logado".
const API_ADMIN_INLINE = new Set(['DELETE /api/historico']);
function classificarRota(metodo, path, guardMw) {
  if (guardMw) return { nivel: guardMw, anonima: false };
  if (API_ADMIN_INLINE.has(`${metodo} ${path}`)) return { nivel: 'admin (verificação interna)', anonima: false };
  if (API_ANONIMAS_EXATAS.has(path) || API_ANONIMAS_PREFIXO.some(p => path.startsWith(p))) return { nivel: 'pública (sem login)', anonima: true };
  return { nivel: 'logado (gate de login)', anonima: false }; // sem guard de área, mas atrás do login global
}
app.get('/api/seguranca/endpoints', exigeAdminOuLocal, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const rotas = [];
  const stack = (app._router && app._router.stack) || [];
  for (const layer of stack) {
    if (!layer.route) continue;
    const path = layer.route.path;
    if (typeof path !== 'string' || !path.startsWith('/api/')) continue;
    const metodos = Object.keys(layer.route.methods).filter(m => layer.route.methods[m]).map(m => m.toUpperCase());
    let guardMw = null;
    for (const h of (layer.route.stack || [])) { const g = rotoLabelSafe(h.handle); if (g) { guardMw = g; break; } }
    for (const metodo of metodos) {
      const c = classificarRota(metodo, path, guardMw);
      rotas.push({ metodo, path, guard: c.nivel, anonima: c.anonima });
    }
  }
  // Rotas que vivem dentro de um Router montado no app (ex.: a API de integração). A varredura
  // acima só enxerga rota registrada direto no `app`, então sem isto elas sumiriam do inventário
  // — e o que não aparece nesta tela é o que ninguém audita.
  for (const reg of ROTEADORES_INTROSPECCAO) {
    for (const layer of ((reg.router && reg.router.stack) || [])) {
      if (!layer.route || typeof layer.route.path !== 'string') continue;
      const path = reg.prefixo + layer.route.path;
      for (const metodo of Object.keys(layer.route.methods).filter(m => layer.route.methods[m]).map(m => m.toUpperCase())) {
        rotas.push({ metodo, path, guard: reg.guard, anonima: false });
      }
    }
  }
  rotas.sort((a, b) => a.path.localeCompare(b.path) || a.metodo.localeCompare(b.metodo));
  const anonimas = rotas.filter(r => r.anonima).length;
  res.json({ total: rotas.length, anonimas, rotas });
});
function rotoLabelSafe(fn) { try { return rotuloGuard(fn); } catch (e) { return null; } }

// SEG-4 — Segredos: só presença das envs sensíveis (NUNCA o valor) + scanner sob demanda.
const ENVS_SENSIVEIS = [
  { nome: 'MONGODB_URI', descricao: 'conexão do banco em produção' },
  { nome: 'SESSION_SECRET', descricao: 'assina os cookies de sessão' },
  { nome: 'APP_PASSWORD', descricao: 'senha mestra do login' },
  { nome: 'COFRE_CHAVE', descricao: 'criptografa o cofre de senhas' },
  { nome: 'COBLI_API_KEY', descricao: 'integração com a Cobli' },
  { nome: 'RESEND_API_KEY', descricao: 'envio de e-mails (notificações)' },
  { nome: 'NOTIF_EMAIL_PARA', descricao: 'destinatários do resumo diário' },
  { nome: 'VIDEO_S3_KEY_ID', descricao: 'chave de acesso do bucket de vídeos de treinamento (R2)' },
  { nome: 'VIDEO_S3_KEY_SECRET', descricao: 'segredo da chave do bucket de vídeos de treinamento (R2)' },
];
app.get('/api/seguranca/segredos', exigeAdminOuLocal, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const envs = ENVS_SENSIVEIS.map(e => ({ nome: e.nome, descricao: e.descricao, definida: !!(process.env[e.nome] && String(process.env[e.nome]).trim()) }));
  res.json({ envs });
});
app.post('/api/seguranca/segredos/scan', exigeAdminOuLocal, rota(async (req, res) => {
  const { execFile } = require('child_process');
  const r = await new Promise((resolve) => {
    execFile(process.execPath, [path.join(RAIZ, 'scripts', 'scan-secrets.js')], { cwd: RAIZ, timeout: 60000, maxBuffer: 4 * 1024 * 1024 },
      (err, stdout, stderr) => resolve({ code: err ? (err.code || 1) : 0, stdout: String(stdout || ''), stderr: String(stderr || '') }));
  });
  // O scanner já REDIGE os valores; ainda assim só devolvemos o resumo + linhas achadas, sem eco cru.
  const achados = (r.stdout.match(/^.*(?:segredo|secret|token|password|api[_-]?key|found|encontrad).*$/gmi) || []).slice(0, 100);
  registrarSeguranca(req, 'scan_segredos', { categoria: 'auditoria', severidade: r.code === 0 ? 'info' : 'alerta', area: 'seguranca', acao: 'scan', detalhes: `saída ${r.code === 0 ? 'limpa' : 'com achados'}` });
  res.json({ ok: r.code === 0, achados, resumo: r.code === 0 ? 'Nenhum segredo aparente no código versionado.' : `${achados.length} linha(s) sinalizada(s) · confira.` });
}));

// SEG-5 — Bloqueios: força-bruta (efêmero) + banimento manual de IP (persistido).
app.get('/api/seguranca/bloqueios', exigeAdminOuLocal, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const agora = Date.now();
  const tentativas = [...tentativasLogin.entries()]
    .filter(([, r]) => agora < r.ate)
    .map(([ip, r]) => ({ ip, tentativas: r.count, bloqueado: r.count >= LOGIN_MAX_TENTATIVAS(), expiraEm: r.ate }));
  const permanentes = [...IP_BLOQUEADOS.entries()].map(([ip, v]) => ({ ip, motivo: v.motivo, ts: v.ts, por: v.por }));
  res.json({ tentativas, permanentes, limite: LOGIN_MAX_TENTATIVAS() });
});
app.post('/api/seguranca/bloqueios', exigeAdminOuLocal, rota(async (req, res) => {
  const ip = String((req.body && req.body.ip) || '').trim();
  const motivo = String((req.body && req.body.motivo) || '').trim().slice(0, 200);
  if (!ip) return res.status(400).json({ erro: 'Informe o IP a bloquear.' });
  if (ip === ipDe(req)) return res.status(400).json({ erro: 'Você não pode bloquear o seu próprio IP.' });
  IP_BLOQUEADOS.set(ip, { motivo, ts: Date.now(), por: quemFez(req) || 'local' });
  await salvarConfigSeguranca();
  registrarSeguranca(req, 'ip_bloqueado', { categoria: 'autorizacao', severidade: 'alerta', area: 'seguranca', acao: 'bloquear_ip', detalhes: `${ip}${motivo ? ' · ' + motivo : ''}` });
  res.json({ ok: true });
}));
app.delete('/api/seguranca/bloqueios/:ip', exigeAdminOuLocal, rota(async (req, res) => {
  const ip = decodeURIComponent(req.params.ip);
  if (!IP_BLOQUEADOS.has(ip)) return res.status(404).json({ erro: 'IP não está bloqueado.' });
  IP_BLOQUEADOS.delete(ip);
  await salvarConfigSeguranca();
  registrarSeguranca(req, 'ip_desbloqueado', { categoria: 'autorizacao', severidade: 'aviso', area: 'seguranca', acao: 'desbloquear_ip', detalhes: ip });
  res.json({ ok: true });
}));
app.post('/api/seguranca/bloqueios/limpar-tentativas', exigeAdminOuLocal, (req, res) => {
  const ip = String((req.body && req.body.ip) || '').trim();
  if (!ip) return res.status(400).json({ erro: 'Informe o IP.' });
  tentativasLogin.delete(ip);
  registrarSeguranca(req, 'tentativas_limpas', { categoria: 'autorizacao', severidade: 'info', area: 'seguranca', acao: 'limpar_tentativas', detalhes: ip });
  res.json({ ok: true });
});

// ---- Credenciais de integração (tokens de máquina para outros sistemas) ----
// Gerência é de ADMIN por cookie: o token da integração não pode se auto-administrar (uma
// credencial vazada emitiria outra). O segredo aparece UMA vez, na emissão — depois só o hash
// fica guardado e nem o admin o vê de novo; perdeu, emite outra e revoga a antiga.
// ⚠️ Estas credenciais NÃO entram no backup (o doc é lido sob demanda, fora de
// montarBackupCompleto): depois de restaurar em ambiente novo, reemita o token do consumidor.
app.get('/api/seguranca/integracoes', exigeAdminOuLocal, rota(async (req, res) => {
  res.set('Cache-Control', 'no-store');
  const tokens = await lerTokensIntegracao();
  res.json({ escopos: ESCOPOS_INTEGRACAO, tokens: tokens.map(resumoTokenIntegracao) });
}));
app.post('/api/seguranca/integracoes', exigeAdminOuLocal, rota(async (req, res) => {
  const c = req.body || {};
  const escopos = Array.isArray(c.escopos) ? c.escopos : ESCOPOS_INTEGRACAO_PADRAO;
  const invalidos = escopos.filter(e => !ESCOPOS_INTEGRACAO.includes(e));
  if (invalidos.length) return res.status(400).json({ erro: `Escopo desconhecido: ${invalidos.join(', ')}` });
  const { registro, token } = await emitirTokenIntegracao({
    nome: c.nome, escopos, empresas: c.empresas, contratos: c.contratos, expiraEm: c.expiraEm,
    criadoPor: quemFez(req),
  });
  registrarSeguranca(req, 'integracao_emitida', { categoria: 'autorizacao', severidade: 'alerta', area: 'seguranca', acao: 'emitir_token', detalhes: `${registro.nome} (${registro.id})` });
  res.status(201).json({ ok: true, credencial: resumoTokenIntegracao(registro), token });
}));
app.delete('/api/seguranca/integracoes/:id', exigeAdminOuLocal, rota(async (req, res) => {
  const id = String(req.params.id || '');
  const tokens = await lerTokensIntegracao();
  const t = tokens.find(x => x && x.id === id);
  if (!t) return res.status(404).json({ erro: 'Credencial não encontrada.' });
  if (t.revogadoEm) return res.json({ ok: true, credencial: resumoTokenIntegracao(t) }); // já estava revogada
  t.revogadoEm = Date.now();                 // revogação LÓGICA: apagar levaria junto a trilha de quem usou o quê
  t.revogadoPor = quemFez(req);
  await salvarTokensIntegracao(tokens);
  registrarSeguranca(req, 'integracao_revogada', { categoria: 'autorizacao', severidade: 'alerta', area: 'seguranca', acao: 'revogar_token', detalhes: `${t.nome} (${t.id})` });
  res.json({ ok: true, credencial: resumoTokenIntegracao(t) });
}));

// SEG-6 — Sessões: as conexões vivas (via SSE) + revogação por usuário / geral.
app.get('/api/seguranca/sessoes', exigeAdminOuLocal, (req, res) => {
  res.set('Cache-Control', 'no-store');
  const sessoes = [...clientesSSE].map(c => ({
    usuario: c.usuario || '', nome: c.nome || '', nivel: c.nivel || '', ip: c.ip || '',
    desde: c.desde || 0, eu: !!(c.usuario && req.usuario && c.usuario === req.usuario.usuario),
  })).sort((a, b) => (b.desde || 0) - (a.desde || 0));
  res.json({ sessoes, total: sessoes.length });
});
app.post('/api/seguranca/sessoes/revogar', exigeAdminOuLocal, rota(async (req, res) => {
  const usuario = String((req.body && req.body.usuario) || '').trim();
  if (!usuario) return res.status(400).json({ erro: 'Informe o usuário.' });
  SESS_EPOCAS.set(usuario, (SESS_EPOCAS.get(usuario) || 0) + 1); // invalida o cookie dele
  await salvarConfigSeguranca();
  for (const c of [...clientesSSE]) if (c.usuario === usuario) { try { c.res.end(); } catch (e) {} clientesSSE.delete(c); } // derruba o SSE vivo
  registrarSeguranca(req, 'sessao_revogada', { categoria: 'autorizacao', severidade: 'alerta', area: 'seguranca', acao: 'revogar_sessao', usuarioAlvo: usuario, detalhes: usuario });
  res.json({ ok: true });
}));
app.post('/api/seguranca/sessoes/revogar-todas', exigeAdminOuLocal, rota(async (req, res) => {
  SESS_EPOCA_GLOBAL += 1; // invalida TODAS as sessões (inclusive a sua — você reloga)
  await salvarConfigSeguranca();
  for (const c of [...clientesSSE]) { try { c.res.end(); } catch (e) {} clientesSSE.delete(c); }
  registrarSeguranca(req, 'sessoes_revogadas_todas', { categoria: 'autorizacao', severidade: 'alerta', area: 'seguranca', acao: 'revogar_todas' });
  res.json({ ok: true });
}));

