app.put('/api/seguranca/config', exigeAdminOuLocal, rota(async (req, res) => {
  const b = req.body || {};
  const clamp = (v, min, max, def) => { const n = Math.round(Number(v)); return Number.isFinite(n) ? Math.max(min, Math.min(max, n)) : def; };
  SEG_CFG = {
    inatividadeMin: clamp(b.inatividadeMin, 1, 1440, SEG_CFG.inatividadeMin),
    absolutoH: clamp(b.absolutoH, 1, 720, SEG_CFG.absolutoH),
    loginMaxTentativas: clamp(b.loginMaxTentativas, 1, 100, SEG_CFG.loginMaxTentativas),
    loginJanelaMin: clamp(b.loginJanelaMin, 1, 1440, SEG_CFG.loginJanelaMin),
  };
  await salvarConfigSeguranca();
  registrarSeguranca(req, 'config_seguranca', { categoria: 'auditoria', severidade: 'alerta', area: 'seguranca', acao: 'alterar_config', detalhes: JSON.stringify(SEG_CFG) });
  res.json({ ok: true, config: { ...SEG_CFG } });
}));

