// ----- BACKUP COMPLETO (download manual + snapshot automático) -----
// Usuários SEM credenciais: tira senhaHash/salt para o JSON baixado não vazar
// hashes (ataque offline) caso o admin compartilhe a cópia. O resto é preservado.
function backupUsuariosSemSenha() {
  const store = lerUsuarios();
  return {
    cadastrosAbertos: store.cadastrosAbertos,
    usuarios: (store.usuarios || []).map(({ senhaHash, salt, ...resto }) => resto),
  };
}
// ASSÍNCRONA de propósito: `vigenciasContratos` e `experienciaDias` moram no doc `sistema_config`
// e só se leem com await. Todos os chamadores já eram async — a alternativa (cache síncrono em
// memória, como o EXP_DIAS_CACHE) foi descartada porque uma falha transitória na leitura do boot
// passaria a gerar .zip com a matriz VAZIA, manifest válido e cobertura OK: silencioso e fatal
// num restore em modo substituir. ⚠️ Esqueceu um `await` num chamador? O dump vira Promise e o
// .zip sai com todos os módulos `null` — por isso o assert em gerarConteudoBackup().
async function montarBackupCompleto() {
  // UMA leitura do sistema_config por dump (o /api/backup/status é chamado a cada carga do Início).
  const cfgSistema = await lerDocBackup('sistema_config', {});
  return {
    geradoEm: new Date().toISOString(),
    versao: VERSAO_INFO.versao,
    veiculos: lerDados().veiculos,
    multas: lerMultas(),
    rastreadores: lerRastreadores(),
    rastreadoresVinculos: lerRastVinculos(),
    cadastros: lerCadastros(),
    instalacoes: lerInstalacoes(),
    envios: lerEnvios(),
    contratos: lerContratos(),
    manutencao: lerManutencao(),
    abastecimento: lerAbastecimento(),
    simulacoes: lerSimulacoes(),
    fornecedores: lerFornecedores(),
    cartoes: lerCartoes(),
    locacoes: lerLocacoes(),
    locacoesConfig: lerLocacoesConfig(),
    locacoesFaturas: lerLocacoesFaturas(),
    senhas: lerSenhas(),
    documentos: lerDocumentosEmpresa(),
    pastasDocumentos: lerPastasDocumentos(),
    pastasTermosMultas: lerPastasTermosMultas(),
    termosMultas: lerTermosMultas(),
    oficina: lerOficina(),
    odometros: lerOdometros(),
    vistorias: lerVistorias(),
    aportes: lerAportes(),
    emprestimos: lerEmprestimos(),
    percentuais: lerPercentuais(),
    retiradas: lerRetiradas(),
    funcionarios: lerFuncionarios(),
    funcobrigatorios: lerObrigatorios(),
    // As duas chaves de NEGÓCIO que moram no doc `sistema_config`. Só elas — o doc também guarda
    // estado de SEGURANÇA vivo (seguranca.sessEpoca*, ipBloqueados, areasLiberadas) que não pode
    // ir para backup: restaurar um sessEpoca menor RE-VALIDA cookies de sessão já revogados.
    experienciaDias: sanitizarExpDias(cfgSistema.experienciaDias || {}),
    vigenciasContratos: sanitizarVigenciasContratos(cfgSistema.vigenciasContratos || {}),
    almoxarifado: lerAlmoxarifado(),
    epiCatalogo: lerEpiCatalogo(),
    epiMovimentacoes: lerEpiMov(),
    epiNotasFiscais: lerEpiNotasFiscais(),
    tiAtivos: lerTiAtivos(),
    tiMovimentacoes: lerTiMov(),
    programas: lerProgramas(),
    acoesSst: lerAcoesSst(),
    admissoes: lerAdmissoes(),
    treinamentos: lerTreinamentos(),
    treinamentoConvites: lerConvites(),
    treinamentoConclusoes: lerConclusoes(),
    contabilidade: lerContabilidade(),
    horasExtras: lerHorasExtras(),
    custosConfig: lerCustosConfig(),
    feedbacks: lerFeedbacks(),
    usuarios: backupUsuariosSemSenha(),
    historico: lerHistorico(),
    loginlogs: lerLoginLogs(),
    seglogs: lerSegLogs(),
  };
}
// Baixa um JSON com TUDO (o jeito mais confiável de guardar uma cópia). Por PADRÃO é LEVE
// (só os dados, sem os arquivos) — incluir todos os binários carregava centenas de MB na
// memória e derrubava o servidor em produção. Para uma cópia COM os arquivos (ex.: espelhar
// a produção no localhost), use ?midia=1 — aí o tamanho é limitado (ver coletarMidias).
app.get('/api/backup', exigeAdminOuLocal, rota(async (req, res) => {
  const dump = await montarBackupCompleto();
  if (req.query.midia === '1' || req.query.midia === 'true') {
    dump.midias = (await coletarMidias()).midias;
  }
  const nome = `backup-frota-${new Date().toISOString().slice(0, 10)}.json`;
  registrarSeguranca(req, 'backup_baixado', { categoria: 'backup', severidade: 'alerta', acao: 'download_backup' });
  res.setHeader('Content-Disposition', `attachment; filename="${nome}"`);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.send(JSON.stringify(dump, null, 2));
}));
// Snapshot automático (rede de segurança best-effort).
async function salvarBackupAuto() {
  try {
    const dump = await montarBackupCompleto();
    if (USE_MONGO) {
      // O histórico tem doc próprio ('historico') e é capado em 1000 — não precisa
      // ser duplicado aqui e é o que mais cresce. Tiramos do snapshot para caber no
      // limite de 16 MB por documento do MongoDB.
      const { historico, ...leve } = dump;
      const bytes = Buffer.byteLength(JSON.stringify(leve));
      if (bytes > 15 * 1024 * 1024) {
        console.error(`Backup automático NÃO salvo: ${(bytes / 1048576).toFixed(1)} MB excede o limite de documento do MongoDB (16 MB). Use o download manual em /api/backup.`);
        return;
      }
      await persistMongo('backup_auto', leve);
    } else {
      escreverJSONAtomico(path.join(DATA_DIR, 'backup-auto.json'), dump);
    }
    console.log('Backup automático salvo —', dump.geradoEm);
  } catch (e) { console.error('Falha no backup automático:', e.message); }
}
setInterval(salvarBackupAuto, 24 * 60 * 60 * 1000).unref(); // 1x/dia

// ----- LIMPEZA DE MÍDIA ÓRFÃ (fotos/comprovantes sem nenhum registro apontando) -----
function midiasReferenciadas() {
  const set = new Set();
  for (const v of lerDados().veiculos || []) if (v && v.crlvDoc && v.crlvDoc.id) set.add(v.crlvDoc.id);
  for (const i of [...lerInstalacoes(), ...lerRastVinculos()]) for (const f of (i.fotos || [])) if (f && f.id) set.add(f.id);
  for (const e of lerEnvios()) for (const c of (e.comprovantes || [])) if (c && c.id) set.add(c.id);
  // Feedback: as imagens duram enquanto o feedback existir. Sem estas referências, a limpeza
  // diária tratava anexos válidos como órfãos e podia apagá-los depois de apenas uma hora.
  for (const f of lerFeedbacks()) for (const imagem of (f.imagens || [])) if (imagem && imagem.id) set.add(imagem.id);
  // Funcionários: foto, PPP e documentos pessoais/de segurança. SEM isto, a limpeza diária
  // considerava TODO arquivo de funcionário como órfão e o apagava do cofre (perda de dados).
  for (const f of lerFuncionarios()) {
    if (f.foto && f.foto.id) set.add(f.foto.id);
    if (f.ppp && f.ppp.id) set.add(f.ppp.id);
    if (f.asoDemissional && f.asoDemissional.id) set.add(f.asoDemissional.id);
    if (f.fichaEpi && f.fichaEpi.id) set.add(f.fichaEpi.id);
    if (f.salarioDoc && f.salarioDoc.id) set.add(f.salarioDoc.id);
    for (const d of (f.documentos || [])) for (const mid of idsMidiaDoc(d)) set.add(mid);
  }
  // Programas de SST (PCMSO, PGR...): o anexo do documento por contrato/obra.
  for (const p of lerProgramas()) if (p && p.documento && p.documento.id) set.add(p.documento.id);
  // Ações de Segurança: as evidências da realização (fotos, listas de presença, PDFs) e as
  // versões anteriores de cada uma. SEM isto a limpeza diária apagaria a prova ~1h após o upload.
  for (const a of lerAcoesSst()) for (const d of (a.evidencias || [])) for (const mid of idsMidiaDoc(d)) set.add(mid);
  for (const c of lerContabilidade()) if (c && c.arquivo && c.arquivo.id) set.add(c.arquivo.id);
  for (const d of lerDocumentosEmpresa()) if (d && d.arquivo && d.arquivo.id) set.add(d.arquivo.id);
  for (const t of lerTermosMultas()) if (t && t.arquivo && t.arquivo.id) set.add(t.arquivo.id);
  // Anexos das multas (notificação, boleto, comprovante, termo) + as versões anteriores de cada um.
  // SEM isto a limpeza diária os trataria como órfãos e apagaria tudo ~1h após o upload.
  for (const m of lerMultas()) for (const d of (m.documentos || [])) for (const mid of idsMidiaDoc(d)) set.add(mid);
  // Oficina: o arquivo (PDF/imagem) da nota fiscal de cada serviço. SEM isto a limpeza diária
  // consideraria as NFs órfãs e as apagaria do cofre (perda de dados).
  for (const o of lerOficina()) if (o && o.anexo && o.anexo.id) set.add(o.anexo.id);
  // Vistorias: as fotos do veículo. Estavam de fora desta lista embora `mapaPastaAnexos()` já
  // apontasse para `files/vistorias` — ou seja, a limpeza diária apagava toda foto ~1h após o
  // upload E elas nunca chegavam ao .zip (o backup percorre só o que está referenciado aqui).
  for (const v of lerVistorias()) for (const ft of (v.fotos || [])) if (ft && ft.id) set.add(ft.id);
  // Locações: os documentos de cada contrato (sub-aba Documentos). Ficam em
  // locacoesConfig.contratos[].documentos, NÃO na lista de locações — sem esta referência a
  // limpeza diária os tratava como órfãos e apagava todos ~1h após o upload.
  for (const c of (lerLocacoesConfig().contratos || [])) {
    for (const d of ((c && c.documentos) || [])) if (d && d.id) set.add(d.id);
  }
  // Locações: o PDF de cada fatura emitida (sub-aba Faturas). SEM isto a limpeza diária apagaria
  // o arquivo ~1h depois de gerado e o histórico apontaria para um PDF que não existe mais.
  for (const f of lerLocacoesFaturas()) if (f && f.arquivo && f.arquivo.id) set.add(f.arquivo.id);
  // Almoxarifado: a assinatura do colaborador e as fotos do material no ato da entrega. São a
  // PROVA da entrega — sem estas referências a limpeza diária as apagaria ~1h depois.
  for (const r of lerAlmoxarifado()) {
    if (r && r.assinatura && r.assinatura.id) set.add(r.assinatura.id);
    for (const f of ((r && r.fotos) || [])) if (f && f.id) set.add(f.id);
  }
  // EPI: a assinatura da ficha, pelo MESMO motivo — é a prova da entrega do equipamento.
  for (const m of lerEpiMov()) {
    if (m && m.assinatura && m.assinatura.id) set.add(m.assinatura.id);
  }
  // EPI: o PDF/imagem da nota fiscal de compra — é o documento fiscal da aquisição.
  for (const n of lerEpiNotasFiscais()) if (n && n.anexo && n.anexo.id) set.add(n.anexo.id);
  // TI: a assinatura do termo de responsabilidade e os anexos do ativo (NF, fotos) — sem estas
  // referências a limpeza diária apagaria a prova ~1h depois de colhida (lição da v1.45.1).
  for (const m of lerTiMov()) if (m && m.assinatura && m.assinatura.id) set.add(m.assinatura.id);
  for (const a of lerTiAtivos()) for (const ax of (a.anexos || [])) if (ax && ax.id) set.add(ax.id);
  // Admissão: os arquivos que o candidato enviou pelo link público (`docs` do convite preenchido
  // e `docsPendentes` de quem ainda está preenchendo). Ficavam DE FORA desta lista, então a
  // limpeza diária os tratava como órfãos e apagava tudo ~1h depois do envio — o "Baixar tudo
  // (.zip)" da revisão respondia "não estão mais no cofre" mesmo em convite recém-preenchido.
  // Pelo mesmo motivo eles nunca chegavam ao backup (`coletarMidias` percorre só o que está
  // aqui), e por isso restaurar backup não os trazia de volta. Mesma lição da v1.45.1.
  for (const id of idsMidiaAdmissoes()) set.add(id);
  return set;
}
// Coleta o BINÁRIO (base64) das mídias EM USO, para o backup completo (?midia=1). Só as
// referenciadas (ignora órfãs) e com TETO de tamanho — carregar tudo de uma vez estourava a
// memória da instância e derrubava o servidor. O que passar do teto é omitido e declarado.
// Ordem ÚNICA do MENOR para o MAIOR entre os dois armazenamentos (R2 e o antigo): a leitura em
// ordem alfabética/natural deixava uma foto de 10 MB consumir o teto e tirar dezenas de anexos
// pequenos e críticos (assinaturas dos recibos) — e, durante a migração, os PDFs novos do
// bucket não podem tirar a vez das assinaturas antigas que ainda estão no Mongo. Os tamanhos
// vêm SEM trazer o binário (listagem do R2, $strLenBytes no Mongo, stat no disco) e são
// medidos em base64, o formato antigo, para o teto não mudar de regra.
const BACKUP_MIDIA_MAX_BYTES = 50 * 1024 * 1024; // ~50 MB de mídia por backup (limita a memória)
async function coletarMidias() {
  // Há anexos só num bucket que esta instância não lê: o .zip sairia "concluído" dando esses
  // arquivos como ausentes. Indisponibilidade é 503, como no download (e no backup-lib).
  if (AVISO_ACERVO_R2) throw new ErroCofreIndisponivel(AVISO_ACERVO_R2);
  const ids = midiasReferenciadas();
  const out = [];
  let bytes = 0, omitidos = 0;
  const porTeto = new Set(); // ids barrados pelo teto — separados dos que sumiram do cofre
  const candidatos = []; // { id, tam (bytes em base64), fonte: 'r2' | 'mongo' | 'local', chave?, f? }
  const noR2 = new Set(); // ids que estão no bucket: o armazenamento antigo não é consultado para eles
  if (COFRE_R2) {
    // A chave do bucket leva o id LIMPO (sem os caracteres que a limpeza tira); o mapa devolve o
    // id original, que é o que o manifest e o mapaPastaAnexos() usam.
    const porLimpo = new Map([...ids].map(id => [CofreMidia.limparId(id), id]));
    let objetos;
    try { objetos = await COFRE_R2.listar(CofreMidia.PREFIXO_MIDIA); }
    catch (e) { throw new ErroCofreIndisponivel(`falha ao listar o R2 (${e.codigo || e.status || 'erro'})`, e); }
    for (const o of objetos) {
      const id = porLimpo.get(CofreMidia.idDaChaveMidia(o.chave));
      if (!id || noR2.has(id)) continue;
      noR2.add(id);
      candidatos.push({ id, tam: CofreMidia.tamanhoBase64(o.bytes), fonte: 'r2', chave: o.chave });
    }
  }
  let mongoSemTamanho = false;
  if (USE_MONGO) {
    if (mongoCol) {
      try {
        const tamanhos = await mongoCol.aggregate([
          { $match: { _id: { $regex: '^midia_' } } },
          { $project: { t: { $strLenBytes: { $ifNull: ['$b64', ''] } } } },
        ], { allowDiskUse: true }).toArray();
        for (const d of tamanhos) {
          const id = String(d._id).slice(6); // tira "midia_"
          if (ids.has(id) && !noR2.has(id)) candidatos.push({ id, tam: d.t || 0, fonte: 'mongo' });
        }
      } catch (e) {
        mongoSemTamanho = true; // banco antigo/sem permissão p/ aggregate: cursor na ordem natural, lá embaixo
      }
    }
  } else if (fs.existsSync(UPLOADS_DIR)) {
    for (const f of fs.readdirSync(UPLOADS_DIR)) {
      const id = f.replace(/\.json$/, '');
      if (!ids.has(id) || noR2.has(id)) continue;
      let tam = 0;
      try { tam = fs.statSync(path.join(UPLOADS_DIR, f)).size; } catch (e) { tam = 0; } // JSON ≥ base64: conta por cima
      candidatos.push({ id, tam, fonte: 'local', f });
    }
  }
  // Reserva (o banco não aceitou o aggregate de tamanhos): cursor do Mongo, 1 doc por vez, na
  // ordem natural — ANTES dos candidatos do R2, para as assinaturas pequenas do acervo antigo
  // não perderem a vez para os PDFs novos do bucket.
  if (mongoSemTamanho && mongoCol) {
    const cursor = mongoCol.find({ _id: { $regex: '^midia_' } });
    for await (const d of cursor) {
      const id = String(d._id).slice(6);
      if (!ids.has(id) || noR2.has(id) || !d.b64) continue;
      if (bytes + d.b64.length > BACKUP_MIDIA_MAX_BYTES) { omitidos++; porTeto.add(id); continue; }
      bytes += d.b64.length;
      out.push({ id, tipo: d.tipo, nome: d.nome, b64: d.b64, ts: d.ts || 0 });
    }
  }
  candidatos.sort((a, b) => a.tam - b.tam);

  // Mongo em lotes (uma consulta por arquivo seria lenta com milhares de assinaturas pequenas),
  // limitados ao que ainda cabe no teto para não trazer à memória o que vai ser descartado.
  const loteMongo = new Map(); // id → doc | null (pedido e não achado)
  async function buscarLoteMongo(desde) {
    const lote = [];
    let soma = 0;
    for (let k = desde; k < candidatos.length && lote.length < 25; k++) {
      const c = candidatos[k];
      if (c.fonte !== 'mongo' || loteMongo.has(c.id)) continue;
      if (lote.length && bytes + soma + c.tam > BACKUP_MIDIA_MAX_BYTES) break;
      lote.push(c.id); soma += c.tam;
    }
    for (const id of lote) loteMongo.set(id, null);
    for (const d of await mongoCol.find({ _id: { $in: lote.map(id => 'midia_' + id) } }).toArray()) loteMongo.set(String(d._id).slice(6), d);
  }
  for (let i = 0; i < candidatos.length; i++) {
    const c = candidatos[i];
    if (bytes + c.tam > BACKUP_MIDIA_MAX_BYTES) {
      // O resto é ainda maior (ordem crescente): cai todo pelo teto.
      for (const r of candidatos.slice(i)) porTeto.add(r.id);
      omitidos += candidatos.length - i;
      break;
    }
    let m = null;
    if (c.fonte === 'r2') {
      let o;
      try { o = await COFRE_R2.ler(c.chave); }
      catch (e) { throw new ErroCofreIndisponivel(`falha ao ler do R2 (${e.codigo || e.status || 'erro'})`, e); }
      if (o) m = { tipo: o.tipo, nome: o.nome, b64: o.buf.toString('base64'), ts: o.ts };
    } else if (c.fonte === 'mongo') {
      if (!loteMongo.has(c.id)) await buscarLoteMongo(i);
      m = loteMongo.get(c.id);
      loteMongo.delete(c.id);
    } else {
      try { m = JSON.parse(fs.readFileSync(path.join(UPLOADS_DIR, c.f), 'utf-8')); } catch (e) { m = null; /* corrompido: pula */ }
    }
    if (!m || !m.b64) continue; // sumiu entre a listagem e a leitura, ou vazio: vai para as falhas
    bytes += m.b64.length;
    out.push({ id: c.id, tipo: m.tipo, nome: m.nome, b64: m.b64, ts: m.ts || 0 });
  }
  if (omitidos) console.warn(`Backup com mídia: ${omitidos} arquivo(s) omitido(s) por exceder o teto de ${(BACKUP_MIDIA_MAX_BYTES / 1048576).toFixed(0)} MB.`);
  // TODO REFERENCIADO que não veio é FALHA declarada, não silêncio. Antes a única pista de um
  // backup incompleto era este console.warn no log do servidor — o .zip saía com manifest válido,
  // hashes corretos e menos arquivos, e ninguém descobria até precisar restaurar.
  // O motivo é derivado por eliminação (quem estava referenciado e não entrou), o que cobre de
  // uma vez os três casos: teto estourado, arquivo sumido do cofre e registro corrompido.
  const coletados = new Set(out.map(m => m.id));
  const falhas = [];
  for (const id of ids) {
    if (coletados.has(id)) continue;
    falhas.push({ id, motivo: porTeto.has(id) ? 'não coube no teto de mídia do backup' : 'ausente ou ilegível no cofre de mídia' });
  }
  return { midias: out, falhas };
}

