// Conta registros de um módulo (array, {usuarios:[]}, {logs:[]}, objeto-mapa) p/ o manifest.
function contarRegistrosBackup(val) {
  if (Array.isArray(val)) return val.length;
  if (val && typeof val === 'object') {
    if (Array.isArray(val.usuarios)) return val.usuarios.length;
    if (Array.isArray(val.logs)) return val.logs.length;
    let n = 0;
    for (const v of Object.values(val)) n += Array.isArray(v) ? v.length : (v && typeof v === 'object' ? Object.keys(v).length : 1);
    return n;
  }
  return val == null ? 0 : 1;
}
function sha256Buf(buf) { return crypto.createHash('sha256').update(buf).digest('hex'); }
