  abastecimento:    { arquivo: 'abastecimento.json',    grupo: 'frota',        tipo: 'array',    chave: 'id',     ler: lerAbastecimento, salvar: salvarAbastecimento },
  simulacoes:       { arquivo: 'simulacoes.json',       grupo: 'frota',        tipo: 'array',    chave: 'id',     ler: lerSimulacoes,    salvar: salvarSimulacoes },
  fornecedores:     { arquivo: 'fornecedores.json',     grupo: 'frota',        tipo: 'array',    chave: 'id',     ler: lerFornecedores,  salvar: salvarFornecedores },
  cartoes:          { arquivo: 'cartoes.json',          grupo: 'frota',        tipo: 'array',    chave: 'id',     ler: lerCartoes,       salvar: salvarCartoes },
