async function boot() {
  if (USE_MONGO) {
    try {
      const { MongoClient } = require('mongodb');
      const client = new MongoClient(process.env.MONGODB_URI);
      await client.connect();
      mongoCol = client.db('frota').collection('app');
      const docFrota = await mongoCol.findOne({ _id: 'frota' });
      const docHist = await mongoCol.findOne({ _id: 'historico' });
      if (docFrota && Array.isArray(docFrota.veiculos)) {
        mem.veiculos = docFrota.veiculos;
      } else {
        // 1ª vez: semeia o banco com os veículos do data.json embarcado
        mem.veiculos = seedDoArquivo();
        await persistMongo('frota', { veiculos: mem.veiculos });
      }
      mem.historico = (docHist && Array.isArray(docHist.historico)) ? docHist.historico : [];
      const docMultas = await mongoCol.findOne({ _id: 'multas' });
      if (docMultas && Array.isArray(docMultas.multas)) {
        mem.multas = docMultas.multas;
      } else {
        mem.multas = seedMultas();
        await persistMongo('multas', { multas: mem.multas });
      }
      const docTermosMultas = await mongoCol.findOne({ _id: 'termosMultas' });
      const estruturaTermos = docTermosMultas && Array.isArray(docTermosMultas.termos)
        ? migrarEstruturaTermosMultas(docTermosMultas.termos, docTermosMultas.pastas)
        : seedEstruturaTermosMultas();
      mem.termosMultas = estruturaTermos.termos;
      mem.pastasTermosMultas = estruturaTermos.pastas;
      if (!docTermosMultas || !Array.isArray(docTermosMultas.pastas)) await persistMongo('termosMultas', estruturaTermos);
      const docRast = await mongoCol.findOne({ _id: 'rastreadores' });
      if (docRast && Array.isArray(docRast.rastreadores)) {
        mem.rastreadores = docRast.rastreadores;
      } else {
        mem.rastreadores = seedRastreadores();
        await persistMongo('rastreadores', { rastreadores: mem.rastreadores });
      }
      const docVinculos = await mongoCol.findOne({ _id: 'rastreadoresVinculos' });
      if (docVinculos && !Array.isArray(docVinculos.eventos)) throw new Error('Histórico de vínculos inválido no MongoDB.');
      mem.rastreadoresVinculos = docVinculos && Array.isArray(docVinculos.eventos) ? docVinculos.eventos : seedRastVinculos();
      if (!docVinculos) await persistMongo('rastreadoresVinculos', { eventos: mem.rastreadoresVinculos });
      const docInst = await mongoCol.findOne({ _id: 'instalacoes' });
      if (docInst && Array.isArray(docInst.instalacoes)) {
        mem.instalacoes = docInst.instalacoes;
      } else {
        mem.instalacoes = seedInstalacoes();
        await persistMongo('instalacoes', { instalacoes: mem.instalacoes });
      }
      const docEnvios = await mongoCol.findOne({ _id: 'envios' });
      if (docEnvios && Array.isArray(docEnvios.envios)) {
        mem.envios = docEnvios.envios;
      } else {
        mem.envios = seedEnvios();
        await persistMongo('envios', { envios: mem.envios });
      }
      const docContr = await mongoCol.findOne({ _id: 'contratos' });
      if (docContr && Array.isArray(docContr.contratos)) { mem.contratos = docContr.contratos; }
      else { mem.contratos = seedContratos(); await persistMongo('contratos', { contratos: mem.contratos }); }
      const docFb = await mongoCol.findOne({ _id: 'feedbacks' });
      if (docFb && Array.isArray(docFb.feedbacks)) { mem.feedbacks = docFb.feedbacks; }
      else { mem.feedbacks = seedFeedbacks(); await persistMongo('feedbacks', { feedbacks: mem.feedbacks }); }
      const docMnt = await mongoCol.findOne({ _id: 'manutencao' });
      if (docMnt && Array.isArray(docMnt.manutencao)) { mem.manutencao = docMnt.manutencao; }
      else { mem.manutencao = seedManutencao(); await persistMongo('manutencao', { manutencao: mem.manutencao }); }
      const docSim = await mongoCol.findOne({ _id: 'simulacoes' });
      if (docSim && Array.isArray(docSim.simulacoes)) { mem.simulacoes = docSim.simulacoes; }
      else { mem.simulacoes = seedSimulacoes(); await persistMongo('simulacoes', { simulacoes: mem.simulacoes }); }
      const docAbt = await mongoCol.findOne({ _id: 'abastecimento' });
      if (docAbt && Array.isArray(docAbt.abastecimento)) { mem.abastecimento = docAbt.abastecimento; }
      else { mem.abastecimento = seedAbastecimento(); await persistMongo('abastecimento', { abastecimento: mem.abastecimento }); }
      const docForn = await mongoCol.findOne({ _id: 'fornecedores' });
      if (docForn && Array.isArray(docForn.fornecedores)) { mem.fornecedores = docForn.fornecedores; }
      else { mem.fornecedores = seedFornecedores(); await persistMongo('fornecedores', { fornecedores: mem.fornecedores }); }
      const docCart = await mongoCol.findOne({ _id: 'cartoes' });
      if (docCart && Array.isArray(docCart.cartoes)) { mem.cartoes = docCart.cartoes; }
      else { mem.cartoes = seedCartoes(); await persistMongo('cartoes', { cartoes: mem.cartoes }); }
      const docAlmox = await mongoCol.findOne({ _id: 'almoxarifado' });
      if (docAlmox && Array.isArray(docAlmox.retiradas)) { mem.almoxarifado = docAlmox.retiradas; }
      else { mem.almoxarifado = seedAlmoxarifado(); await persistMongo('almoxarifado', { retiradas: mem.almoxarifado }); }
      const docEpiCat = await mongoCol.findOne({ _id: 'epiCatalogo' });
      if (docEpiCat && Array.isArray(docEpiCat.catalogo)) { mem.epiCatalogo = docEpiCat.catalogo; }
      else { mem.epiCatalogo = seedEpiCatalogo(); await persistMongo('epiCatalogo', { catalogo: mem.epiCatalogo }); }
      const docEpiMov = await mongoCol.findOne({ _id: 'epiMovimentacoes' });
      if (docEpiMov && Array.isArray(docEpiMov.movimentacoes)) { mem.epiMovimentacoes = docEpiMov.movimentacoes; }
      else { mem.epiMovimentacoes = seedEpiMov(); await persistMongo('epiMovimentacoes', { movimentacoes: mem.epiMovimentacoes }); }
      const docEpiNf = await mongoCol.findOne({ _id: 'epiNotasFiscais' });
      if (docEpiNf && Array.isArray(docEpiNf.notas)) { mem.epiNotasFiscais = docEpiNf.notas; }
      else { mem.epiNotasFiscais = seedEpiNotasFiscais(); await persistMongo('epiNotasFiscais', { notas: mem.epiNotasFiscais }); }
      const docTiAtv = await mongoCol.findOne({ _id: 'tiAtivos' });
      if (docTiAtv && Array.isArray(docTiAtv.ativos)) { mem.tiAtivos = docTiAtv.ativos; }
      else { mem.tiAtivos = seedTiAtivos(); await persistMongo('tiAtivos', { ativos: mem.tiAtivos }); }
      const docTiMov = await mongoCol.findOne({ _id: 'tiMovimentacoes' });
      if (docTiMov && Array.isArray(docTiMov.movimentacoes)) { mem.tiMovimentacoes = docTiMov.movimentacoes; }
      else { mem.tiMovimentacoes = seedTiMov(); await persistMongo('tiMovimentacoes', { movimentacoes: mem.tiMovimentacoes }); }
      const docSenhas = await mongoCol.findOne({ _id: 'senhas' });
      if (docSenhas && Array.isArray(docSenhas.senhas)) { mem.senhas = docSenhas.senhas; mem.senhasCategorias = normalizarCategoriasSenha(docSenhas.categorias || []); }
      else { mem.senhas = seedSenhas(); mem.senhasCategorias = normalizarCategoriasSenha(mem.senhas.map(s => s && s.categoria)); await persistMongo('senhas', { senhas: mem.senhas, categorias: mem.senhasCategorias }); }
      const docEmpresa = await mongoCol.findOne({ _id: 'documentosEmpresa' });
      const estruturaDocs = docEmpresa && Array.isArray(docEmpresa.documentos)
        ? migrarEstruturaDocumentos(docEmpresa.documentos, docEmpresa.pastas)
        : seedEstruturaDocumentos();
      mem.documentosEmpresa = estruturaDocs.documentos;
      mem.pastasDocumentos = estruturaDocs.pastas;
      if (!docEmpresa || !Array.isArray(docEmpresa.pastas)) await persistMongo('documentosEmpresa', estruturaDocs);
      const docOfi = await mongoCol.findOne({ _id: 'oficina' });
      if (docOfi && Array.isArray(docOfi.oficina)) { mem.oficina = docOfi.oficina; }
      else { mem.oficina = seedOficina(); await persistMongo('oficina', { oficina: mem.oficina }); }
      const docOdo = await mongoCol.findOne({ _id: 'odometros' });
      if (docOdo && Array.isArray(docOdo.leituras)) { mem.odometros = docOdo.leituras; }
      else { mem.odometros = seedOdometros(); await persistMongo('odometros', { leituras: mem.odometros }); }
      const docVist = await mongoCol.findOne({ _id: 'vistorias' });
      if (docVist && Array.isArray(docVist.vistorias)) { mem.vistorias = docVist.vistorias; }
      else { mem.vistorias = seedVistorias(); await persistMongo('vistorias', { vistorias: mem.vistorias }); }
      const docInv = await mongoCol.findOne({ _id: 'investimentos' });
      mem.investimentos = (docInv && docInv.dados) ? docInv.dados : null; // snapshot opcional; sem seed
      const docCustos = await mongoCol.findOne({ _id: 'custos' });
      mem.custos = (docCustos && docCustos.dados) ? docCustos.dados : null; // snapshot da planilha CUSTOS ATLAS; sem seed
      const docCstCfg = await mongoCol.findOne({ _id: 'custosConfig' });
      if (docCstCfg && docCstCfg.gruposCategoria) { mem.custosConfig = { gruposCategoria: docCstCfg.gruposCategoria }; }
      else { mem.custosConfig = seedCustosConfig(); await persistMongo('custosConfig', mem.custosConfig); }
      const docHE = await mongoCol.findOne({ _id: 'horasExtras' });
      if (docHE && Array.isArray(docHE.horasExtras)) { mem.horasExtras = docHE.horasExtras; }
      else { mem.horasExtras = seedHorasExtras(); await persistMongo('horasExtras', { horasExtras: mem.horasExtras }); }
      const docContab = await mongoCol.findOne({ _id: 'contabilidade' });
      if (docContab && Array.isArray(docContab.contabilidade)) {
        mem.contabilidade = docContab.contabilidade;
        mem.contabilidadeEmpresas = Array.isArray(docContab.empresas) ? docContab.empresas.map(normalizarEmpresaContab).filter(e => e.nome) : derivarEmpresasContab(mem.contabilidade);
      } else {
        mem.contabilidade = seedContabilidade();
        mem.contabilidadeEmpresas = seedEmpresasContabilidade();
        await persistMongo('contabilidade', { contabilidade: mem.contabilidade, empresas: mem.contabilidadeEmpresas });
      }
      const docApt = await mongoCol.findOne({ _id: 'aportes' });
      if (docApt && Array.isArray(docApt.aportes)) { mem.aportes = docApt.aportes; }
      else { mem.aportes = seedAportes(); await persistMongo('aportes', { aportes: mem.aportes }); }
      const docEmp = await mongoCol.findOne({ _id: 'emprestimos' });
      if (docEmp && Array.isArray(docEmp.emprestimos)) { mem.emprestimos = docEmp.emprestimos; }
      else { mem.emprestimos = seedEmprestimos(); await persistMongo('emprestimos', { emprestimos: mem.emprestimos }); }
      const docPct = await mongoCol.findOne({ _id: 'percentuais' });
      if (docPct && Array.isArray(docPct.percentuais)) { mem.percentuais = docPct.percentuais; }
      else { mem.percentuais = seedPercentuais(); await persistMongo('percentuais', { percentuais: mem.percentuais }); }
      const docRet = await mongoCol.findOne({ _id: 'retiradas' });
      if (docRet && Array.isArray(docRet.retiradas)) { mem.retiradas = docRet.retiradas; }
      else { mem.retiradas = seedRetiradas(); await persistMongo('retiradas', { retiradas: mem.retiradas }); }
      const docFunc = await mongoCol.findOne({ _id: 'funcionarios' });
      if (docFunc && Array.isArray(docFunc.funcionarios)) { mem.funcionarios = docFunc.funcionarios; }
      else { mem.funcionarios = seedFuncionarios(); await persistMongo('funcionarios', { funcionarios: mem.funcionarios }); }
      const docFuncObr = await mongoCol.findOne({ _id: 'funcobrigatorios' });
      mem.funcobrigatorios = { cargos: (docFuncObr && docFuncObr.cargos) || {}, contratos: (docFuncObr && docFuncObr.contratos) || {} };
      const docProg = await mongoCol.findOne({ _id: 'programas' });
      if (docProg && Array.isArray(docProg.programas)) { mem.programas = docProg.programas; }
      else { mem.programas = seedProgramas(); await persistMongo('programas', { programas: mem.programas }); }
      const docAcoesSst = await mongoCol.findOne({ _id: 'acoesSst' });
      if (docAcoesSst && Array.isArray(docAcoesSst.acoes)) { mem.acoesSst = docAcoesSst.acoes; }
      else { mem.acoesSst = seedAcoesSst(); await persistMongo('acoesSst', { acoes: mem.acoesSst }); }
      const docAdm = await mongoCol.findOne({ _id: 'admissoes' });
      if (docAdm && Array.isArray(docAdm.admissoes)) { mem.admissoes = docAdm.admissoes; }
      else { mem.admissoes = seedAdmissoes(); await persistMongo('admissoes', { admissoes: mem.admissoes }); }
      const docTrein = await mongoCol.findOne({ _id: 'treinamentos' });
      if (docTrein && Array.isArray(docTrein.treinamentos)) { mem.treinamentos = docTrein.treinamentos; }
      else { mem.treinamentos = seedTreinamentos(); await persistMongo('treinamentos', { treinamentos: mem.treinamentos }); }
      const docTreinConv = await mongoCol.findOne({ _id: 'treinamentoConvites' });
      if (docTreinConv && Array.isArray(docTreinConv.treinamentoConvites)) { mem.treinamentoConvites = docTreinConv.treinamentoConvites; }
      else { mem.treinamentoConvites = seedConvites(); await persistMongo('treinamentoConvites', { treinamentoConvites: mem.treinamentoConvites }); }
      const docTreinConc = await mongoCol.findOne({ _id: 'treinamentoConclusoes' });
      if (docTreinConc && Array.isArray(docTreinConc.treinamentoConclusoes)) { mem.treinamentoConclusoes = docTreinConc.treinamentoConclusoes; }
      else { mem.treinamentoConclusoes = seedConclusoes(); await persistMongo('treinamentoConclusoes', { treinamentoConclusoes: mem.treinamentoConclusoes }); }
      const docCad = await mongoCol.findOne({ _id: 'cadastros' });
      if (docCad && (Array.isArray(docCad.centrosCusto) || Array.isArray(docCad.responsaveis) || Array.isArray(docCad.motoristas) || Array.isArray(docCad.contratosFuncionarios))) {
        mem.cadastros = {
          centrosCusto: docCad.centrosCusto || [],
          responsaveis: docCad.responsaveis || [],
          motoristas: docCad.motoristas || [],
          contratosFuncionarios: normalizarCatalogoContratosFunc(docCad.contratosFuncionarios),
        };
      } else {
        // 1ª vez: semeia o doc vazio no banco (como os demais), p/ não ficar sem registro
        mem.cadastros = { centrosCusto: [], responsaveis: [], motoristas: [], contratosFuncionarios: [] };
        await persistMongo('cadastros', mem.cadastros);
      }
      const docLoc = await mongoCol.findOne({ _id: 'locacoes' });
      if (docLoc && Array.isArray(docLoc.locacoes)) { mem.locacoes = docLoc.locacoes; }
      else { mem.locacoes = seedLocacoes(); await persistMongo('locacoes', { locacoes: mem.locacoes }); }
      const docLocCfg = await mongoCol.findOne({ _id: 'locacoesConfig' });
      const { _id: _locacoesConfigId, ...locacoesConfigSalva } = docLocCfg || {};
      mem.locacoesConfig = docLocCfg
        ? { ...locacoesConfigSalva, ipca: locacoesConfigSalva.ipca || {}, contratos: locacoesConfigSalva.contratos || [] }
        : seedLocacoesConfig();
      // Migração aditiva e idempotente da lista inicial informada: preserva qualquer
      // cadastro existente e insere somente placas ausentes na primeira execução.
      if (Number(mem.locacoesConfig.cadastroInicialVersao || 0) < 1) {
        const placasExistentes = new Set(mem.locacoes.map((locacao) => String(locacao && locacao.placa || '').toUpperCase()));
        const faltantes = seedLocacoes().filter((locacao) => locacao && locacao.placa && !placasExistentes.has(String(locacao.placa).toUpperCase()));
        if (faltantes.length) {
          mem.locacoes = mem.locacoes.concat(faltantes);
          await persistMongo('locacoes', { locacoes: mem.locacoes });
        }
        mem.locacoesConfig.cadastroInicialVersao = 1;
        await persistMongo('locacoesConfig', mem.locacoesConfig);
      }
      const docLocFat = await mongoCol.findOne({ _id: 'locacoesFaturas' });
      if (docLocFat && Array.isArray(docLocFat.faturas)) { mem.locacoesFaturas = docLocFat.faturas; }
      else { mem.locacoesFaturas = seedLocacoesFaturas(); await persistMongo('locacoesFaturas', { faturas: mem.locacoesFaturas }); }
      const docUsu = await mongoCol.findOne({ _id: 'usuarios' });
      mem.usuarios = (docUsu && Array.isArray(docUsu.usuarios))
        ? { usuarios: docUsu.usuarios, cadastrosAbertos: docUsu.cadastrosAbertos !== false }
        : { usuarios: [], cadastrosAbertos: true };
      const docLogs = await mongoCol.findOne({ _id: 'loginlogs' });
      mem.loginlogs = (docLogs && Array.isArray(docLogs.logs)) ? docLogs.logs : [];
      const docSeg = await mongoCol.findOne({ _id: 'seglogs' });
      mem.seglogs = (docSeg && Array.isArray(docSeg.logs)) ? docSeg.logs : [];
      console.log('MongoDB conectado. Veículos:', mem.veiculos.length, '| Multas:', mem.multas.length, '| Rastreadores:', mem.rastreadores.length, '| Usuários:', mem.usuarios.usuarios.length);
    } catch (e) {
      console.error('Falha ao conectar no MongoDB:', e.message);
      process.exit(1);
    }
  }
  await recuperarVinculosLegados();
  await sincronizarAreasNovas(); // tranca abas NOVAS p/ comuns (senão sobem liberadas — ver a função)
  await marcarAvisoFotoDosAntigos(); // aviso da foto de perfil só para quem chegar depois
  try { await carregarConfigSeguranca(); } catch (e) { console.error('[seguranca] carga da config falhou:', e.message); }
  try { EXP_DIAS_CACHE = await lerExperienciaDias(); } catch (e) { /* mantém o padrão 45 */ }
  await prepararCofreNoBoot(); // teste do bucket + marcador cofre_r2 (antes do listen)
  iniciarServidor();
  // Projeção diária do rendimento dos investimentos: back-fill no boot + timer 01:00 BRT.
  atualizarProjecaoInvestimentos().catch(e => console.error('projeção (boot):', e.message));
  agendarProjecaoDiaria();
}

boot();
